	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    task.New(self,function()
        do local s1,_d_s1=(0),(s/20) local a,_d_a=(0),(7) for _=1,20 do
            self.vscale=s1
            self.hscale=s1
            _object.set_color(self,"mul+add",a,225,225,255)
            task._Wait(1)
        s1=s1+_d_s1 a=a+_d_a end end
        task._Wait(50)
        do local s1,_d_s1=(s),(-s/20) local a,_d_a=(140),(-7) for _=1,20 do
            self.vscale=s1
            self.hscale=s1
            _object.set_color(self,"mul+add",a,225,225,255)
            task._Wait(1)
        s1=s1+_d_s1 a=a+_d_a end end
        _del(self,true)
    end)
    task.New(self,function()
        do local aerfa,_d_aerfa=(0),(2*i) for _=1,_infinite do
            self.rot=360*sin(aerfa)
            task._Wait(1)
        aerfa=aerfa+_d_aerfa end end
    end)
end
