_editor_class["lizi_小玉毛玉:Normal"]=Class(enemy)
_editor_class["lizi_小玉毛玉:Normal"].init=function(self,_x,_y,i)
    enemy.init(self,19,5,false,true,false)
    self.x,self.y=_x,_y
    self.drop={0,0,2}
    task.New(self,function() self.protect=true task.Wait(5) self.protect=false end)
    self.group=GROUP_GHOST
    task.New(self,function()
        task.New(self,function()
            do local a,_d_a=(0),(255/150) local s,_d_s=(0.1),(0.9/150) for _=1,150 do
                _object.set_color(self,"",a,255,255,255)
                self.lscale=s
                self.hscale=s
                task._Wait(1)
            a=a+_d_a s=s+_d_s end end
        end)
        do local beta,_d_beta=(90-90*i),(-i*90/120) for _=1,120 do
            self.x=-220*i+440*cos(beta)
            self.y=240+240*sin(beta)
            task._Wait(1)
        beta=beta+_d_beta end end
        self.group=GROUP_ENEMY
        task.New(self,function()
            task._Wait(ran:Float(20,30))
            do for _=1,_infinite do
                last=New(_straight,ball_mid_c,COLOR_BLUE,self.x+ran:Float(-5,5),self.y+ran:Float(-5,5),3,Angle(self,player),false,0,true,true,0,false,0,0,0,false)
                PlaySound("tan00",0.05,self.x/256,false)
                task._Wait(ran:Float(20,30))
                task._Wait(1)
            end end
        end)
        do local aerfa,_d_aerfa=(90),(-0.75) for _=1,_infinite do
            self.vx=3*i
            self.vy=3*sin(aerfa)
            task._Wait(1)
        aerfa=aerfa+_d_aerfa end end
    end)
    task.New(self,function()
        SetV2(self,5,270,false,false)
        task._Wait(15)
        do local a,_d_a=(270),(90/60*i) for _=1,60 do
            SetV2(self,5,a,false,false)
            task._Wait(1)
        a=a+_d_a end end
    end)
end
