        _connect(self,last,0,true)
    end
    task.New(self,function()
        self.bound=false
        task._Wait(240)
        self.bound=true
    end)
    task.New(self,function()
        self.hscale=1.2
        self.vscale=1.2
        self.a=self.vscale*self.a
        self.b=self.hscale*self.b
        do local r,_d_r=(0),(dr) for _=1,_infinite do
            local r1=r*n*(2)^(0.5)/14
            _set_rel_pos(self,r1*cos(self._master.rot),r1*sin(self._master.rot),self.rot,false)
            self.rot=self._master.rot+90
            task._Wait(1)
        r=r+_d_r end end
    end)
end
