    self.drop={0,0,0}
    task.New(self,function() self.protect=true task.Wait(9999999) self.protect=false end)
    self.bound=false
    task.New(self,function()
        do local a,_d_a=(a0),(i) local r,_d_r=(0),(100/60) for _=1,60 do
            _set_rel_pos(self,r*cos(a),r*sin(a),self.rot,false)
            task._Wait(1)
        a=a+_d_a r=r+_d_r end end
        do local a,_d_a=(a0+60*i),(2*i) for _=1,_infinite do
            _set_rel_pos(self,100*cos(a),100*sin(a),self.rot,false)
            if self.timer%16==0 then
                _create_bullet_group(lz_grain_b,COLOR_GREEN,self.x,self.y,3,0,2.5,2,a+10,20,false,0,true,true,0,false,self)
