_editor_class["祢津七符激光:Normal"]=Class(laser)
_editor_class["祢津七符激光:Normal"].init=function(self,_x,_y,i,a)
    laser.init(self,COLOR_GREEN,_x,_y,0,0,400,0,8,4,8)
    laser.ChangeImage(self,4)
    self.rot=a
    task.New(self,function()
        laser._TurnHalfOn(self,60,true)
        laser._TurnOn(self,60,true,true)
    end)
    task.New(self,function()
        task._Wait(120)
        do local a1,_d_a1=(a),(0.2*i) for _=1,_infinite do
            self.rot=a1
            local aa = a1%360
            if aa>=180 and aa<360 then
                aa=aa-360
            else
            end
            local aaa = Angle(self,player)
            local da = abs(aa-aaa)
            if da>12 and da<=30 then
                local l0 = Dist(self,player)-96+96*sin(12)
                self.l2=l0+(400-l0)*sin((da-12)*90/18)
            else
            end
            if da<=12 then
                if self.l2>0 then
                    self.l2=Dist(self,player)-96+96*sin(da)
                else
                    self.l2=0
                end
                if self.timer%40==0 then
                    last=New(_straight,lz_ball_mid,COLOR_GREEN,self.x+self.l2*cos(a1),self.y+self.l2*sin(a1),ran:Float(0.5,1),a1+ran:Float(-10,10),false,0,false,true,0,false,0,0,0,false)
                else
                end
            else
            end
            task._Wait(1)
        a1=a1+_d_a1 end end
    end)
end
