                do for _=1,_infinite do
                    do for _=1,5 do
                        do local b,_d_b=(0),(90) for _=1,4 do
                            last=New(_editor_class["祢津终符绿鳞弹"],self.x+50*cos(a+b),self.y+20*sin(a+b),1,a+b,2)
                            task._Wait(0)
                        b=b+_d_b end end
                        a=a+5.3*sign(self.x)
                        PlaySound("kira00",0.1,self.x/256,false)
                        task._Wait(4)
                    end end
                    a=a+11*sign(self.x)
                    task._Wait(45)
                end end
            end)
            SetV2(self,1.5,270,false,false)
        else
        end
        if mode==4 then
            task.New(self,function()
                do for _=1,_infinite do
                    if self.timer%7==0 then
                        last=New(_editor_class["祢津终符光效"],self.x,self.y,ran:Float(1,2),ran:Float(0,360),COLOR_PURPLE)
                    else
                    end
                    task._Wait(1)
                end end
            end)
            task.New(self,function()
                self.bound=false
                do local a,_d_a=(45),(72) for _=1,5 do
                    last=New(_editor_class["祢津终符白激光:Normal"],self.x,self.y,sign(self.x),a)
                    _connect(self,last,0,true)
                    task._Wait(0)
                a=a+_d_a end end
                task._Wait(120)
                self.bound=true
            end)
            task.New(self,function()
                local a = 90+90*sign(self.x)
                do for _=1,_infinite do
                    do for _=1,5 do
                        do local b,_d_b=(0),(90) for _=1,4 do
                            last=New(_editor_class["祢津三符鳞弹"],self.x+50*cos(a+b),self.y+20*sin(a+b),1,a+b)
                            task._Wait(0)
                        b=b+_d_b end end
                        a=a-5.3*sign(self.x)
                        PlaySound("kira00",0.1,self.x/256,false)
                        task._Wait(4)
                    end end
                    a=a-11*sign(self.x)
                    task._Wait(75)
                end end
            end)
            SetV2(self,1.5,270,false,false)
        else
        end
    end)
end
_editor_class["祢津终符蓝激光:Normal"]=Class(laser)
_editor_class["祢津终符蓝激光:Normal"].init=function(self,_x,_y,a)
    laser.init(self,COLOR_BLUE,_x,_y,0,0,400,0,4,4,8)
    laser.ChangeImage(self,4)
    self.rot=a
    laser._TurnOn(self,1,false,false)
    SetV2(self,0.8,270,false,false)
    task.New(self,function()
        do for _=1,_infinite do
            local da = abs(self.y-player.y)
            if da<=32 then
                self.l2=48
                if self.timer%45==0 then
                    last=New(_straight,water_drop_dark,COLOR_BLUE,self.x+self.l2*cos(a),self.y+self.l2*sin(a),ran:Float(0.5,1),a+ran:Float(-10,10),false,0,false,true,0,false,0,0,0,false)
                else
                end
            else
                self.l2=400
            end
            task._Wait(1)
        end end
    end)
end
_editor_class["祢津终符白激光:Normal"]=Class(laser)
_editor_class["祢津终符白激光:Normal"].init=function(self,_x,_y,i,a)
    laser.init(self,COLOR_DEEP_GRAY,_x,_y,0,0,300,0,8,4,24)
    laser.ChangeImage(self,4)
    self.rot=a
    self.bound=false
    task.New(self,function()
        laser._TurnOn(self,1,false,false)
        do local a1,_d_a1=(a),(0.5*i) for _=1,_infinite do
            _set_rel_pos(self,50*cos(a1),20*sin(a1),self.rot,false)
            self.rot=a1
            local aa = a1%360
            if aa>=180 and aa<360 then
                aa=aa-360
            else
            end
            local aaa = Angle(self,player)
            local da = abs(aa-aaa)
            if da>15 and da<=30 then
                local l0 = Dist(self,player)-128
                self.l2=l0+(300-l0)*sin((da-15)*90/15)
            else
            end
            if da<=15 then
                if self.l2>0 then
                    self.l2=Dist(self,player)-128
                else
                    self.l2=0
                end
                if self.timer%11==0 then
                    last=New(_straight,water_drop_dark,COLOR_DEEP_GRAY,self.x+self.l2*cos(a1),self.y+self.l2*sin(a1),ran:Float(0.5,1),270+ran:Float(-10,10),false,0,false,true,0,false,0,0,0,false)
                else
                end
            else
            end
            task._Wait(1)
        a1=a1+_d_a1 end end
    end)
end
_editor_class["祢津终符蓝鳞弹:Normal"]=Class(bullet)
_editor_class["祢津终符蓝鳞弹:Normal"].init=function(self,_x,_y,v,a)
    bullet.init(self,lz_arrow_big,COLOR_BLUE,false,false)
    self.x,self.y=_x,_y
    do
        _object.set_color(self,"mul+add",255,255,255,255)
        last=New(_editor_class["祢津鳞弹阴影"],self.x,self.y,COLOR_YELLOW)
        _connect(self,last,0,true)
        self.hscale=1.2
        self.vscale=1.2
        self.a=self.vscale*self.a
        self.b=self.hscale*self.b
    end
    self.navi=true
    SetV2(self,v,a,true,false)
end
