            boss.dialog.sentence(self,"image:lizi_reimu_dialog2","left","去去去，就算你是鬼王，也不能不让人回家呀！",180,1,1)
        else
        end
        if GetGlobal('player_name')=='marisa_player' then
            boss.dialog.sentence(self,"image:lizi_marisa_dialog1","left","唔啊，你就是那个人里的魔术师吧！好厉害啊！",180,-1,1)
            boss.dialog.sentence(self,"image:几缟雪嬢符卡立绘","right","哼，人类的魔法使，就算你装傻，我也不会让你过去！",180,1,1)
            boss.dialog.sentence(self,"image:lizi_marisa_dialog3","left","我说你，别太小看人类了！",180,-1,1)
        else
        end
        if GetGlobal('player_name')=='sanae_player' then
            boss.dialog.sentence(self,"image:lizi_sanae_dialog4","left","诶诶？怎么就开始弹幕游戏了？",180,1,1)
            boss.dialog.sentence(self,"image:几缟雪嬢符卡立绘","right","现人神吗？前面可没有信仰，只有幻觉哦~",180,1,1)
            boss.dialog.sentence(self,"image:lizi_sanae_dialog1","left","幻觉……非常识的东西不是挺有趣的嘛……",180,1,1)
        else
        end
        if GetGlobal('player_name')=='wuer_player' then
            boss.dialog.sentence(self,"image:lizi_wuer_dialog5","left","哇，好惊人，刚才那是世界闻名的幻觉模型呢！",180,-0.33,0.33)
            boss.dialog.sentence(self,"image:几缟雪嬢符卡立绘","right","嘻嘻，没有什么幻觉是我不会的哦~",180,1,1)
            boss.dialog.sentence(self,"image:lizi_wuer_dialog2","left","……emmm，不对，话说你是谁呀！",180,-0.33,0.33)
        else
        end
    end)
end
