                last=New(_editor_class["雪嬢二符旋转中心:Lunatic"],self.x,self.y,v,270+120*sin(aerfa)*i,i)
                PlaySound("shot7",0.7,self.x/256,true)
                task._Wait(6)
            aerfa=aerfa+_d_aerfa v=v+_d_v end end
            task.MoveToPlayer(60,-48,48,112,124,16,32,8,16,MOVE_DECEL,MOVE_X_TOWARDS_PLAYER)
            do local a,_d_a=(Angle(self,player)*i),(9) local aerfa,_d_aerfa=(-90),(450/240) for _=1,240 do
                do local b,_d_b=(0),(90) for _=1,4 do
                    local c = ran:Float(-2,2)
                    last=New(_straight,lz_arrow_big,COLOR_YELLOW,self.x+8*cos(a+b+c),self.y+8*sin(a+b+c),2+1*sin(aerfa),a+b+c,false,0,true,true,0,false,0,0,0,false)
                    task._Wait(0)
                b=b+_d_b end end
                PlaySound("kira00",0.1,self.x/256,false)
                task._Wait(1)
            a=a+_d_a aerfa=aerfa+_d_aerfa end end
            task.MoveToPlayer(60,-48,48,112,124,16,32,8,16,MOVE_DECEL,MOVE_X_TOWARDS_PLAYER)
            do local a,_d_a=(Angle(self,player)),(18) for _=1,20 do
                _create_bullet_group(ball_big,COLOR_ORANGE,self.x,self.y,10,0,1,4,a,0,false,0,true,true,0,false,self)
                task._Wait(0)
            a=a+_d_a end end
            PlaySound("kira00",0.1,self.x/256,false)
            i=-i
            task._Wait(1)
        end end
    end)
end
