_editor_class["狐狸灵梦一符鬼火:Lunatic"]=Class(enemy)
_editor_class["狐狸灵梦一符鬼火:Lunatic"].init=function(self,_x,_y,a0,i)
    enemy.init(self,32,150,false,false,false)
    self.x,self.y=_x,_y
    self.drop={0,0,0}
    task.New(self,function() self.protect=true task.Wait(1) self.protect=false end)
    task.New(self,function()
        task._Wait(360)
        self.bound=true
    end)
    task.New(self,function()
        self.bound=false
        local list={2,4,8,10,12,14}
        do local a,_d_a=(1),(1) for _=1,7 do
            list[a]=2*a
            task._Wait(0)
        a=a+_d_a end end
        do local aa,_d_aa=(a0),(360/15) local flag,_d_flag=(0),(1) for _=1,24 do
            local a = ran:Int(1,7)
            last=New(_editor_class["狐狸灵梦一符鬼火光"],self.x,self.y,list[a],aa,i,flag%3)
            _connect(self,last,0,false)
            task._Wait(0)
        aa=aa+_d_aa flag=flag+_d_flag end end
        do local v,_d_v=(0),(2/30) local a,_d_a=(a0),(i) for _=1,30 do
            SetV2(self,v,a,true,false)
            task._Wait(1)
        v=v+_d_v a=a+_d_a end end
        do local a,_d_a=(a0+30*i),(i*0.4) for _=1,_infinite do
            SetV2(self,2,a,true,false)
            task._Wait(1)
        a=a+_d_a end end
    end)
    task.New(self,function()
        task._Wait(60)
        do for _=1,_infinite do
            if self.x<-195 or self.x>195 then
                if true then break end
            else
            end
            task._Wait(1)
        end end
        PlaySound("shot7",0.7,self.x/256,true)
        _del(self,true)
    end)
end
_editor_class["狐狸灵梦一符鬼火光"]=Class(bullet)
_editor_class["狐狸灵梦一符鬼火光"].init=function(self,_x,_y,c,a0,i,flag)
    bullet.init(self,ball_mid_c,c,true,false)
    self.x,self.y=_x,_y
    _object.set_color(self,"mul+add",255,255,255,255)
    task.New(self,function()
        task._Wait(240)
        self.bound=true
    end)
    task.New(self,function()
        self.bound=false
        do local a,_d_a=(a0),(2.3*i) for _=1,_infinite do
            _set_rel_pos(self,40*cos(a),40*sin(a),self.rot,false)
            if not(IsValid(self._master)) then
                self.rot=a
                if true then break end
            else
            end
            task._Wait(1)
        a=a+_d_a end end
        if flag==0 then
            _del(self,true)
        else
        end
        ChangeBulletImage(self,ball_mid_c,COLOR_GRAY)
        SetV2(self,0,self.rot,true,false)
        do local v,_d_v=(0),(1.5/30) for _=1,30 do
            SetV2(self,v,self.rot,true,false)
            task._Wait(1)
        v=v+_d_v end end
    end)
end
