_editor_class["狐狸灵梦二符激光:Lunatic"].init=function(self,_x,_y,angle1,r,i,cx,cy)
    laser.init(self,COLOR_BLUE,_x,_y,0,0,r*(2)^(0.5),0,1,8,0)
    task.New(self,function()
        self.colli=false
        self.bound=false
