    end)
    task.New(self,function()
        do local angle,_d_angle=(angle1),(0.4*i) local r1,_d_r1=(0),(r/90) for _=1,_infinite do
            self.rot=angle+135
            self.l2=r1*(2)^(0.5)
            self.x=cx+r1*cos(angle)
            self.y=cy+r1*sin(angle)
            task._Wait(1)
        angle=angle+_d_angle r1=r1+_d_r1 end end
    end)
    task.New(self,function()
        do local n,_d_n=(1),(1) for _=1,18 do
            last=New(_editor_class["狐狸灵梦二符结界札弹:Lunatic"],self.x,self.y,n,r/90)
            _connect(self,last,0,true)
            task._Wait(0)
        n=n+_d_n end end
        task._Wait(360)
        self.bound=true
    end)
end
