_tmp_sc=boss.card.New("幻化「dark spark的悲哀」",3,6,50,1000,{50,20,0},false)
function _tmp_sc:init()
    task.New(self,function()
        do
            last=New(_editor_class["狐狸魔理沙符卡立绘"],-175,0,_)
            last=New(_editor_class["击破"],200,0,_)
            local i = 1
            task.New(self,function()
                do local s,_d_s=(1),(2/4) for _=1,4 do
                    last=New(_editor_class["开符效果"],0,0,s,i)
                    i=-i
                    task._Wait(0)
                s=s+_d_s end end
            end)
            task.New(self,function()
                do for _=1,4 do
                    do local y,_d_y=(ran:Float(-200,-150)),(100) for _=1,4 do
                        last=New(_editor_class["青蛙子泡泡特效"],-220,y,ran:Float(6,10),0)
                        task._Wait(0)
                    y=y+_d_y end end
                    task._Wait(10)
                end end
            end)
        end
        boss.show_aura(self,false)
        task.MoveTo(0,124,60,MOVE_DECEL)
        task._Wait(60)
        task.New(self,function()
            task._Wait(150)
            task.New(self,function()
                do for _=1,_infinite do
                    do local a,_d_a=(ran:Float(0,360)),(360/15) for _=1,15 do
                        last=New(_editor_class["狐狸魔理沙一符大星弹:Lunatic"],self.x,self.y,ran:Float(2,5),a,ran:Int(1,16))
                        task._Wait(0)
                    a=a+_d_a end end
                    task._Wait(15)
                end end
            end)
        end)
        local i = 1
        do for _=1,_infinite do
            task.MoveTo(100*i,ran:Float(112,124),60,MOVE_DECEL)
            do
                last=New(_editor_class["lizi蓄力charge"],self.x,self.y,_)
                PlaySound("ch02",1.5,self.x/256,false)
                task._Wait(60)
            end
            local a = 270-30*i
            do local da,_d_da=(135),(-60/10) for _=1,5 do
                last=New(_editor_class["狐狸魔理沙二符大炮预警"],self.x,self.y,1,a,da)
                last=New(_editor_class["狐狸魔理沙二符大炮预警"],self.x,self.y,-1,a,da)
                task._Wait(2)
            da=da+_d_da end end
            task._Wait(64)
            misc.ShakeScreen(90, 5)
            PlaySound("nep00",0.5,self.x/256,false)
            do local a1,_d_a1=(a),(0) for _=1,18 do
                do for _=1,6 do
                    last=New(_editor_class["狐狸魔理沙大炮2:Lunatic"],self.x,self.y,ran:Float(15,19),a1+ran:Float(-10,10),COLOR_RED)
                    last=New(_editor_class["狐狸魔理沙大炮2:Lunatic"],self.x,self.y,ran:Float(15,19),a1+ran:Float(-10,10),COLOR_YELLOW)
                    task._Wait(0)
                end end
                task._Wait(5)
            a1=a1+_d_a1 end end
            task._Wait(90)
            i=-i
            task._Wait(1)
        end end
    end)
end
function _tmp_sc:del()
end
