_editor_class["狐狸早苗一非鬼火:Lunatic"]=Class(enemy)
_editor_class["狐狸早苗一非鬼火:Lunatic"].init=function(self,_x,_y,a0,i)
    enemy.init(self,32,10,false,false,false)
    self.x,self.y=_x,_y
    self.drop={0,0,0}
    task.New(self,function() self.protect=true task.Wait(9999999) self.protect=false end)
    self.bound=false
    task.New(self,function()
        do local a,_d_a=(a0),(i) local r,_d_r=(0),(100/60) for _=1,60 do
            _set_rel_pos(self,r*cos(a),r*sin(a),self.rot,false)
            task._Wait(1)
        a=a+_d_a r=r+_d_r end end
        do local a,_d_a=(a0+60*i),(2*i) for _=1,_infinite do
            _set_rel_pos(self,100*cos(a),100*sin(a),self.rot,false)
            if self.timer%16==0 then
                _create_bullet_group(lz_grain_b,COLOR_GREEN,self.x,self.y,4,0,3.5,3,a+10,20,false,0,true,true,0,false,self)
                _create_bullet_group(lz_grain_b,COLOR_GREEN,self.x,self.y,4,0,3.5,3,a-10,-20,false,0,true,true,0,false,self)
                PlaySound("tan00",0.1,self.x/256,false)
            else
            end
            if self.timer%8==0 then
                do local a1,_d_a1=(a),(18) for _=1,20 do
                    last=New(_editor_class["狐狸早苗一非光效"],self.x,self.y,1.5,a1)
                    task._Wait(0)
                a1=a1+_d_a1 end end
            else
            end
            task._Wait(1)
        a=a+_d_a end end
    end)
end
_editor_class["狐狸早苗一非光效"]=Class(bullet)
_editor_class["狐狸早苗一非光效"].init=function(self,_x,_y,v,a)
    bullet.init(self,ball_light,COLOR_BLUE,false,false)
    self.x,self.y=_x,_y
    self.bound=false
    self.layer=LAYER_ENEMY-1
    _object.set_color(self,"mul+add",200,255,255,255)
    self.vscale=0.75
    self.hscale=0.75
    task.New(self,function()
        self.colli=false
        do local v1,_d_v1=(v),(-v/30) local s,_d_s=(0.75),(-0.5/30) local al,_d_al=(200),(-150/30) for _=1,30 do
            SetV2(self,v,a,true,false)
            self.vscale=s
            self.hscale=s
            _object.set_color(self,"mul+add",al,255,255,255)
            task._Wait(1)
        v1=v1+_d_v1 s=s+_d_s al=al+_d_al end end
        _del(self,false)
    end)
end
_editor_class["狐狸早苗一符中心"]=Class(_object)
_editor_class["狐狸早苗一符中心"].init=function(self,_x,_y,i,a0)
    self.x,self.y=_x,_y
	self.img="img_void"
	self.layer=LAYER_ENEMY_BULLET
	self.group=GROUP_INDES
	self.hide=true
	self.bound=true
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=false
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    task.New(self,function()
        do local a,_d_a=(a0),(72) for _=1,5 do
            last=New(_editor_class["狐狸早苗一符激光"],self.x,self.y,a,80,i)
            _connect(self,last,0,true)
            task._Wait(0)
        a=a+_d_a end end
        local v = 2
        do local v1,_d_v1=(v),(-v/30) for _=1,30 do
            SetV2(self,v1,a0,false,false)
            task._Wait(1)
        v1=v1+_d_v1 end end
        task._Wait(60)
        do local v1,_d_v1=(0),(v/30) for _=1,30 do
            SetV2(self,v1,a0,false,false)
            task._Wait(1)
        v1=v1+_d_v1 end end
    end)
end
_editor_class["狐狸早苗一符激光"]=Class(laser)
_editor_class["狐狸早苗一符激光"].init=function(self,_x,_y,angle1,r,i)
    laser.init(self,COLOR_BLUE,_x,_y,0,0,0,0,8,0,16)
    laser.ChangeImage(self,4)
    task.New(self,function()
        self.colli=false
        self.bound=false
        laser._TurnHalfOn(self,60,true)
        laser._TurnOn(self,30,false,true)
        self.colli=true
    end)
    task.New(self,function()
        do local angle,_d_angle=(angle1),(0.4*i) local r1,_d_r1=(0),(r/90) for _=1,90 do
            self.rot=angle+162
            self.l2=r1*2*cos(18)
            _set_rel_pos(self,r1*cos(angle),r1*sin(angle),self.rot,false)
            task._Wait(1)
        angle=angle+_d_angle r1=r1+_d_r1 end end
        do local angle,_d_angle=(angle1+36*i),(0.4*i) for _=1,_infinite do
            self.rot=angle+162
            self.l2=r*2*cos(18)
            _set_rel_pos(self,r*cos(angle),r*sin(angle),self.rot,false)
            task._Wait(1)
        angle=angle+_d_angle end end
    end)
end
_editor_class["狐狸早苗二符鳞弹"]=Class(bullet)
_editor_class["狐狸早苗二符鳞弹"].init=function(self,_x,_y,v,angle,i)
    bullet.init(self,lz_arrow_big,COLOR_GREEN,false,true)
    self.x,self.y=_x,_y
    SetV2(self,v,angle,false,false)
    task.New(self,function()
        local e = (-3)*i
        local angle1 = angle
        do local angle1,_d_angle1=(angle),(e) for _=1,50 do
            SetV2(self,v,angle1,true,false)
            e=e+0.5*i
            task._Wait(2)
        angle1=angle1+_d_angle1 end end
    end)
end
