_editor_class["祢津六符枪"].init=function(self,_x,_y,i)
    laser.init(self,COLOR_RED,_x,_y,0,0,0,0,8,0,0)
    task.New(self,function()
        PlaySound("ch00",1.0,self.x/256,false)
        self.bound=false
        laser.ChangeImage(self,2)
        self.rot=90-45*i
        _object.set_color(self,"mul+add",200,200,200,200)
        task.New(self,function()
            self.colli=false
            do local aerfa,_d_aerfa=(0),(3) for _=1,30 do
                self.l1=120*sin(aerfa)
                self.l2=80*sin(aerfa)
                self.l3=120*sin(aerfa)
                task._Wait(1)
            aerfa=aerfa+_d_aerfa end end
        end)
        task.New(self,function()
            do local c,_d_c=(1),(1) for _=1,_infinite do
                _set_rel_pos(self,0,0,self.rot,false)
                last=New(_editor_class["祢津六符枪虚影"],self.x+ran:Float(-2,2),self.y+ran:Float(-2,2),self.rot,self.l1,self.l2,self.l3,c%14)
                task._Wait(1)
            c=c+_d_c end end
        end)
        laser._TurnOn(self,30,false,false)
        task._Wait(30)
        PlaySound("se_freeze",1.0,self.x/256,true)
        do local aerfa,_d_aerfa=(0),(90/60) local beta,_d_beta=(90),(90/60) local sp,_d_sp=(140),(-80/60) local t,_d_t=(60),(-1) for _=1,60 do
            self.rot=90-45*i+450*sin(aerfa)*i
            self.l1=5+100*sin(beta)
            self.l2=2+68*sin(beta)
            self.l3=5+100*sin(beta)
            if self.timer%1==0 then
                do local r,_d_r=(0),((self.l1+self.l2+self.l3)/4) local dv,_d_dv=(90),(-30/4) for _=1,4 do
                    last=New(_editor_class["祢津六符火弹"],self.x+r*cos(self.rot),self.y+r*sin(self.rot),sp/dv,self.rot,self.timer%14,t,sp/2)
                    last=New(_editor_class["祢津六符火弹"],self.x+r*cos(self.rot),self.y+r*sin(self.rot),sp/dv,self.rot,self.timer%14,t,-sp/2)
                    task._Wait(0)
                r=r+_d_r dv=dv+_d_dv end end
            else
            end
            task._Wait(1)
        aerfa=aerfa+_d_aerfa beta=beta+_d_beta sp=sp+_d_sp t=t+_d_t end end
        self.colli=false
        laser._TurnOff(self,30,true)
        _del(self,false)
    end)
end
