    task.New(self,function()
        SetV2(self,0,a,true,false)
        laser._TurnOn(self,1,false,false)
        task.New(self,function()
            do local w,_d_w=(2),(5/30) for _=1,30 do
                self.w=w
                task._Wait(1)
            w=w+_d_w end end
        end)
        task._Wait(5)
        do local v,_d_v=(0),(20/7) for _=1,7 do
            SetV2(self,v,a,true,false)
            task._Wait(1)
        v=v+_d_v end end
        task._Wait(60)
        self.bound=true
    end)
end
