_editor_class["祢津终符要石:Lunatic"]=Class(_object)
_editor_class["祢津终符要石:Lunatic"].init=function(self,_x,_y,mode)
    self.x,self.y=_x,_y
	self.img="ani:mijin_stone"
	self.layer=LAYER_ENEMY
	self.group=GROUP_ENEMY
	self.hide=false
	self.bound=true
	self.navi=false
	self.hp=300
	self.maxhp=300
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    self.vscale=0.75
    self.hscale=0.75
    task.New(self,function()
        if mode==1 then
            task.New(self,function()
                do for _=1,_infinite do
                    if self.timer%7==0 then
                        last=New(_editor_class["祢津终符光效"],self.x,self.y,ran:Float(1,2),ran:Float(0,360),COLOR_BLUE)
                    else
                    end
                    task._Wait(1)
                end end
            end)
            task.New(self,function()
                do for _=1,_infinite do
                    if _boss.hp<=3000 then
                        _del(self,true)
                    else
                    end
                    task._Wait(1)
                end end
            end)
            task.New(self,function()
                self.bound=false
                do local a,_d_a=(ran:Float(0,360)),(12) for _=1,30 do
                    last=New(_editor_class["祢津终符蓝鳞弹:Lunatic"],self.x,self.y,1,a)
                    last=New(_editor_class["祢津终符蓝鳞弹:Lunatic"],self.x,self.y,1.25,a)
                    last=New(_editor_class["祢津终符蓝鳞弹:Lunatic"],self.x,self.y,1.5,a)
                    task._Wait(0)
                a=a+_d_a end end
                PlaySound("kira00",0.1,self.x/256,false)
                task._Wait(180)
                self.bound=true
            end)
            last=New(_editor_class["祢津终符蓝激光:Lunatic"],self.x+8,self.y,0)
            _connect(self,last,0,true)
            last=New(_editor_class["祢津终符蓝激光:Lunatic"],self.x-8,self.y,180)
            _connect(self,last,0,true)
            SetV2(self,0.8,270,false,false)
        else
        end
        if mode==2 then
            task.New(self,function()
                do for _=1,_infinite do
                    if self.timer%7==0 then
                        last=New(_editor_class["祢津终符光效"],self.x,self.y,ran:Float(1,2),ran:Float(0,360),COLOR_GREEN)
                    else
                    end
                    task._Wait(1)
                end end
            end)
            task.New(self,function()
                do for _=1,_infinite do
                    if _boss.hp<=2000 then
                        _del(self,true)
                    else
                    end
                    task._Wait(1)
                end end
            end)
            task.New(self,function()
                self.bound=false
                do local a,_d_a=(ran:Float(0,360)),(18) for _=1,20 do
                    last=New(_editor_class["祢津终符绿鳞弹"],self.x,self.y,1,a,1)
                    task._Wait(0)
                a=a+_d_a end end
                PlaySound("kira00",0.1,self.x/256,false)
                task._Wait(180)
                self.bound=true
            end)
            last=New(_editor_class["祢津终符绿激光"],self.x+8,self.y,0,130)
            _connect(self,last,0,true)
            last=New(_editor_class["祢津终符绿激光"],self.x-8,self.y,180,130)
            _connect(self,last,0,true)
            SetV2(self,1.5,270,false,false)
        else
        end
        if mode==3 then
            task.New(self,function()
                do for _=1,_infinite do
                    if self.timer%7==0 then
                        last=New(_editor_class["祢津终符光效"],self.x,self.y,ran:Float(1,2),ran:Float(0,360),COLOR_RED)
                    else
                    end
                    task._Wait(1)
                end end
            end)
            task.New(self,function()
                do for _=1,_infinite do
                    if _boss.hp<=1000 then
                        _del(self,true)
                    else
                    end
                    task._Wait(1)
                end end
            end)
            task.New(self,function()
                self.bound=false
                task._Wait(180)
                self.bound=true
            end)
            task.New(self,function()
                local a = 90+90*sign(self.x)
                do for _=1,_infinite do
                    do for _=1,6 do
                        do local b,_d_b=(0),(90) for _=1,4 do
                            last=New(_editor_class["祢津终符绿鳞弹"],self.x+50*cos(a+b),self.y+20*sin(a+b),1,a+b,2)
                            task._Wait(0)
                        b=b+_d_b end end
                        a=a+5.3*sign(self.x)
                        PlaySound("kira00",0.1,self.x/256,false)
                        task._Wait(3)
                    end end
                    a=a+11*sign(self.x)
                    task._Wait(45)
                end end
            end)
            SetV2(self,1.5,270,false,false)
        else
        end
        if mode==4 then
            task.New(self,function()
                do for _=1,_infinite do
                    if self.timer%7==0 then
                        last=New(_editor_class["祢津终符光效"],self.x,self.y,ran:Float(1,2),ran:Float(0,360),COLOR_PURPLE)
                    else
                    end
                    task._Wait(1)
                end end
            end)
            task.New(self,function()
                self.bound=false
                do local a,_d_a=(45),(72) for _=1,5 do
                    last=New(_editor_class["祢津终符白激光:Lunatic"],self.x,self.y,sign(self.x),a)
                    _connect(self,last,0,true)
                    task._Wait(0)
                a=a+_d_a end end
                task._Wait(120)
                self.bound=true
            end)
            task.New(self,function()
                local a = 90+90*sign(self.x)
                do for _=1,_infinite do
                    do for _=1,6 do
                        do local b,_d_b=(0),(90) for _=1,4 do
                            last=New(_editor_class["祢津三符鳞弹"],self.x+50*cos(a+b),self.y+20*sin(a+b),1,a+b)
                            task._Wait(0)
                        b=b+_d_b end end
                        a=a-5.3*sign(self.x)
                        PlaySound("kira00",0.1,self.x/256,false)
                        task._Wait(3)
                    end end
                    a=a-11*sign(self.x)
                    task._Wait(75)
                end end
            end)
            SetV2(self,1.5,270,false,false)
        else
        end
    end)
end
_editor_class["祢津终符光效"]=Class(bullet)
_editor_class["祢津终符光效"].init=function(self,_x,_y,v,a,c)
    bullet.init(self,ball_light,c,false,false)
    self.x,self.y=_x,_y
    self.bound=false
    self.layer=LAYER_ENEMY-1
    _object.set_color(self,"mul+add",200,255,255,255)
    self.vscale=0.75
    self.hscale=0.75
    task.New(self,function()
        self.colli=false
        do local v1,_d_v1=(v),(-v/60) local s,_d_s=(0.75),(-0.5/60) local al,_d_al=(200),(-150/60) for _=1,60 do
            SetV2(self,v,a,true,false)
            self.vscale=s
            self.hscale=s
            _object.set_color(self,"mul+add",al,255,255,255)
            task._Wait(1)
        v1=v1+_d_v1 s=s+_d_s al=al+_d_al end end
        _del(self,false)
    end)
end
_editor_class["祢津终符蓝激光:Lunatic"]=Class(laser)
_editor_class["祢津终符蓝激光:Lunatic"].init=function(self,_x,_y,a)
    laser.init(self,COLOR_BLUE,_x,_y,0,0,400,0,4,4,8)
    laser.ChangeImage(self,4)
    self.rot=a
    laser._TurnOn(self,1,false,false)
    SetV2(self,0.8,270,false,false)
    task.New(self,function()
        do for _=1,_infinite do
            local da = abs(self.y-player.y)
            if da<=32 then
                self.l2=48
                if self.timer%21==0 then
                    last=New(_straight,water_drop_dark,COLOR_BLUE,self.x+self.l2*cos(a),self.y+self.l2*sin(a),ran:Float(0.5,1),a+ran:Float(-10,10),false,0,false,true,0,false,0,0,0,false)
                else
                end
            else
                self.l2=400
            end
            task._Wait(1)
        end end
    end)
end
_editor_class["祢津终符绿激光"]=Class(laser)
_editor_class["祢津终符绿激光"].init=function(self,_x,_y,a,l)
    laser.init(self,COLOR_GREEN,_x,_y,0,0,400,0,4,4,8)
    laser.ChangeImage(self,4)
    self.rot=a
    laser._TurnOn(self,1,false,false)
    SetV2(self,1.5,270,false,false)
    task.New(self,function()
        self.l2=l
    end)
end
_editor_class["祢津终符白激光:Lunatic"]=Class(laser)
_editor_class["祢津终符白激光:Lunatic"].init=function(self,_x,_y,i,a)
    laser.init(self,COLOR_DEEP_GRAY,_x,_y,0,0,300,0,8,4,24)
    laser.ChangeImage(self,4)
    self.rot=a
    self.bound=false
    task.New(self,function()
        laser._TurnOn(self,1,false,false)
        do local a1,_d_a1=(a),(0.5*i) for _=1,_infinite do
            _set_rel_pos(self,50*cos(a1),20*sin(a1),self.rot,false)
            self.rot=a1
            local aa = a1%360
            if aa>=180 and aa<360 then
                aa=aa-360
            else
            end
            local aaa = Angle(self,player)
            local da = abs(aa-aaa)
            if da>15 and da<=30 then
                local l0 = Dist(self,player)-128
                self.l2=l0+(300-l0)*sin((da-15)*90/15)
            else
            end
            if da<=15 then
                if self.l2>0 then
                    self.l2=Dist(self,player)-128
                else
                    self.l2=0
                end
                if self.timer%6==0 then
                    last=New(_straight,water_drop_dark,COLOR_DEEP_GRAY,self.x+self.l2*cos(a1),self.y+self.l2*sin(a1),ran:Float(0.5,1),270+ran:Float(-10,10),false,0,false,true,0,false,0,0,0,false)
                else
                end
            else
            end
            task._Wait(1)
        a1=a1+_d_a1 end end
    end)
end
