            boss.dialog.sentence(self,"image:lizi_mijin_dialog2","right","小姐终于想通了吗，",180,1,1)
            boss.dialog.sentence(self,"image:lizi_mijin_dialog2","right","决定加入幻想乡搞事四人组？",180,1,1)
            boss.dialog.sentence(self,"image:lizi_marisa_dialog1","left","我只是听说博丽神社有鬼怪出没，",180,-1,1)
            boss.dialog.sentence(self,"image:lizi_marisa_dialog4","left","本来期待着很有趣的东西过来看看，",180,-1,1)
            boss.dialog.sentence(self,"image:lizi_marisa_dialog2","left","没想到是你这家伙",180,-1,1)
            boss.dialog.sentence(self,"image:lizi_mijin_dialog3","right","那，你打算回去么？",180,1,1)
            boss.dialog.sentence(self,"image:lizi_marisa_dialog3","left","我魔理沙怎么可能放过在灵梦前解决异变的机会？",180,-1,1)
            boss.dialog.sentence(self,"image:lizi_mijin_dialog6","right","祢津正在解放九尾的力量，",180,1,1)
            boss.dialog.sentence(self,"image:lizi_mijin_dialog6","right","若你真想战胜那巫女，有没有兴趣合作？",180,1,1)
            _stop_music()
            boss.dialog.sentence(self,"image:lizi_marisa_dialog3","left","嘿，那我就让你见识下，",180,-1,1)
            boss.dialog.sentence(self,"image:lizi_marisa_dialog3","left","被你瞧不起的人类魔法使的厉害！",180,-1,1)
            boss.dialog.sentence(self,"image:lizi_mijin_dialog5","right","呵，祢津遍历了鬼怪幻化术，在此，",180,1,1)
            boss.dialog.sentence(self,"image:lizi_mijin_dialog5","right","赐予你百万鬼王的恐惧！",180,1,1)
        else
        end
        if GetGlobal('player_name')=='sanae_player' then
            boss.dialog.sentence(self,"image:lizi_mijin_dialog3","right","……一定要藏好吗？",180,1,1)
            boss.dialog.sentence(self,"image:lizi_mijin_dialog2","right","我还以为尾巴是很萌的属性呢……",180,1,1)
            boss.dialog.sentence(self,"image:lizi_sanae_dialog1","left","可是侵犯人家肖像权就不好玩了呢",180,1,1)
            boss.dialog.sentence(self,"image:lizi_mijin_dialog3","right","所以还是只有你一个人过来？",180,1,1)
            boss.dialog.sentence(self,"image:lizi_sanae_dialog1","left","这种程度的异变，用不着守矢的神明出马，",180,1,1)
            boss.dialog.sentence(self,"image:lizi_sanae_dialog3","left","话说回来我也是神明啊……",180,1,1)
            boss.dialog.sentence(self,"image:lizi_mijin_dialog6","right","七夕的事多亏了守矢的信仰呢！~",180,1,1)
            boss.dialog.sentence(self,"image:lizi_sanae_dialog4","left","这次又想干什么？",180,1,1)
            boss.dialog.sentence(self,"image:lizi_sanae_dialog1","left","……狐狸真是信不过的动物",180,1,1)
            boss.dialog.sentence(self,"image:lizi_mijin_dialog1","right","祢津只是在这里研究幻化之术罢了，",180,1,1)
            boss.dialog.sentence(self,"image:lizi_mijin_dialog5","right","还是说，守矢家的神社更欢迎我带来的灵异？",180,1,1)
            _stop_music()
            boss.dialog.sentence(self,"image:lizi_sanae_dialog2","left","看来必须让你一次记住，奇迹的力量呢！",180,1,1)
            boss.dialog.sentence(self,"image:lizi_mijin_dialog5","right","呵，不再是九条族家犬的祢津，",180,1,1)
            boss.dialog.sentence(self,"image:lizi_mijin_dialog5","right","在此赐予你百万鬼王的恐惧！",180,1,1)
        else
        end
        if GetGlobal('player_name')=='wuer_player' then
            boss.dialog.sentence(self,"image:lizi_mijin_dialog3","right","为什么？明明这次连耳朵和尾巴也伪装得很好……",180,1,1)
            boss.dialog.sentence(self,"image:lizi_mijin_dialog3","right","为什么祢津被看穿了呢……",180,1,1)
            boss.dialog.sentence(self,"image:lizi_wuer_dialog1","left","因为……劳资玩过《东方魔宝城》！",180,-0.33,0.33)
            boss.dialog.sentence(self,"image:lizi_wuer_dialog5","left","就记得你是用鬼火模仿别人弹幕的唯一的人。",180,-0.33,0.33)
            boss.dialog.sentence(self,"image:lizi_mijin_dialog4","right","唔啊！",180,1,1)
            boss.dialog.sentence(self,"image:lizi_mijin_dialog4","right","原来祢津的幻术在外面世界的科技面前不值一提！",180,1,1)
            boss.dialog.sentence(self,"image:lizi_mijin_dialog2","right","太美好了！",180,1,1)
            boss.dialog.sentence(self,"image:lizi_mijin_dialog2","right","异界人，我对你越来越感兴趣了~",180,1,1)
            boss.dialog.sentence(self,"image:lizi_mijin_dialog6","right","咕唔唔唔唔~~",180,1,1)
            boss.dialog.sentence(self,"image:lizi_wuer_dialog2","left","……你脑子坏掉了吧？",180,-0.33,0.33)
            boss.dialog.sentence(self,"image:lizi_mijin_dialog1","right","恶魔祢津一直期盼着你这种人的存在！",180,1,1)
            _stop_music()
            boss.dialog.sentence(self,"image:lizi_wuer_dialog4","left","……好，我懂，接下来就是赌上封印的战斗吧？",180,-0.33,0.33)
            boss.dialog.sentence(self,"image:lizi_mijin_dialog5","right","祢津从不骗人，祢津这次被完全看透了呢~",180,1,1)
            boss.dialog.sentence(self,"image:lizi_mijin_dialog6","right","那么，赐予你百万鬼王的恐惧！！！",180,1,1)
        else
        end
        PlayMusic('龙と桜巫女',0.8)
        task.New(self,function()
            do local r,_d_r=(163),(92/60) local g,_d_g=(73),(-13/60) local b,_d_b=(164),(16/60) for _=1,61 do
                _boss.fxr=r _boss.fxg=g _boss.fxb=b
                task._Wait(1)
            r=r+_d_r g=g+_d_g b=b+_d_b end end
        end)
        boss.show_aura(self,true)
    end)
end
