_editor_class["祢津LSC激光"]=Class(laser)
_editor_class["祢津LSC激光"].init=function(self,_x,_y,i,a)
    laser.init(self,COLOR_RED,_x,_y,0,0,400,0,6,4,12)
    laser.ChangeImage(self,4)
    self.rot=a
    task.New(self,function()
        laser._TurnHalfOn(self,60,true)
        laser._TurnOn(self,30,true,true)
        do local a1,_d_a1=(a),(0.2*i) for _=1,_infinite do
            self.rot=a1
            local aa = a1%360
            if aa>=180 and aa<360 then
                aa=aa-360
            else
            end
            local aaa = -90
            local da = abs(aa-aaa)
            if da>15 and da<=75 then
                local l0 = 64+32*sin(15)
                self.l2=l0+(400-l0)*sin((da-15)*90/60)
            else
            end
            if da<=15 then
                if self.l2>0 then
                    self.l2=64+32*sin(da)
                else
                    self.l2=0
                end
            else
            end
            task._Wait(1)
        a1=a1+_d_a1 end end
    end)
end
