_editor_class["Wriggle:Normal"]=Class(boss)
_editor_class["Wriggle:Normal"].cards={}
_editor_class["Wriggle:Normal"].name="Wriggle Nightbug"
_editor_class["Wriggle:Normal"].init=function(self,cards)
    boss.init(self,-500,100,"Wriggle Nightbug",cards,New(_editor_class["XY-SCBG-LGL"]))
	self.difficulty="Normal"
	self.ani_intv=6
	for i=1,4 do self['img'..i]={} end
	self.nn={5,4,4,2}
	self.mm={1,1,1}
	for i=2,4 do self['ani'..i]=self.nn[i]-self.mm[i-1] end
	for i=1,4 do
		for j=1,self.nn[i] do
			self['img'..i][j]='anonymous:'.."XY-bossA02.png"..i..j
		end
	end
end
_editor_class["Wriggle:Normal"].bgm = "BGM-TKZ-3"
_editor_class["Wriggle:Normal"]._bg = XY_Midsummer_background
_editor_class["Wriggle:Normal"].difficulty = "Normal"
_tmp_sc=boss.card.New("",1,10,30,250,{0,50,0},false)
function _tmp_sc:init()
    task.New(self,function()
        task.MoveTo(0,120,60,MOVE_DECEL)
        last=New(_editor_class["XY-蓄力-特A"],self.x,self.y,255,255,50,1)
        task._Wait(60)
        task.New(self,function()
            do local a0,_d_a0=(0),(360/100) for _=1,_infinite do
                boss.cast(self,200)
                do for _=1,6 do
                    PlaySound("option",0.6,self.x/256,false)
                    last=New(_editor_class["XY-萤火虫C"],self.x,self.y,ball_big,ball_small,6)
                    _connect(self,last,0.2,true)
                    task._Wait(10)
                end end
                task._Wait(60)
                do local a1,_d_a1=(Angle(self,player)),(360/6) for _=1,6 do
                    _create_bullet_group(grain_a,COLOR_GREEN,self.x-10,self.y+20,3,0,2,0.5,a1,0,false,0,true,true,0,false,self)
                    task._Wait(0)
                a1=a1+_d_a1 end end
                task._Wait(60)
                task.MoveToPlayer(60,-96,96,100,120,15,30,10,20,MOVE_DECEL,MOVE_X_TOWARDS_PLAYER)
                task._Wait(20)
                task._Wait(1)
            a0=a0+_d_a0 end end
        end)
    end)
end
function _tmp_sc:del()
end
table.insert(_editor_class["Wriggle:Normal"].cards,_tmp_sc)
_tmp_sc=boss.card.New("",1,10,40,350,{75,0,0},false)
function _tmp_sc:init()
    task.New(self,function()
        task.MoveTo(0,120,60,MOVE_DECEL)
        last=New(_editor_class["XY-蓄力-特A"],self.x,self.y,255,255,50,1)
        task._Wait(60)
        task.New(self,function()
            www=100
            do local a0,_d_a0=(0),(360/100) local s1,_d_s1=(50),(15) local x,_d_x=(1),(1) for _=1,_infinite do
                boss.cast(self,200)
                do local a0,_d_a0=(90),(360*((-1)^x)/14) local a2,_d_a2=(Angle(self,player)),(450*((-1)^(x+1))/14) for _=1,15 do
                    PlaySound("option",0.6,self.x/256,false)
                    last=New(_editor_class["XY-萤火虫B1"],self.x,self.y,ball_huge,a2,a0,s1,ball_big,ball_small)
                    _connect(self,last,0.2,true)
                    task._Wait(5)
                a0=a0+_d_a0 a2=a2+_d_a2 end end
                task._Wait(ww)
                if www==0 then
                    www=0
                else
                    www=www-10
                end
                task.MoveToPlayer(60,-96,96,100,120,15,30,10,20,MOVE_DECEL,MOVE_X_TOWARDS_PLAYER)
                task._Wait(20)
                task._Wait(0)
            a0=a0+_d_a0 s1=s1+_d_s1 x=x+_d_x end end
        end)
    end)
end
function _tmp_sc:del()
end
table.insert(_editor_class["Wriggle:Normal"].cards,_tmp_sc)
table.insert(_editor_class["Wriggle:Normal"].cards,boss.move.New(0,144,60,MOVE_DECEL))
_tmp_sc=boss.dialog.New(true)
function _tmp_sc:init()
	lstg.player.dialog=true
	_dialog_can_skip=true
	self.dialog_displayer=New(dialog_displayer)
    task.New(self,function()
        boss.show_aura(self,false)
        if GetGlobal('player_name')=='reimu_player' then
            boss.dialog.sentence(self,"image:XY-face02A","right","原来是巫女啊",240)
        else
        end
        if GetGlobal('player_name')=='marisa_player' then
            boss.dialog.sentence(self,"image:XY-face02A","right","原来是魔法使啊",240)
        else
        end
        if GetGlobal('player_name')=='sanae_player' then
            boss.dialog.sentence(self,"image:XY-face02A","right","是山上的巫女吗？",240)
            boss.dialog.sentence(self,"image:XY-face02A","right","不重要了",240)
        else
        end
        if GetGlobal('player_name')=='wuer_player' then
            boss.dialog.sentence(self,"image:XY-face02A","right","你是谁啊？",240)
            boss.dialog.sentence(self,"image:XY-face02A","right","新来的妖怪吗？",240)
            boss.dialog.sentence(self,"image:XY-face02A","right","不重要了",240)
        else
        end
        boss.dialog.sentence(self,"image:XY-face02A","right","是来参加我们的宴会的吗？",240)
        boss.dialog.sentence(self,"image:XY-face02A","right","今晚大家都很开心",240)
        boss.dialog.sentence(self,"image:XY-face02A","right","要继续跟着来的话也不阻拦你了",240)
        task.MoveTo(100,350,60,MOVE_DECEL)
    end)
end
table.insert(_editor_class["Wriggle:Normal"].cards,_tmp_sc)
