	self.difficulty="Normal"
	self.ani_intv=7
	for i=1,4 do self['img'..i]={} end
	self.nn={5,6,6,6}
	self.mm={3,3,6}
	for i=2,4 do self['ani'..i]=self.nn[i]-self.mm[i-1] end
	for i=1,4 do
		for j=1,self.nn[i] do
			self['img'..i][j]='anonymous:'.."XY-bossA01.png"..i..j
		end
	end
end
_editor_class["Larva:Normal"].bgm = "BGM-TKZ-1"
_editor_class["Larva:Normal"]._bg = XY_Midsummer_background
_editor_class["Larva:Normal"].difficulty = "Normal"
_tmp_sc=boss.dialog.New(true)
function _tmp_sc:init()
	lstg.player.dialog=true
	_dialog_can_skip=true
	self.dialog_displayer=New(dialog_displayer)
    task.New(self,function()
        boss.show_aura(self,false)
        if GetGlobal('player_name')=='reimu_player' then
            boss.dialog.sentence(self,"image:【XY-灵梦01","left","靠近之后意外的没那么吵了",600)
            boss.dialog.sentence(self,"image:【XY-灵梦01","left","不过犯人不是萤火虫的话……",600)
            boss.dialog.sentence(self,"img_void","right","哎呀",600)
            task.MoveTo(0,100,60,MOVE_DECEL)
            boss.dialog.sentence(self,"image:XY-face01E","right","被巫女发现啦——",600)
            boss.dialog.sentence(self,"image:【XY-灵梦02","left","上次的妖精？",600)
            boss.dialog.sentence(self,"image:【XY-灵梦02","left","在这里吵的翻天的犯人难道就是你吗？",600)
            boss.dialog.sentence(self,"image:XY-face01D","right","犯人什么的，这是大家的夏祭啦",600)
            boss.dialog.sentence(self,"image:XY-face01D","right","力量因为背后的门原因变强了",600)
            boss.dialog.sentence(self,"image:XY-face01C","right","所以就在进行小小的庆祝游行——！",600)
            boss.dialog.sentence(self,"image:【XY-灵梦03","left","一点也不小！",600)
            boss.dialog.sentence(self,"image:【XY-灵梦04","left","而且那门，应该已经关上了才对啊",600)
            boss.dialog.sentence(self,"image:【XY-灵梦02","left","难道说……？",600)
            boss.dialog.sentence(self,"image:XY-face01C","right","塔——诺西——！！",600)
            boss.dialog.sentence(self,"image:XY-face01C","right","四——国以——！！",600)
            boss.dialog.sentence(self,"image:【XY-灵梦04","left","……暂且不管他们又在搞些什么",600)
            boss.dialog.sentence(self,"image:【XY-灵梦03","left","你现在先给我适可而止啊！",600)
        else
        end
        if GetGlobal('player_name')=='marisa_player' then
            boss.dialog.sentence(self,"image:【XY-魔理沙01","left","吵死啦——！",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙01","left","虫子这么吵根本不可能睡得着啊",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙02","left","说起来刚刚好像还看到灵梦了……",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙02","left","该不会吵到神社都能听到吧？",600)
            boss.dialog.sentence(self,"img_void","right","哎呀",600)
            task.MoveTo(0,100,60,MOVE_DECEL)
            boss.dialog.sentence(self,"image:XY-face01E","right","被发现啦——",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙02","left","凤蝶的妖精？",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙03","left","你有看到一个红白色的巫女吗？",600)
            boss.dialog.sentence(self,"image:XY-face01E","right","诶？",600)
            boss.dialog.sentence(self,"image:XY-face01E","right","巫女不是应该在神社里睡觉吗？",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙02","left","但愿是",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙03","left","话说回来，你们这是在干什么？",600)
            boss.dialog.sentence(self,"image:XY-face01C","right","因为背后的门~力量变强了！",600)
            boss.dialog.sentence(self,"image:XY-face01C","right","所以大家就办了个小小的祭典！",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙04","left","……",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙04","left","什么都感觉不到啊",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙04","left","……",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙04","left","背后哪里有门啊？",600)
            boss.dialog.sentence(self,"image:XY-face01E","right","啊咧？啊咧？",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙06","left","因为是妖精所以搞错了，这样的借口可平复不了我的心情",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙05","left","在回去睡觉之前先让你睡上三天吧DA☆ZE",600)
        else
        end
        if GetGlobal('player_name')=='sanae_player' then
            boss.dialog.sentence(self,"image:【XY-早苗01","left","好像真的是祭典啊",600)
            boss.dialog.sentence(self,"image:【XY-早苗01","left","刚才的萤火虫也是这样说的",600)
            boss.dialog.sentence(self,"img_void","right","哎呀",600)
            task.MoveTo(0,100,60,MOVE_DECEL)
            boss.dialog.sentence(self,"image:XY-face01E","right","被发现啦!",600)
            boss.dialog.sentence(self,"image:【XY-早苗02","left","第一次见到这么大的蝴蝶啊",600)
            boss.dialog.sentence(self,"image:【XY-早苗02","left","妖精吗？",600)
            boss.dialog.sentence(self,"image:【XY-早苗02","left","诶……头上有绿○虫一样的触角呢",600)
            boss.dialog.sentence(self,"image:【XY-早苗04","left","就是说是完全变态的妖精对吧！",600)
            boss.dialog.sentence(self,"image:XY-face01G","right","是凤蝶的妖精啦！",600)
            boss.dialog.sentence(self,"image:XY-face01G","right","我生气了哦！",600)
            boss.dialog.sentence(self,"image:【XY-早苗02","left","不过仔细看一看的话……",600)
            boss.dialog.sentence(self,"image:【XY-早苗02","left","你好像也是神明呢？",600)
            boss.dialog.sentence(self,"image:XY-face01D","right","大概吧？",600)
            boss.dialog.sentence(self,"image:XY-face01C","right","好像是叫……常夜神什么的",600)
            boss.dialog.sentence(self,"image:【XY-早苗03","left","那是死者之国",600)
            boss.dialog.sentence(self,"image:【XY-早苗01","left","是常世神才对吧",600)
            boss.dialog.sentence(self,"image:XY-face01C","right","也是凤蝶妖精所以没问题！",600)
            boss.dialog.sentence(self,"image:【XY-早苗03","left","不管妖精还是神啦",600)
            boss.dialog.sentence(self,"image:【XY-早苗04","left","感觉挺可疑的总之先绑回去吧",600)
        else
        end
        if GetGlobal('player_name')=='wuer_player' then
            boss.dialog.sentence(self,"image:【XY-无耳01","left","好像没什么人啊",600)
            boss.dialog.sentence(self,"image:【XY-无耳01","left","而且真的站在莉格露面前的话还是有点可怕",600)
            boss.dialog.sentence(self,"image:【XY-无耳06","left","毕竟是虫子吧……",600)
            boss.dialog.sentence(self,"img_void","right","哎呀",600)
            task.MoveTo(0,100,60,MOVE_DECEL)
            boss.dialog.sentence(self,"image:XY-face01E","right","被发现了……",600)
            boss.dialog.sentence(self,"image:【XY-无耳01","left","你是……",600)
            boss.dialog.sentence(self,"image:【XY-无耳03","left","幺蛾子！",600)
            boss.dialog.sentence(self,"image:XY-face01G","right","是凤蝶妖精！",600)
            boss.dialog.sentence(self,"image:XY-face01D","right","幺蛾子是什么啊",600)
            boss.dialog.sentence(self,"image:XY-face01D","right","不过你是生面孔啊",600)
            boss.dialog.sentence(self,"image:XY-face01D","right","也是来参加我们的宴会的吗",600)
            boss.dialog.sentence(self,"image:XY-face01D","right","不过莉格露酱不是说只邀请了虫妖怪吗 ",600)
            boss.dialog.sentence(self,"image:【XY-无耳04","left","……虫妖怪",600)
            boss.dialog.sentence(self,"image:【XY-无耳05","left","……幻想乡原来还有其他虫妖怪的吗",600)
            boss.dialog.sentence(self,"image:XY-face01C","right","不过你来参加我们的宴会也可以的哦",600)
            boss.dialog.sentence(self,"image:XY-face01C","right","大家的力量因为背后的门原因变强了",600)
            boss.dialog.sentence(self,"image:XY-face01C","right","所以就办了这个小祭典",600)
            boss.dialog.sentence(self,"image:【XY-无耳09","left","绝对不！",600)
        else
        end
        boss.show_aura(self,true)
        last=New(_editor_class["BGM真夏梦"],self.x,self.y,_)
        LoadMusicRecord("BGM-TKZ-1");_play_music("BGM-TKZ-1")
    end)
end
