function _tmp_sc:init()
    task.New(self,function()
        task.MoveTo(0,144,60,MOVE_DECEL)
        last=New(_editor_class["XY-蓄力-特A"],self.x,self.y,50,255,50,1)
        task._Wait(60)
        task.New(self,function()
            do for _=1,_infinite do
                PlaySound("kira00",0.15,self.x/256,false)
                last=New(_straight,ball_big,COLOR_GREEN,self.x,self.y,2.5,0,true,0,true,true,0,false,0,0,0,false)
                task._Wait(100)
            end end
        end)
        task.New(self,function()
            do for _=1,_infinite do
                task.MoveToPlayer(60,-96,96,112,144,15,40,20,30,MOVE_DECEL,MOVE_X_TOWARDS_PLAYER)
                do local a1,_d_a1=(360),(-350/9) for _=1,10 do
                    PlaySound("tan00",0.1,self.x/256,false)
                    _create_bullet_group(grain_a,COLOR_GREEN,self.x,self.y,6,0,2,2,270,a1,false,0,true,true,0,false,self)
                    _create_bullet_group(grain_a,COLOR_GREEN,self.x,self.y,6,0,3,3,270,a1,false,0,true,true,0,false,self)
                    task._Wait(20)
                a1=a1+_d_a1 end end
                task._Wait(0)
            end end
        end)
    end)
end
function _tmp_sc:del()
end
