                    PlaySound("boon01",1,self.x/256,false)
                    last=New(_editor_class["XY-阴阳蹴鞠-右1"],self.x,self.y,-aaa1,4,1,40,(-1)^x1)
                    task._Wait(ww)
                    task._Wait(220)
                    task._Wait(0)
                a0=a0+_d_a0 x1=x1+_d_x1 end end
                do local a0,_d_a0=(0),(360/100) local x1,_d_x1=(2),(1) for _=1,1 do
                    task._Wait(10)
                    boss.cast(self,200)
                    last=New(_editor_class["XY-蓄力-特A"],self.x,self.y,50,50,255,1)
                    last=New(_editor_class["XY-蓄力-特A"],self.x,self.y,50,100,255,-1)
