                    PlaySound("boon01",1,self.x/256,false)
                    last=New(_editor_class["XY-阴阳蹴鞠-左1"],self.x,self.y,-aaa2,4,1,40,(-1)^x1)
                    task._Wait(ww)
                    task._Wait(220)
                    task._Wait(0)
                a0=a0+_d_a0 x1=x1+_d_x1 end end
                if ww==0 then
                    ww=0
                else
                    ww=ww-50
                end
                if aaa1==10 then
                    aaa1=10
                else
                    aaa1=aaa1+2.5
                end
                if aaa2==170 then
                    aaa2=170
