            boss.dialog.sentence(self,"image:【XY-魔理沙03","right","虽然我不认识你",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙06","right","难道因为是我太善良了",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙06","right","所以大家都知道了吗?",600)
            boss.dialog.sentence(self,"image:【XY-无耳06","left","并不是",600)
            boss.dialog.sentence(self,"image:【XY-无耳06","left","而且你是小偷吧",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙04","right","真是失礼啊",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙05","right","那么，你是狗妖怪吗？",600)
            boss.dialog.sentence(self,"image:【XY-无耳04","left","？",600)
            boss.dialog.sentence(self,"image:【XY-无耳06","left","是吧",600)
            boss.dialog.sentence(self,"image:【XY-无耳05","left","不对，不是！",600)
