            boss.dialog.sentence(self,"image:【XY-魔理沙06","right","不过",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙06","right","其实你很可疑啊",600)
            last=New(_editor_class["BGM星之器"],self.x,self.y,_)
