        task._Wait(30)
        task.New(self,function()
            do for _=1,_infinite do
                boss.cast(self,200)
                do for _=1,5 do
                    PlaySound("tan00",0.1,self.x/256,false)
                    _create_bullet_group(ball_mid,COLOR_BLUE,self.x,self.y,4,0,1,4,0,0,true,0,true,true,0,false,self)
                    task._Wait(10)
                end end
                task._Wait(50)
                do local a1,_d_a1=(180),(180/49) for _=1,50 do
                    PlaySound("tan00",0.1,self.x/256,false)
                    last=New(_straight,ball_big,COLOR_BLUE,self.x+ran:Float(-30,30),self.y+ran:Float(-30,30),ran:Float(1,2),a1,false,0,true,true,0,false,0,0,0,false)
                    task._Wait(1)
                a1=a1+_d_a1 end end
                task._Wait(50)
                boss.cast(self,200)
                do for _=1,5 do
                    PlaySound("tan00",0.1,self.x/256,false)
                    _create_bullet_group(ball_mid,COLOR_BLUE,self.x,self.y,4,0,1,4,0,0,true,0,true,true,0,false,self)
                    task._Wait(10)
                end end
                task._Wait(50)
                do local vv,_d_vv=(2),(3/10) for _=1,10 do
                    PlaySound("tan00",0.1,self.x/256,false)
                    _create_bullet_group(star_small,COLOR_PURPLE,self.x,self.y,13,0,vv,vv,0,180,true,-5,true,true,0,false,self)
                    task._Wait(10)
                vv=vv+_d_vv end end
                task._Wait(0)
            end end
        end)
        task.New(self,function()
            do for _=1,_infinite do
                task.MoveToPlayer(50,-110,110,100,120,30,40,10,20,MOVE_DECEL,MOVE_X_TOWARDS_PLAYER)
                task._Wait(50)
                task._Wait(0)
            end end
        end)
    end)
end
