function _tmp_sc:init()
    task.New(self,function()
        task.MoveTo(0,120,60,MOVE_DECEL)
        last=New(_editor_class["XY-蓄力-特A"],self.x,self.y,255,255,50,1)
        task._Wait(60)
        task.New(self,function()
            do local a0,_d_a0=(0),(360/100) for _=1,_infinite do
                boss.cast(self,200)
                do local x,_d_x=(0),(180/19) local xx,_d_xx=(-150),(300/19) for _=1,20 do
                    PlaySound("option",0.6,self.x/256,false)
                    last=New(_editor_class["XY-萤火虫A"],self.x,self.y,ball_big,ball_small,4,self.x+xx,self.y-200+(200*sin(x)))
                    _connect(self,last,0.2,true)
                    task._Wait(10)
                x=x+_d_x xx=xx+_d_xx end end
                task._Wait(60)
                do local a1,_d_a1=(Angle(self,player)),(360/30) for _=1,30 do
                    _create_bullet_group(grain_a,COLOR_GREEN,self.x-10,self.y+20,6,0,3,0.5,a1,0,false,0,true,true,0,false,self)
                    task._Wait(0)
                a1=a1+_d_a1 end end
                task._Wait(60)
                task.MoveToPlayer(60,-96,96,100,120,15,30,10,20,MOVE_DECEL,MOVE_X_TOWARDS_PLAYER)
                task._Wait(20)
                boss.cast(self,200)
                do local x,_d_x=(0),(180/19) local xx,_d_xx=(150),(-300/19) for _=1,20 do
                    PlaySound("option",0.6,self.x/256,false)
                    last=New(_editor_class["XY-萤火虫A"],self.x,self.y,ball_big,ball_small,4,self.x+xx,self.y-200+(200*sin(x)))
                    _connect(self,last,0.2,true)
                    task._Wait(10)
                x=x+_d_x xx=xx+_d_xx end end
                task._Wait(60)
                do local a1,_d_a1=(Angle(self,player)),(360/30) for _=1,30 do
                    _create_bullet_group(grain_a,COLOR_GREEN,self.x-10,self.y+20,6,0,3,0.5,a1,0,false,0,true,true,0,false,self)
                    task._Wait(0)
                a1=a1+_d_a1 end end
                task._Wait(60)
                task.MoveToPlayer(60,-96,96,100,120,15,30,10,20,MOVE_DECEL,MOVE_X_TOWARDS_PLAYER)
                task._Wait(20)
                task._Wait(0)
            a0=a0+_d_a0 end end
        end)
    end)
