function _tmp_sc:init()
    last=New(_editor_class["XY-新开符-莉格露"],self.x,self.y,_)
    task.New(self,function()
        task.MoveTo(0,120,60,MOVE_DECEL)
        last=New(_editor_class["XY-蓄力-特A"],self.x,self.y,255,255,50,1)
        task._Wait(60)
        task.New(self,function()
            www=50
            PlaySound("tan00",0.1,self.x/256,false)
            do local a0,_d_a0=(0),(360/100) local s1,_d_s1=(50),(12) local x,_d_x=(1),(1) for _=1,_infinite do
                boss.cast(self,200)
                do local a0,_d_a0=(Angle(self,player)),(540*((-1)^x)/30) local a2,_d_a2=(Angle(self,player)),(540*((-1)^(x))-(180*((-1)^x))/30) for _=1,30 do
                    PlaySound("option",0.6,self.x/256,false)
                    last=New(_editor_class["XY-萤火虫B"],self.x,self.y,ball_huge,a2,a0,s1,ball_big,ball_small)
                    _connect(self,last,0.2,true)
                    task._Wait(5)
                a0=a0+_d_a0 a2=a2+_d_a2 end end
                task._Wait(ww)
                if www==0 then
                    www=0
                else
                    www=www-25
                end
                do local a1,_d_a1=(Angle(self,player)-(60/4+(60/4/2))),(60/3) for _=1,3 do
                    _create_bullet_group(ball_big,COLOR_GOLDEN_YELLOW,self.x-10,self.y+20,6,0,3,1.5,a1,0,false,0,true,true,0,false,self)
                    task._Wait(0)
                a1=a1+_d_a1 end end
                task.MoveToPlayer(60,-96,96,100,120,15,30,10,20,MOVE_DECEL,MOVE_X_TOWARDS_PLAYER)
                task._Wait(20)
                task._Wait(0)
            a0=a0+_d_a0 s1=s1+_d_s1 x=x+_d_x end end
        end)
    end)
end
