_editor_class["Reimu:Lunatic"].init=function(self,cards)
    boss.init(self,0,600,"Hakurei Reimu",cards,New(_editor_class["XY-SCBG-BLLM"]))
	self.difficulty="Lunatic"
	self.ani_intv=6
	for i=1,4 do self['img'..i]={} end
