function _tmp_sc:init()
	lstg.player.dialog=true
	_dialog_can_skip=true
	self.dialog_displayer=New(dialog_displayer)
    task.New(self,function()
        boss.show_aura(self,false)
        LoadMusicRecord("BGM-TKZ-3");_play_music("BGM-TKZ-3")
        if GetGlobal('player_name')=='marisa_player' then
            boss.dialog.sentence(self,"image:【XY-魔理沙06","left","你的败因，只有一个",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙06","left","那就是打扰了我每天9小时的睡眠时间！",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙04","left","……不过",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙04","left","刚刚确实有像是偷懒大王的人飞到这边来吧",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙04","left","难道被夜雀打败了？",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙04","left","……",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙05","left","不可能DA☆",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙05","left","一定是错觉，回去吧",600)
            boss.dialog.sentence(self,"img_void","right","你刚才说谁像是小野冢小町来着？",600)
            task.MoveTo(0,144,60,MOVE_DECEL)
            boss.dialog.sentence(self,"image:【XY-灵梦04","right","我可是很勤快的",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙03","left","哦哦",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙03","left","果然没看错",600)
            boss.dialog.sentence(self,"image:【XY-灵梦02","right","为什么魔理沙会在这里啊",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙06","left","当然是被吵醒的啊",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙04","left","倒是你为什么会大半夜出现在这",600)
            boss.dialog.sentence(self,"image:【XY-灵梦06","right","当然是被吵醒的啊",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙04","left","能从西边的森林吵到东边的神社……",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙04","left","这怎么说也不可能吧",600)
            boss.dialog.sentence(self,"image:【XY-灵梦07","right","虽然是很可疑……",600)
            boss.dialog.sentence(self,"image:【XY-灵梦07","right","我只是听到这边传来了声音然后睡不着觉了而已",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙05","left","现在声音已经停下了",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙05","left","就是说……可以睡觉了☆",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙06","left","每天10小时的睡眠时间是很宝贵的",600)
            boss.dialog.sentence(self,"image:【XY-灵梦02","right","你的生活作息才没那么健康！",600)
            boss.dialog.sentence(self,"image:【XY-灵梦02","right","特地跑一趟结果还被你抢了功",600)
            boss.dialog.sentence(self,"image:【XY-灵梦03","right","我被吵醒的郁闷心情又该怎么办啊！",600)
            _stop_music()
            boss.dialog.sentence(self,"image:【XY-魔理沙03","left","那就，还是那个嘛",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙03","left","例行的那个",600)
            last=New(_editor_class["BGM少女绮想曲"],self.x,self.y,_)
            LoadMusicRecord("BGM-LM-1");_play_music("BGM-LM-1")
            boss.show_aura(self,true)
            boss.dialog.sentence(self,"image:【XY-灵梦09","right","今天你倒是挺亲切的嘛",600)
            boss.dialog.sentence(self,"image:【XY-灵梦01","right","我可没想过要手下留情哦？",600)
            boss.dialog.sentence(self,"image:【XY-魔理沙04","left","这好像是我的台词啊",600)
        else
        end
        if GetGlobal('player_name')=='sanae_player' then
            boss.dialog.sentence(self,"image:【XY-早苗04","left","怎么样胖虎混蛋！",600)
            boss.dialog.sentence(self,"image:【XY-早苗08","left","……啊",600)
            boss.dialog.sentence(self,"image:【XY-早苗08","left","好像我也太吵了",600)
            boss.dialog.sentence(self,"image:【XY-早苗08","left","虽然让她逃了……",600)
            boss.dialog.sentence(self,"image:【XY-早苗01","left","……嗯",600)
            boss.dialog.sentence(self,"image:【XY-早苗01","left","差不多该回去了吧",600)
            boss.dialog.sentence(self,"img_void","right","等等！",600)
            task.MoveTo(0,144,60,MOVE_DECEL)
            boss.dialog.sentence(self,"image:【XY-灵梦03","right","为什么你会在这里啊！",600)
            boss.dialog.sentence(self,"image:【XY-早苗02","left","啊，灵梦小姐",600)
            boss.dialog.sentence(self,"image:【XY-早苗02","left","我是看到这边有异常的骚动所以来看一下情况",600)
            boss.dialog.sentence(self,"image:【XY-早苗03","left","还顺便退治了妖怪哦",600)
            boss.dialog.sentence(self,"image:【XY-灵梦08","right","啊啊，是啊",600)
            boss.dialog.sentence(self,"image:【XY-灵梦08","right","我也是听到了吵吵闹闹的声音才过来的",600)
            boss.dialog.sentence(self,"image:【XY-灵梦08","right","拜此所赐觉都睡不了了",600)
            boss.dialog.sentence(self,"image:【XY-早苗02","left","是这样吗？",600)
            boss.dialog.sentence(self,"image:【XY-早苗02","left","但是这里距离博丽神社，可是相当的远啊？",600)
            boss.dialog.sentence(self,"image:【XY-灵梦07","right","嗯……确实很可疑啊",600)
            boss.dialog.sentence(self,"image:【XY-灵梦07","right","而且好像那个异变的影响还残留着……",600)
            boss.dialog.sentence(self,"image:【XY-早苗03","left","是在说季节异变的事情吧",600)
            _stop_music()
            boss.dialog.sentence(self,"image:【XY-早苗03","left","虽然挺壮观的不过最后没什么问题的吧？",600)
            boss.dialog.sentence(self,"image:【XY-灵梦08","right","啊啊，确实已经解决了",600)
            boss.dialog.sentence(self,"image:【XY-灵梦09","right","……",600)
            last=New(_editor_class["BGM少女绮想曲"],self.x,self.y,_)
            LoadMusicRecord("BGM-LM-1");_play_music("BGM-LM-1")
            boss.show_aura(self,true)
            boss.dialog.sentence(self,"image:【XY-灵梦04","right","不过这次守矢神社居然没有任何行动",600)
            boss.dialog.sentence(self,"image:【XY-灵梦04","right","你刚才的话也很可疑",600)
            boss.dialog.sentence(self,"image:【XY-灵梦03","right","给我从实招来！“又是守矢”吗？",600)
            boss.dialog.sentence(self,"image:【XY-早苗09","left","诶诶——",600)
            boss.dialog.sentence(self,"image:【XY-早苗09","left","真不讲理——",600)
        else
        end
    end)
end
