_editor_class["qxs_enm01"]=Class(enemy)
_editor_class["qxs_enm01"].init=function(self,_x,_y,st,num)
    enemy.init(self,st,7,false,true,false)
    self.x,self.y=_x,_y
    self.drop={0,2,2}
    task.New(self,function() self.protect=true task.Wait(1) self.protect=false end)
    self.colli=false
    self.x3d=self.x
    self.y3d=self.y-224
    task.New(self,function()
        self.colli=false
        do local tr,_d_tr=(0),(255/59) local z,_d_z=(0),(3) for _=1,60 do
            self.x=self.x3d*90/(270-z)
            self.y=self.y3d*90/(270-z)+224
            self.hscale=90/(270-z)
            self.vscale=self.hscale
            _object.set_color(self,"",tr,255,255,255)
            task._Wait(1)
        tr=tr+_d_tr z=z+_d_z end end
        self.colli=true
        task._Wait(9)
        PlaySound("tan00",0.1,self.x/256,false)
        if st == 23 then
            do local a2,_d_a2=(ran:Sign()*90),(0) local a,_d_a=(ran:Float(0,360)),(360/num) for _=1,num do
                do local v2,_d_v2=(1.5),(0.5) for _=1,2+(num-3)/2 do
                    last=New(_editor_class["qxs_enm01-decel"],self.x,self.y,1.5,a,v2,a2,23)
                v2=v2+_d_v2 end end
                task._Wait(0)
            a2=a2+_d_a2 a=a+_d_a end end
        else
            do local v,_d_v=(1),(0.5) for _=1,num do
                last=New(_editor_class["qxs_enm01-decel"],self.x,self.y,v,Angle(self,player),0,0,26)
            v=v+_d_v end end
        end
        task._Wait(69)
        _set_a(self,0.02,Angle(self,player)+ran:Float(-15,15),false)
    end)
end
_editor_class["qxs_enm01-decel"]=Class(bullet)
_editor_class["qxs_enm01-decel"].init=function(self,_x,_y,v,angle,v2,a2,mod)
    bullet.init(self,butterfly,COLOR_PURPLE,true,true)
    self.x,self.y=_x,_y
    if mod == 23 then
        task.New(self,function()
            do local aa,_d_aa=(angle),(a2/45) for _=1,46 do
                SetV2(self,v,aa,true,false)
                task._Wait(1)
            aa=aa+_d_aa end end
            SetV2(self,v2,angle+a2,true,false)
        end)
    else
        _object.set_color(self,"mul+add",255,255,255,255)
        task.New(self,function()
            do local vv,_d_vv=(7),((v-7)/30) for _=1,31 do
                SetV2(self,vv,angle,true,false)
                task._Wait(1)
            vv=vv+_d_vv end end
        end)
    end
end
