_editor_class["qxs_sc0-shift"]=Class(bullet)
_editor_class["qxs_sc0-shift"].init=function(self,_x,_y,v,angle,co,a2)
    bullet.init(self,arrow_big,co,true,true)
    self.x,self.y=_x,_y
    local dis = 0
    local a = angle
    self.navi=true
    task.New(self,function()
        do for _=1,30 do
            dis = dis + v
            task._Wait(1)
        end end
        ChangeBulletImage(self,arrow_big,COLOR_GRAY)
        do for _=1,2 do
            do local vv,_d_vv=(v),(-v/29) for _=1,30 do
                dis = dis + vv
                task._Wait(1)
            vv=vv+_d_vv end end
            do local vv,_d_vv=(0),(v/44) local aa,_d_aa=(a),(a2/44) for _=1,45 do
                dis=dis+vv
                a = aa
                task._Wait(1)
            vv=vv+_d_vv aa=aa+_d_aa end end
            do for _=1,15 do
                dis = dis + v
                task._Wait(1)
            end end
            task._Wait(0)
        end end
        ChangeBulletImage(self,arrow_big,co)
        do for _=1,_infinite do
            dis = dis + v
            task._Wait(1)
        end end
    end)
    task.New(self,function()
        do for _=1,_infinite do
            _set_rel_pos(self,dis*cos(a),dis*sin(a),self.rot,false)
            task._Wait(1)
        end end
    end)
end
