            task._Wait(1)
        v=v+_d_v a=a+_d_a end end
        do local v,_d_v=(v0),(v0/21) local a,_d_a=(a0+120),(-12) for _=1,21 do
            PlaySound("tan00",0.1,self.x/256,false)
