            boss.dialog.sentence(self,"image:qxs_dialog_reimu_sm","left","对，是我。",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_cm","right","你来了。",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_reimu_em","left","我来了。",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_no","right","终于敢直面自己内心的恐惧了吗？",300,1,1)
