            boss.dialog.sentence(self,"image:qxs_dialog_cm","right","想试着这样说说而已。",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_reimu_sm","left","我家的镜子总是出现一些奇怪的影像，你有头绪吗？",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_cm","right","是我搞的。",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_reimu_an","left","...你果然是傻的。",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_ce","right","你来到这里，就没有感觉到一些异样吗？",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_reimu_em","left","没有，你干什么了？",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_cm","right","你可还记得那个叫雷鼓的付丧神？",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_cm","right","前些日子我向她学习了从外界获取力量的方法。",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_reimu_sm","left","是这样啊。魔镜从外界得到了强大的魔力，以为可以挑战巫女。",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_reimu_an","left","看你不顺眼很久了。",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_reimu_an","left","正好趁此机会，让你明白在这个幻想乡谁才是管事的。",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_no","right","有话就不能好好说吗...",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_reimu_an","left","接招！",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_an","right","果然在幻想乡，一定要在战斗后才可以交流！",300,1,1)
        else
        end
        if GetGlobal('player_name')=='marisa_player' then
            boss.dialog.sentence(self,"image:qxs_dialog_marisa_no","left","你总算出现了",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_marisa_no","left","我家的镜子啊...",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_no","right","终于敢直面自己内心的恐惧了吗？",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_marisa_cm","left","...",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_marisa_em","left","搞什么啊。",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_cm","right","想试着这样说说而已。",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_marisa_em","left","我懂。我也有过这样的时期呢。",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_marisa_no","left","可以解释一下我家镜子里面出现的奇怪影像吗？",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_no","right","这个嘛，你还记得那个叫雷鼓的付丧神吗？",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_cm","right","前些日子我向她学习了从外界获取力量的方法。",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_ce","right","得益于这份力量，连胸也变大了。",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_marisa_bm","left","不要一副洋洋得意的样子啊。",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_no","right","然后我小小地试验了下获得的力量。",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_no","right","你家的镜子也是实验地点之一。",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_marisa_an","left","...",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_marisa_an","left","觉悟吧！",300,1,1)
        else
        end
        if GetGlobal('player_name')=='sanae_player' then
            boss.dialog.sentence(self,"image:qxs_dialog_sanae_!","left","你就是上次见到的付丧神吧。",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_sanae_nt","left","那么快点。",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_cm","right","你想干啥，突然跑到我家来还说一些莫名其妙的话。",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_sanae_em","left","你做了什么自己心中有数啦。",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_cm","right","我心中没有数啊",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_sanae_an","left","捉弄魔理沙也就算了",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_sanae_ao","left","好死不死，乱弄我家神明的八咫镜，还装傻",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_an","right","喂喂  那真的不是我搞的啊",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_sanae_nt","left","不过我早就想修理你一顿了，这个机会正好～",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_an","right","你执意要这么认为的话",300,1,1)
            boss.dialog.sentence(self,"image:qxs_dialog_an","right","那就在你身上试试这份新的力量吧！",300,1,1)
        else
        end
