_tmp_sc=boss.card.New("[Monocular Miracle]",1,1,100,4000,{0,0,150},true)
function _tmp_sc:init()
    boss.show_aura(self,true)
    _boss.pp = 0
    last=New(_editor_class["qxs_KageFace"],64,0,0.3,-160)
    last=New(_editor_class["qxs_scbgface"],0,0,_)
    _connect(self,last,0,true)
    task.New(self,function()
        task.MoveTo(0,48,90,MOVE_DECEL)
        self.colli=true
        --[[ 1p --]]
        task._Wait(30)
        New(boss_cast_ef,self.x,self.y)
        task._Wait(60)
        _boss.pp = 1
        do local vy,_d_vy=(0),(144) for _=1,3 do
            do local xx,_d_xx=(-168),(336) for _=1,2 do
                last=New(_editor_class["qxs_sc7-mirror1"],xx,128-vy%384,18)
                _connect(self,last,0,true)
            xx=xx+_d_xx end end
            task._Wait(200)
        vy=vy+_d_vy end end
        task.New(self,function()
            --[[ 2p --]]
            New(boss_cast_ef,self.x,self.y)
            task._Wait(60)
            _boss.pp = 2
            task.New(self,function()
                do local da,_d_da=(0),(0.65) for _=1,_infinite do
                    _boss.da=30*sin(da)
                    task._Wait(1)
                da=da+_d_da end end
            end)
            local ct = {COLOR_RED,COLOR_PURPLE,COLOR_BLUE,COLOR_CYAN,COLOR_GREEN,COLOR_YELLOW}
            task._Wait(60)
            do local idx,_d_idx=(0),(1) for _=1,_infinite do
                do local fa1,_d_fa1=(0),(1) local fa2,_d_fa2=(8),(-1) local v,_d_v=(2),(-0.12) for _=1,9 do
                    PlaySound("kira00",0.1,self.x/256,false)
                    last=New(_editor_class["qxs_sc7-leap"],self.x,self.y,v,-90+10*min(fa1,fa2),ct[idx%6+1],8)
                    last=New(_editor_class["qxs_sc7-leap"],self.x,self.y,v,-90-10*min(fa1,fa2),ct[idx%6+1],8)
                    task._Wait(4)
                fa1=fa1+_d_fa1 fa2=fa2+_d_fa2 v=v+_d_v end end
                task._Wait(45)
            idx=idx+_d_idx end end
        end)
        task.New(self,function()
            do for _=1,_infinite do
                if self.hp<1800 or self.timer > 3600 or _boss.pp == 3 then break end
                task._Wait(1)
            end end
            _boss.pp = 3
            New(boss_cast_ef,self.x,self.y)
            task._Wait(60)
            --[[ 4p --]]
            do local a,_d_a=(0),(5) for _=1,_infinite do
                do local xx,_d_xx=(76*cos(a)-116),(232) for _=1,2 do
                    last=New(_editor_class["qxs_sc7-wave"],xx,349,_)
                xx=xx+_d_xx end end
                task._Wait(3)
            a=a+_d_a end end
        end)
    end)
end
