                    last=New(_editor_class["qxs_sc2-reimu-drop"],self.x,self.y,v,-90,COLOR_GRAY)
                v=v+_d_v end end
                if true then break end
            else
            end
            if abs(self.x)>192 then
                do local v,_d_v=(1/2),(2/num) for _=1,num do
                    last=New(_editor_class["qxs_sc2-reimu-drop"],self.x,self.y,v,90+90*sign(self.x),COLOR_GRAY)
