        self.hp=900
        self.maxhp=self.hp
        task.New(self,function()
            task._Wait(60)
            do for _=1,_infinite do
                if player.death>0 then
                    task._Wait(30)
                else
                    PlaySound("tan00",0.1,self.x/256,false)
                    do local a,_d_a=(ran:Float(0,360)),(360/(24+12*luna)) for _=1,30+18*luna do
                        do local v,_d_v=(3),(0.5) for _=1,3+luna do
                            last=New(_straight,square,COLOR_GRAY,self.x,self.y,v,a,false,0,true,true,0,false,0,0,0,false)
                        v=v+_d_v end end
                    a=a+_d_a end end
                    do local a0,_d_a0=(ran:Float(0,360)),(2) local v,_d_v=(1.5),(0.1) for _=1,3+luna*2 do
                        do local aa,_d_aa=(a0),(360/(24+12*luna)) for _=1,24+12*luna do
                            last=New(_straight,square,COLOR_RED,self.x,self.y,v,aa,false,0,true,true,0,false,0,0,0,false)
                        aa=aa+_d_aa end end
                    a0=a0+_d_a0 v=v+_d_v end end
                    task._Wait(180)
                end
                task._Wait(0)
            end end
        end)
        task.New(self,function()
            task._Wait(60)
            do local a,_d_a=(ran:Float(0,360)),(45) for _=1,_infinite do
                if player.death>0 then
                else
                    do local aa,_d_aa=(a),(5) for _=1,3+2*luna do
                        PlaySound("tan00",0.1,self.x/256,false)
                        do local v,_d_v=(3),(1) for _=1,5 do
                            last=New(_editor_class["qxs_sc6-reimu-shoot"],self.x,self.y,v,aa)
                        v=v+_d_v end end
                        task._Wait(0)
                    aa=aa+_d_aa end end
                end
                task._Wait(45-15*luna)
            a=a+_d_a end end
        end)
    else
    end
    if GetGlobal('player_name')=='sanae_player' then
        self.hp=1200
        self.maxhp=self.hp
        task.New(self,function()
            task._Wait(60)
            do for _=1,_infinite do
                local ll = 150+30*luna
                local ix = self.x+ll*sin(18)
                local iy = self.y+(ll*sin(18))/tan(36)
                local a0 = Angle(self,player)
                local w = 120
                do local ia,_d_ia=(-144),(144) for _=1,5 do
                    do local va,_d_va=(-30),(-120/(9+9*luna-1)) for _=1,9+9*luna do
                        PlaySound("tan00",0.05,self.x/256,false)
