                            last=New(_editor_class["qxs_sc6-sanae-star"],ix,iy,1.05+0.3*luna,a1,ia+va,w,ball_small)
                        a1=a1+_d_a1 end end
                        ix=ix+((150+30*luna)/(9+9*luna))*cos(ia)
                        iy=iy+((150+30*luna)/(9+9*luna))*sin(ia)
                        w=w-2+luna
                        task._Wait(2-luna)
                    va=va+_d_va end end
                    task._Wait(0)
                ia=ia+_d_ia end end
                task._Wait(210)
                do local s,_d_s=(-1),(2) for _=1,2 do
                    do local vv,_d_vv=(0),(1/10) local a,_d_a=(ran:Float(0,360)),(s*(1.8-0.6*luna)) local xx,_d_xx=(self.x),(0) local yy,_d_yy=(self.y),(0) for _=1,80+40*luna do
