                        task._Wait(1)
                    vv=vv+_d_vv a=a+_d_a xx=xx+_d_xx yy=yy+_d_yy end end
                    task._Wait(20)
                s=s+_d_s end end
                task._Wait(0)
            end end
        end)
    else
    end
    if GetGlobal('player_name')=='marisa_player' then
