_editor_class["qxs_sc6-fakepl"].frame=function(self)
    self.class.base.frame(self)
    self.x=-player.x
    self.y=-player.y
    self.rot=180
    self.hide=player.hide
    self.hpbarlen=self.hp/self.maxhp
    --img
    if not(player.time_stop) then
    	if abs(player.lr)==1 then
    		self.img=player.imgs[int(player.ani/8)%8+1]
    	elseif player.lr==-6 then
    		self.img=player.imgs[int(player.ani/8)%4+13]
    	elseif player.lr== 6 then
    		self.img=player.imgs[int(player.ani/8)%4+21]
    	elseif player.lr<0 then
    		self.img=player.imgs[7-player.lr]
    	elseif player.lr>0 then
    		self.img=player.imgs[15+player.lr]
    	end
    end
    --death
    if player.death==90 then
    	self.deathee={}
    	self.deathee[1]=New(deatheff,self.x,self.y,'first')
    	self.deathee[2]=New(deatheff,self.x,self.y,'second')
    	New(player_death_ef,self.x,self.y)
