_editor_class["qxs_sc6-reimu-shoot"]=Class(bullet)
_editor_class["qxs_sc6-reimu-shoot"].init=function(self,_x,_y,v,angle)
    bullet.init(self,square,COLOR_GRAY,true,true)
    self.x,self.y=_x,_y
    SetV2(self,v,angle,true,false)
    task.New(self,function()
        do local vv,_d_vv=(v),(-v/45) for _=1,46 do
            SetV2(self,vv,angle,true,false)
            task._Wait(1)
        vv=vv+_d_vv end end
        ChangeBulletImage(self,ball_mid,COLOR_GRAY)
        task._Wait(10)
        ChangeBulletImage(self,ball_mid,COLOR_RED)
        task._Wait(10)
        ChangeBulletImage(self,square,COLOR_RED)
        do local vv,_d_vv=(5),(-5/45) local aa,_d_aa=(Angle(self,player)),(0) for _=1,46 do
            SetV2(self,vv,aa,true,false)
            task._Wait(1)
        vv=vv+_d_vv aa=aa+_d_aa end end
        ChangeBulletImage(self,ball_mid,COLOR_RED)
        task._Wait(10)
        ChangeBulletImage(self,ball_mid,COLOR_PURPLE)
        task._Wait(10)
        ChangeBulletImage(self,square,COLOR_PURPLE)
        SetV2(self,3,Angle(self,player),true,false)
    end)
end
