    self.aa = angle
    task.New(self,function()
        do local tr,_d_tr=(72),(144/60) local va,_d_va=(0),(90/60) for _=1,61 do
            _object.set_color(self,"mul+add",tr,255,255,255)
            self.dis=210*sin(va)
            task._Wait(1)
        tr=tr+_d_tr va=va+_d_va end end
        do local dv,_d_dv=(0),(1.2/(44*100)) for _=1,_infinite do
            last=New(_straight,water_drop,COLOR_YELLOW,self.x,self.y,0,self.aa,false,0,true,true,0,false,0.08,self.aa,0,false)
