    task.New(self,function()
        do local sc,_d_sc=(0),(1/60) local tr,_d_tr=(0),(255/60) for _=1,61 do
            self.hscale=sc
            self.vscale=sc
            _object.set_color(self,"",tr,255,255,255)
            task._Wait(1)
        sc=sc+_d_sc tr=tr+_d_tr end end
        do for _=1,10 do
            do local a,_d_a=(Angle(self,player)),(360/num) for _=1,num do
                last=New(_editor_class["qxs_sc7-aimlaser"],self.x,self.y,a)
