_editor_class["qxs_sc7-leap"]=Class(bullet)
_editor_class["qxs_sc7-leap"].init=function(self,_x,_y,v,angle,co,slice)
    bullet.init(self,qxs_glow,co,true,false)
    self.x,self.y=_x,_y
    if IsValid(_boss) then
        if _boss.timer>5400 then
            ChangeBulletImage(self,ball_light,co)
        else
            self.timer=11
        end
    else
    end
    self.trans=255
    self.bound=false
    do local va,_d_va=(720/slice),(720/slice) for _=1,slice/2-1 do
        last=New(_editor_class["qxs_sc7-leapsvt"],self.x,self.y,self,co,va,1)
    va=va+_d_va end end
    do local va,_d_va=(360/slice),(720/slice) for _=1,slice/2 do
        last=New(_editor_class["qxs_sc7-leapsvt"],self.x,self.y,self,co,va,-1)
    va=va+_d_va end end
    task.New(self,function()
        do for _=1,_infinite do
            if IsValid(_boss) then
                if _boss.da then
                  SetV2(self,v,angle+_boss.da,true,false)
                end
                if Angle(_boss,self)<(-90-180/slice) or Angle(_boss,self)>(-90+180/slice) then
                    self.hscale,self.vscale=0,0
                    self.colli=false
                else
                    self.hscale,self.vscale=1,1
                    self.colli=true
                end
                self.trans=max(0,255*(cos(abs(Angle(_boss,self)+90)*90/(180/slice)))^(4/5))
                _object.set_color(self,"mul+add",self.trans,255,255,255)
            else
            end
            if not BoxCheck(self,-300,300,-300,300) then
                _del(self,false)
            else
            end
            task._Wait(1)
        end end
    end)
end
_editor_class["qxs_sc7-leapsvt"]=Class(bullet)
_editor_class["qxs_sc7-leapsvt"].init=function(self,_x,_y,mst,co,va,s)
    bullet.init(self,qxs_glow,co,true,false)
    self.x,self.y=_x,_y
    if _boss.timer>5400 then
        ChangeBulletImage(self,ball_light,co)
    else
    end
    self.mst=mst
    self.va=va
    self.bound=false
    self.s=s
    _object.set_color(self,"mul+add",195,255,255,255)
end
_editor_class["qxs_sc7-leapsvt"].frame=function(self)
    self.class.base.frame(self)
    if IsValid(self.mst) then
        self.x=Dist(self.mst.x,self.mst.y,0,48)*cos(Angle(0,48,self.mst.x,self.mst.y)+self.va)
        self.y=Dist(self.mst.x,self.mst.y,0,48)*self.s*sin(Angle(0,48,self.mst.x,self.mst.y)+self.va)+48
        self.colli=self.mst.colli
        self.hscale=self.mst.hscale
        self.vscale=self.mst.vscale
        _object.set_color(self,"mul+add",self.mst.trans,255,255,255)
    else
        _del(self,false)
    end
end
