function _tmp_sc:init()
    boss.show_aura(self,true)
    last=New(_editor_class["qxs_KageFace"],64,0,0.3,-160)
    last=New(_editor_class["qxs_scbgface"],0,0,_)
    _connect(self,last,0,true)
    self.colli=true
    task.New(self,function()
        do
            _boss.pp=4
            task.MoveTo(0,112,60,MOVE_DECEL)
            New(boss_cast_ef,self.x,self.y)
            task._Wait(60)
            task.New(self,function()
                _boss.aa=90
                do local va,_d_va=(-90),(180) local vva,_d_vva=(0),(360/18) for _=1,2 do
                    do local ix,_d_ix=(0),(360/9) for _=1,9 do
                        last=New(_editor_class["qxs_sc?-cr4"],self.x,self.y,va,ix)
                        _connect(self,last,0,true)
                    ix=ix+_d_ix end end
                va=va+_d_va vva=vva+_d_vva end end
                do local a,_d_a=(90),(-1/2) local idx,_d_idx=(0),(1) for _=1,_infinite do
                    _boss.aa=a
                    _boss.x0=60*cos(idx/3)
                    _boss.y0=60*sin(idx/3)
                    if idx%3==0 and IsValid(_boss) then
                        do local s,_d_s=(-0.8),(1.6) for _=1,2 do
                            last=New(_editor_class["qxs_sc?-laser4"],self.x,self.y,-800*cos(a)+s*120*cos(a+90)+_boss.x0,-800*sin(a)+s*140*sin(a+90)+_boss.y0,1600,8,a)
                        s=s+_d_s end end
                    else
                    end
                    task._Wait(1)
                a=a+_d_a idx=idx+_d_idx end end
            end)
        end
    end)
end
