_editor_class["qxs_sc?-laser3-1"]=Class(laser)
_editor_class["qxs_sc?-laser3-1"].init=function(self,_x,_y,mst)
    laser.init(self,COLOR_RED,_x,_y,0,0,0,0,4,4,6)
    self.ll=0
    self.bound=false
    task.New(self,function()
        laser._TurnOn(self,0,false,false)
        do for _=1,_infinite do
            self.ll=min(self.ll+4,600)
            if IsValid(mst) then
                self.x=mst.x
                self.y=mst.y
                self.rot=mst.aa+mst.da
            else
            end
            do local dd,_d_dd=(0),(4) for _=1,self.ll/4+1 do
                if Dist(player.x,player.y,self.x+dd*cos(self.rot),self.y+dd*sin(self.rot))<50 then
                    self.ll=dd
                    if self.timer%10==0 then
                        PlaySound("kira00",0.1,self.x/256,false)
                        last=New(_straight,arrow_big,COLOR_RED,self.x+dd*cos(self.rot),self.y+dd*sin(self.rot),0,self.rot,false,0,true,true,0,false,0.005,self.rot,1,false)
                    else
                    end
                    if true then break end
                else
                end
            dd=dd+_d_dd end end
            self.l2=self.ll*0.9
            self.l3=self.ll*0.1
            task._Wait(1)
        end end
    end)
end
