    self.bound=false
    self.colli=false
    self.layer=self.layer-2
    self.x3d=xx
    self.y3d=yy
    self.l3d=ll
    self.w3d=ww
    self.rot=rot
    task.New(self,function()
        do local ap,_d_ap=(0),(0.5/200) for _=1,200 do
            self.z=self.z+1
            self.x=self.x3d*100/(300-self.z)
            self.y=self.y3d*100/(300-self.z)
            self.l2=self.l3d*100/(300-self.z)
            self.w=self.w3d*100/(300-self.z)
            self.alpha=ap
            task._Wait(1)
        ap=ap+_d_ap end end
        self.alpha=1
        self.colli=true
        do for _=1,91 do
            self.z=self.z+1
            self.x=self.x3d*100/(300-self.z)
            self.y=self.y3d*100/(300-self.z)
            self.l2=self.l3d*100/(300-self.z)
            self.w=self.w3d*100/(300-self.z)
            task._Wait(1)
        end end
        _del(self,false)
    end)
end
_editor_class["qxs_sc?-laser4"].kill=function(self)
    PreserveObject(self)
    self.class=laser_death_ef
    self.group=GROUP_GHOST
    local alpha=self.alpha
    local d=self.w
    task.Clear(self)
    task.New(self,function()
    	for i=1,30 do
    		self.alpha=self.alpha-alpha/30
    		self.w=self.w-d/30
    		task.Wait()
    	end
    	Del(self)
    end)
end
