_editor_class["Karl-符卡立绘"]=Class(_object)
_editor_class["Karl-符卡立绘"].init=function(self,_x,_y,angle)
    self.x,self.y=_x,_y
	self.img="image:琪露诺立绘"
	self.layer=LAYER_ENEMY_BULLET
	self.group=7
	self.hide=false
	self.bound=false
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    _object.set_color(self,"",0,255,255,255)
    task.New(self,function()
        SetV2(self,10,angle,false,false)
        do local a,_d_a=(7),(8) for _=1,32 do
            _object.set_color(self,"",a,255,255,255)
            task._Wait(1)
        a=a+_d_a end end
        SetV2(self,0.5,angle,false,false)
        task._Wait(92)
        SetV2(self,10,angle,false,false)
        do local a,_d_a=(255),(-8) for _=1,32 do
            _object.set_color(self,"",a,255,255,255)
            task._Wait(1)
        a=a+_d_a end end
        _object.set_color(self,"",0,255,255,255)
        _del(self,true)
    end)
end
_editor_class["karl_hBlueFountainEnemy"]=Class(enemy)
_editor_class["karl_hBlueFountainEnemy"].init=function(self,_x,_y,x,y,t1,t2,t3,t4,t5,n,px,vy,avy,bi,style,hp,dpower)
    enemy.init(self,style,hp,false,true,false)
    self.x,self.y=_x,_y
    self.drop={dpower,0,0}
    task.New(self,function() self.protect=true task.Wait(1) self.protect=false end)
    task.New(self,function()
        task.BezierMoveTo(t1,MOVE_NORMAL,self.x,self.y,self.x+x,self.y+y,self.x+2*x,self.y)
        _del(self,true)
    end)
    task.New(self,function()
        task._Wait(t2)
        do for _=1,_infinite do
            task.New(self,function()
                if self.x<200 and self.x>-200 then
                    PlaySound("kira00",0.1,self.x/256,false)
                else
                end
                do local count,_d_count=(1),(1) for _=1,n do
                    local temp = count
                    bi:bullet_control("set_bullet_v",vy+avy*temp,270,true)
                    if self.x>-200 and self.x<200 then
                        last=New(_editor_class["karl_hBlueFountainEnemyBullet"],self.x,self.y-4*(n-temp),ran:Float(-px,px)*sqrt(temp),t5,bi)
                    else
                    end
                    task._Wait(t4)
                count=count+_d_count end end
            end)
            task._Wait(t3)
        end end
    end)
end
_editor_class["karl_hBlueFountainEnemyBullet"]=Class(bullet)
_editor_class["karl_hBlueFountainEnemyBullet"].init=function(self,_x,_y,px,t,bi)
    bullet.init(self,arrow_big,COLOR_CYAN,true,true)
    self.x,self.y=_x,_y
    bi:initialize_bullet(self)
    self.a=self.a+0.5
    self.b=self.b+0.5
    task.New(self,function()
        local count = 0
        do for _=1,t do
            self.x=self.x+count*count*px
            count=count+1
            task._Wait(1)
        end end
        do for _=1,_infinite do
            self.x=self.x+count*count*px
            task._Wait(1)
        end end
    end)
end
_editor_class["karl_hShadowButterfly"]=Class(enemy)
_editor_class["karl_hShadowButterfly"].init=function(self,_x,_y,style,v,a,a2,pt,pt2,pwidth,a3,bi,bi2,pt3,flag,list)
    enemy.init(self,style,150,false,true,false)
    self.x,self.y=_x,_y
    self.drop={0,6,36}
    task.New(self,function() self.protect=true task.Wait(120) self.protect=false end)
    if bi==bi2 then
        bi2=bi:copy()
    else
    end
    self.flag=true
    task.New(self,function()
        task.MoveTo(0,100,90,MOVE_DECEL)
        local b_x = self.x
        local b_y = self.y
        local l = 50
        PlaySound("kira00",0.1,self.x/256,false)
        task.MoveTo(b_x+cos(a)*l,b_y+sin(a)*l,30,MOVE_DECEL)
        local l2 = 82
        task.New(self,function()
            do for _=1,pt3 do
                l=l+(l2-l)*0.03
                task._Wait(1)
            end end
            if flag==false then
                self.flag=false
            else
            end
            do local count,_d_count=(1),(1) for _=1,_infinite do
                l=l+count*count*0.0022
                task._Wait(1)
            count=count+_d_count end end
        end)
        do for _=1,_infinite do
            self.x=b_x+cos(a)*l
            self.y=b_y+sin(a)*l
            l=l+(l2-l)*0.03
            a=a+a3
            task._Wait(1)
        end end
    end)
    task.New(self,function()
        task._Wait(150)
        local t = pt
        local t2 = pt2
        local width = pwidth
        local ng = karl_nointersection_generation.new(a+210-a2,a+210+a2,false)
        task.New(self,function()
            do for _=1,_infinite do
                ng:set_line(a+210-a2,a+210+a2)
                task._Wait(1)
            end end
        end)
        local timer = karl_float_timer:new(0)
        do for _=1,_infinite do
            ng:renew_line(width)
            PlaySound("tan01",0.1,self.x/256,false)
            local a = ng:born_position()
            if a then
                ng:insert(a-width,a+width,t)
                bi:change_property("rot",a)
                bi:bullet_control('set_bullet_v',v*1.04,a,false)
                bi2:change_property("rot",a)
                bi2:bullet_control('set_bullet_v',v,a,false)
                last=New(karl_initializer_bullet,self.x,self.y,bi,true)
                last=New(karl_initializer_bullet,self.x,self.y,bi2,true)
            else
            end
            ng:wait(t2)
            timer:wait(t2)
            if self.flag==false then
                if true then break end
            else
            end
            task._Wait(0)
        end end
    end)
    task.New(self,function()
        task._Wait(150)
        if list~=nil then
            local bi=list.bi
            do for _=1,_infinite do
                if self.flag==false then
                    if true then break end
                else
                end
                PlaySound("tan00",0.1,self.x/256,false)
                do local a1,_d_a1=(a),(360/list.n1) for _=1,list.n1 do
                    do local a2,_d_a2=(a1),(-list.da) local v,_d_v=(list.v),(-list.dv) for _=1,list.n2 do
                        local ac=karl_acc_controller.new(list.s_v)
                        ac:add_speed(list.s_t,v)
                        bi:bullet_control('acc_bullet_task',ac,a2)
                        last=New(karl_initializer_bullet,self.x,self.y,bi,true)
                    a2=a2+_d_a2 v=v+_d_v end end
                    do local a2,_d_a2=(a1+list.da),(list.da) local v,_d_v=(list.v-list.dv),(-list.dv) for _=1,list.n2-1 do
                        local ac=karl_acc_controller.new(list.s_v)
                        ac:add_speed(list.s_t,v)
                        bi:bullet_control('acc_bullet_task',ac,a2)
                        last=New(karl_initializer_bullet,self.x,self.y,bi,true)
                    a2=a2+_d_a2 v=v+_d_v end end
                a1=a1+_d_a1 end end
                task._Wait(list.w_t)
            end end
        else
        end
    end)
end
_editor_class["karl_hBallEnemy"]=Class(enemy)
_editor_class["karl_hBallEnemy"].init=function(self,_x,_y,angle,l,v1,v2,y1,lista,listb,t1,t2,l2)
    enemy.init(self,25,20,false,true,false)
    self.x,self.y=_x,_y
    self.drop={0,8,0}
    task.New(self,function() self.protect=true task.Wait(50) self.protect=false end)
    local x = self.x
    local y = self.y
    task.New(self,function()
        local ac = karl_acc_controller.new(v1)
        ac:add_speed(l/(v1+v2)*2,v2)
        local start_time = ac:get_max()
        task.New(self,function()
            task._Wait(listb.start_time)
            local shoot_bullet=function(a,ac,bi)
            	bi:change_property("rot",a)
            	bi:bullet_control("acc_bullet_task",ac)
            	last=New(karl_initializer_bullet,self.x,self.y,bi)
            end
            local w_t=listb.w_t
            local ac1=karl_acc_controller.new(listb.v1)
            ac1:add_speed(listb.t,listb.v2)
            do local count,_d_count=(ran:Int(1,4)),(1) for _=1,_infinite do
                if self.timer>listb.last_time then
                    if true then break end
                else
                end
                last=New(_editor_class["karl_hBallEnemyBullet"],self.x,self.y,listb,count)
                task._Wait(listb.w_t2)
            count=count+_d_count end end
        end)
        ac:add_speed(t1,v2)
        local change_time = ac:get_max()
        do local t,_d_t=(1),(1) for _=1,change_time do
            local length=ac:get_length(t)
            self.x=x+cos(angle)*length
            self.y=y+sin(angle)*length
            task._Wait(1)
        t=t+_d_t end end
        task.BezierMoveTo(t2,MOVE_NORMAL,self.x,self.y,self.x+cos(angle)*l2,self.y+sin(angle)*l2,player.x,y1)
        _del(self,true)
    end)
    task.New(self,function()
        local shoot_bullet=function(a)
        	lista.bi:change_property("rot",a)
        	lista.bi:bullet_control("acc_bullet_task",lista.ac)
        	last=New(karl_initializer_bullet,self.x+cos(a)*lista.l,self.y+sin(a)*lista.l,lista.bi,true)
        end
        task._Wait(lista.w_t)
        do for _=1,lista.n1 do
            PlaySound("tan00",0.1,self.x/256,false)
            do local a,_d_a=(ran:Float(0,360)),(360/lista.n2) for _=1,lista.n2 do
                shoot_bullet(a)
                shoot_bullet(a+lista.a)
            a=a+_d_a end end
            task._Wait(lista.w_t)
        end end
    end)
end
_editor_class["karl_hBallEnemyBullet"]=Class(_object)
_editor_class["karl_hBallEnemyBullet"].init=function(self,_x,_y,listb,count)
    self.x,self.y=_x,_y
	self.img="leaf"
	self.layer=LAYER_ENEMY_BULLET
	self.group=GROUP_INDES
	self.hide=true
	self.bound=true
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=false
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    task.New(self,function()
        local shoot_bullet=function(a,ac,bi)
        	bi:change_property("rot",a)
        	bi:bullet_control("acc_bullet_task",ac)
        	last=New(karl_initializer_bullet,self.x,self.y,bi)
        end
        local w_t=listb.w_t
        local ac1=karl_acc_controller.new(listb.v1)
        ac1:add_speed(listb.t,listb.v2)
        local temp=0
        if count%4<=1 then
        	temp=-listb.dv
        else
        	temp=listb.dv
        end
        local ac2=karl_acc_controller.new(listb.v1+temp)
        ac2:add_speed(listb.t,listb.v2+temp)
        PlaySound("tan01",0.1,self.x/256,false)
        local temp=Angle(self,player)
        shoot_bullet(temp,ac1,listb.bi1)
        task._Wait(w_t)
        PlaySound("tan01",0.1,self.x/256,false)
        shoot_bullet(temp+listb.da2,ac1,listb.bi1)
        shoot_bullet(temp-listb.da2,ac1,listb.bi1)
        task._Wait(w_t)
        PlaySound("tan01",0.1,self.x/256,false)
        shoot_bullet(temp+2*listb.da2,ac1,listb.bi1)
        if (count-1)%4<=1 then
            shoot_bullet(temp+listb.da,ac2,listb.bi2)
        else
            shoot_bullet(temp-listb.da,ac2,listb.bi2)
        end
        shoot_bullet(temp-2*listb.da2,ac1,listb.bi1)
        task._Wait(w_t)
        PlaySound("tan01",0.1,self.x/256,false)
        shoot_bullet(temp+listb.da2,ac1,listb.bi1)
        shoot_bullet(temp-listb.da2,ac1,listb.bi1)
        task._Wait(w_t)
        PlaySound("tan01",0.1,self.x/256,false)
        shoot_bullet(temp,ac1,listb.bi1)
        _del(self,true)
    end)
end
_editor_class["karl_hFlowerButterfly"]=Class(enemy)
_editor_class["karl_hFlowerButterfly"].init=function(self,_x,_y,x,y,t1,t2,t3,dv,list,hp)
    enemy.init(self,9,hp,false,true,false)
    self.x,self.y=_x,_y
    self.drop={15,25,0}
    task.New(self,function() self.protect=true task.Wait(30) self.protect=false end)
    task.New(self,function()
        task.MoveTo(x,y,t1,MOVE_DECEL)
        task.New(self,function()
            local da = 360/list.n2
            local a3 = da/list.n3*0.5
            local v3 = (list.v1-list.v2)/list.n3
            do local v,_d_v=(0),(list.dv) for _=1,list.n1 do
                PlaySound("kira00",0.1,self.x/256,false)
                do local a,_d_a=(list.a),(da) for _=1,list.n2 do
                    local a2 = a
                    local v2 = list.v1
                    do for _=1,list.n3 do
                        last=New(_straight,list.style,list.color,self.x+cos(a2)*list.l,self.y+sin(a2)*list.l,v2+v,a2,false,0,true,true,0,false,0,0,0,false)
                        a2=a2+a3
                        v2=v2-v3
                    end end
                    do for _=1,list.n3 do
                        last=New(_straight,list.style,list.color,self.x+cos(a2)*list.l,self.y+sin(a2)*list.l,v2+v,a2,false,0,true,true,0,false,0,0,0,false)
                        a2=a2+a3
                        v2=v2+v3
                    end end
                a=a+_d_a end end
                task._Wait(list.t)
            v=v+_d_v end end
        end)
        task._Wait(t2)
        do for _=1,t3 do
            self.vy=self.vy+dv
            task._Wait(1)
        end end
    end)
end
