_editor_class["karl_靠近会爆炸的冰块"]=Class(bullet)
_editor_class["karl_靠近会爆炸的冰块"].init=function(self,_x,_y,l,n1,n2,n3,v2,bullet_initializer)
    bullet.init(self,arrow_big,COLOR_BLUE,true,true)
    self.x,self.y=_x,_y
    bullet_initializer:initialize_bullet(self)
    bullet_task=karl_bullet_task.new()
    bullet_task:bullet_control("exist_time_task",100)
    task.New(self,function()
        do for _=1,_infinite do
            do for _=1,_infinite do
                if hypot(self.x-player.x,self.y-player.y)<l then
                    if true then break end
                else
                end
                task._Wait(1)
            end end
            PlaySound("tan00",0.1,self.x/256,false)
            local a2 = 360/n3
            task.New(self,function()
                local x = self.x+self.vx*12
                local y = self.y+self.vy*12
                do local angle,_d_angle=(ran:Float(0,360)),(a2) for _=1,n3 do
                    local n = n1+n2
                    local a3 = a2/n
                    do local count,_d_count=(0),(1) for _=1,n1 do
                        last=New(karl_acc_bullet,x,y,ball_mid,COLOR_BLUE,false,true,true,angle+a3*count,0,0,0,45,v2)
                    count=count+_d_count end end
                    do local count,_d_count=(n1),(1) for _=1,n2 do
                        last=New(karl_acc_bullet,x,y,ball_mid,COLOR_BLUE,false,true,true,angle+a3*count,0,0,0,45,v2)
                        bullet_task:set_bullet(last)
                    count=count+_d_count end end
                angle=angle+_d_angle end end
            end)
            task._Wait(90)
        end end
    end)
end
