	self.group=GROUP_ENEMY_BULLET
	self.hide=true
	self.bound=true
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=false
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    task.New(self,function()
        local shoot_bullet=function(angle)
        	bi2:bullet_control("set_bullet_v",v,angle)
        	 last=New(_editor_class["karl_冻结弹"],self.x,self.y,t2-boss.timer,bi,bi2)
        end
        shoot_bullet(a1)
        do local a,_d_a=(a2),(a2) for _=1,n-1 do
            task._Wait(t1)
            shoot_bullet(a1+a)
            shoot_bullet(a1-a)
            task._Wait(0)
        a=a+_d_a end end
        task._Wait(t3)
        shoot_bullet(a1+a3)
        shoot_bullet(a1-a3)
        _del(self,true)
    end)
end
_editor_class["karl_冰流"]=Class(bullet)
_editor_class["karl_冰流"].init=function(self,_x,_y,t,bullet_initializer,bi2,bi3,bi4)
    bullet.init(self,kite,COLOR_BLUE,true,true)
    self.x,self.y=_x,_y
    bi2:initialize_bullet(self,false)
    task.New(self,function()
        task._Wait(t)
        PlaySound("kira00",0.3,self.x/256,false)
        self.vx=0
        self.vy=0
        self.navi=false
        _set_a(self,0,0,false)
        bullet_initializer:set_bullet_style(self)
        do
            if ran:Float(0,1)<0.1 then
                local n = ran:Int(2,4)
                local x = self.x
                local y = self.y
                do for _=1,n do
                    x=x+ran:Float(-2,2)
                    y=y+ran:Float(-8,-10)
                    bi3:bullet_control("set_bullet_v",0,270)
                    last=New(_editor_class["karl_冻结弹"],x,y,0,bi4,bi3)
                end end
            else
            end
        end
        task._Wait(60)
        PlaySound("kira00",0.3,self.x/256,false)
        local a1 = (self.y+244)/488
        if a1>0 then
            a1=a1*a1*180
        else
            a1=0
        end
        if a1>30 and (self.x>192 or self.x<-192) then
            a1=30
        else
        end
        bullet_initializer:change_property("rot",270+ran:Float(-a1,a1))
        last=New(karl_initializer_bullet,self.x,self.y,bullet_initializer)
        _del(self,true)
    end)
    --[[ x方向速度绝对值<384 --]]
end
