_editor_class["karl_冷气弹"]=Class(bullet)
_editor_class["karl_冷气弹"].init=function(self,_x,_y,t,av,l,a2,v2,boss,v3)
    bullet.init(self,ball_mid_c,COLOR_GRAY,true,true)
    self.x,self.y=_x,_y
    task.New(self,function()
        task.New(self,function()
            do for _=1,_infinite do
                local d = hypot(self.x-boss.x,self.y-boss.y)
                d=math.min(255,d*5)
                _object.set_color(self,"",d,255,255,255)
                task._Wait(1)
            end end
        end)
        task._Wait(t)
        local v = 0
        do local t,_d_t=(1),(1) for _=1,_infinite do
            v=v+av
            if IsValid(boss) then
            else
                if true then break end
            end
            local d = hypot(self.x-boss.x,self.y-boss.y)
            if d<l then
                SetV2(self,v2+t*v3,Angle(self,player)+ran:Float(-a2,a2),true,false)
                if true then break end
            else
                local a=Angle(self,boss)
                self.x=self.x+cos(a)*v
                self.y=self.y+sin(a)*v
            end
            task._Wait(1)
        t=t+_d_t end end
        PlaySound("tan00",0.1,self.x/256,false)
        ChangeBulletImage(self,ball_mid_c,COLOR_GRAY)
        task._Wait(ran:Int(20,30))
        ChangeBulletImage(self,ball_mid_c,COLOR_BLUE)
    end)
end
