_tmp_sc=boss.card.New("冰符「巨大冰块呼脸」",1,1,30,1100,{0,0,0},false)
function _tmp_sc:init()
    task.New(self,function()
        last=New(_editor_class["Karl-符卡立绘"],250,40,190)
        task.MoveTo(0,144,60,MOVE_DECEL)
        New(boss_cast_ef,self.x,self.y)
        task._Wait(60)
        local a2 = 15
        local a3 = 10
        local length = 300
        task.New(self,function()
            do for _=1,_infinite do
                length=length-(length-64)*0.006
                task._Wait(1)
            end end
        end)
        task.New(self,function()
            do for _=1,_infinite do
                task.MoveToPlayer(60,-96,96,112,144,16,32,8,16,MOVE_DECEL,MOVE_X_TOWARDS_PLAYER)
                task._Wait(180)
            end end
        end)
        local bullet = karl_set.new()
        do for _=1,_infinite do
            local n=1
            while n<=bullet.n do
            	if IsValid(bullet:get(n)) then
            		n=n+1
            	else
            		bullet:delete(n)
            	end
            end
            do local y,_d_y=(254),(0) for _=1,3 do
                local v=4.5
                local x=ran:Float(-210,210)
                local rot=Angle(self,player)%360
                if rot>270+a3 or rot<90 then
                	rot=270+a3
                elseif rot>90 and rot<270-a3 then
                	rot=270-a3
                end
                rot=rot+ran:Float(-a2,a2)
                local vx2=cos(rot)*v
                local vy2=sin(rot)*v
                local flag=0
                local n=1
                while n<=bullet.n do
                	local b=bullet:get(n)
                	local dx=x-b.x
                	local dy=y-b.y
                	local vx=vx2-b.vx
                	local vy=vy2-b.vy
                	local t=(vx*vx+vy*vy)
                	if t>=0.000001 then
                		t=-(vx*dx+vy*dy)/t
                	else
                		t=55
                	end
                	if t<55 then
                		t=55
                	elseif t>140 then
                		t=140
                	end
                	local l2=hypot(dx+t*vx,dy+t*vy)
                	if l2<length then
                		flag=flag+1
                	end
                	n=n+1
                end
                if flag<=0 then
                    last=New(_straight,ball_light,COLOR_GRAY,x,y,v,rot,false,0,false,true,0,false,0,0,0,false)
                    bullet:insert(last)
                else
                end
                task._Wait(0)
            y=y+_d_y end end
            task._Wait(1)
        end end
    end)
end
function _tmp_sc:del()
end
