_tmp_sc=boss.card.New("冰符「纯白色的冰凌阵」",1,1,60,1700,{0,0,0},false)
function _tmp_sc:init()
    task.New(self,function()
        boss.show_aura(self,false)
        last=New(_editor_class["Karl-符卡立绘"],250,40,190)
        task.MoveTo(0,144,180,MOVE_NORMAL)
        task.New(self,function()
            do for _=1,_infinite do
                task.MoveTo(110,144,120,MOVE_DECEL)
                task._Wait(180)
                task.MoveTo(-110,144,120,MOVE_DECEL)
                task._Wait(180)
            end end
        end)
        task.New(self,function()
            local bullet_initializer=karl_bullet_initializer.new()
            		bullet_initializer:change_property("style",grain_b)
            		bullet_initializer:change_property("color",COLOR_GRAY)
            		bullet_initializer:change_property("bound",false)
            		bullet_initializer:set_bullet_bound(-1000,-254,1000,1000)
            local count = {1,1,4,_infinite}
            local shape_kind = 1
            local f = {}
            f[1]=function(shape,boss)
            	shape:hexagon_diamond_tessellation(50,false,{x=boss.x,y=boss.y},-222,20
            ,222,420,ran:Float(0,360))
            end

            f[2]=function(shape,boss)
            	shape:hexagon_diamond_tessellation(50,true,{x=-boss.x,y=boss.y},-222,20
            ,222,420,ran:Float(0,360))
            end

            f[3]=function(shape,boss)
            	shape:triangle_square_octagon_tessellation(45,{x=boss.x,y=boss.y},-222,40
            ,222,420,ran:Float(0,360))
            end

            f[4]=function(shape,boss)
            	shape:cirno_tessellation(42,{x=boss.x,y=boss.y},-222,0
            ,222,420,ran:Float(-3,3),20)
            end
            do for _=1,_infinite do
                task.New(self,function()
                    task._Wait(10)
                    PlaySound("kira00",0.2,self.x/256,false)
                end)
                local shape=karl_bullet_shape.new()
                f[shape_kind](shape,self)
                local shoot_bullet=function(angle,v1,v2,v,n)
                	local i=1.5
                	local x1=v1.x
                	local x2=v2.x
                	local y1=v1.y
                	local y2=v2.y
                	local v=ran:Float(1.5,3)
                	local average_y=(v1.y+v2.y)*0.5
                	while i<n-1 do
                		local x=(x1*i+x2*(n-i))/n
                		local y=(y1*i+y2*(n-i))/n
                		local controller=karl_acc_controller.new(0)
                		controller:add_speed(40+y*0.4+average_y*0.1,0)
                		controller:add_speed(10,8)
                		controller:add_speed((8-v)*1.8,v)
                		controller:add_speed(100,v)
                		controller:add_speed(90,3)
                		last=New(karl_acc_bullet_v3_shooter,x,y,bullet_initializer,-0.05*y,controller,angle+x*0.03)
                		i=i+1
                	end
                end
                do local n,_d_n=(1),(1) for _=1,shape.n do
                    local b=shape:get(n)
                    local x1=b.x
                    local y1=b.y
                    local x2=x1+b.v*cos(b.angle)
                    local y2=y1+b.v*sin(b.angle)
                    if hypot(player.x-(x1+x2)*0.5,player.y-(y1+y2)*0.5)>30 then
                        last=New(_editor_class["karl_冷气弹"],x1,y1,60,0.006,10,120,ran:Float(1,1.5),self,0.005)
                        last=New(_editor_class["karl_冷气弹"],x2,y2,60,0.006,10,120,ran:Float(1,1.5),self,0.005)
                        shoot_bullet(270,karl_2d_vector.new(x1,y1),karl_2d_vector.new(x2,y2),2,5)
                    else
                    end
                n=n+_d_n end end
                do for _=1,420 do
                    if player.death~=0 then
                        task._Wait(180)
                        if true then break end
                    else
                        task._Wait(1)
                    end
                end end
                count[shape_kind]=count[shape_kind]-1
                if count[shape_kind]<=0 then
                    shape_kind=shape_kind+1
                else
                end
                task._Wait(0)
            end end
        end)
    end)
end
function _tmp_sc:del()
end
