function _tmp_sc:init()
    task.New(self,function()
        task.MoveTo(0,144,150,MOVE_NORMAL)
        local shoot_bullet=function(angle,v1,color,t1,v,l,type)
        	l=l or 0
        	last=New(karl_acc_bullet,self.x+l*cos(angle),self.y+l*sin(angle),type,color,false,true,true,angle,0,t1,v1,30,v)
        	--_object.set_color(last,"",255,255,255,255)
        end
        task.New(self,function()
            task._Wait(240)
            do for _=1,_infinite do
                task.MoveToPlayer(60,-32,32,124,144,16,32,8,16,MOVE_DECEL,MOVE_X_TOWARDS_PLAYER)
                task._Wait(120)
            end end
        end)
        task.New(self,function()
            local a = 0
            local n1 = 24
            local n2 = 8
            local v = 3.5
            do local n,_d_n=(1),(1) for _=1,_infinite do
                do local a1,_d_a1=(a),(360/n1) local count,_d_count=(1),(1) for _=1,n1 do
                    local temp = count%n2
                    if temp<=3 and temp>3-n then
                        shoot_bullet(a1-1.2,8.2,COLOR_GRAY,3,v,0,grain_b)
                        shoot_bullet(a1,9,COLOR_BLUE,3,v,0,grain_b)
                    else
                    end
                a1=a1+_d_a1 count=count+_d_count end end
                a=a+360/n1+1.3
                task._Wait(3)
            n=n+_d_n end end
        end)
        task.New(self,function()
            task._Wait(120)
            local n1 = 15
            local v = 3
            local a = ran:Float(0,360)
            do local count,_d_count=(0),(1) for _=1,_infinite do
                if count%8<=3 then
                    PlaySound("tan01",0.1,self.x/256,false)
                    do local a1,_d_a1=(a),(360/n1) local count,_d_count=(1),(1) for _=1,n1 do
                        shoot_bullet(a1+1.1,3.5,COLOR_CYAN,3,v,70,water_drop)
                        shoot_bullet(a1,4,COLOR_BLUE,3,v,70,water_drop)
                    a1=a1+_d_a1 count=count+_d_count end end
                else
                end
                a=a-1.3
                task._Wait(4)
            count=count+_d_count end end
        end)
    end)
end
