function _tmp_sc:init()
    self.achi_graze=lstg.var.graze
    task.New(self,function()
        last=New(_editor_class["Karl-符卡立绘"],250,40,190)
        task.MoveTo(0,120,180,MOVE_NORMAL)
        task.New(self,function()
            task._Wait(180)
            do for _=1,_infinite do
                task.MoveToPlayer(60,-96,96,112,144,16,32,8,16,MOVE_DECEL,MOVE_X_TOWARDS_PLAYER)
                task._Wait(180)
            end end
        end)
        task.New(self,function()
            local shoot_bullet=function(style,a,v,t,avy,avx)
            	last=New(karl_gravity_bullet,self.x,self.y,style,COLOR_BLUE,false,false,false,true,a,0,t,v*cos(a),v*sin(a),avx,avy)
            end
            --function(self,_x,_y,style,color,highlight,stay,des,navi,angle,omiga,t,vx,vy,avx,avy,bound_pos)
            local t = 18.5
            local t2 = 1.64
            local avy = -0.025
            local v = 2.4
            local width = 0.8
            local bullet_type = {grain_b,ball_small,ball_small}
            local ng = karl_nointersection_generation.new(20,90,false)
            task.New(self,function()
                local a2 = -35
                do local a,_d_a=(0),(2.4) for _=1,_infinite do
                    local temp = 55+a2*cos(a)
                    ng:set_line(temp,temp+70)
                    task._Wait(1)
                a=a+_d_a end end
            end)
            local timer = karl_float_timer:new(0)
            do for _=1,_infinite do
                ng:renew_line(width)
                PlaySound("msl",0.3,self.x/256,false)
                local a = ng:born_position()
                if a then
                    ng:insert(a-width,a+width,t)
                    do local p,_d_p=(1.015),(-0.015) local n,_d_n=(1),(1) for _=1,3 do
                        shoot_bullet(bullet_type[n],a,v*p,0,avy*p*p,0)
                    p=p+_d_p n=n+_d_n end end
                else
                end
                ng:wait(t2)
                timer:wait(t2)
                task._Wait(0)
            end end
        end)
        task.New(self,function()
            local v1=1.3
            local v2=2.5
            local l=56
            task.New(self,function()
                task._Wait(23)
                local n = 34
                do local a,_d_a=(270),(180/n) local count,_d_count=(1),(1) for _=1,_infinite do
                    local v = ran:Float(v1,v2)
                    if count==1 then
                        v=2.2
                    else
                    end
                    PlaySound("kira00",0.01,self.x/256,false)
                    do local a2,_d_a2=(a),(360/n) for _=1,n do
                        last=New(_straight,ball_mid_c,COLOR_GRAY,self.x+l*cos(a2),self.y+l*sin(a2),v,a2,false,0,true,true,0,false,0,0,0,false)
                    a2=a2+_d_a2 end end
                    task._Wait(40)
                a=a+_d_a count=count+_d_count end end
            end)
            local n = 5
            do local count,_d_count=(1),(1) for _=1,_infinite do
                if n<6 then
                    n=n+1
                else
                end
                task.New(self,function()
                    local v=ran:Float(v1,v2)
                    if count==1 then
                    	v=1.7
                    end
                    local a=ran:Float(0,360)
                    local t=1
                    local l=50
                    local shoot_bullet=function(x,y,angle,v)
                    	last=New(karl_acc_bullet,x+cos(angle)*l,y+sin(angle)*l,ball_mid_c,COLOR_GRAY,false,true,true,angle,0,t,v,60,v)
                    end
                    local shape=karl_bullet_shape.new()
                    shape:random_group_shape(n,80,83,v)
                    local n1=shape:size()
                    local n2=10
                    do local count,_d_count=(1),(n2) for _=1,_infinite do
                        if count>n1 then
                            if true then break end
                        else
                            PlaySound("kira00",0.01,self.x/256,false)
                            shape:copy(count,count+n2-1):rotate_then_translate(a,self.x,self.y):shoot(shoot_bullet)
                        end
                        t=t+1
                        task._Wait(1)
                    count=count+_d_count end end
                    shape=nil
                end)
                task._Wait(40)
            count=count+_d_count end end
        end)
    end)
end
function _tmp_sc:del()
    if (lstg.var.sc_bonus and lstg.var.sc_bonus>0) and (lstg.var.graze-self.achi_graze>=2300) and (not ext.replay.IsReplay()) and scoredata.achi[9]~=1 then
        scoredata.achi[9]=1
        New(achievement_obj,1,9)
    else
    end
end
