_tmp_sc=boss.card.New("雪符「雪崩」",1,1,60,2300,{0,0,0},false)
function _tmp_sc:init()
    task.New(self,function()
        last=New(_editor_class["Karl-符卡立绘"],250,40,190)
        task.MoveTo(0,144,180,MOVE_NORMAL)
        local list = {t=0,x=0}
        local ac = karl_acc_controller.new(3)
        ac:add_speed(90,1)
        task.New(self,function()
            do for _=1,_infinite do
                CollisionCheck(GROUP_INDES,8)
                CollisionCheck(9,GROUP_INDES)
                task._Wait(1)
            end end
        end)
        task.New(self,function()
            task._Wait(240)
            New(boss_cast_ef,self.x,self.y)
            task._Wait(60)
            do for _=1,_infinite do
                do for _=1,3 do
                    do local a,_d_a=(Angle(self,player)+36),(36) for _=1,9 do
                        last=New(_editor_class["karl_雪炸弹"],self.x,self.y,a,5)
                    a=a+_d_a end end
                    task._Wait(3)
                end end
                task._Wait(32)
            end end
        end)
        task.New(self,function()
            do for _=1,_infinite do
                PlaySound("tan00",0.1,self.x/256,false)
                do local v,_d_v=(4.1),(0.4) for _=1,3 do
                    local ac=karl_acc_controller.new(10)
                    ac:add_speed(20,v)
                    local bi=karl_bullet_initializer.new()
                    bi:change_highlight(true)
                    bi:bullet_control("acc_bullet_task",ac)
                    last=New(_straight,grain_b,COLOR_PURPLE,self.x,self.y,v,0,true,0,true,true,0,false,0,0,0,false)
                    bi:set_bullet(last)
                    task._Wait(0)
                v=v+_d_v end end
                task._Wait(50)
            end end
        end)
        task.New(self,function()
            do for _=1,_infinite do
                list.t=list.t+1
                task._Wait(1)
            end end
        end)
        task.New(self,function()
            local t = list.t
            local n = 4
            local style = {ball_huge,ball_big,ball_mid,ball_small}
            local color = {COLOR_GRAY,COLOR_GRAY,COLOR_GRAY,COLOR_GRAY}
            local generator = karl_nointersection_generation_v2.new(-192,192,false)
            local v = 2.4
            generator:add_new_style(30,20,16,1)
            generator:add_new_style(12,8,8,1)
            generator:add_new_style(6,6,5,2)
            generator:add_new_style(3,3,2,5)
            do for _=1,_infinite do
                local b=nil
                if t>list.t then
                else
                    b=generator:go_through((list.t-t)*v)
                end
                t=list.t
                local i = 1
                do for _=1,_infinite do
                    if i<=b.n then
                        local sb=b:get(i)
                        local flag = true
                        if (sb.x>list.x-50 and sb.x<list.x+50) or ((t<200 and ran:Float(0,200)>t) and style[sb.n]~=ball_huge) then
                            flag=false
                        else
                        end
                        if flag then
                            last=New(_editor_class["karl_可被炸开的积雪"],sb.x,264-sb.y,270,v,style[sb.n],color[sb.n],list)
                        else
                        end
                        i=i+1
                    else
                        if true then break end
                    end
                end end
                task._Wait(1)
            end end
        end)
    end)
end
function _tmp_sc:del()
    for _,unit in ObjList(7) do
        _del(unit,true)
    end
    for _,unit in ObjList(8) do
        _del(unit,true)
    end
end
