                task._Wait(30)
            end end
        end)
        task.New(self,function()
            local type = {ball_small,grain_b}
            local color = {COLOR_GRAY,COLOR_GRAY}
            do for _=1,_infinite do
                PlaySound("tan00",0.1,self.x/256,false)
                do for _=1,3 do
                    do local n,_d_n=(1),(1) for _=1,2 do
                        local l = ran:Float(0,60)
                        local a = ran:Float(0,360)
                        local x = self.x+l*cos(a)
                        local y = self.y+l*sin(a)
                        local v = ran:Float(2.3,3.5)
                        do local a,_d_a=(ran:Float(0,360)),(60) for _=1,6 do
                            last=New(_straight,type[n],color[n],x,y,v,a,false,0,true,true,0,false,0,0,0,false)
                        a=a+_d_a end end
                    n=n+_d_n end end
                end end
                task._Wait(15)
            end end
        end)
        task.New(self,function()
            local v1 = 2.7
            local v2 = 0.14
            local n2 = 17
            local a2 = 1.5
            local n3 = 7
            local color = {COLOR_BLUE,COLOR_BLUE}
            do local a,_d_a=(270),(360/n2) local n,_d_n=(1),(1) for _=1,_infinite do
                if n>7 then
                    PlaySound("tan00",0.1,self.x/256,false)
                    do local a1,_d_a1=(a),(180) for _=1,2 do
                        do local a3,_d_a3=(a1-a2),(a2*2) local i,_d_i=(1),(1) for _=1,2 do
                            do local v,_d_v=(v1),(v2*2) for _=1,n3+1 do
                                last=New(_straight,grain_b,color[i],self.x,self.y,v,a3,false,0,true,true,0,false,0,0,0,false)
                            v=v+_d_v end end
                        a3=a3+_d_a3 i=i+_d_i end end
                        do local v,_d_v=(v1+v2),(v2*2) for _=1,n3 do
                            last=New(_straight,ball_small,COLOR_BLUE,self.x,self.y,v,a1,false,0,true,true,0,false,0,0,0,false)
                        v=v+_d_v end end
                    a1=a1+_d_a1 end end
                else
                end
                task._Wait(7)
            a=a+_d_a n=n+_d_n end end
        end)
    end)
