        task.Do(self)
        end,
        function(self)
        end
    )
    _spellcard_background.AddLayer(self,"image:kabi-cdbg07b",true,0,0,0,0.5,0.5,0,"",1,1,
        function(self)
        self.task={}
            _object.set_color(self,"",200,255,255,255)
        end,
        function(self)
        task.Do(self)
        end,
        function(self)
        end
    )
    _spellcard_background.AddLayer(self,"image:kabi-cdbg07a",false,0,0,0,0,0,0,"mul+add",1,1,
        function(self)
        self.task={}
        end,
        function(self)
