        end,
        function(self)
        end
    )
end
_editor_class["鵺蛇"]=Class(laser_bent)
_editor_class["鵺蛇"].init=function(self,_x,_y,a,i,col)
    laser_bent.init(self,col,_x,_y,16,8,4,1)
    a=a-30
    --[[ a决定初始角度（并不是 --]]
    --[[ i决定抖动幅度 --]]
    task.New(self,function()
        PlaySound("kira01",0.5,self.x/256,false)
        do for _=1,100 do
            do local aa,_d_aa=(a),(9*i) for _=1,11 do
                SetV2(self,4,aa,true,false)
                task._Wait(1)
            aa=aa+_d_aa end end
            do local aa,_d_aa=(a+i*90),(-9*i) for _=1,11 do
                SetV2(self,4,aa,true,false)
                task._Wait(1)
            aa=aa+_d_aa end end
            task._Wait(0)
        end end
        _del(self,true)
    end)
end
_editor_class["多边形"]=Class(_object)
_editor_class["多边形"].init=function(self,_x,_y,W,A,D,M,R,V,color)
    self.x,self.y=_x,_y
	self.img="leaf"
	self.layer=LAYER_ENEMY_BULLET
	self.group=GROUP_ENEMY_BULLET
	self.hide=false
	self.bound=true
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    --[[ W为边的数量（重复次数） --]]
    --[[ A为扩散角度。构成完整多边形则为360/n --]]
    --[[ D为对准角度 --]]
    --[[ M为子弹密度 --]]
    --[[ R为出现半径 --]]
    --[[ V为扩散速度 --]]
    _object.set_color(self,"",0,255,255,255)
    task.New(self,function()
        do local B,_d_B=(D),(360/W) for _=1,W do
            do local dx,_d_dx=(R*cos(B)),(2*R*sin(0.5*A)*sin(B-0.5*A)/(M-1)) local dy,_d_dy=(R*sin(B)),(-2*R*sin(0.5*A)*cos(B-0.5*A)/(M-1)) for _=1,M-1 do
                last=New(_straight,square,color,self.x+dx,self.y+dy,V/cos(Angle(self.x,self.y,self.x+dx,self.y+dy)-B+0.5*A),Angle(self.x,self.y,self.x+dx,self.y+dy),false,0,true,true,0,false,0,0,0,false)
                _object.set_color(last,"mul+add",255,255,255,255)
                task._Wait(0)
            dx=dx+_d_dx dy=dy+_d_dy end end
            task._Wait(0)
        B=B+_d_B end end
        _del(self,false)
    end)
end
_editor_class["鵺-罩子"]=Class(_object)
_editor_class["鵺-罩子"].init=function(self,_x,_y,_)
    self.x,self.y=_x,_y
	self.img="image:卡比--遮罩 (1)"
	self.layer=LAYER_ENEMY_BULLET-1
	self.group=GROUP_GHOST
	self.hide=false
	self.bound=true
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    _object.set_color(self,"mul+add",255,255,255,255)
    task.New(self,function()
        do local i,_d_i=(0),(1) for _=1,10 do
            self.hscale=sin(90*i/9)
            self.vscale=self.hscale
            task._Wait(1)
        i=i+_d_i end end
    end)
    task.New(self,function()
        do for _=1,_infinite do
            _set_rel_pos(self,0,0,self.rot,false)
            task._Wait(1)
        end end
    end)
    task.New(self,function()
        last=New(_editor_class["鵺-罩子边"],self.x,self.y,_)
        _connect(self,last,0,true)
        do local rr,_d_rr=(0),(7) for _=1,_infinite do
            self.rot=rr
            task._Wait(1)
        rr=rr+_d_rr end end
    end)
end
