_tmp_sc=boss.card.New("",3,15,60,600,{0,0,0},false)
function _tmp_sc:init()
    --[[ 5非 --]]
    --[[ 蓝色加速转 --]]
    task.New(self,function()
        --[[ 发弹task --]]
        --[[ 速度范围：vvv~2VVV+vvv --]]
        local VVV = 1.5
        local vvv = 0.5
        --[[ 密度 --]]
        local Times = 20
        New(boss_cast_ef,self.x,self.y)
        task._Wait(60)
        do for _=1,_infinite do
            do local JIZHUN,_d_JIZHUN=(90),(10) for _=1,3 do
                PlaySound("kira00",0.3,self.x/256,false)
                do local Ang,_d_Ang=(ran:Float(0,360)),(360/Times) for _=1,Times do
                    last=New(_straight,square,COLOR_BLUE,self.x,self.y,VVV+VVV*sin((JIZHUN-Ang)*2-90)+vvv,Ang,false,0,false,true,0,false,0,0,0,false)
                    _object.set_color(last,"mul+add",255,255,255,255)
                Ang=Ang+_d_Ang end end
                task._Wait(20)
            JIZHUN=JIZHUN+_d_JIZHUN end end
            do local JIZHUN,_d_JIZHUN=(130),(10) for _=1,5 do
                PlaySound("kira00",0.3,self.x/256,false)
                do local Ang,_d_Ang=(ran:Float(0,360)),(360/Times) for _=1,Times do
                    last=New(_straight,square,COLOR_BLUE,self.x,self.y,VVV+VVV*sin((JIZHUN-Ang)*2-90)+vvv,Ang,false,0,false,true,0,false,0,0,0,false)
                    _object.set_color(last,"mul+add",255,255,255,255)
                Ang=Ang+_d_Ang end end
                task._Wait(15)
            JIZHUN=JIZHUN+_d_JIZHUN end end
            do local JIZHUN,_d_JIZHUN=(190),(10) for _=1,8 do
                PlaySound("kira00",0.3,self.x/256,false)
                do local Ang,_d_Ang=(ran:Float(0,360)),(360/Times) for _=1,Times do
                    last=New(_straight,square,COLOR_BLUE,self.x,self.y,VVV+VVV*sin((JIZHUN-Ang)*2-90)+vvv,Ang,false,0,false,true,0,false,0,0,0,false)
                    _object.set_color(last,"mul+add",255,255,255,255)
                Ang=Ang+_d_Ang end end
                task._Wait(10)
            JIZHUN=JIZHUN+_d_JIZHUN end end
            do local JIZHUN,_d_JIZHUN=(280),(10) for _=1,27 do
                PlaySound("kira00",0.3,self.x/256,false)
                do local Ang,_d_Ang=(ran:Float(0,360)),(360/Times) for _=1,Times do
                    last=New(_straight,square,COLOR_BLUE,self.x,self.y,VVV+VVV*sin((JIZHUN-Ang)*2-90)+vvv,Ang,false,0,false,true,0,false,0,0,0,false)
                    _object.set_color(last,"mul+add",255,255,255,255)
                Ang=Ang+_d_Ang end end
                task._Wait(5)
            JIZHUN=JIZHUN+_d_JIZHUN end end
            task._Wait(60)
            New(boss_cast_ef,self.x,self.y)
            task._Wait(120)
            do local JIZHUN,_d_JIZHUN=(90),(-10) for _=1,3 do
                PlaySound("kira00",0.3,self.x/256,false)
                do local Ang,_d_Ang=(ran:Float(0,360)),(360/Times) for _=1,Times do
                    last=New(_straight,square,COLOR_BLUE,self.x,self.y,VVV+VVV*sin((JIZHUN-Ang)*2-90)+vvv,Ang,false,0,false,true,0,false,0,0,0,false)
                    _object.set_color(last,"mul+add",255,255,255,255)
                Ang=Ang+_d_Ang end end
                task._Wait(20)
            JIZHUN=JIZHUN+_d_JIZHUN end end
            do local JIZHUN,_d_JIZHUN=(50),(-10) for _=1,5 do
                PlaySound("kira00",0.3,self.x/256,false)
                do local Ang,_d_Ang=(ran:Float(0,360)),(360/Times) for _=1,Times do
