            do local dx,_d_dx=(-150-100*(k%3)/3),(100) for _=1,7 do
                do local dy,_d_dy=(225),(-8) local dh,_d_dh=(0),(3) for _=1,1 do
                    last=New(_editor_class["鵺-SC4-大玉"],dx,dy,-90,3,1,-10+dh,30,DIF)
                dy=dy+_d_dy dh=dh+_d_dh end end
            dx=dx+_d_dx end end
