    self.group=GROUP_INDES
    self.i=iiii
    self.bound=false
    task.New(self,function()
        --[[ 自旋task --]]
        do for _=1,_infinite do
            self.rot=self.rot+da
            task._Wait(1)
        end end
    end)
    task.New(self,function()
        --[[ 没啥意义的减速 --]]
        do local dvv,_d_dvv=(2*v),(-v/30) for _=1,30 do
            SetV2(self,dvv,-90,true,false)
