_editor_class["鵺-SC2-核"].frame=function(self)
    self.class.base.frame(self)
    if self.y<-250 then
        _del(self,false)
    else
    end
end
_editor_class["鵺-SC2-核"].frame=function(self)
    self.class.base.frame(self)
    --[[ 图形半径 --]]
    local R = 80
    if self.i==0 and self.flag==0 then
        self.flag=1
    else
        if self.i<13 and self.flag==0 then
            --[[ 圆 --]]
            do local daaa,_d_daaa=(0),(360/26) for _=1,26 do
                last=New(_editor_class["鵺-SC2-弹幕"],self.x,self.y,R*cos(daaa),R*sin(daaa),6)
                _connect(self,last,0,true)
            daaa=daaa+_d_daaa end end
            self.flag=2
        else
            if self.i<27 and self.flag==0 then
                task.New(self,function()
                    --[[ 方 --]]
                    do local B,_d_B=(ran:Float(0,90)),(90) for _=1,4 do
                        do local dx,_d_dx=(R*cos(B)),(2*R*sin(45)*sin(B-45)/6) local dy,_d_dy=(R*sin(B)),(-2*R*sin(0.5*90)*cos(B-0.5*90)/6) for _=1,6 do
                            last=New(_editor_class["鵺-SC2-弹幕"],self.x,self.y,dx,dy,1)
                            _connect(self,last,0,true)
                            task._Wait(0)
                        dx=dx+_d_dx dy=dy+_d_dy end end
                        task._Wait(0)
                    B=B+_d_B end end
                end)
                self.flag=2
            else
                if self.i<40 and self.flag==0 then
                    task.New(self,function()
                        --[[ 三角 --]]
                        do local B,_d_B=(ran:Float(0,120)),(120) for _=1,3 do
                            do local dx,_d_dx=(R*cos(B)),(2*R*sin(60)*sin(B-60)/8) local dy,_d_dy=(R*sin(B)),(-2*R*sin(60)*cos(B-60)/8) for _=1,8 do
                                last=New(_editor_class["鵺-SC2-弹幕"],self.x,self.y,dx,dy,7)
                                _connect(self,last,0,true)
                                task._Wait(0)
                            dx=dx+_d_dx dy=dy+_d_dy end end
                            task._Wait(0)
                        B=B+_d_B end end
                    end)
                    self.flag=2
                else
                    if self.i<49 and self.flag==0 then
                        --[[ X --]]
                        do local DIRECTION,_d_DIRECTION=(ran:Float(0,360)),(90) for _=1,4 do
                            do local dr,_d_dr=(0),(15) for _=1,8 do
                                last=New(_editor_class["鵺-SC2-弹幕"],self.x,self.y,dr*cos(DIRECTION),dr*sin(DIRECTION),14)
                                _connect(self,last,0,true)
                            dr=dr+_d_dr end end
                        DIRECTION=DIRECTION+_d_DIRECTION end end
                        self.flag=2
                    else
                        if self.i<50 and self.flag==0 then
                            --[[ 扇 --]]
                            do local DIRECTION,_d_DIRECTION=(ran:Float(0,360)),(30) for _=1,6 do
                                do local dr,_d_dr=(0),(20) for _=1,6 do
                                    last=New(_editor_class["鵺-SC2-弹幕"],self.x,self.y,dr*cos(DIRECTION),dr*sin(DIRECTION),14)
                                    _connect(self,last,0,true)
                                dr=dr+_d_dr end end
                            DIRECTION=DIRECTION+_d_DIRECTION end end
                            self.flag=2
                        else
                            if self.i<51 and self.flag==0 then
                                --[[ 双椭圆 --]]
                                do local daaa,_d_daaa=(0),(360/24) for _=1,24 do
                                    last=New(_editor_class["鵺-SC2-弹幕"],self.x,self.y,0.75*R*cos(daaa),1.5*R*sin(daaa),16)
                                    _connect(self,last,0,true)
                                daaa=daaa+_d_daaa end end
                                do local daaa,_d_daaa=(0),(360/24) for _=1,24 do
                                    last=New(_editor_class["鵺-SC2-弹幕"],self.x,self.y,1.5*R*cos(daaa),0.75*R*sin(daaa),16)
                                    _connect(self,last,0,true)
                                daaa=daaa+_d_daaa end end
                                self.flag=2
                            else
                                if self.flag==0 then
                                    --[[ 噫 --]]
                                    do for _=1,72 do
                                        last=New(_editor_class["鵺-SC2-弹幕"],self.x,self.y,ran:Float(R/2,R)*cos(ran:Float(0,360)),ran:Float(R/2,R)*sin(ran:Float(0,360)),9)
                                        _connect(self,last,0,true)
                                    end end
                                    self.flag=2
                                else
                                end
                            end
                        end
                    end
                end
            end
        end
    end
end
_editor_class["鵺-SC2-核"].colli=function(self,other)
    self.class.base.colli(self,other)
    --[[ 好想吃菠萝包。。 --]]
