_editor_class["鵺-SC2-弹幕"].init=function(self,_x,_y,xxx,yyy,color)
    bullet.init(self,star_small,color,true,false)
    self.x,self.y=_x,_y
    self.bound=false
    local dR = 150
    task.New(self,function()
        --[[ 透明度task
         --]]
        do local toumingdu,_d_toumingdu=(255/60),(255/60) for _=1,60 do
            _object.set_color(self,"",toumingdu,255,255,255)
            task._Wait(1)
        toumingdu=toumingdu+_d_toumingdu end end
    end)
    task.New(self,function()
        do local DX,_d_DX=(xxx/dR),(xxx/dR) local DY,_d_DY=(yyy/dR),(yyy/dR) local ROT,_d_ROT=(ran:Float(0,360)),(ran:Float(-1,1)) local tt,_d_tt=(0),(90/360) for _=1,360 do
            --[[ 扩大循环 --]]
            _set_rel_pos(self,sin(tt)*361*xxx/dR,sin(tt)*361*yyy/dR,ROT,true)
            task._Wait(1)
        DX=DX+_d_DX DY=DY+_d_DY ROT=ROT+_d_ROT tt=tt+_d_tt end end
        do local DX,_d_DX=(361*xxx/dR),(0) local DY,_d_DY=(361*yyy/dR),(0) local ROT,_d_ROT=(ran:Float(0,360)),(ran:Float(-1,1)) for _=1,_infinite do
            --[[ 缩圈 --]]
            _set_rel_pos(self,DX,DY,ROT,true)
            task._Wait(1)
        DX=DX+_d_DX DY=DY+_d_DY ROT=ROT+_d_ROT end end
    end)
end
