    bullet.init(self,grain_a,COLOR_CYAN,true,true)
    self.x,self.y=_x,_y
    self.rot=a
    task.New(self,function()
        do local dv,_d_dv=(v/t),(v/t) for _=1,t do
            SetV2(self,dv,a,true,false)
            task._Wait(1)
        dv=dv+_d_dv end end
    end)
end
_editor_class["鵺-SC5-子弹"]=Class(bullet)
_editor_class["鵺-SC5-子弹"].init=function(self,_x,_y,xxx,yyy)
    bullet.init(self,water_drop,COLOR_RED,true,false)
    self.x,self.y=_x,_y
    _object.set_color(self,"mul+add",255,255,255,255)
    self.xxx,self.yyy=xxx,yyy
    self.bound=false
    self.group=5
    self.R=1
    task.New(self,function()
        task._Wait(30)
        do for _=1,4 do
            do for _=1,50 do
                self.R=self.R+0.018
                task._Wait(1)
            end end
            task._Wait(50)
        end end
        task._Wait(60)
        do for _=1,180 do
            self.R=self.R+0.15
            task._Wait(1)
        end end
        do for _=1,_infinite do
            self.R=self.R+0.03
            task._Wait(1)
        end end
    end)
end
_editor_class["鵺-SC5-子弹"].frame=function(self)
    self.class.base.frame(self)
    local a = ran:Float(0,360)
    a=a+3
    local m = 2
    _set_rel_pos(self,m*cos(a)+self.R*self.xxx,self.R*self.yyy+m*sin(a),180,true)
end
_editor_class["鵺-SC5-核心"]=Class(_object)
_editor_class["鵺-SC5-核心"].init=function(self,_x,_y,dif)
    self.x,self.y=_x,_y
	self.img="leaf"
	self.layer=LAYER_ENEMY_BULLET
	self.group=GROUP_INDES
	self.hide=false
	self.bound=true
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    self.bound=false
    self.rot=Angle(self,player)
    self.i=0
    ChangeBulletImage(self,water_drop,COLOR_RED)
    _object.set_color(self,"mul+add",255,255,255,255)
    task.New(self,function()
        do local dr,_d_dr=(20),(-4) local n,_d_n=(30),(-6) local aaaa,_d_aaaa=(ran:Float(0,360)),(0) for _=1,5 do
            do local da,_d_da=(aaaa),(360/n) for _=1,n do
                last=New(_editor_class["鵺-SC5-子弹"],self.x+dr*cos(da),self.y+dr*sin(da),dr*cos(da),dr*sin(da))
                _connect(self,last,0,true)
            da=da+_d_da end end
        dr=dr+_d_dr n=n+_d_n aaaa=aaaa+_d_aaaa end end
    end)
    task.New(self,function()
        New(boss_cast_ef,self.x,self.y)
        task._Wait(30)
        do for _=1,4 do
            if dif==1 then
                _create_bullet_group(ball_mid_c,COLOR_RED,self.x,self.y,16,0,2.5,2.5,ran:Float(0,360),360,false,0,true,true,0,false,self)
                _create_bullet_group(ball_mid_c,COLOR_RED,self.x,self.y,16,0,3.5,3.5,ran:Float(0,360),360,false,0,true,true,0,false,self)
                _create_bullet_group(ball_mid_c,COLOR_RED,self.x,self.y,16,0,3,3,ran:Float(0,360),360,false,0,true,true,0,false,self)
            else
                do local dv,_d_dv=(-0.5),(0.5) for _=1,3 do
                    do local da,_d_da=(ran:Float(0,360)),(360/16) for _=1,16 do
                        last=New(_straight,ball_mid_c,COLOR_BLUE,self.x,self.y,ran:Float(2.5,3.5)+dv,da,false,0,true,true,0,false,0,0,0,false)
                    da=da+_d_da end end
                dv=dv+_d_dv end end
                do local AAA,_d_AAA=(0),(90) for _=1,4 do
                    do for _=1,36 do
                        last=New(_straight,ball_mid,COLOR_RED,self.x,self.y,ran:Float(2,4.5),ran:Float(-5,5)+AAA,true,0,true,true,0,false,0,0,0,false)
                    end end
                    do for _=1,16 do
                        last=New(_straight,ball_big,COLOR_RED,self.x,self.y,ran:Float(1.5,4),ran:Float(-5,5)+AAA,true,0,true,true,0,false,0,0,0,false)
                    end end
                    do for _=1,3 do
                        last=New(_straight,ball_huge,COLOR_RED,self.x,self.y,ran:Float(1,3.5),ran:Float(-5,5)+AAA,true,0,true,true,0,false,0,0,0,false)
                    end end
                AAA=AAA+_d_AAA end end
            end
            PlaySound("enep02",1,self.x/256,false)
            task.New(self,function()
                do for _=1,80 do
                    self.rot=self.rot+(Angle(self,player)-self.rot)/2
                    task._Wait(1)
                end end
            end)
            task.MoveTo(player.x,player.y,80,MOVE_DECEL)
            task._Wait(20)
        end end
        New(boss_cast_ef,self.x,self.y)
        task._Wait(60)
        PlaySound("enep02",1,self.x/256,false)
        if dif==1 then
            _create_bullet_group(ball_mid_c,COLOR_RED,self.x,self.y,20,0,2.75,2.75,ran:Float(0,360),360,false,0,true,true,0,false,self)
            _create_bullet_group(ball_mid_c,COLOR_RED,self.x,self.y,20,0,2.5,2.5,ran:Float(0,360),360,false,0,true,true,0,false,self)
            _create_bullet_group(ball_mid_c,COLOR_RED,self.x,self.y,20,0,3.5,3.5,ran:Float(0,360),360,false,0,true,true,0,false,self)
            _create_bullet_group(ball_mid_c,COLOR_RED,self.x,self.y,20,0,3.25,3.25,ran:Float(0,360),360,false,0,true,true,0,false,self)
            _create_bullet_group(ball_mid_c,COLOR_RED,self.x,self.y,20,0,3,3,ran:Float(0,360),360,false,0,true,true,0,false,self)
        else
            do local dv,_d_dv=(-0.5),(0.5) for _=1,3 do
                do local da,_d_da=(ran:Float(0,360)),(360/16) for _=1,16 do
                    last=New(_straight,ball_mid_c,COLOR_BLUE,self.x,self.y,ran:Float(2.5,3.5)+dv,da,false,0,true,true,0,false,0,0,0,false)
                da=da+_d_da end end
            dv=dv+_d_dv end end
            do local AAA,_d_AAA=(45),(90) for _=1,4 do
                do for _=1,36 do
                    last=New(_straight,ball_mid,COLOR_RED,self.x,self.y,ran:Float(2.5,4.5),ran:Float(-10,10)+AAA,true,0,true,true,0,false,0,0,0,false)
                end end
                do for _=1,16 do
                    last=New(_straight,ball_big,COLOR_RED,self.x,self.y,ran:Float(2,4),ran:Float(-10,10)+AAA,true,0,true,true,0,false,0,0,0,false)
                end end
                do for _=1,3 do
                    last=New(_straight,ball_huge,COLOR_RED,self.x,self.y,ran:Float(1.7,3.5),ran:Float(-10,10)+AAA,true,0,true,true,0,false,0,0,0,false)
                end end
            AAA=AAA+_d_AAA end end
        end
        do local ddd,_d_ddd=(1),(-1/50) local aaa,_d_aaa=(Angle(self,player)),(0) for _=1,800 do
            SetV2(self,1^(ddd)+0.7,aaa,false,false)
            task._Wait(1)
        ddd=ddd+_d_ddd aaa=aaa+_d_aaa end end
        _del(self,false)
    end)
end
_editor_class["鵺-SC6改-激光"]=Class(laser)
_editor_class["鵺-SC6改-激光"].init=function(self,_x,_y,Angle,id,LONGTH,XX,YY,DIFF)
    laser.init(self,COLOR_BLUE,_x,_y,0,2*LONGTH,1.2*LONGTH,2*LONGTH,8,10,0)
    self.bound=false
    local L = 5*LONGTH
    self.x,self.y,self.rot=XX+L*cos(Angle),YY+L*sin(Angle),17*Angle
    task.New(self,function()
        laser.grow(self,30,true,false)
        task._Wait(60)
        laser._TurnOn(self,60,true,true)
        local ANGLE = Angle
        task._Wait(60)
        do local tt,_d_tt=(0),(0.5) for _=1,180 do
            ANGLE=ANGLE+0.027*sin(tt)
            self.x,self.y,self.rot=XX+L*cos(ANGLE),YY+L*sin(ANGLE),17*ANGLE
            task._Wait(1)
        tt=tt+_d_tt end end
        do for _=1,_infinite do
            ANGLE=ANGLE+0.027
            self.x,self.y,self.rot=XX+L*cos(ANGLE),YY+L*sin(ANGLE),17*ANGLE
            task._Wait(1)
        end end
    end)
    task.New(self,function()
        task._Wait(120)
        if DIFF==0 then
            do for _=1,_infinite do
                do local da,_d_da=(self.rot-15),(15) for _=1,3 do
                    PlaySound("tan00",1,self.x/256,false)
                    last=New(_editor_class["鵺-SC6改-噫"],self.x,self.y,da,1,0.03,2.5)
                da=da+_d_da end end
                task._Wait(120)
            end end
        else
            do for _=1,20 do
                do local da,_d_da=(self.rot-45),(45) for _=1,3 do
                    PlaySound("tan00",1,self.x/256,false)
                    last=New(_editor_class["鵺-SC6改-噫"],self.x,self.y,da,1,0.06,2.5)
                da=da+_d_da end end
                task._Wait(120)
            end end
            do for _=1,_infinite do
                do local da,_d_da=(self.rot-45),(45) for _=1,3 do
                    PlaySound("tan00",1,self.x/256,false)
                    last=New(_editor_class["鵺-SC6改-噫"],self.x,self.y,da,1,0.06,3)
                da=da+_d_da end end
                task._Wait(90)
            end end
        end
    end)
end
