_editor_class["鵺-SC7-曲线激光"]=Class(laser_bent)
_editor_class["鵺-SC7-曲线激光"].init=function(self,_x,_y,Ang,DIF)
    laser_bent.init(self,COLOR_DEEP_GREEN,_x,_y,64,64,4,0)
    self.DIF=DIF
    self.flag=0
    task.New(self,function()
        task._Wait(30)
        self.flag=1
    end)
    task.New(self,function()
        --[[ 移动~ --]]
        if DIF==0 then
            local aaa = Angle(self,player)
            do local t,_d_t=(0),(1) for _=1,_infinite do
                SetV2(self,1.1^t,aaa,true,false)
                task._Wait(3)
            t=t+_d_t end end
        else
            do local t,_d_t=(0),(1) for _=1,20 do
                SetV2(self,1.11^t,Angle(self,player),true,false)
                task._Wait(3)
            t=t+_d_t end end
            do local t,_d_t=(21),(1) for _=1,_infinite do
                SetV2(self,1.1^t,self.rot,true,false)
                task._Wait(3)
            t=t+_d_t end end
        end
    end)
    task.New(self,function()
        --[[ 射击~ --]]
        task._Wait(10)
        local R = 7
        if DIF==0 then
            do for _=1,80 do
                do local dvvv,_d_dvvv=(1.5),(0.1) local dcol,_d_dcol=(13),(-1) local dang,_d_dang=(170),(-15) local k,_d_k=(0),(1) for _=1,5 do
                    do local aaaaaa,_d_aaaaaa=(-dang),(2*dang) for _=1,2 do
                        last=New(_editor_class["鵺-SC7-鳞片"],self.x+k*R*cos(aaaaaa+self.rot),self.y+k*R*sin(aaaaaa+self.rot),aaaaaa+self.rot,dvvv,dcol)
                    aaaaaa=aaaaaa+_d_aaaaaa end end
                dvvv=dvvv+_d_dvvv dcol=dcol+_d_dcol dang=dang+_d_dang k=k+_d_k end end
                task._Wait(4)
            end end
        else
            do for _=1,80 do
                do local dvvv,_d_dvvv=(1.5),(0.1) local dcol,_d_dcol=(13),(-1) local dang,_d_dang=(170),(-15) local k,_d_k=(0),(1) for _=1,5 do
                    do local aaaaaa,_d_aaaaaa=(-dang),(2*dang) for _=1,2 do
                        do local dv,_d_dv=(0),(0.05) for _=1,3 do
                            last=New(_editor_class["鵺-SC7-鳞片"],self.x+k*R*cos(aaaaaa+self.rot),self.y+k*R*sin(aaaaaa+self.rot),aaaaaa+self.rot,dvvv+dv,dcol)
                        dv=dv+_d_dv end end
                    aaaaaa=aaaaaa+_d_aaaaaa end end
                dvvv=dvvv+_d_dvvv dcol=dcol+_d_dcol dang=dang+_d_dang k=k+_d_k end end
                task._Wait(4)
            end end
        end
    end)
end
_editor_class["鵺-SC7-曲线激光"].frame=function(self)
    self.class.base.frame(self)
    if self.y>224 and self.flag==1 then
        last=New(_editor_class["鵺-SC7-光圈l"],self.x,self.y,self.DIF)
        self.flag=0
    else
    end
    if self.y<-224 and self.flag==1 then
        last=New(_editor_class["鵺-SC7-光圈l"],self.x,self.y,self.DIF)
