    end
    if self.x>196 and self.flag==1 then
        last=New(_editor_class["鵺-SC7-光圈l"],self.x,self.y,self.DIF)
        self.flag=0
    else
    end
    if self.x<-196 and self.flag==1 then
        last=New(_editor_class["鵺-SC7-光圈l"],self.x,self.y,self.DIF)
        self.flag=0
    else
    end
end
