    self.a,self.b=4,4
    self.timer=11
    self.flag=1
    task.New(self,function()
        do for _=1,_infinite do
            if Dist(self,player)<Range then
                if self.flag==1 then
                    PlaySound("focusfix",0.5,self.x/256,false)
                    self.flag=0
                else
                end
                ChangeBulletImage(self,ball_huge_dark,COLOR_RED)
                self.vscale,self.hscale=3.5/12,3.5/12
                self.a,self.b=4,4
            else
                if self.flag==0 then
                    self.flag=1
                else
                end
                ChangeBulletImage(self,ball_huge_dark,COLOR_BLUE)
                self.vscale,self.hscale=3.5/12,3.5/12
                self.a,self.b=4,4
            end
            task._Wait(1)
        end end
    end)
    task.New(self,function()
