                    do for _=1,300 do
                        _set_rel_pos(self,self.XX,self.YY,0,true)
                        task._Wait(1)
                    end end
                    PlaySound("lazer00",1,self.x/256,false)
                    do local dh,_d_dh=(H/90),(H/90) for _=1,90 do
                        _set_rel_pos(self,self.XX+dh*cos(angle),self.YY+dh*sin(angle),0,true)
                        task._Wait(1)
                    dh=dh+_d_dh end end
                    do for _=1,60 do
                        _set_rel_pos(self,self.XX,self.YY,0,true)
                        task._Wait(1)
                    end end
                end end
            end
        end
    end)
