        local vvv = 0.5
        --[[ 密度 --]]
        local Times = DIF
        task._Wait(1)
        do local JIZHUN,_d_JIZHUN=(90-WW*45),(240/9*WW) for _=1,_infinite do
            local AAA = ran:Float(0,360)
            PlaySound("kira00",0.3,self.x/256,false)
            do local Ang,_d_Ang=(AAA),(360/Times) for _=1,Times do
                last=New(_straight,square,COLOR_DEEP_GREEN,self.x,self.y,VVV+VVV*sin(JIZHUN-Ang)+vvv,Ang,false,0,false,true,0,false,0,0,0,false)
                _object.set_color(last,"mul+add",255,255,255,255)
            Ang=Ang+_d_Ang end end
            do local Ang,_d_Ang=(AAA+ran:Float(2,10)),(360/Times) for _=1,Times do
                last=New(_straight,square,COLOR_DEEP_GREEN,self.x,self.y,VVV+VVV*sin(JIZHUN-Ang)+vvv,Ang,false,0,false,true,0,false,0,0,0,false)
                _object.set_color(last,"mul+add",255,255,255,255)
            Ang=Ang+_d_Ang end end
            task._Wait(9)
        JIZHUN=JIZHUN+_d_JIZHUN end end
    end)
end
