_editor_class["鵺-LW"]=Class(_object)
_editor_class["鵺-LW"].init=function(self,_x,_y,ANG,DIS,WT1,WT2,COL,XX,YY,MT)
    self.x,self.y=_x,_y
	self.img="leaf"
