	self.group=GROUP_ENEMY_BULLET
	self.hide=false
	self.bound=true
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    --[[ ANG：角度
    DIS：高度
    WT1：开始收缩时间
    WT2：射出时间
    COL：颜色
    MT：移动时间 --]]
    --[[ XX,YY：中心 --]]
    self.bound=false
    local dis = 14
    --[[ dis:子弹间隔 --]]
    task.New(self,function()
        if COL==1 then
            do
                last=New(_editor_class["鵺-LW-particalR"],XX-27*dis*cos(ANG)+DIS*cos(-27*180)*sin(180-ANG),YY-27*dis*sin(ANG)+DIS*cos(-27*180)*cos(180-ANG),ANG)
                last=New(_editor_class["鵺-LW-particalR"],XX-26*dis*cos(ANG)+DIS*cos(-26*180)*sin(180-ANG),YY-26*dis*sin(ANG)+DIS*cos(-26*180)*cos(180-ANG),ANG)
            end
        else
            do
                last=New(_editor_class["鵺-LW-particalB"],XX-27*dis*cos(ANG)+DIS*cos(-27*180)*sin(180-ANG),YY-27*dis*sin(ANG)+DIS*cos(-27*180)*cos(180-ANG),ANG)
                last=New(_editor_class["鵺-LW-particalB"],XX-26*dis*cos(ANG)+DIS*cos(-26*180)*sin(180-ANG),YY-26*dis*sin(ANG)+DIS*cos(-26*180)*cos(180-ANG),ANG)
            end
        end
        task._Wait(30)
        do local k,_d_k=(-27),(1) for _=1,55 do
            last=New(_editor_class["鵺-LW-火弹"],XX+k*dis*cos(ANG)+DIS*cos(k*180)*sin(180-ANG),YY+k*dis*sin(ANG)+DIS*cos(k*180)*cos(180-ANG),COL,XX+k*dis*cos(ANG),YY+k*dis*sin(ANG),WT1,MT,WT2,ANG,(k+27))
        k=k+_d_k end end
        task._Wait(60)
        _del(self,false)
    end)
end
