_editor_class["鵺-开幕红碟"].init=function(self,_x,_y,DIF)
    self.x,self.y=_x,_y
	self.img="ani:卡比--UFO红"
	self.layer=LAYER_ENEMY
	self.group=GROUP_ENEMY
	self.hide=false
	self.bound=true
	self.navi=false
	self.hp=500
	self.maxhp=500
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    if GetGlobal('player_name')=='wuer_player' then
        self.img="image:卡比--红锅"
        self.hscale,self.vscale=0.3,0.3
    else
    end
    task.New(self,function()
        --[[ 晃悠 --]]
        PlaySound("boon01",1,self.x/256,false)
        do local ttt,_d_ttt=(0),(4) for _=1,_infinite do
            self.rot=15*sin(ttt)
            task._Wait(1)
        ttt=ttt+_d_ttt end end
    end)
    task.New(self,function()
        task.BezierMoveTo(180,MOVE_ACC_DEC,-150,150,120,60)
        local COL = 1
        task.New(self,function()
            if DIF==0 then
                do for _=1,_infinite do
                    PlaySound("tan00",1,self.x/256,false)
                    _create_bullet_group(ball_big,COL,self.x,self.y,9,0,2.5,2.5,0,360,true,1,true,true,0,false,self)
                    _create_bullet_group(ball_mid,COL,self.x,self.y,9,0,2.75,2.75,0,360,true,1,true,true,0,false,self)
                    _create_bullet_group(grain_a,COL,self.x,self.y,9,0,3,3,0,360,true,0,true,true,0,false,self)
                    task._Wait(30)
                end end
            else
                local dda = 7
                do for _=1,_infinite do
                    PlaySound("tan00",1,self.x/256,false)
