    bullet.init(self,ball_mid_c,COLOR_BLUE,true,false)
    self.x,self.y=_x,_y
    self.bound=false
    task.New(self,function()
        task._Wait(240)
        self.bound=true
    end)
    task.New(self,function()
        do for _=1,_infinite do
            if IsValid(self._master) then
                _set_rel_pos(self,20*cos(aa),20*sin(aa),self.rot+aa,true)
            else
                ChangeBulletImage(self,ball_mid_c,COLOR_RED)
                do local tt,_d_tt=(0),(6) for _=1,30 do
                    SetV2(self,3.5+cos(tt),aa,true,false)
                    task._Wait(1)
                tt=tt+_d_tt end end
                if true then break end
            end
            task._Wait(1)
        end end
    end)
end
