                                                        self.img="image:sf_波士顿"
                                                    else
                                                        if _boss.ui.sc_name=='穗符「净土的恩赐」' then
                                                            self.img="image:sf_布达佩斯"
                                                        else
                                                            if _boss.ui.sc_name=='借物「贤者的宝弓」' then
                                                                self.img="image:sf_新加坡"
                                                            else
                                                                if _boss.ui.sc_name=='神禽「月之都的开光」' then
                                                                    self.img="image:sf_纽约"
                                                                else
