_editor_class["sf_早苗立绘"]=Class(_object)
_editor_class["sf_早苗立绘"].init=function(self,_x,_y,_)
    self.x,self.y=_x,_y
	self.img="image:sf_早苗立绘2"
	self.layer=LAYER_TOP
	self.group=GROUP_ENEMY
	self.hide=false
	self.bound=false
	self.navi=false
	self.hp=99999
	self.maxhp=99999
	self.colli=false
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    task.New(self,function()
        self.vscale=1.2
        self.hscale=1.2
        task.MoveTo(100,0,60,MOVE_DECEL)
        task.New(self,function()
            do local al,_d_al=(255),(-2) for _=1,120 do
                _object.set_color(self,"",al,255,255,255)
                task._Wait(1)
            al=al+_d_al end end
            _del(self,true)
        end)
        task.MoveTo(-150,-150,120,MOVE_ACCEL)
    end)
end
--[[ 1符 --]]
_editor_class["sf_道中1符"]=Class(bullet)
_editor_class["sf_道中1符"].init=function(self,_x,_y,cl,sty,list,i,flag,a)
    bullet.init(self,sty,cl,true,true)
    self.x,self.y=_x,_y
    task.New(self,function()
        self.group=GROUP_INDES
        self.navi=true
        self.list=list
        if flag==1 then
            task.MoveTo(list[i],list[i+1],90,MOVE_DECEL)
            task._Wait(40)
            PlaySound("kira01",0.1,self.x/256,false)
            do local v,_d_v=(0),(1/120) for _=1,120 do
                SetV2(self,v,a+2,true,false)
                task._Wait(1)
            v=v+_d_v end end
        else
        end
        if flag==2 then
            task.MoveTo(list[i],list[i+1],80,MOVE_DECEL)
            task._Wait(50)
            do local v,_d_v=(0),(1/120) for _=1,120 do
                SetV2(self,v,a,true,false)
                task._Wait(1)
            v=v+_d_v end end
        else
        end
        if flag==3 then
            task.MoveTo(list[i],list[i+1],70,MOVE_DECEL)
            task._Wait(60)
            do local v,_d_v=(0),(1/120) for _=1,120 do
                SetV2(self,v,a,true,false)
                task._Wait(1)
            v=v+_d_v end end
        else
        end
        if flag==4 then
            task.MoveTo(list[i],list[i+1],100,MOVE_DECEL)
            task._Wait(30)
            do local v,_d_v=(0),(1.5/120) for _=1,120 do
                SetV2(self,v,a+180+2,false,false)
                task._Wait(1)
            v=v+_d_v end end
        else
        end
        self.group=GROUP_ENEMY_BULLET
    end)
end
--[[ 2符 --]]
_editor_class["sf_道中2符米蛋"]=Class(bullet)
_editor_class["sf_道中2符米蛋"].init=function(self,_x,_y,a,list,cl)
    bullet.init(self,sf_grain_a,cl,false,false)
    self.x,self.y=_x,_y
    self.list=list
    self.navi=true
    self.bound=false
    task.New(self,function()
        task.New(self,function()
            local y=self.y
            local x=self.x
            task._Wait(60)
            do for _=1,_infinite do
                if Dist(self.x,self.y,x,y)<10 then
                    local judge=ran:Int(1,18)
                    if judge==5 then
                        PlaySound("tan01",0.1,self.x/256,false)
                        local aa=ran:Float(0,360)
                        last=New(_straight,sf_grain_a,COLOR_YELLOW,self.x,self.y,-5,aa+180,false,0,true,true,0,false,ran:Float(2.5,4.5)/60,aa,ran:Float(1.5,2.5),false)
                        last.layer=LAYER_ENEMY
                        last.navi=true
                        if true then break end
                    else
                    end
                else
                end
                task._Wait(1)
            end end
            task._Wait(60)
            do for _=1,_infinite do
                if Dist(self.x,self.y,x,y)<30 then
                    local judge=ran:Int(1,18)
                    if judge==5 then
                        PlaySound("tan01",0.1,self.x/256,false)
                        local aa=ran:Float(0,360)
                        last=New(_straight,sf_grain_a,COLOR_YELLOW,self.x,self.y,-5,aa+180,false,0,true,true,0,false,ran:Float(2.5,4.5)/60,aa,ran:Float(1.5,2.5),false)
                        last.layer=LAYER_ENEMY
                        last.navi=true
                        if true then break end
                    else
                    end
                else
                end
                task._Wait(1)
            end end
            task._Wait(60)
            do for _=1,_infinite do
                if Dist(self.x,self.y,x,y)<30 then
                    local judge=ran:Int(1,18)
                    if judge==5 then
                        PlaySound("tan01",0.1,self.x/256,false)
                        local aa=ran:Float(0,360)
                        last=New(_straight,sf_grain_a,COLOR_YELLOW,self.x,self.y,-5,aa+180,false,0,true,true,0,false,ran:Float(2.5,4.5)/60,aa,ran:Float(1.5,2.5),false)
                        last.layer=LAYER_ENEMY
                        last.navi=true
                        if true then break end
                    else
                    end
                else
                end
                task._Wait(1)
            end end
        end)
        do local i,_d_i=(1),(2) for _=1,#list/2 do
            SetV2(self,list[i],list[i+1]+a,true,false)
            task._Wait(1)
        i=i+_d_i end end
        local judge=ran:Int(1,7)
        if judge==3 then
            _del(self,false)
        else
            local aa=ran:Float(0,360)
            do local v,_d_v=(5),(-ran:Float(3.5,4.5)/60) for _=1,60 do
                SetV2(self,v,aa,true,false)
                task._Wait(1)
            v=v+_d_v end end
        end
        self.bound=true
    end)
end
