    if (self.rot%360)>0 and (self.rot%360)<180 then
        self.bound=false
    else
    end
    _set_a(self,0.01,a,false)
    task.New(self,function()
        do for _=1,_infinite do
            if self.vx^2+self.vy^2>2.25 then
                _set_a(self,0,a,false)
                if true then break end
            else
            end
            task._Wait(1)
        end end
        if (self.rot%360)>0 and (self.rot%360)<180 then
            _set_a(self,0.03,270,false)
            ChangeBulletImage(self,sf_grain_a,COLOR_BLUE)
        else
        end
        do for _=1,_infinite do
            if self.vx^2+self.vy^2>4.2 then
                _set_a(self,0,a,false)
                self.bound=true
                if true then break end
            else
            end
            task._Wait(1)
        end end
    end)
end
