                        boss.dialog.sentence(self,"image:sf_早苗立绘1","right","...........",nil)
                        boss.dialog.sentence(self,"image:sf_早苗立绘1","right","你就是那个做弹幕的无耳?",nil)
                        misc.ShakeScreen(40, 3)
                        boss.dialog.sentence(self,"image:sf_早苗立绘1","right","去死!",nil)
                    end
                else
