    task.New(self,function()
        if GetGlobal('player_name')=='marisa_player' then
            do
                boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","我还以为是谁",nil)
                boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","原来是老熟人",nil)
                boss.dialog.sentence(self,"image:sf_魔理沙立绘","left","啊，是你啊",nil)
                boss.dialog.sentence(self,"image:sf_魔理沙立绘","left","其实我觉得你比那个探什么的强一点",nil)
                boss.dialog.sentence(self,"image:sf_魔理沙立绘","left","可惜也当了逃兵",nil)
                boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","好久没见结果嘴皮子还是这么利索",nil)
                boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","作为唯一的优点来说锻炼的很出彩",nil)
                boss.dialog.sentence(self,"image:sf_魔理沙立绘","left","丰姬小姐未免也太过谦虚了",nil)
                boss.dialog.sentence(self,"image:sf_魔理沙立绘","left","您的逃跑功力怕是也不下纯狐",nil)
                boss.dialog.sentence(self,"image:sf_魔理沙立绘","left","虽然没有锻炼过，但是从熟练度来看似乎是天生的本能",nil)
                boss.dialog.sentence(self,"image:sf_魔理沙立绘","left","真好啊",nil)
                boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","于是你又来这里，是为了什么",nil)
                boss.dialog.sentence(self,"image:sf_魔理沙立绘","left","反正不是为了来转移话题的",nil)
                boss.dialog.sentence(self,"image:sf_魔理沙立绘","left","大概就是作为人类代表来参观一下月之都战后重建工作吧",nil)
                boss.dialog.sentence(self,"image:sf_魔理沙立绘","left","这个理由怎么样",nil)
                boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","大概可以得七分吧",nil)
                boss.dialog.sentence(self,"image:sf_魔理沙立绘","left","百分制的吗",nil)
                boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","九十六分制",nil)
                boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","就结果来说你估计的很准确",nil)
                boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","你可以继续估计一下这个借口的被放行率是多少",nil)
                boss.dialog.sentence(self,"image:sf_魔理沙立绘","left","十成",nil)
                boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","很遗憾，少了一点",nil)
                LoadMusicRecord("绵月的符卡");_play_music("绵月的符卡")
                boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","我是月海的防御官，能力是连接两个世界",nil)
                boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","我的任务是防止污秽干涉月都的纯净",nil)
                boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","在这个静之海上，能通过的人类不存在!",nil)
                boss.dialog.sentence(self,"image:sf_魔理沙立绘","left","月球人原来也有中二病吗",nil)
            end
        else
            if GetGlobal('player_name')=='sanae_player' then
                do
                    boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","为什么最近老是有人闯进来",nil)
                    boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","你们觉得这里是游乐场吗",nil)
                    boss.dialog.sentence(self,"image:sf_早苗立绘1","left","月亮的外交官换人了啊",nil)
                    boss.dialog.sentence(self,"image:sf_早苗立绘1","left","上次那个被薅了半边毛的鸭子小姐呢",nil)
                    boss.dialog.sentence(self,"image:sf_早苗立绘1","left","有点事情找她",nil)
                    boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","你说的是探女小姐么？",nil)
                    boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","你们认识么",nil)
                    boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","的确有传言说有几个人类协助了作战来着",nil)
                    boss.dialog.sentence(self,"image:sf_早苗立绘1","left","那就是我啊",nil)
                    boss.dialog.sentence(self,"image:sf_早苗立绘1","left","作为地上最强国津神的东风谷早苗大人",nil)
                    boss.dialog.sentence(self,"image:sf_早苗立绘1","left","完美★无瑕地完成了月都保卫战",nil)
                    boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","地上的神都这么弱吗，那我就放心了",nil)
                    boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","话又说回来，你还来这里干什么",nil)
                    boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","明明事情都已经结束了",nil)
                    boss.dialog.sentence(self,"image:sf_早苗立绘1","left","这么说还真是薄情",nil)
                    boss.dialog.sentence(self,"image:sf_早苗立绘1","left","我就不能常来看看被自己拯救过的子民吗",nil)
                    boss.dialog.sentence(self,"image:sf_早苗立绘1","left","啊，神拯救了世人，又被世人抛弃",nil)
                    boss.dialog.sentence(self,"image:sf_早苗立绘1","left","不过没事，我原谅你们，因为我爱着你们",nil)
                    boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","所以我们的神能够自己安安静静的被抛弃吗",nil)
                    boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","那就真是谢天谢地了",nil)
                    boss.dialog.sentence(self,"image:sf_早苗立绘1","left","比起十进制还是十六进制好点",nil)
                    boss.dialog.sentence(self,"image:sf_早苗立绘1","left","那位鸭子小姐呢，我想让她帮我找点东西",nil)
                    boss.dialog.sentence(self,"image:sf_早苗立绘1","left","外面我已经翻遍了，大概率就在都城里面",nil)
                    boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","仔细想想，我们月之都这次确实欠你一个人情",nil)
                    boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","但是你把这里弄得一团糟，也是有责任的吧",nil)
                    LoadMusicRecord("绵月的符卡");_play_music("绵月的符卡")
                    boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","我是绵月丰姬，能力是管理地月的通道",nil)
                    boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","我的任务是防止污秽干涉月都的纯净",nil)
                    boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","在这个静之海上，能通过的人类不存在!",nil)
                    boss.dialog.sentence(self,"image:sf_早苗立绘1","left","也就是说其实你是路由器的神明吧",nil)
                end
            else
                if GetGlobal('player_name')=='wuer_player' then
                    do
                        boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","一路闯到这里",nil)
                        boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","至少也留下名字吧",nil)
                        boss.dialog.sentence(self,"image:sf_无耳立绘","left","问我是谁吗？",nil)
                        boss.dialog.sentence(self,"image:sf_无耳立绘","left","那你听好了",nil)
                        boss.dialog.sentence(self,"image:sf_无耳立绘","left","我——",nil)
                        boss.dialog.sentence(self,"image:sf_无耳立绘","left","自幼心事且拏云，有朝一日无人超",nil)
                        boss.dialog.sentence(self,"image:sf_无耳立绘","left","少时入群虽懵懂，亦有雄心比天高",nil)
                        boss.dialog.sentence(self,"image:sf_无耳立绘","left","十三学的理论成，来年弹幕显光耀",nil)
                        boss.dialog.sentence(self,"image:sf_无耳立绘","left","四座皆惊不得叹，八方来拜称英豪",nil)
                        boss.dialog.sentence(self,"image:sf_无耳立绘","left","始我功名真得幸，各路虎狼认大佬",nil)
                        boss.dialog.sentence(self,"image:sf_无耳立绘","left","又有群主来禅让，指我人生路途遥",nil)
                        boss.dialog.sentence(self,"image:sf_无耳立绘","left","帐中贤者来献策，开办群活炼法宝",nil)
                        boss.dialog.sentence(self,"image:sf_无耳立绘","left","两仪雕花紫金锅，上有游龙盘一条",nil)
                        boss.dialog.sentence(self,"image:sf_无耳立绘","left","中原逐鹿破千军，诸侯皆顺竞来朝",nil)
                        boss.dialog.sentence(self,"image:sf_无耳立绘","left","自此天下归一统，我欲飞升上九霄",nil)
                        boss.dialog.sentence(self,"image:sf_无耳立绘","left","回光内照宁心坐，身中日月坎离交",nil)
                        boss.dialog.sentence(self,"image:sf_无耳立绘","left","万事不思全寡欲，六根清净体坚牢",nil)
                        boss.dialog.sentence(self,"image:sf_无耳立绘","left","三花五气齐聚首，东来紫云显大道",nil)
                        boss.dialog.sentence(self,"image:sf_无耳立绘","left","滚滚天雷来炼我，祭出法器将身保",nil)
                        boss.dialog.sentence(self,"image:sf_无耳立绘","left","一脚踏破雷音寺，凌云渡口战波涛",nil)
                        boss.dialog.sentence(self,"image:sf_无耳立绘","left","大罗金仙难助阵，十八罗汉把命逃",nil)
                        boss.dialog.sentence(self,"image:sf_无耳立绘","left","玉皇奉我为天帝，三十三天走一遭",nil)
                        boss.dialog.sentence(self,"image:sf_无耳立绘","left","我就是那天上天下八荒六合唯我独尊东方不败的LSTG群无耳大人",nil)
                        boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","哦",nil)
                        LoadMusicRecord("绵月的符卡");_play_music("绵月的符卡")
                        boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","死吧，变态",nil)
                    end
                else
                    do
                        boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","是你啊",nil)
                        boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","上次那个被暴揍一顿灰溜溜逃回地上的贫乏巫女",nil)
                        boss.dialog.sentence(self,"image:sf_灵梦立绘","left","是我啊",nil)
                        boss.dialog.sentence(self,"image:sf_灵梦立绘","left","上次那个拯救了月之都于水火之中的英雄巫女",nil)
                        boss.dialog.sentence(self,"image:sf_灵梦立绘","left","月球的人都不会好好说话的吗",nil)
                        boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","真失礼啊",nil)
                        boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","你会对突然闯进你的房子里的人好好说话吗",nil)
                        boss.dialog.sentence(self,"image:sf_灵梦立绘","left","那种事情怎样都好，已经习惯了",nil)
                        boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","真是可怜的人呢",nil)
                        boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","话说回来，你还来这里干什么",nil)
                        boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","事情明明都已经解决了",nil)
                        boss.dialog.sentence(self,"image:sf_灵梦立绘","left","有点善后的事情，需要和那个探女谈谈",nil)
                        boss.dialog.sentence(self,"image:sf_灵梦立绘","left","举手之劳，放我过去怎么样",nil)
                        boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","举手之劳，把你打落到三途川怎么样",nil)
                        boss.dialog.sentence(self,"image:sf_灵梦立绘","left","别像个妖怪一样说话",nil)
                        boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","那就把你打落到海底吧",nil)
                        boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","虽然差不多",nil)
                        boss.dialog.sentence(self,"image:sf_灵梦立绘","left","虽然可以游回幻想乡",nil)
                        boss.dialog.sentence(self,"image:sf_灵梦立绘","left","但是在这里被你干掉那就太失败了",nil)
                        boss.dialog.sentence(self,"image:sf_灵梦立绘","left","你们这群家伙，反正不被打趴下是不会让道的吧",nil)
                        boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","职责所在，没有办法",nil)
                        LoadMusicRecord("绵月的符卡");_play_music("绵月的符卡")
                        boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","我是月海的防御官，能力是隔断现世和幻想",nil)
                        boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","我的任务是防止污秽干涉月都的纯净",nil)
                        boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","在这个静之海上，能通过的人类不存在!",nil)
                        boss.dialog.sentence(self,"image:sf_灵梦立绘","left","没人陪你对诗肯定很不爽吧",nil)
                    end
                end
            end
        end
    end)
end
