_editor_class["sf_wave6_狙"]=Class(enemy)
_editor_class["sf_wave6_狙"].init=function(self,_x,_y,sty,aa,bb,list)
    enemy.init(self,sty,1,false,true,false)
    self.x,self.y=_x,_y
    self.drop={aa,1,bb}
    task.New(self,function() self.protect=true task.Wait(1) self.protect=false end)
    task.New(self,function()
        self.list=list
        task.New(self,function()
            if sty==31 then
                do for _=1,_infinite do
                    PlaySound("tan00",0.1,self.x/256,false)
                    do local v,_d_v=(2),(0.4) for _=1,7 do
                        last=New(_straight,sf_ball_mid_c,COLOR_RED,self.x,self.y,v,0,true,0,true,true,0,false,0,0,0,false)
                        last.omiga=4
                        task._Wait(0)
                    v=v+_d_v end end
                    task._Wait(120)
                end end
            else
                do for _=1,_infinite do
                    PlaySound("tan00",0.1,self.x/256,false)
                    do local v,_d_v=(2),(0.4) for _=1,7 do
                        last=New(_straight,sf_ball_mid_c,COLOR_BLUE,self.x,self.y,v,0,true,0,true,true,0,false,0,0,0,false)
                        last.omiga=4
                        task._Wait(0)
                    v=v+_d_v end end
                    task._Wait(120)
                end end
            end
        end)
        do local i,_d_i=(1),(2) for _=1,#list/2 do
            SetV2(self,list[i],list[i+1],false,false)
            task._Wait(1)
        i=i+_d_i end end
    end)
end
