        do local a,_d_a=(0),(180) for _=1,2 do
            last=New(_editor_class["sf_wave6_slave"],self.x,self.y,self,a)
            task._Wait(0)
        a=a+_d_a end end
        task.MoveTo(self.x,y,60,MOVE_DECEL)
