_editor_class["sf_wave6_slave"]=Class(enemy)
_editor_class["sf_wave6_slave"].init=function(self,_x,_y,mst,a)
    enemy.init(self,28,50,false,true,false)
    self.x,self.y=_x,_y
    self.drop={0,0,2}
    task.New(self,function() self.protect=true task.Wait(1) self.protect=false end)
    if IsValid(mst) then
        _connect(mst,self,0.5,true)
    else
    end
    task.New(self,function()
        do for _=1,_infinite do
            _set_rel_pos(self,40*cos(a),40*sin(a),self.rot,false)
            task._Wait(1)
        end end
    end)
    task.New(self,function()
        task._Wait(60)
        if a==0 then
            do local aa,_d_aa=(a),(15) for _=1,_infinite do
                PlaySound("tan00",0.1,self.x/256,false)
                do local a1,_d_a1=(aa),(72) for _=1,5 do
                    last=New(_straight,sf_grain_a,COLOR_BLUE,self.x+15*cos(a1),self.y+15*sin(a1),3,a1,false,0,true,true,0,false,0,0,0,false)
                    task._Wait(0)
                a1=a1+_d_a1 end end
                task._Wait(4)
            aa=aa+_d_aa end end
        else
            do local aa,_d_aa=(a),(-15) for _=1,_infinite do
                PlaySound("tan00",0.1,self.x/256,false)
                do local a1,_d_a1=(aa),(72) for _=1,5 do
                    last=New(_straight,sf_grain_a,COLOR_BLUE,self.x+15*cos(a1),self.y+15*sin(a1),3,a1,false,0,true,true,0,false,0,0,0,false)
                    task._Wait(0)
                a1=a1+_d_a1 end end
                task._Wait(4)
            aa=aa+_d_aa end end
        end
    end)
end
