_editor_class["sf_wave7_毛玉"].init=function(self,_x,_y,a)
    enemy.init(self,19,8,false,true,false)
    self.x,self.y=_x,_y
    self.drop={ran:Int(0,1),ran:Int(0,1),ran:Int(0,1)}
    task.New(self,function() self.protect=true task.Wait(1) self.protect=false end)
    PlaySound("boon00",0.1,self.x/256,false)
    task.New(self,function()
        do local v,_d_v=(0),(5/120) for _=1,120 do
            SetV2(self,v,a,false,false)
            task._Wait(1)
        v=v+_d_v end end
    end)
    task.New(self,function()
        do for _=1,_infinite do
            task._Wait(ran:Float(0,40))
            local aa=a+ran:Float(-90,90)
            last=New(_straight,sf_star_small,COLOR_RED,self.x,self.y,0,aa,false,0,true,true,0,false,0.02,aa,ran:Float(1,2),false)
            last.omiga=3
            task._Wait(0)
        end end
    end)
end
_editor_class["sf_wave7_毛玉"].kill=function(self)
    New(tasker, function()
        if self.y<player.y or self.y<0 then
        else
            PlaySound("tan00",0.1,self.x/256,false)
            do local v,_d_v=(2),(0.4) for _=1,7 do
                last=New(_straight,sf_ball_mid_c,COLOR_BLUE,self.x,self.y,v,0,true,0,true,true,0,false,0,0,0,false)
                last.omiga=4
                task._Wait(0)
            v=v+_d_v end end
        end
    end)
    self.class.base.kill(self)
end
