_tmp_sc=boss.dialog.New(true)
function _tmp_sc:init()
	lstg.player.dialog=true
	_dialog_can_skip=true
	self.dialog_displayer=New(dialog_displayer)
    task.New(self,function()
        if (not ext.replay.IsReplay()) then
            New(achievement_obj,1,15)
        else
        end
        if GetGlobal('player_name')=='marisa_player' then
            do
                boss.dialog.sentence(self,"image:sf_魔理沙立绘","left","啊，赢了",nil)
                boss.dialog.sentence(self,"image:sf_魔理沙立绘","left","原来月球人都这么弱的吗",nil)
                boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","我发现你的思维方式和正常人类不一样",nil)
                boss.dialog.sentence(self,"image:sf_魔理沙立绘","left","褒义的？",nil)
                boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","你认为呢",nil)
                boss.dialog.sentence(self,"image:sf_魔理沙立绘","left","也许吧",nil)
                boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","这是你第一次没有使用肯定句",nil)
                boss.dialog.sentence(self,"image:sf_魔理沙立绘","left","总之我可以进去了吧",nil)
                boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","我们月之民确实欠你一份人情",nil)
                boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","从这个道理上来说放你进去也是合情合理的",nil)
                boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","出去的时候小心别踩到捕鼠器了",nil)
                boss.dialog.sentence(self,"image:sf_魔理沙立绘","left","不许玩双关",nil)
            end
        else
            if GetGlobal('player_name')=='sanae_player' then
                do
                    boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","啊，败了败了",nil)
                    boss.dialog.sentence(self,"image:sf_早苗立绘1","left","那就多谢了",nil)
                    boss.dialog.sentence(self,"image:sf_早苗立绘1","left","果然这里的人还是对我心存感激的啊",nil)
                    boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","没有，其实我并没有放水",nil)
                    boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","你有着不下纯狐的实力，这我是确实体会到了",nil)
                    boss.dialog.sentence(self,"image:sf_早苗立绘1","left","诶，真的吗",nil)
                    boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","恩，是真的",nil)
                    boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","在给人搞事的方面",nil)
                    boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","还有我能问问吗，你到底要找什么",nil)
                    boss.dialog.sentence(self,"image:sf_早苗立绘1","left","枪啊，枪，红色的，长长的",nil)
                    boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","那个我知道，不过吸血鬼自己给拿回去了",nil)
                    boss.dialog.sentence(self,"image:sf_早苗立绘1","left","不是那个啊，另外一个",nil)
                    boss.dialog.sentence(self,"image:sf_早苗立绘1","left","那个是信仰啊信仰，不如我直接去问鸭子小姐吧",nil)
                    boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","倒是也行，你的那把枪叫什么名字",nil)
                    boss.dialog.sentence(self,"image:sf_早苗立绘1","left","是Longinus啊",nil)
                end
            else
                if GetGlobal('player_name')=='wuer_player' then
                    do
                        boss.dialog.sentence(self,"image:sf_无耳立绘","left","将军",nil)
                        boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","恩，打得不错",nil)
                        boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","那么去试试别的mod吧",nil)
                        boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","一定要用无耳机体哦",nil)
                        boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","(或许会变成无耳无惨也说不定)",nil)
                        boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","恩，芜茸机体",nil)
                    end
                else
                    do
                        boss.dialog.sentence(self,"image:sf_灵梦立绘","left","还有什么要说",nil)
                        boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","原来你有这么强的么",nil)
                        boss.dialog.sentence(self,"image:sf_灵梦立绘","left","总之我可以进去了吧",nil)
                        boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","我们月之民确实欠你一份人情",nil)
                        boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","从这个道理上来说放你进去也是合情合理的",nil)
                        boss.dialog.sentence(self,"image:sf_灵梦立绘","left","所以完全可以避免打一架",nil)
                        boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","毕竟是任务",nil)
                        boss.dialog.sentence(self,"image:sf_灵梦立绘","left","那还真是不巧，我这边也是任务",nil)
                        boss.dialog.sentence(self,"image:sf_丰姬立绘1","right","你既然这么强为什么上次会输的那么惨呢",nil)
                        boss.dialog.sentence(self,"image:sf_灵梦立绘","left","那是上上次",nil)
                    end
                end
            end
        end
    end)
end
