                    _set_a(self,0.005,ran:Float(225,315),false)
                    if true then break end
                else
                    task._Wait(t)
                    _set_a(self,0.005,ran:Float(225,315)+180,false)
                    if true then break end
                end
            end
            task._Wait(1)
        end end
        do for _=1,_infinite do
            if self.y<-130 then
                _set_a(self,0,0,false)
                if true then break end
            else
            end
            task._Wait(1)
        end end
    end)
end
