--[[ 5符 --]]
_editor_class["sf5符变相N"]=Class(bullet)
_editor_class["sf5符变相N"].init=function(self,_x,_y,a)
    bullet.init(self,sf_ellipse,COLOR_BLUE,true,true)
    self.x,self.y=_x,_y
    PlaySound("tan00",0.1,self.x/256,false)
    self.navi=true
    SetV2(self,0,a,true,false)
    if (self.rot%360)>0 and (self.rot%360)<180 then
        self.bound=false
        task.New(self,function()
            do for _=1,_infinite do
                if self.vx^2+self.vy^2>2.25 then
                    _set_a(self,0,a,false)
                    if true then break end
                else
                end
                task._Wait(1)
            end end
            if (self.rot%360)>0 and (self.rot%360)<180 then
                _set_a(self,0.03,270,false)
                ChangeBulletImage(self,sf_ellipse,COLOR_GREEN)
            else
            end
        end)
    else
    end
    task.New(self,function()
        local judge=ran:Int(1,3)
        do for _=1,_infinite do
            if (self.rot%360)>0 and (self.rot%360)<180 and judge==1 then
                PlaySound("tan00",0.1,self.x/256,false)
                last=New(_editor_class["sf5符狙"],self.x,self.y,Angle(self,player))
            else
            end
            task._Wait(85)
        end end
    end)
    _set_a(self,0.03,a,false)
    task.New(self,function()
        do for _=1,_infinite do
            if self.vx^2+self.vy^2>10 then
                _set_a(self,0,a,false)
                self.bound=true
                if true then break end
            else
            end
            task._Wait(1)
        end end
    end)
end
--[[ 10符 --]]
_editor_class["sf_10符p2米蛋N"]=Class(bullet)
_editor_class["sf_10符p2米蛋N"].init=function(self,_x,_y,a,cl,t,judge)
    bullet.init(self,sf_grain_a,cl,true,true)
    self.x,self.y=_x,_y
    self.bound=false
    SetV2(self,2.5,a,true,false)
    task.New(self,function()
        task._Wait(30)
        task.New(self,function()
            do local v,_d_v=(2),(-2/60) for _=1,60 do
                SetV2(self,v,self.rot,true,false)
                task._Wait(1)
            v=v+_d_v end end
        end)
        task._Wait(40)
        if judge%5==1 then
            if cl==1 then
                local judge=ran:Int(1,3)
                if judge==1 then
                else
                    last=New(_editor_class["sf10符P2鳞弹"],self.x,self.y,self.rot)
                end
                _del(self,true)
            else
                if t==1 then
                    do local a,_d_a=(self.rot+120),(90) for _=1,4 do
                        last=New(_straight,sf_arrow_small,COLOR_BLUE,self.x,self.y,1.5,a,false,0,true,true,0,false,0,0,0,false)
                        task._Wait(0)
                    a=a+_d_a end end
                    _del(self,true)
                else
                    do local a,_d_a=(self.rot-120),(90) for _=1,4 do
                        last=New(_straight,sf_arrow_small,COLOR_BLUE,self.x,self.y,1.5,a,false,0,true,true,0,false,0,0,0,false)
                        task._Wait(0)
                    a=a+_d_a end end
                    _del(self,true)
                end
            end
        else
            _del(self,true)
        end
    end)
end
