                local ra=ran:Float(-15,15)
                last=New(_straight,sf_ball_mid_c,COLOR_DEEP_BLUE,self.x,self.y,0,270+ra,false,0,true,true,0,false,0.006,270+ra,0.2,false)
                last.omiga=2
                _del(self,false)
