                    local ra=ran:Float(-15,15)
                    last=New(_straight,sf_ball_mid_c,COLOR_DEEP_BLUE,self.x,self.y,0,270+ra,false,0,true,true,0,false,0.006,270+ra,1,false)
                    last.omiga=2
                    _del(self,false)
                else
                    task._Wait((Dist(self.x,self.y,_boss.x,_boss.y)/192)*60)
                    _del(self,false)
                end
            end
        end
    end)
end
