_editor_class["sf9符水N"]=Class(bullet)
_editor_class["sf9符水N"].init=function(self,_x,_y,COLlist,ROWlist,POSITION,WHERE,iii,flagg)
    bullet.init(self,arrow_big,COLOR_RED,true,false)
    self.x,self.y=_x,_y
    if IsValid(_boss) then
        _connect(_boss,self,0,true)
    else
    end
    self.bound=false
    self.timer=11
    task.New(self,function()
        do local al,_d_al=(100),(125/(110-(Dist(self.x,self.y,0,0)/192)*40)) for _=1,110-(Dist(self.x,self.y,0,0)/192)*40 do
            _object.set_color(self,"",al,255,255,255)
            task._Wait(1)
        al=al+_d_al end end
    end)
    self.colli=false
    self.navi=true
    self.img="ani:sf_water_drop"
    task.New(self,function()
        if POSITION<42 then
            SetV2(self,0,0,true,false)
            task._Wait(110-(Dist(self.x,self.y,0,0)/192)*40)
            self.colli=true
            PlaySound("tan01",0.1,self.x/256,false)
            last=New(_editor_class["sf9符水1N"],self.x,self.y,COLlist,ROWlist,POSITION,WHERE,iii,3,0,0,flagg)
            _del(self,false)
        else
            SetV2(self,0,270,true,false)
            task._Wait(110-(Dist(self.x,self.y,0,0)/192)*40)
            self.colli=true
            PlaySound("tan01",0.1,self.x/256,false)
            last=New(_editor_class["sf9符水1N"],self.x,self.y,COLlist,ROWlist,POSITION,WHERE,iii,3,270,0,flagg)
            _del(self,false)
        end
    end)
end
