                AA=ROWlist[WHERE+flag-6][(8-((iii+1)/2))*2-1]
                BB=ROWlist[WHERE+flag-6][(8-((iii+1)/2))*2]
            else
                AA=ROWlist[WHERE+flag][(8-((iii+1)/2))*2-1]
                BB=ROWlist[WHERE+flag][(8-((iii+1)/2))*2]
