                task.BezierMoveTo(t,MOVE_ACC_DEC,self.x,self.y,0.25*Dist(self.x,self.y,AA,BB)*cos(Angle(self.x,self.y,AA,BB))+(0.3*Dist(self.x,self.y,AA,BB))*cos(Angle(self.x,self.y,AA,BB)+90)+self.x,0.25*Dist(self.x,self.y,AA,BB)*sin(Angle(self.x,self.y,AA,BB))+(0.3*Dist(self.x,self.y,AA,BB))*sin(Angle(self.x,self.y,AA,BB)+90)+self.y,0.5*Dist(self.x,self.y,AA,BB)*cos(Angle(self.x,self.y,AA,BB))+(0.6*Dist(self.x,self.y,AA,BB))*cos(Angle(self.x,self.y,AA,BB)+90)+self.x,0.5*Dist(self.x,self.y,AA,BB)*sin(Angle(self.x,self.y,AA,BB))+(0.6*Dist(self.x,self.y,AA,BB))*sin(Angle(self.x,self.y,AA,BB)+90)+self.y,0.75*Dist(self.x,self.y,AA,BB)*cos(Angle(self.x,self.y,AA,BB))+(0.3*Dist(self.x,self.y,AA,BB))*cos(Angle(self.x,self.y,AA,BB)+90)+self.x,0.75*Dist(self.x,self.y,AA,BB)*sin(Angle(self.x,self.y,AA,BB))+(0.3*Dist(self.x,self.y,AA,BB))*sin(Angle(self.x,self.y,AA,BB)+90)+self.y,AA,BB)
            else
                task.BezierMoveTo(t,MOVE_ACC_DEC,self.x,self.y,0.25*Dist(self.x,self.y,AA,BB)*cos(Angle(self.x,self.y,AA,BB))+(0.3*Dist(self.x,self.y,AA,BB))*cos(Angle(self.x,self.y,AA,BB)-90)+self.x,0.25*Dist(self.x,self.y,AA,BB)*sin(Angle(self.x,self.y,AA,BB))+(0.3*Dist(self.x,self.y,AA,BB))*sin(Angle(self.x,self.y,AA,BB)-90)+self.y,0.5*Dist(self.x,self.y,AA,BB)*cos(Angle(self.x,self.y,AA,BB))+(0.6*Dist(self.x,self.y,AA,BB))*cos(Angle(self.x,self.y,AA,BB)-90)+self.x,0.5*Dist(self.x,self.y,AA,BB)*sin(Angle(self.x,self.y,AA,BB))+(0.6*Dist(self.x,self.y,AA,BB))*sin(Angle(self.x,self.y,AA,BB)-90)+self.y,0.75*Dist(self.x,self.y,AA,BB)*cos(Angle(self.x,self.y,AA,BB))+(0.3*Dist(self.x,self.y,AA,BB))*cos(Angle(self.x,self.y,AA,BB)-90)+self.x,0.75*Dist(self.x,self.y,AA,BB)*sin(Angle(self.x,self.y,AA,BB))+(0.3*Dist(self.x,self.y,AA,BB))*sin(Angle(self.x,self.y,AA,BB)-90)+self.y,AA,BB)
            end
            if (WHERE+flag)>=7 then
                self.w=self.w+flag-6
                self.p=self.p+42
            else
                self.w=self.w+flag
                self.p=self.p+42
            end
            task._Wait(20)
