                if _boss.timer>5*60 and _boss.timer<25*60 then
                    last=New(_straight,sf_kite,COLOR_CYAN,self.x,self.y,0.5,Angle(self.x,self.y,0,0),false,0,true,true,30,false,0,0,0,false)
