_editor_class["sf_wave2N"]=Class(_object)
_editor_class["sf_wave2N"].init=function(self,_x,_y,y)
    self.x,self.y=_x,_y
	self.img="ani:sf_兔子1"
	self.layer=LAYER_ENEMY
	self.group=GROUP_ENEMY
	self.hide=false
	self.bound=true
	self.navi=false
	self.hp=70
	self.maxhp=70
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    task.New(self,function()
        last=New(_editor_class["sf_hideobj"],self.x,self.y,self,12,12,6)
        do local a,_d_a=(225),(22) local flag,_d_flag=(1),(1) for _=1,5 do
            last=New(_editor_class["sf_wave2_slaveN"],self.x,self.y,self,a,flag)
            task._Wait(0)
        a=a+_d_a flag=flag+_d_flag end end
        task.MoveTo(self.x,y,60,MOVE_DECEL)
        task.New(self,function()
            task._Wait(300)
            task.MoveTo(self.x,350,60,MOVE_ACCEL)
        end)
        do for _=1,_infinite do
            local aa=ran:Float(0,360)
            PlaySound("tan00",0.1,self.x/256,false)
            do local v,_d_v=(1),(0.4) for _=1,4 do
                _create_bullet_group(sf_grain_a,COLOR_RED,self.x,self.y,18,0,v,v,aa,360,false,0,true,true,0,false,self)
                task._Wait(0)
            v=v+_d_v end end
            task._Wait(180)
        end end
    end)
end
_editor_class["sf_wave2_slaveN"]=Class(enemy)
_editor_class["sf_wave2_slaveN"].init=function(self,_x,_y,mst,a,flag)
    enemy.init(self,28,20,false,true,false)
    self.x,self.y=_x,_y
    self.drop={0,0,2}
    task.New(self,function() self.protect=true task.Wait(1) self.protect=false end)
    if IsValid(mst) then
        _connect(mst,self,0,true)
    else
    end
    task.New(self,function()
        do for _=1,_infinite do
            _set_rel_pos(self,50*cos(a),50*sin(a),self.rot,false)
            task._Wait(1)
        end end
    end)
    task.New(self,function()
        task._Wait(60)
        do for _=1,_infinite do
            PlaySound("tan00",0.1,self.x/256,false)
            if flag%2==1 then
                last=New(_straight,sf_grain_b,COLOR_BLUE,self.x,self.y,2,270-30,false,0,true,true,0,false,0,0,0,false)
                last=New(_straight,sf_grain_b,COLOR_BLUE,self.x,self.y,2,270+30,false,0,true,true,0,false,0,0,0,false)
            else
                last=New(_straight,sf_grain_b,COLOR_BLUE,self.x,self.y,2,270,false,0,true,true,0,false,0,0,0,false)
            end
            task._Wait(40)
        end end
    end)
end
