_editor_class["sf_wave3_slaveN"]=Class(_object)
_editor_class["sf_wave3_slaveN"].init=function(self,_x,_y,a,mst,flag)
    self.x,self.y=_x,_y
	self.img="image:sf_magicblue"
	self.layer=LAYER_ENEMY
	self.group=GROUP_INDES
	self.hide=false
	self.bound=false
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=false
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    task.New(self,function()
        if IsValid(mst) then
            _connect(mst,self,0,false)
        else
            _del(self,true)
        end
        task.New(self,function()
            task.MoveTo(mst.x+60*cos(a),mst.y+60*sin(a),60,MOVE_DECEL)
        end)
        do local al,_d_al=(0),(4) for _=1,60 do
            _object.set_color(self,"",al,255,255,255)
            task._Wait(1)
        al=al+_d_al end end
        self.omiga=4.5
        do for _=1,_infinite do
            if IsValid(mst) then
                if mst.flag==1 then
                    do local v,_d_v=(1),(0.5) for _=1,3 do
                        PlaySound("tan00",0.1,self.x/256,false)
                        _create_bullet_group(sf_arrow_mid,COLOR_RED,self.x,self.y,23,0,v,v,0,360,true,0,true,true,0,false,self)
                        task._Wait(30)
                    v=v+_d_v end end
                    _del(self,true)
                else
                end
            else
                do local v,_d_v=(1),(0.5) for _=1,3 do
                    PlaySound("tan00",0.1,self.x/256,false)
                    _create_bullet_group(sf_arrow_mid,COLOR_RED,self.x,self.y,23,0,v,v,0,360,true,0,true,true,0,false,self)
                    task._Wait(30)
                v=v+_d_v end end
                _del(self,true)
            end
            task._Wait(1)
        end end
    end)
end
