    task.New(self,function()
        self.colli=false
        do for _=1,_infinite do
            if Dist(self,player)<50 and self.flag==0 then
                self.flag=1
                self.timer=0
                self.class=self.imgclass
                _object.set_color(self,"mul+add",155,255,255,255)
                PlaySound("kira00",0.4,self.x/256,false)
                self.navi=true
                task.New(self,function()
                    do local v2,_d_v2=(v),(-v/25) local i,_d_i=(130),(5) local al,_d_al=(255),(-5) for _=1,26 do
                        _object.set_color(self,"mul+add",al,i,i,255)
