    self.x,self.y=_x,_y
    SetV2(self,v,a,true,false)
    _object.set_color(self,"mul+add",255,255,255,255)
    task.New(self,function()
        do local vv,_d_vv=(v),(-v/65) for _=1,61 do
            SetV2(self,vv,a,true,false)
            task._Wait(1)
        vv=vv+_d_vv end end
        PlaySound("kira00",0.1,self.x/256,false)
        _set_a(self,0.03,a,false)
        _forbid_v(self,v,'original','original')
    end)
end
