_editor_class["嫦娥N:Normal"]=Class(boss)
_editor_class["嫦娥N:Normal"].cards={}
_editor_class["嫦娥N:Normal"].name="Chang e"
_editor_class["嫦娥N:Normal"].init=function(self,cards)
    boss.init(self,240,384,"Chang e",cards,New(_editor_class["change_bg"]))
	self.difficulty="Normal"
	self.ani_intv=40
	for i=1,3 do self['img'..i]={} end
	self.nn={4,3,4}
	self.mm={1,1,1}
	for i=2,3 do self['ani'..i]=self.nn[i]-self.mm[i-1] end
	for i=1,3 do
		for j=1,self.nn[i] do
			self['img'..i][j]='anonymous:'.."AE_Chang'e.png"..i..j
		end
	end
end
_editor_class["嫦娥N:Normal"].bgm = "AE_bgm-final"
_editor_class["嫦娥N:Normal"]._bg = AE_moonworld_background
_editor_class["嫦娥N:Normal"].difficulty = "Normal"
_tmp_sc=boss.dialog.New(true)
function _tmp_sc:init()
	lstg.player.dialog=true
	_dialog_can_skip=true
	self.dialog_displayer=New(dialog_displayer)
    task.New(self,function()
        boss.show_aura(self,false)
        self.hide=true
        task._Wait(150)
        task.MoveTo(0,84,0,MOVE_ACC_DEC)
        task._Wait(60)
        self.hide=false
        task._Wait(60)
        boss.show_aura(self,true)
        task._Wait(120)
        if GetGlobal('player_name')=='reimu_player' then
            boss.dialog.sentence(self,"image:AE_Chang'e_pic","right","人类",600,1)
            boss.dialog.sentence(self,"image:AE_Chang'e_pic","right","广寒宫可不欢迎你",600,1)
            boss.dialog.sentence(self,"image:AE_reimu_face1","left","还真是冷淡的大小姐呢...",600,1)
            boss.dialog.sentence(self,"image:AE_reimu_face2","left","好歹也是我帮你赶走了纯狐",600,1)
            boss.dialog.sentence(self,"image:AE_reimu_face2","left","然而最后只是想做个一夜游都不行啊",600,1)
            boss.dialog.sentence(self,"image:AE_Chang'e_pic","right","你也太高估自己了",600,1)
            boss.dialog.sentence(self,"image:AE_Chang'e_pic","right","你以为你在和谁对话",600,1)
            boss.dialog.sentence(self,"image:AE_Chang'e_pic","right","你可是面对着月之神，太阴的象征",600,1)
            boss.dialog.sentence(self,"image:AE_Chang'e_pic","right","居然还敢口出狂言",600,1)
            boss.dialog.sentence(self,"image:AE_reimu_face1","left","月球上的神明都这么难缠啊...",600,1)
            boss.dialog.sentence(self,"image:AE_Chang'e_pic","right","可笑",600,1)
            boss.dialog.sentence(self,"image:AE_Chang'e_pic","right","你以为广寒宫是你的小神社吗？",600,1)
            boss.dialog.sentence(self,"image:AE_reimu_face1","left","虽然说得很有道理...",600,1)
            boss.dialog.sentence(self,"image:AE_reimu_face1","left","但说到底不就是区区一个月神...",600,1)
            LoadMusicRecord("AE_bgm-final");_play_music("AE_bgm-final")
            boss.dialog.sentence(self,"image:AE_Chang'e_pic","right","......",600,1)
            boss.dialog.sentence(self,"image:AE_Chang'e_pic","right","你太放肆了",600,1)
            boss.dialog.sentence(self,"image:AE_Chang'e_pic","right","自求多福吧，人类",600,1)
        else
        end
        if GetGlobal('player_name')=='marisa_player' then
            boss.dialog.sentence(self,"image:AE_Chang'e_pic","right","人类",600,1)
            boss.dialog.sentence(self,"image:AE_Chang'e_pic","right","广寒宫可不欢迎你",600,1)
            boss.dialog.sentence(self,"image:AE_marisa_face2","left","(哎呀被发现了)",600,1)
            boss.dialog.sentence(self,"image:AE_marisa_face1","left","(本来还想偷偷带走点宝贝呢...)",600,1)
            boss.dialog.sentence(self,"image:AE_Chang'e_pic","right","放肆！",600,1)
            boss.dialog.sentence(self,"image:AE_Chang'e_pic","right","你以为你站在哪里？",600,1)
            boss.dialog.sentence(self,"image:AE_Chang'e_pic","right","居然还敢说要带走几件宝贝？",600,1)
            boss.dialog.sentence(self,"image:AE_Chang'e_pic","right","你把我当成什么三教九流了？",600,1)
            boss.dialog.sentence(self,"image:AE_marisa_face2","left","不是蛤蟆吗...",600,1)
            boss.dialog.sentence(self,"image:AE_Chang'e_pic","right","......",600,1)
            LoadMusicRecord("AE_bgm-final");_play_music("AE_bgm-final")
            boss.dialog.sentence(self,"image:AE_Chang'e_pic","right","你太放肆了",600,1)
            boss.dialog.sentence(self,"image:AE_Chang'e_pic","right","自求多福吧，人类",600,1)
        else
        end
        if GetGlobal('player_name')=='sanae_player' then
            boss.dialog.sentence(self,"image:AE_sanae_face1","left","恩...月神的宫殿就是不一样啊",600,1)
            boss.dialog.sentence(self,"image:AE_sanae_face2","left","仅仅一个庭院就这么大了啊",600,1)
            boss.dialog.sentence(self,"image:AE_sanae_face1","left","有——人——吗？",600,1)
            boss.dialog.sentence(self,"image:AE_Chang'e_pic","right","......",600,1)
            boss.dialog.sentence(self,"image:AE_Chang'e_pic","right","一点都没有来客的样子...",600,1)
            boss.dialog.sentence(self,"image:AE_sanae_face1","right","啊！你就是月之神",600,1)
            boss.dialog.sentence(self,"image:AE_sanae_face1","right","克劳恩说的那个蛤蟆",600,1)
            boss.dialog.sentence(self,"image:AE_Chang'e_pic","right",".........",600,1)
            LoadMusicRecord("AE_bgm-final");_play_music("AE_bgm-final")
            boss.dialog.sentence(self,"image:AE_Chang'e_pic","right","人类",600,1)
            boss.dialog.sentence(self,"image:AE_Chang'e_pic","right","自求多福吧",600,1)
            boss.dialog.sentence(self,"image:AE_sanae_face1","left","诶诶诶？",600,1)
        else
        end
        if GetGlobal('player_name')=='wuer_player' then
            boss.dialog.sentence(self,"image:AE_wuer_face1","left","哦呀哦呀",600,1)
            boss.dialog.sentence(self,"image:AE_wuer_face2","left","这广寒宫还真像个迷宫啊",600,1)
            boss.dialog.sentence(self,"image:AE_Chang'e_pic","right","......",600,1)
            boss.dialog.sentence(self,"image:AE_wuer_face1","left","啊！晚上好啊月神大人",600,1)
            boss.dialog.sentence(self,"image:AE_Chang'e_pic","right","(这人类怎么回事)",600,1)
            boss.dialog.sentence(self,"image:AE_Chang'e_pic","right","广寒宫不欢迎你，出去",600,1)
            boss.dialog.sentence(self,"image:AE_wuer_face1","left","呀这还真是抱歉呢",600,1)
            boss.dialog.sentence(self,"image:AE_wuer_face1","left","如果您不尝试用点手段的话",600,1)
            boss.dialog.sentence(self,"image:AE_wuer_face1","left","我是不会乖乖听命的呢",600,1)
