            boss.dialog.sentence(self,"image:AE_Chang'e_pic","right","......",600,1)
            boss.dialog.sentence(self,"image:AE_Chang'e_pic","right","如你所愿",600,1)
            boss.dialog.sentence(self,"image:AE_Chang'e_pic","right","死在这里可不会有人帮你收尸",600,1)
            boss.dialog.sentence(self,"image:AE_wuer_face2","left","还真是冷酷呢...",600,1)
