function _tmp_sc:init()
    task.New(self,function()
        task.MoveTo(0,112,90,MOVE_DECEL)
        task._Wait(60)
        local i = 1
        do for _=1,_infinite do
            do local a,_d_a=(ran:Float(0,360)),(i*2) local v,_d_v=(8),(-0.1) for _=1,5 do
                do local aa,_d_aa=(a),(6) for _=1,60 do
                    last=New(_editor_class["AE_B2_1_B1"],self.x+10*cos(aa),self.y+10*sin(aa),aa,v)
                    task._Wait(0)
                aa=aa+_d_aa end end
                PlaySound("tan00",0.1,self.x/256,false)
                task._Wait(6)
            a=a+_d_a v=v+_d_v end end
            i=-i
            task._Wait(45-self.timer/60)
        end end
    end)
end
function _tmp_sc:del()
end
