_editor_class["void_marisa_disap"]=Class(_object)
_editor_class["void_marisa_disap"].init=function(self,_x,_y,_)
    self.x,self.y=_x,_y
	self.img="image:void_empty"
	self.layer=LAYER_TOP+10
	self.group=GROUP_GHOST
	self.hide=false
	self.bound=true
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    self.bound=false
    self.aph=255
    self.dtx=0
    task.New(self,function()
        do local a,_d_a=(255),(-255/15) local b,_d_b=(0),(40/15) for _=1,15 do
            self.aph=a
            self.dtx=b
            task._Wait(1)
        a=a+_d_a b=b+_d_b end end
        self.aph=0
        task._Wait(45)
        _del(self,true)
    end)
end
_editor_class["void_marisa_disap"].render=function(self)
    SetViewMode'ui'
    SetImageState('image:void_marisa_4','',Color(self.aph,255,255,255))
    Render('image:void_marisa_4',112-self.dtx,150,0,0.65,0.65)
