    laser.init(self,COLOR_BLUE,_x,_y,0,0,600,0,5,0,0)
    self.w=5
    self.rot=b.rot
    self.alpha=0.999
    if IsValid(b) then self.xt=b.x+level*wide*cos(b.rot+way*90) end
    if IsValid(b) then self.yt=b.y+level*wide*sin(b.rot+way*90) end
    task.New(self,function()
        do for _=1,wt do
            if IsValid(b) then self.rot=b.rot end
            if IsValid(b) then self.xt=b.x+level*wide*cos(b.rot+way*90) end
            if IsValid(b) then self.yt=b.y+level*wide*sin(b.rot+way*90) end
            if IsValid(b) then self.x=self.x+(self.xt-self.x)/sqrt(wt) end
            if IsValid(b) then self.y=self.y+(self.yt-self.y)/sqrt(wt) end
            self.w=self.w+(1-self.w)/sqrt(wt)
            task._Wait(1)
        end end
        do for _=1,10 do
            if IsValid(b) then self.rot=b.rot end
            self.w=self.w-1/10
            task._Wait(1)
        end end
        self.w=0
        _del(self,true)
    end)
end
