	self.img="leaf"
	self.layer=LAYER_ENEMY_BULLET
	self.group=GROUP_ENEMY
	self.hide=false
	self.bound=true
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    self.img='image:void_book_'..type
    self.hscale=0.25
    self.vscale=self.hscale
    self.grabbed=false
    self.v=v
    self.angle=angle
    self.grabid=0
    self.type=type
    self.omg=0.2
    task.New(self,function()
        _connect(b,self,0,true)
        do for _=1,_infinite do
            if IsValid(b) then
                if b.grabbing then
                    if Dist(b,self)<=100 then
                        self.grabbed=true
                        b.grabcount=b.grabcount+1
                        self.grabid=b.grabcount
                        b.grabitem[b.grabcount]=self
                        if true then break end
                    else
                    end
                else
                end
            else
            end
            task._Wait(1)
        end end
    end)
    task.New(self,function()
        do for _=1,_infinite do
            if self.grabbed==true then
                if true then break end
            else
            end
            task._Wait(1)
        end end
        do for _=1,_infinite do
            if IsValid(b) then if self.grabbed==true and b.grabbing==true then
            self.v=0
            self.x=self.x+(b.x-self.x)/5
            self.y=self.y+(b.y-self.y)/5 end end
            if IsValid(b) then
                if b.grabbing==false then
                    if IsValid(b) then b.grabitem[self.grabid]=nil end
                    if true then break end
                else
                end
            else
            end
            task._Wait(1)
        end end
    end)
    task.New(self,function()
        do for _=1,_infinite do
            self.x=self.x+self.v*cos(self.angle)
