_editor_class["void_boss2_none2_laser"].init=function(self,_x,_y,v,a,way,r,x0,y0,borninsc,b)
    laser.init(self,COLOR_YELLOW,_x,_y,0,64,512,0,12,12,0)
    self.changed=0
    self.truebound=true
    self.bound=false
    self.rot=a
    if IsValid(b) then self.boss=b end
    task.New(self,function()
        do for _=1,_infinite do
            if lstg.world.issc and self.changed==0 and not borninsc then
                self.changed=1
                self.x=self.x-lstg.world.centerxo
                self.y=self.y-lstg.world.centeryo
            else
            end
            if self.truebound==true then
                if abs(self.x)>256 or abs(self.y)>288 then
                    _del(self,true)
                else
                end
            else
            end
            task._Wait(1)
        end end
    end)
    task.New(self,function()
        do for _=1,_infinite do
            self.rot=self.rot+way*v
            if IsValid(b) then
            	self.x=b.x+r*cos(self.rot)
            	self.y=b.y+r*sin(self.rot)
            end
            task._Wait(1)
        end end
    end)
    task.New(self,function()
        laser._TurnOn(self,30,true,true)
        task._Wait(80)
        laser._TurnOff(self,20,true)
        _del(self,true)
    end)
end
