            self.x=self.x+self.v*cos(a)
            self.y=self.y+self.v*sin(a)
            task._Wait(1)
        end end
        PlaySound("kira00",0.1,self.x/256,false)
        do local nv,_d_nv=(0.2),((v-0.2)/120) local da,_d_da=(0),(self.rd/120) for _=1,120 do
            self.v=nv
            self.x=self.x+self.v*cos(a+da)
            self.y=self.y+self.v*sin(a+da)
            task._Wait(1)
        nv=nv+_d_nv da=da+_d_da end end
        do local da,_d_da=(self.rd),(0) for _=1,_infinite do
            self.x=self.x+self.v*cos(a+da)
            self.y=self.y+self.v*sin(a+da)
            task._Wait(1)
        da=da+_d_da end end
    end)
end
