_editor_class["void_boss2_lava_mid"]=Class(_object)
_editor_class["void_boss2_lava_mid"].init=function(self,_x,_y,nowr,tor,angle,v,x0,y0,rotway,layer,waittime,master)
    self.x,self.y=_x,_y
	self.img="image:void_mid_lava"
	self.layer=LAYER_ENEMY_BULLET
	self.group=GROUP_ENEMY_BULLET
	self.hide=false
	self.bound=false
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    _object.set_color(self,"mul+alpha",0,255,255,255)
    self.r=nowr
    self.tor=tor
    self.angle=angle
    self.layer=self.layer+layer
    self.waittime=waittime
    self.x0=x0
    self.y0=y0
    self.v=0
    self.scale=3
    self.group=GROUP_GHOST
    self.layer=LAYER_ENEMY_BULLET-1
    self.a=5
    self.b=self.a
    master.prelavacount=master.prelavacount+1
    master.prelava[master.prelavacount]=self
    self._index=1
    task.New(self,function()
        do local s,_d_s=(self.scale),(-2/40) local a,_d_a=(0),(255/30) for _=1,_infinite do
            self.rot=self.rot+127.5
            self.vscale=max(1,s)
            self.hscale=max(1,s)
            _object.set_color(self,"mul+alpha",min(255,a),255,255,255)
            task._Wait(1)
        s=s+_d_s a=a+_d_a end end
    end)
    task.New(self,function()
        task._Wait(30)
        self.group=GROUP_ENEMY_BULLET
    end)
    task.New(self,function()
        do for _=1,waittime do
            self.r=self.r+(self.tor-self.r)/sqrt(30)
            self.angle=self.angle+rotway*0.3
            self.x=x0+self.r*cos(self.angle)
            self.y=y0+self.r*sin(self.angle)
            task._Wait(1)
        end end
        local lockplayer=Angle(x0,y0,player.x,player.y)+ran:Float(-7.5,7.5)
        PlaySound("kira00",0.2,self.x/256,false)
        do local red,_d_red=(255),(-255/240) local t,_d_t=(0),(1) for _=1,1200 do
            _object.set_color(self,"mul+alpha",255,255,max(red,0),max(red,0))
            self.v=math.min(self.v+0.0075,3)
            self.x0=self.x0+self.v*cos(lockplayer)
            self.y0=self.y0+self.v*sin(lockplayer)
            self.angle=self.angle+rotway*0.3
            self.x=self.x0+self.r*cos(self.angle)
            self.y=self.y0+self.r*sin(self.angle)
            if t>=120 then
                if self.x>=195 then
                    last=New(_editor_class["void_boss2_flare_mid"],194,self.y,0,-1*self.dx,self.dy,-0.098,master)
                    PlaySound("msl",0.2,self.x/256,false)
                    _del(self,true)
                else
                    if self.x<=-195 then
                        last=New(_editor_class["void_boss2_flare_mid"],-194,self.y,0,-1*self.dx,self.dy,-0.098,master)
                        PlaySound("msl",0.2,self.x/256,false)
                        _del(self,true)
                    else
                    end
                end
            else
            end
            if t>=120 then
                if self.y<=-225 then
                    last=New(_editor_class["void_boss2_flare_mid"],self.x,-224,0,0.75*self.dx,-0.5*self.dy,-0.098,master)
                    PlaySound("msl",0.2,self.x/256,false)
                    _del(self,true)
                else
                end
            else
            end
            task._Wait(1)
        red=red+_d_red t=t+_d_t end end
    end)
end
_editor_class["void_boss2_lava_mid"].kill=function(self)
    New(item_faith_minor,self.x,self.y)
    	if self._index then New(BulletBreak,self.x,self.y,self._index) end


    self.class.base.kill(self)
end
_editor_class["void_boss2_lava_mid"].del=function(self)
    if self._index and BoxCheck(self,-192,192,-224,224) then New(BulletBreak,self.x,self.y,self._index) end
    self.class.base.del(self)
end
