_editor_class["void_boss2_pillar_main_N"]=Class(_object)
_editor_class["void_boss2_pillar_main_N"].init=function(self,_x,_y,master,way)
    self.x,self.y=_x,_y
	self.img="leaf"
	self.layer=LAYER_ENEMY_BULLET-1
	self.group=GROUP_INDES
	self.hide=false
	self.bound=false
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    _object.set_color(self,"",0,255,255,255)
    self.bound=false
    self.y=0
    self.scale=0
    self.scalet=1.5
    self.f1v=10
    self.f2v=16
    self.wfa=0
    self.rect=true
    self.a=32*self.scale
    self.b=448
    self.boss=master
    self.uratimer=ran:Int(0,512)
    task.New(self,function()
        if  way==-1 then
            do for _=1,2 do
                local a={}
                for i=1,4 do
                	a[i]=i
                end
                for i=#a,2,-1 do
                	local r,s=ran:Int(1,i),a[i]
                	a[i]=a[r]
                	a[r]=s
                end
                do local m,_d_m=(0),(1) for _=1,2 do
                    last=New(_editor_class["void_boss2_flare_mid3"],self.x+32*(a[(m%4)+1]-2.5)+ran:Int(-2,2),240,0,ran:Float(-0.25,0.25),0,-0.08,master)
                    task._Wait(6)
                m=m+_d_m end end
                task._Wait(0)
            end end
        else
        end
    end)
    task.New(self,function()
        if abs(self.x)<=224 then
            do for _=1,10 do
                last=New(_editor_class["void_boss2_flare_mid_2"],self.x+ran:Int(-20,20),-224,0,ran:Float(-0.25,0.25),ran:Float(1,4),-0.098,master)
                task._Wait(0)
            end end
        else
        end
        do for _=1,90 do
            local b=self.boss
            self.scale=min(self.scale+1/5,self.scalet)
            self.a=32*self.scale
            self.b=448
            do local i,_d_i=(1),(1) for _=1,b.prelavacount do
                if IsValid(b.prelava[i]) then
                    if abs(b.prelava[i].x-self.x)<32 then
                        last=New(_editor_class["void_boss2_flare_mid"],b.prelava[i].x,b.prelava[i].y,0,b.prelava[i].dx,b.prelava[i].dy,-0.098,self.boss)
                        PlaySound("msl",0.2,self.x/256,false)
                        _del(b.prelava[i],true)
                    else
                    end
                else
                end
                task._Wait(0)
            i=i+_d_i end end
            task._Wait(1)
        end end
        do for _=1,12 do
            self.wfa=min(self.wfa+255/10,255)
            self.scale=self.scale+(0-self.scale)/sqrt(12)
            self.a=32*self.scale
            self.b=448
            task._Wait(1)
        end end
