_editor_class["void_boss2_wall_N"]=Class(_object)
_editor_class["void_boss2_wall_N"].init=function(self,_x,_y,face,tx,ty,b)
    self.x,self.y=_x,_y
	self.img="image:void_goldearth"
	self.layer=LAYER_ENEMY_BULLET-5
	self.group=GROUP_INDES
	self.hide=false
	self.bound=true
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    _object.set_color(self,"",0,255,255,255)
    self.r=0 --inner range=outside range-75/2
    self.x0=self.x
    self.y0=self.y
    self.hscale=2
    self.vscale=self.hscale
    self.face=face
    self.invade=0
    self.wall={}
    for i=1,6 do --hp,working,hitted
    	self.wall[i]={}
    	self.wall[i].rgb=255
    	self.wall[i].color=Color(255,255,255,255)
    	if lstg.player.name=='Sanae' then self.wall[i].hp=50 else self.wall[i].hp=100 end
    	self.wall[i].hitted=0
    	self.wall[i].breaked=false
    	self.wall[i].working=true
    end
    task.New(self,function()
        do for _=1,_infinite do
            self.rot=self.rot+0.3
            for i=1,6 do
            	if self.wall[i].hp<=0 then
            		self.wall[i].color=Color(255,255,200,200)
            		self.wall[i].working=false
            	else
            		self.wall[i].rgb=min(255,self.wall[i].rgb+64)
            		self.wall[i].color=Color(255,self.wall[i].rgb,self.wall[i].rgb,self.wall[i].rgb)
            		self.wall[i].hitted=max(0,self.wall[i].hitted-1)
            	end
            end
            do local i,_d_i=(0),(1) for _=1,6 do
                if self.wall[i+1].working==false and self.wall[i+1].breaked==false then
                    PlaySound("enep00",0.4,self.x/256,false)
                    last=New(_editor_class["void_boss2_prewallbreak"],self.x,self.y,i,self.r,self.face)
                    if IsValid(b) then b.wallbreakcount=b.wallbreakcount+1 end
                    self.wall[i+1].breaked=true
                else
                end
                task._Wait(0)
            i=i+_d_i end end
            if self.wall[1].working==false and self.wall[2].working==false and self.wall[3].working==false and self.wall[4].working==false and self.wall[5].working==false and self.wall[6].working==false or self.invade>6 then
                _del(self,true)
            else
            end
            task._Wait(1)
        end end
    end)
    task.New(self,function()
        do local a,_d_a=(0),(255/30) local dx,_d_dx=(tx-self.x),(0) local dy,_d_dy=(ty-self.y),(0) local t,_d_t=(0),(1) for _=1,30 do
            self.x=self.x0+dx*(t/30)^0.9
            self.y=self.y0+dy*(t/30)^0.9
            self.hscale=self.hscale-1/30
            self.vscale=self.hscale
            _object.set_color(self,"",a,255,255,255)
            task._Wait(1)
        a=a+_d_a dx=dx+_d_dx dy=dy+_d_dy t=t+_d_t end end
        do for _=1,_infinite do
            misc.ShakeScreen(60, 1)
            PlaySound("don00",0.2,self.x/256,false)
            last=New(_editor_class["void_boss2_spread"],self.x,self.y,self.r)
            do local a,_d_a=(ran:Float(0,360)),(360/6) for _=1,6 do
                last=New(_editor_class["void_boss2_bigball"],self.x,self.y,1.5,a)
                PlaySound("tan00",0.1,self.x/256,false)
                task._Wait(0)
            a=a+_d_a end end
            do local t,_d_t=(0),(1) for _=1,55 do
                self.r=self.r+2*sin(t/60*180)
                task._Wait(1)
            t=t+_d_t end end
            self.invade=self.invade+1
            do local t,_d_t=(55),(1) for _=1,5 do
                self.r=self.r+2*sin(t/60*180)
                do local i,_d_i=(0),(1) for _=1,6*self.invade do
                    if self.wall[(i%6)+1].working==true then
                        local rd=ran:Float(-30,30)
                        local x,y=((self.r+75/4)/cos(abs(rd)))*cos(rd+((-i)*60+self.face)),((self.r+75/4)/cos(abs(rd)))*sin(rd+((-i)*60+self.face))
                        PlaySound("kira00",0.1,self.x/256,false)
                        last=New(_straight,ball_mid_c,COLOR_GREEN,self.x+x,self.y+y,ran:Float(1,5*max(3,4-self.invade)/6),Angle(self.x,self.y,self.x+x,self.y+y),false,1,true,true,0,false,0,0,0,false)
                    else
                    end
                    task._Wait(0)
                i=i+_d_i end end
                task._Wait(1)
            t=t+_d_t end end
            task._Wait(60)
            last=New(_editor_class["void_boss2_wallcharge"],self.x,self.y,_)
            PlaySound("ch02",0.2,self.x/256,false)
            task._Wait(60)
        end end
    end)
end
_editor_class["void_boss2_wall_N"].frame=function(self)
    for i=0,5,1 do
    	for _,o in ObjList(GROUP_PLAYER_BULLET)	do
    		if self.wall[i+1].working then
    			if ((-i)*60+self.face-30)%360 < ((-i)*60+self.face+30)%360 then
    				if Angle(self.x,self.y,o.x,o.y)%360 >= ((-i)*60+self.face-30)%360 and Angle(self.x,self.y,o.x,o.y)%360 <= ((-i)*60+self.face+30)%360 then
    					if Dist(self.x,self.y,o.x,o.y) <= (self.r+75/2)/cos(abs(Angle(self.x,self.y,o.x,o.y)-((-i)*60+self.face))) and
    						Dist(self.x,self.y,o.x,o.y) >= (self.r)/cos(abs(Angle(self.x,self.y,o.x,o.y)-((-i)*60+self.face))) then
    						if self.invade == 1 then self.wall[i+1].hp=self.wall[i+1].hp-o.dmg/2 end
    						if self.invade >= 2 then self.wall[i+1].hp=self.wall[i+1].hp-o.dmg end
    						if self.wall[i+1].hp<=100 then
    							self.wall[i+1].rgb=0
    						else
    							self.wall[i+1].rgb=128
    						end
    						PlaySound('nodamage',0.2,self.x/256)
    						if self.wall[i+1].hp<=100 then
    							PlaySound('damage01',0.2,self.x/256)
    						else
    							PlaySound('damage00',0.2,self.x/256)
    						end
    						if self.wall[i+1].hitted==0 then
    							New(_straight,ball_mid_c,COLOR_GREEN,o.x,o.y,ran:Float(1,3),Angle(self.x,self.y,o.x,o.y)+ran:Float(-15,15),false,1,true,true,0,false,0,0,0,false)
    							self.wall[i+1].hitted=4
    						end
    						if lstg.player.name == 'Reimu' or lstg.player.name == 'Marisa' then Kill(o)
    						elseif lstg.player.name=='Wuer' then if o.class==wuer_locked_bullet or o.class==wuer_support_fire then Kill(o) end end
    					end
    				end
    			else
    				if Angle(self.x,self.y,o.x,o.y)%360 >= ((-i)*60+self.face-30)%360 and Angle(self.x,self.y,o.x,o.y)%360 <= (((-i)*60+self.face+30)%360)+360 then
    					if Dist(self.x,self.y,o.x,o.y) <= (self.r+75/2)/cos(abs(Angle(self.x,self.y,o.x,o.y)-((-i)*60+self.face))) and
    						Dist(self.x,self.y,o.x,o.y) >= (self.r)/cos(abs(Angle(self.x,self.y,o.x,o.y)-((-i)*60+self.face))) then
    						if self.invade == 1 then self.wall[i+1].hp=self.wall[i+1].hp-o.dmg/2 end
    						if self.invade >= 2 then self.wall[i+1].hp=self.wall[i+1].hp-o.dmg end
    						if self.wall[i+1].hp<=100 then
    							self.wall[i+1].rgb=0
    						else
    							self.wall[i+1].rgb=128
    						end
    						PlaySound('nodamage',0.2,self.x/256)
    						if self.wall[i+1].hp<=100 then
    							PlaySound('damage01',0.2,self.x/256)
    						else
    							PlaySound('damage00',0.2,self.x/256)
    						end
    						if self.wall[i+1].hitted==0 then
    							New(_straight,ball_mid_c,COLOR_GREEN,o.x,o.y,ran:Float(1,3),Angle(self.x,self.y,o.x,o.y)+ran:Float(-15,15),false,1,true,true,0,false,0,0,0,false)
    							self.wall[i+1].hitted=4
    						end
    						if lstg.player.name == 'Reimu' or lstg.player.name == 'Marisa' then Kill(o)
    						elseif lstg.player.name=='Wuer' then if o.class==wuer_locked_bullet or o.class==wuer_support_fire then Kill(o) end end
    					end
    				end
    			end
    		end
    	end
    end
    for i=0,5,1 do
    	if self.wall[i+1].working then
    		if ((-i)*60+self.face-30)%360 < ((-i)*60+self.face+30)%360 then
    			if Angle(self.x,self.y,player.x,player.y)%360 >= ((-i)*60+self.face-30)%360 and Angle(self.x,self.y,player.x,player.y)%360 <= ((-i)*60+self.face+30)%360 then
    				if Dist(self.x,self.y,player.x,player.y) <= (self.r+75/2)/cos(abs(Angle(self.x,self.y,player.x,player.y)-((-i)*60+self.face))) and
    					Dist(self.x,self.y,player.x,player.y) >= (self.r)/cos(abs(Angle(self.x,self.y,player.x,player.y)-((-i)*60+self.face))) then
    					if player.death==0 and not player.dialog and not cheat then
    						if player.protect==0 then
    							PlaySound('pldead00',0.5)
    							player.death=100
    						end
    					end
    				end
    			end
    		else
    			if Angle(self.x,self.y,player.x,player.y)%360 >= ((-i)*60+self.face-30)%360 and Angle(self.x,self.y,player.x,player.y)%360 <= (((-i)*60+self.face+30)%360)+360 then
    				if Dist(self.x,self.y,player.x,player.y) <= (self.r+75/2)/cos(abs(Angle(self.x,self.y,player.x,player.y)-((-i)*60+self.face))) and
    					Dist(self.x,self.y,player.x,player.y) >= (self.r)/cos(abs(Angle(self.x,self.y,player.x,player.y)-((-i)*60+self.face))) then
    					if player.death==0 and not player.dialog and not cheat then
    						if player.protect==0 then
    							PlaySound('pldead00',0.5)
    							player.death=100
    						end
    					end
    				end
    			end
    		end
    	end
    end
    self.class.base.frame(self)
end
