    bullet.init(self,ball_light,COLOR_GRAY,true,true)
    self.x,self.y=_x,_y
    if type == 1  then
        ChangeBulletImage(self,ball_big,COLOR_GRAY)
    else
        if type == 2 then
            ChangeBulletImage(self,ball_mid,COLOR_GRAY)
        else
            if type == 3 then
                ChangeBulletImage(self,ball_mid,COLOR_GRAY)
            else
                if type >= 4 then
                    ChangeBulletImage(self,ball_small,COLOR_GRAY)
                else
                end
            end
        end
    end
    task.New(self,function()
        do for _=1,_infinite do
            self.rot=self.rot+1.7
            task._Wait(1)
        end end
    end)
    task.New(self,function()
        do for _=1,_infinite do
            self.x=self.x+v*cos(angle)
            self.y=self.y+v*sin(angle)
            task._Wait(1)
        end end
    end)
end
