    self.x,self.y=_x,_y
	self.img="image:void_watertree"
	self.layer=LAYER_ENEMY_BULLET
	self.group=GROUP_INDES
	self.hide=false
	self.bound=false
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    self.x0=self.x
    self.y0=self.y
    self.v=0
    self.rot=self.rot+ran:Float(0,360)
    task.New(self,function()
        do for _=1,_infinite do
            self.rot=self.rot+0.3
            task._Wait(1)
        end end
    end)
    task.New(self,function()
        do local a,_d_a=(0),(255/20) for _=1,20 do
            _object.set_color(self,"mul+add",a,255,255,255)
            task._Wait(1)
        a=a+_d_a end end
        do for _=1,_infinite do
            self.v=min(v,self.v+0.1)
            self.x=self.x+self.v*cos(angle)
            self.y=self.y+self.v*sin(angle)
            if abs(self.x)>300 then
                self.bound=true
            else
            end
            task._Wait(1)
        end end
    end)
    task.New(self,function()
        task._Wait(20)
        if plant==1 then
            PlaySound("tan00",0.1,self.x/256,false)
            last=New(_editor_class["void_boss2_treeseed_N"],self.x,self.y,0,0)
            last=New(_editor_class["void_boss2_rain"],self.x,self.y,(self.x-self.x0)/48,1)
        else
        end
        task._Wait(frequence)
        do for _=1,3 do
            PlaySound("tan00",0.1,self.x/256,false)
            last=New(_editor_class["void_boss2_rain"],self.x,self.y,(self.x-self.x0)/48,-1)
            last=New(_editor_class["void_boss2_rain"],self.x,self.y,(self.x-self.x0)/48,1)
            task._Wait(frequence)
        end end
        do for _=1,_infinite do
            PlaySound("tan00",0.1,self.x/256,false)
            last=New(_editor_class["void_boss2_flwseed_N"],self.x,self.y,(self.x-self.x0)/48,fireway,xc)
            last=New(_editor_class["void_boss2_rain"],self.x,self.y,(self.x-self.x0)/48,1)
            task._Wait(frequence)
            do for _=1,3 do
                PlaySound("tan00",0.1,self.x/256,false)
                last=New(_editor_class["void_boss2_rain"],self.x,self.y,(self.x-self.x0)/48,-1)
                last=New(_editor_class["void_boss2_rain"],self.x,self.y,(self.x-self.x0)/48,1)
                task._Wait(frequence)
            end end
            task._Wait(0)
        end end
    end)
end
