_editor_class["void_boss2_treeseed_N"]=Class(bullet)
_editor_class["void_boss2_treeseed_N"].init=function(self,_x,_y,v,angle)
    bullet.init(self,ball_light,COLOR_ORANGE,true,true)
    self.x,self.y=_x,_y
    self.group=GROUP_INDES
    self.rd=ran:Float(0,360)
    task.New(self,function()
        do for _=1,_infinite do
            if self.y<=-224 then
                self.vx=0
                self.vy=0
                self.y=-224
                if true then break end
            else
                self.vy=self.vy-0.046
            end
            task._Wait(1)
        end end
        task._Wait(60)
        last=New(_editor_class["void_boss2_treelead_N"],self.x,self.y,1,16,self.x,true,self.rd)
        last=New(_editor_class["void_boss2_treelead_N"],self.x,self.y,-1,16,self.x,nil,self.rd)
        PlaySound("kira01",0.1,self.x/256,false)
        last=New(_editor_class["void_boss2_treebreak"],self.x,self.y,_)
        _del(self,true)
    end)
end
