            task._Wait(1)
        end end
        PlaySound("kira00",0.1,self.x/256,false)
        do for _=1,120 do
            self.v=min(v,self.v+0.1)
            self.x=self.x+self.v*cos(self.angle)
            self.y=self.y+self.v*sin(self.angle)
            task._Wait(1)
        end end
        do for _=1,_infinite do
            self.v=self.v+0.005
            self.x=self.x+self.v*cos(self.angle)
            self.y=self.y+self.v*sin(self.angle)
            task._Wait(1)
        end end
    end)
end
