_editor_class["void_boss2_raincharge"]=Class(_object)
_editor_class["void_boss2_raincharge"].init=function(self,_x,_y,_)
    self.x,self.y=_x,_y
	self.img="image:void_charge"
	self.layer=LAYER_ENEMY_BULLET
	self.group=GROUP_GHOST
	self.hide=false
	self.bound=true
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    _object.set_color(self,"mul+add",0,0,0,255)
    self.scale=1.5

    self.hscale=self.scale
    self.vscale=self.hscale
    task.New(self,function()
        do local a,_d_a=(0),(255/60) local t,_d_t=(1),(1) for _=1,60 do
            local k=4
            local m=1
            _object.set_color(self,"mul+add",255*((t/60)^(m*2)),0,0,255)
            self.hscale=self.scale*(1-(t/60)^k)
            self.vscale=self.hscale

            task._Wait(1)
        a=a+_d_a t=t+_d_t end end
        _del(self,true)
    end)
end
