_editor_class["void_boss2_windfire_N"]=Class(bullet)
_editor_class["void_boss2_windfire_N"].init=function(self,_x,_y,r,rc,angle,xc,yc,b,way)
    bullet.init(self,water_drop,COLOR_RED,true,true)
    self.x,self.y=_x,_y
    self.bound=false
    self.navi=true
    self.thetat=ran:Float(0,360)
    self.r=r
    self.rc=rc
    self.rcv=0
    self.rca=0
    self.rr=75
    self.rt=self.rc+self.rr*sin(self.thetat)
    self.xc=xc
    self.yc=yc
    self.angle=angle
    self.ome=ran:Float(0.25,0.5)
    self.protect=0
    b.windfirecount=b.windfirecount+1
    b.windfire[b.windfirecount]=self
    task.New(self,function()
        do local t,_d_t=(0),(1) local a,_d_a=(0),(self.ome/240/2) for _=1,240 do
            local maxv=(self.rt-r)*5/600
            self.angle=self.angle+min(self.ome,a)*way
            self.r=self.r+min(maxv,(self.rt-self.r)/(40/0.75))
            self.x=self.xc+self.r*cos(self.angle)
            self.y=self.yc+self.r*sin(self.angle)
            task._Wait(1)
        t=t+_d_t a=a+_d_a end end
        do local t,_d_t=(0),(1) local a,_d_a=(self.ome/2),(self.ome/240/2) for _=1,_infinite do
            self.rcv=self.rcv+self.rca
            self.rc=self.rc+self.rcv
            self.thetat=self.thetat+0.75*min(1,t/120)
            self.rr=max(25,self.rr+min(1,t/120)*(25-self.rr)/(40/0.75))
            self.rt=self.rc+self.rr*sin(self.thetat)
            local maxv=(self.rt-r)*5/600
            self.angle=self.angle+min(self.ome,a)*way
            self.r=self.r+(self.rt-self.r)/2*min(1,t/120)
            self.x=self.xc+self.r*cos(self.angle)
            self.y=self.yc+self.r*sin(self.angle)
            if self.r > 600 then
                _del(self,true)
            else
            end
            task._Wait(1)
        t=t+_d_t a=a+_d_a end end
    end)
end
_editor_class["void_boss2_windfire_N"].frame=function(self)
    if lstg.player.death>0 then
        self.protect=60
    else
    end
    if self.protect>0 then
        self.group=GROUP_INDES
    else
        self.group=GROUP_ENEMY_BULLET
    end
    self.protect=self.protect-1
    self.class.base.frame(self)
end
