_editor_class["void_boss2_moonrune"]=Class(_object)
_editor_class["void_boss2_moonrune"].init=function(self,_x,_y,b)
    self.x,self.y=_x,_y
	self.img="image:void_moonrune"
	self.layer=LAYER_ENEMY_BULLET-1
	self.group=GROUP_GHOST
	self.hide=false
	self.bound=true
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    _object.set_color(self,"",0,255,255,255)
    if IsValid(b) then b.rune=self end
    if IsValid(b) then self.boss=b end
    self.scale=0
    self.phi=90
    self.angle=-90
    self.spin=0
    self.spinv=0.5
    self.controlling=nil
    --command
    self.lockon=0
    self.lockhold=0
    self.lockratio=1/240
    self.laserfire=0
    task.New(self,function()
        do for _=1,_infinite do
            if IsValid(b) then self.x=b.x end
            if IsValid(b) then self.y=b.y end
            self.scale=self.scale+(1.5-self.scale)/40
            self.spin=self.spin+self.spinv
            self.phi=self.phi+(15-self.phi)/80
            if self.lockon>0 then
                if IsValid(b) then if self.lockhold==0 then self.angle=self.angle+(max(-120,min(-60,Angle(b,lstg.player)))-self.angle)*self.lockratio else self.angle=self.angle end end
            else
                self.angle=self.angle+(-90-self.angle)/240
            end
            task._Wait(1)
        end end
    end)
    task.New(self,function()
        task._Wait(120)
        self.group=GROUP_INDES
    end)
    task.New(self,function()
        do for _=1,_infinite do
            if IsValid(b) then
                if b.breakdown==true then
                    _del(self,true)
                else
                end
            else
            end
            task._Wait(1)
        end end
    end)
end
_editor_class["void_boss2_moonrune"].render=function(self)
    local r=196*self.scale
    local tr=480/cos(45)
    RenderTexture('image:void_moonrune','mul+add',	{self.x+r*cos(self.angle+90)+r*sin(self.phi)*cos(self.angle),		self.y+r*sin(self.angle+90)+r*sin(self.phi)*sin(self.angle),0.5,	512+tr*cos(-135+self.spin),512+tr*sin(-135+self.spin),Color(60+195*sin(self.phi),255,255,255)},
    												{self.x+r*cos(self.angle-90)+r*sin(self.phi)*cos(self.angle),		self.y+r*sin(self.angle-90)+r*sin(self.phi)*sin(self.angle),0.5,	512+tr*cos(-45+self.spin),512+tr*sin(-45+self.spin),Color(60+195*sin(self.phi),255,255,255)},
    												{self.x+r*cos(self.angle-90)+r*sin(self.phi)*cos(self.angle+180),	self.y+r*sin(self.angle-90)+r*sin(self.phi)*sin(self.angle+180),0.5,512+tr*cos(45+self.spin),512+tr*sin(45+self.spin),Color(255,255,255,255)},
    												{self.x+r*cos(self.angle+90)+r*sin(self.phi)*cos(self.angle+180),	self.y+r*sin(self.angle+90)+r*sin(self.phi)*sin(self.angle+180),0.5,512+tr*cos(135+self.spin),512+tr*sin(135+self.spin),Color(255,255,255,255)}
    			)
end
