    self.uratimer0=self.uratimer
    self.f1st=0
    self.f2st=0
    self.tailsize=0.75
    task.New(self,function()
        last=New(_editor_class["void_boss2_moonpillar_mask"],self.x,self.y,self)
        do for _=1,10 do
            self.tailsize=self.tailsize+1.25/10
            task._Wait(1)
        end end
        do for _=1,170 do
            self.tailsize=self.tailsize+(0.5-self.tailsize)/120
            task._Wait(1)
        end end
    end)
    task.New(self,function()
        do for _=1,_infinite do
            if self.longp==1 then
                self.f1st=(self.uratimer0*self.f1v-self.uratimer*6)%512
                self.f2st=(self.uratimer0*self.f2v)%512
                self.uratimer=1
                if true then break end
            else
            end
            task._Wait(1)
        end end
    end)
    task.New(self,function()
        do local i,_d_i=(0),(1) local ra,_d_ra=(ran:Float(0,360)),(3.1) for _=1,180 do
            self.long=min(self.longlimit,self.long+16)
            self.longhead=min(self.longheadL,self.longhead+16)
            self.longp=self.long/self.longlimit
            self.scale=min(self.scale+1/5,self.scalet)
            if IsValid(b) then
                self.x=b.x
                self.y=b.y
            else
            end
            task._Wait(1)
        i=i+_d_i ra=ra+_d_ra end end
        do for _=1,12 do
            self.wfa=min(self.wfa+255/10,255)
            self.scale=self.scale+(0-self.scale)/sqrt(12)
            self.tailsize=self.tailsize+(0-self.tailsize)/sqrt(12)
            if IsValid(b) then self.x=b.x self.y=b.y end
            task._Wait(1)
        end end
        self.scale=0
        self.tailsize=0
        do local a,_d_a=(ran:Float(0,360)),(36) for _=1,10 do
            last=New(_editor_class["void_boss2_lightball"],self.x,self.y,1,a)
            last=New(_straight,ball_light,COLOR_BLUE,self.x,self.y,3,a,false,0,true,true,0,false,0,0,0,false)
            task._Wait(0)
        a=a+_d_a end end
        _del(self,true)
    end)
end
_editor_class["void_boss2_moonpillar_main"].frame=function(self)
    self.uratimer=self.uratimer+1
    local x=lstg.player.x-self.x
    	local y=lstg.player.y-self.y
    	local rot=self.angle
    	local dist=2
    	x,y=x*cos(rot)+y*sin(rot),y*cos(rot)-x*sin(rot)
    	y=abs(y)
    	if x>0 then
    		if x<self.long-15 then
    			if y<32*self.scale then lstg.player.class.colli(player,self) end
    		end
    		if self.timer%2==0 then
    			if x<self.long then
    				if y<32*self.scale+16 then item.PlayerGraze() lstg.player.grazer.grazed=true end
    			end
    		end
    	end
    self.class.base.frame(self)
end
