_editor_class["void_boss2_moonpillar_mask"]=Class(_object)
_editor_class["void_boss2_moonpillar_mask"].init=function(self,_x,_y,b)
    self.x,self.y=_x,_y
	self.img="image:void_moonflare_mask"
	self.layer=LAYER_BG+1
	self.group=GROUP_GHOST
	self.hide=false
	self.bound=true
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    _object.set_color(self,"",0,255,255,255)
    self.tailsize=1.5
    self.hscale=self.tailsize
    self.vscale=self.hscale
    task.New(self,function()
        do local a,_d_a=(0),(255/10/3) for _=1,10 do
            _object.set_color(self,"",a,255,255,255)
            self.tailsize=self.tailsize+2.5/10
            if IsValid(b) then self.x=b.x self.y=b.y end
            self.hscale=self.tailsize
            self.vscale=self.hscale
            task._Wait(1)
        a=a+_d_a end end
        do for _=1,170 do
            self.tailsize=self.tailsize+(1.5-self.tailsize)/120
            if IsValid(b) then self.x=b.x self.y=b.y end
            self.hscale=self.tailsize
            self.vscale=self.hscale
            task._Wait(1)
        end end
        do for _=1,12 do
            self.tailsize=self.tailsize+(0-self.tailsize)/sqrt(12)
            if IsValid(b) then self.x=b.x self.y=b.y end
            self.hscale=self.tailsize
            self.vscale=self.hscale
            task._Wait(1)
        end end
        self.tailsize=0
        _del(self,true)
    end)
    task.New(self,function()
        do for _=1,_infinite do
            if IsValid(b) then
            else
                _del(self,true)
            end
            task._Wait(1)
        end end
    end)
end
_editor_class["void_boss2_moonstone_N"]=Class(_object)
_editor_class["void_boss2_moonstone_N"].init=function(self,_x,_y,b,oangle)
    self.x,self.y=_x,_y
	self.img="leaf"
	self.layer=LAYER_ENEMY_BULLET-1
	self.group=GROUP_GHOST
	self.hide=false
	self.bound=true
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    b.stonecount=b.stonecount+1
    b.stone[b.stonecount]=self
    self.bound=false
    self.scale=0.75
    self.angle=-90
    self.spin=oangle
    self.spinv=0.5
    self.phi=90
    self.range=100
    _object.set_color(self,"",0,255,255,255)
    --command
    self.lockon=0
    self.lockhold=0
    self.lockratio=1/240
    self.laseraim=0
    self.laserfire=0
    self.firetype={0,0,0}
    task.New(self,function()
        do for _=1,_infinite do
            self.range=self.range+(192-self.range)/40
            self.spin=self.spin+self.spinv
            self.phi=self.phi+(15-self.phi)/80
            self.scale=0.625+0.125*sin((self.phi-15)*1.2)+0.125*cos((self.phi-15)*1.2)*sin(self.spin)
            self.laseraim=max(0,self.laseraim-1)
            self.firetype[1]=max(0,self.firetype[1]-1)
            self.firetype[2]=max(0,self.firetype[2]-1)
            self.firetype[3]=max(0,self.firetype[3]-1)
            if self.lockon>0 then
                if self.lockhold==0 then self.angle=self.angle+(max(-120,min(-60,Angle(b,lstg.player)))-self.angle)*self.lockratio else self.angle=self.angle end
            else
                self.angle=self.angle+(-90-self.angle)/240
            end
            self.x=b.x+self.range*cos(self.spin)*cos(self.angle+90)-(self.range*sin(self.phi))*sin(self.spin)*sin(self.angle+90)
            self.y=b.y+self.range*cos(self.spin)*sin(self.angle+90)+(self.range*sin(self.phi))*sin(self.spin)*cos(self.angle+90)
            if self.laseraim>0 then
                last=New(_editor_class["void_boss2_moonwarning"],self.x,self.y,self,b,self.laseraim)
                last=New(_editor_class["void_boss2_moonwarning2"],self.x,self.y,self,b,self.laseraim)
                self.laseraim=0
            else
            end
            if self.laserfire>0 then
                PlaySound("void_moonlaser",3.0,self.x/256,false)
                last=New(_editor_class["void_boss2_moonpillar_main"],self.x,self.y,self.angle,self)
                self.laserfire=0
            else
            end
            task._Wait(1)
        end end
    end)
    task.New(self,function()
        do for _=1,_infinite do
            do for _=1,1 do
                if self.firetype[1]>0 then
                    if self.timer%2==0 then
                        PlaySound("tan00",0.05,self.x/256,false)
                    else
                    end
                    last=New(_editor_class["void_boss2_moonhigh_N"],self.x,self.y,2.5,self.angle)
                else
                end
                task._Wait(1)
            end end
            do for _=1,7 do
                if self.firetype[1]>0 then
                    if self.timer%2==0 then
                        PlaySound("tan00",0.05,self.x/256,false)
                    else
                    end
                else
                end
                task._Wait(1)
            end end
            task._Wait(0)
        end end
    end)
    task.New(self,function()
        do for _=1,_infinite do
            do local a,_d_a=(ran:Float(0,360)),(360/5) for _=1,5 do
                if self.firetype[2]>0 then
                    PlaySound("tan00",0.1,self.x/256,false)
                    last=New(_straight,ball_mid_c,COLOR_BLUE,self.x,self.y,1.75,a,false,0,true,true,0,false,0,0,0,false)
                    last=New(_straight,ball_big,COLOR_BLUE,self.x,self.y,2.5,a,false,0,true,true,0,false,0,0,0,false)
                else
                end
                task._Wait(0)
            a=a+_d_a end end
            task._Wait(60)
        end end
    end)
    task.New(self,function()
        do local c,_d_c=(ran:Int(0,7)),(1) local d,_d_d=(ran:Float(0,360)),(30) for _=1,_infinite do
            do local a,_d_a=(0),(90) for _=1,4 do
                if self.firetype[3]>0 then
                    local wid=c%8
                    if wid>4 then wid=8-wid end
                    PlaySound("tan00",0.1,self.x/256,false)
                    do local b,_d_b=(0),(1.5) for _=1,wid+1 do
                        last=New(_straight,water_drop,COLOR_BLUE,self.x,self.y,1.75+wid*0.1,a+b+d,false,0,true,true,0,false,0,0,0,false)
                        task._Wait(0)
                    b=b+_d_b end end
                else
                end
                task._Wait(0)
            a=a+_d_a end end
            task._Wait(50)
        c=c+_d_c d=d+_d_d end end
    end)
    task.New(self,function()
        task._Wait(120)
        self.group=GROUP_INDES
    end)
    task.New(self,function()
        do for _=1,_infinite do
            if b.breakdown==true then
                _del(self,true)
            else
            end
            task._Wait(1)
        end end
    end)
end
_editor_class["void_boss2_moonstone_N"].render=function(self)
    Render('void_stone_moon'..math.floor(self.timer/3)%10,self.x,self.y,0,self.scale)
    self.class.base.render(self)
end
_editor_class["void_boss2_moonstone_N"].kill=function(self)
    last=New(_editor_class["void_boss2_moonbreak"],self.x,self.y,_)
    self.class.base.kill(self)
end
_editor_class["void_boss2_moonstone_N"].del=function(self)
    last=New(_editor_class["void_boss2_moonbreak"],self.x,self.y,_)
    self.class.base.del(self)
end
