    self.vx=v*cos(angle)
    self.vy=v*sin(angle)
    self.reflected=0
    task.New(self,function()
        do for _=1,_infinite do
            if abs(self.x)>192 and self.reflected<1 then
                PlaySound("kira00",0.1,self.x/256,false)
                self.x=191*self.x/abs(self.x)
                self.vx=(-1)*self.vx
                self.reflected=self.reflected+1
            else
            end
            if self.y>224 and self.reflected<1 then
                PlaySound("kira00",0.1,self.x/256,false)
                self.y=223
                self.vy=(-1)*self.vy
                self.reflected=self.reflected+1
            else
            end
            task._Wait(1)
        end end
    end)
end
