    self.ir=8
    self.outr=0
    self.innr=max(0,self.outr-22)
    self.midr=self.innr+(self.outr-self.innr)/2
    self.a=self.midr
    self.b=self.a
    self.tcyc=10
    self.rot=-90
    self.color={
    Color(255,255,0,0),
    Color(255,255,127,0),
    Color(255,255,255,0),
    Color(255,0,0,255),
    Color(255,0,255,0)
    }
    self.bound=false
    self.frot=Angle(cx,cy,self.x,self.y)
    self.fway=6
    self.fint=28
    task.New(self,function()
        do for _=1,60+waittime do
            self.rot=self.rot-2.8*way
            self.outr=self.outr+(size-self.outr)/15
            self.innr=max(0,self.outr-22)
            self.midr=self.innr+(self.outr-self.innr)/2
            self.a=self.midr
            self.b=self.a
            task._Wait(1)
        end end
        do local a,_d_a=(0),(0.025) for _=1,_infinite do
            self.rot=self.rot-2.8*way
            self.outr=max(0,self.outr-a)
            self.innr=max(0,self.outr-22)
            self.midr=self.innr+(self.outr-self.innr)/2
            self.a=self.midr
            self.b=self.a
            if self.outr==0 then
                if lstg.tmpvar.boss.hp<2800 then
                    PlaySound("tan00",0.1,self.x/256,false)
                    PlaySound("kira00",0.1,self.x/256,false)
                    do local d,_d_d=(ran:Float(0,360)),(360/20) for _=1,20 do
                        last=New(_editor_class["void_boss2_five_ellipse"],self.x,self.y,type,1.5,d)
                        task._Wait(0)
                    d=d+_d_d end end
                else
                end
                if true then break end
            else
            end
            task._Wait(1)
        a=a+_d_a end end
        _del(self,true)
    end)
    task.New(self,function()
        task._Wait(60)
        task._Wait(waittime)
        do local b,_d_b=(0),((360/self.fway/3)/(self.fint*2.8)*way) for _=1,_infinite do
            PlaySound("tan00",0.1,self.x/256,false)
            do local a,_d_a=(self.frot),(360/self.fway) for _=1,self.fway do
                last=New(_editor_class["void_boss2_five_bullet"],self.x+self.midr*cos(a+b),self.y+self.midr*sin(a+b),type,20,a+90*way+b)
                task._Wait(0)
            a=a+_d_a end end
            self.frot=self.frot-2.8*self.fint*way
            task._Wait(self.fint)
        b=b+_d_b end end
    end)
end
