    												self.x+self.innr*cos(self.rot+(c-1)*360/self.tcyc+(i)*360/self.tcyc/self.ir),		self.y+self.innr*sin(self.rot+(c-1)*360/self.tcyc+(i)*360/self.tcyc/self.ir),0.5,
    												self.x+self.innr*cos(self.rot+(c-1)*360/self.tcyc+(i-1)*360/self.tcyc/self.ir),		self.y+self.innr*sin(self.rot+(c-1)*360/self.tcyc+(i-1)*360/self.tcyc/self.ir),0.5
    )
    end
    end
    self.class.base.render(self)
end
