_editor_class["void_boss2_five_bullet"].init=function(self,_x,_y,type,v,angle)
    self.x,self.y=_x,_y
	self.img="leaf"
	self.layer=LAYER_ENEMY_BULLET
	self.group=GROUP_ENEMY_BULLET
	self.hide=false
	self.bound=true
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    _object.set_color(self,"",0,255,255,255)
    self.v=v
    self.vx=0
    self.vy=0
    self.rot=angle
    self.type=type
    self.hscale=0
    self.vscale=0
    self.fscale=0.5
    self.aph=0
    self.rot=angle
    self.bound=false
    self.a=8*0.5
    self.b=8*0.375
    task.New(self,function()
        do for _=1,10 do
            self.fscale=self.fscale+(0-self.fscale)/10
            task._Wait(1)
        end end
        self.fscale=0
        self.vx=self.v*cos(angle)
        self.vy=self.v*sin(angle)
        do for _=1,30 do
            self.aph=self.aph+(255-self.aph)/2
            self.hscale=self.hscale+(0.5-self.hscale)/2
            self.vscale=self.vscale+(0.375-self.vscale)/10
            self.v=self.v+(0.5-self.v)/sqrt(30)
            self.vx=self.v*cos(angle)
            self.vy=self.v*sin(angle)
            task._Wait(1)
        end end
        do for _=1,_infinite do
            self.aph=self.aph+(255-self.aph)/2
            self.hscale=self.hscale+(0.5-self.hscale)/2
            self.vscale=self.vscale+(0.375-self.vscale)/10
            self.v=self.v+0.0125
            self.vx=self.v*cos(angle)
            self.vy=self.v*sin(angle)
            if abs(self.x)>224 or abs(self.y)>256 then
                _del(self,true)
            else
            end
            task._Wait(1)
        end end
    end)
end
_editor_class["void_boss2_five_bullet"].render=function(self)
    if self.fscale~=0 then Render('image:void_five_bulletflash_'..self.type,self.x,self.y,self.timer*13,self.fscale) end
    if self.fscale==0 then SetImageState('void_five_bullet_'..self.type..math.floor(self.timer/2)%10,'mul+add',Color(self.aph,255,255,255)) Render('void_five_bullet_'..self.type..math.floor(self.timer/2)%10,self.x,self.y,self.rot,self.hscale,self.vscale) end
end
