    if type==1 then
        ChangeBulletImage(self,grain_a,COLOR_RED)
    else
        if type==2 then
            ChangeBulletImage(self,grain_a,COLOR_ORANGE)
        else
            if type==3 then
                ChangeBulletImage(self,grain_a,COLOR_GOLDEN_YELLOW)
            else
                if type==4 then
                    ChangeBulletImage(self,grain_a,COLOR_BLUE)
                else
                    if type==5 then
                        ChangeBulletImage(self,grain_a,COLOR_GREEN)
                    else
                    end
                end
            end
        end
    end
    self.rot=angle
    self.v=5
    self.vx=self.v*cos(angle)
    self.vy=self.v*sin(angle)
    task.New(self,function()
        do for _=1,60 do
            self.v=self.v+(v-5)/60
            self.vx=self.v*cos(angle)
            self.vy=self.v*sin(angle)
            task._Wait(1)
        end end
    end)
end
