_editor_class["akuma"]=Class(_spellcard_background)
_editor_class["akuma"].init=function(self)
    _spellcard_background.init(self)
end
_editor_class["akuma"]=Class(_spellcard_background)
_editor_class["akuma"].init=function(self)
	_spellcard_background.init(self)
	self.aph=0
	if IsValid(_boss) then
        _boss.fxr=160 _boss.fxg=160 _boss.fxb=255
	end
	self.fxsize=0
    CreateRenderTarget('koakumabg')
end
_editor_class["akuma"].frame=function(self)
	if lstg.tmpvar.bg and lstg.tmpvar.bg.hide==true then
		self.fxsize=min(self.fxsize+2,200)
	else
		self.fxsize=max(self.fxsize-2,0)
	end
end
_editor_class["akuma"].render=function(self)
	SetViewMode'world'
	SetImageState('image:void_boss1bg','',Color(255*self.alpha,255,255,255))
	SetImageState('image:void_boss1bgb','mul+add',Color(255*self.alpha,255,255,255))
	self.aph=min(1,self.aph+1/90)
	if self.alpha>0 then
		local showboss = IsValid(_boss) and lstg.tmpvar.bg and lstg.tmpvar.bg.hide==true
		if showboss and self.aph==1 then
			PushRenderTarget('koakumabg')
		end
		Render('image:void_boss1bg',-196,224,self.timer*0.05,1.25,1.25)
        Render('image:void_boss1bgb',-196,224,self.timer*(-0.1),2.5,2.5)
		if showboss and self.aph==1 then
			PopRenderTarget('koakumabg')
			local x,y = WorldToScreen(_boss.x,_boss.y)
			local x1 = x * screen.scale
			local y1 = (screen.height - y) * screen.scale
			local fxa = _boss.fxa or 125
			local fxr = _boss.fxr or 163
			local fxg = _boss.fxg or 73
			local fxb = _boss.fxb or 164
			PostEffect('koakumabg',"distortion_colorburn", "mul+alpha", {
				centerX = x1,
				centerY = y1,
				size = _boss.aura_alpha*self.fxsize*lstg.scale_3d,
				color = Color(fxa*self.fxsize/200,fxr,fxg,fxb),
				colorsize = _boss.aura_alpha*200*lstg.scale_3d,
				arg=1500*_boss.aura_alpha/128*lstg.scale_3d,
				timer = self.timer
			})
		end
	end
end
