        SetImageState('image:void_boss2bgb','mul+alpha',Color(max(0,255*sin(self.timer*0.75))*self.alpha,255,255,255))
        Render('image:void_boss2bgb',self.x,0+(self.timer*4)%448,0,self.hscale*384/256,self.vscale*448/256)
        Render('image:void_boss2bgb',self.x,-448+(self.timer*4)%448,0,self.hscale*384/256,self.vscale*448/256)
        Render('image:void_boss2bgb',self.x,448+(self.timer*4)%448,0,self.hscale*384/256,self.vscale*448/256)
