function _tmp_sc:init()
    self.rm=ran:Sign()
    task.New(self,function()
        do for _=1,_infinite do
            task._Wait(180)
            do for _=1,6 do
                last=New(_editor_class["void_boss1_magic_N"],self.x,self.y,_)
                task._Wait(10)
            end end
            task._Wait(0)
        end end
    end)
    task.New(self,function()
        task.MoveTo(0,96,0,MOVE_NORMAL)
        do local ct,_d_ct=(0),(1) for _=1,_infinite do
            PlaySound("power02",0.1,self.x/256,false)
            do local b,_d_b=(ran:Float(0,360)),(13*(-1)^ct) for _=1,8 do
                PlaySound("tan00",0.1,self.x/256,false)
                do local a,_d_a=(0),(360/8) for _=1,8 do
                    last=New(_editor_class["void_boss1_none_blue"],self.x,self.y,0.5,a+b,false)
                    task._Wait(0)
                a=a+_d_a end end
                task._Wait(20)
            b=b+_d_b end end
            task._Wait(20)
            if self.x<0 then
                task.MoveTo(self.x+96,ran:Int(96,160),60,MOVE_DECEL)
