        lstg.world.centerxo=lstg.world.centerx
        lstg.world.centeryo=lstg.world.centery
        lstg.world.centerxt=0
        lstg.world.centeryt=0
        lstg.world.centerx=0
        lstg.world.centery=0
        self.sa=-45
        task.MoveTo(0,144,60,MOVE_NORMAL)
    end)
    task.New(self,function()
        task._Wait(180)
        do local count,_d_count=(1),(1) for _=1,_infinite do
            local lsa=ran:Float(30,45)
            if count<=1 then self.sa=-45 else self.sa=ran:Float(-45,-1) end
            PlaySound("option",0.1,self.x/256,false)
            do local a,_d_a=(self.sa),(-self.sa-self.sa) local w,_d_w=(0),(1) local rd,_d_rd=(ran:Float(0,360)),(0) for _=1,2 do
                last=New(_editor_class["void_boss1_beast_N"],self.x,self.y,a,3,(-1)^w,lsa)
                task._Wait(0)
            a=a+_d_a w=w+_d_w rd=rd+_d_rd end end
            do local a,_d_a=(180-self.sa),(-2*abs(180-self.sa)) local w,_d_w=(1),(1) local rd,_d_rd=(ran:Float(0,360)),(0) for _=1,2 do
                last=New(_editor_class["void_boss1_beast_N"],self.x,self.y,a,3,(-1)^w,lsa)
                task._Wait(0)
            a=a+_d_a w=w+_d_w rd=rd+_d_rd end end
            task._Wait(120)
            task.MoveToPlayer(120,-96,96,112,144,64,96,8,16,MOVE_ACC_DEC,MOVE_RANDOM)
            task._Wait(120)
        count=count+_d_count end end
    end)
