    lstg.world.scale=384
    lstg.world.vscale=448
    lstg.world.issc=false
    lstg.world.l=-224
    lstg.world.r=224
    lstg.world.b=-256
    lstg.world.t=256
    lstg.world.boundl=-256
    lstg.world.boundr=256
    lstg.world.boundb=-288
    lstg.world.boundt=288
    lstg.world.pl=-224
    lstg.world.pr=224
    lstg.world.pb=-256
    lstg.world.pt=256
    lstg.world.abscx=0
    lstg.world.abscy=0
    New(item_extend,self.x-32,self.y)
    New(item_bomb,self.x+32,self.y)
end
