        task._Wait(60)
        last=New(_editor_class["void_boss1_gateopen"],self.x,self.y,90,16)
        last=New(_editor_class["void_boss1_gateopen"],self.x-16,self.y-16,90,16)
        last=New(_editor_class["void_boss1_gateopen"],self.x+16,self.y-16,90,16)
        last=New(_editor_class["void_boss1_gateopen"],self.x-32,self.y-32,90,16)
        last=New(_editor_class["void_boss1_gateopen"],self.x+32,self.y-32,90,16)
        last=New(_editor_class["void_boss1_gateopen"],self.x-48,self.y-48,90,16)
        last=New(_editor_class["void_boss1_gateopen"],self.x+48,self.y-48,90,16)
        PlaySound("lazer01",0.1,self.x/256,false)
        task._Wait(30)
        last=New(_editor_class["void_boss1_gatespark"],self.x,self.y,_)
        PlaySound("don00",0.1,self.x/256,false)
        misc.ShakeScreen(120, 5)
        last=New(_editor_class["void_boss1_mask"],0,512,self)
        task.MoveTo(0,144,60,MOVE_ACC_DEC)
        do for _=1,774 do
            last=New(_editor_class["void_boss1_book"],ran:Int(-192,192),255,self,ran:Int(1,5),3,-90)
            task._Wait(5)
        end end
        PlaySound("explode",0.1,self.x/256,false)
        PlaySound("alert",1,self.x/256,true)
        do for _=1,1200 do
            last=New(_editor_class["void_boss1_book"],ran:Int(-192,192),255,self,ran:Int(1,5),3,-90)
            task._Wait(1)
        end end
    end)
    task.New(self,function()
        task._Wait(180)
        task._Wait(240)
        do for _=1,_infinite do
            PlaySound("hyz_charge00",0.5,self.x/256,true)
            last=New(_editor_class["void_boss1_grabcharge"],self.x,self.y,self)
            self.grabbing=true
            task.MoveToPlayer(30,-96,96,112,144,96,112,8,16,MOVE_ACC_DEC,MOVE_RANDOM)
            PlaySound("ophide",0.4,self.x/256,true)
            PlaySound("explode",0.4,self.x/256,false)
            do local i,_d_i=(1),(1) local a,_d_a=(Angle(self,lstg.player)-self.waveway*(1-self.grabcount%2)*self.angleadd/2-self.waveway*math.floor((self.grabcount-1)/2)*self.angleadd),(self.waveway*self.angleadd) for _=1,self.grabcount do
                if IsValid(self.grabitem[i]) then self.grabitem[i].v=5 end
                if IsValid(self.grabitem[i]) then self.grabitem[i].angle=a self.grabitem[i].rot=a+90 end
                task._Wait(0)
            i=i+_d_i a=a+_d_a end end
            self.grabbing=false
            self.grabcount=0
            task._Wait(180)
        end end
    end)
end
function _tmp_sc:del()
