_tmp_sc=boss.dialog.New(true)
function _tmp_sc:init()
	lstg.player.dialog=true
	_dialog_can_skip=true
	self.dialog_displayer=New(dialog_displayer)
    task.New(self,function()
        if lstg.player.name=='Reimu' then
            task.New(self,function()
                boss.dialog.sentence(self,"image:void_boss2_1","right","到此为止了，红白。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_1","right","为什么又来这里打砸了？这里是图书馆，是安静阅读书本的地方，要打架去旁边的湖找妖精打。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_reimu_2","left","我来是要问这次异变的，结果你图书馆的那些门卫妖精不由分说地就打过来了。",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_reimu_0","left","你应该也知道外界的魔力比平常要浓厚得多了吧？而且越来越严重。",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_reimu_0","left","我还没来得及做好防护，大结界就受到了影响，连到了奇怪的世界，不过现在修好了。",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_reimu_0","left","你对这魔力的来源有什……",10,0.65,0.65)
                task._Wait(10)
                boss.dialog.sentence(self,"image:void_boss2_1","right","打住。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_1","right","你不觉得砸了我一堆书之后，再向我提问题很不合适吗？",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_reimu_2","left","其实那些书是那只恶魔扔的。",600,0.65,0.65)
                _stop_music()
                boss.dialog.sentence(self,"image:void_boss2_2","right","算了。",600,-0.65,0.65)
                LoadMusicRecord("贤者の密室 ~ roaring element");_play_music("贤者の密室 ~ roaring element")
                boss.dialog.sentence(self,"image:void_boss2_2","right","我今天状态还不错，应该不会哮喘。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_0","right","你是时候出去了。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_reimu_1","left","你都没让我问完问题，在这之前我是不会走的。",600,0.65,0.65)
                lstg.player.dialog=false
            end)
        else
        end
        if lstg.player.name=='Marisa' then
            task.New(self,function()
                boss.dialog.sentence(self,"image:void_boss2_1","right","这里已经没有你想偷的东西了，出去。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_marisa_1","left","什么啊，我这次不是来偷东西的！",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_1","right","那么请把之前的书都还过来，黑白小偷。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_marisa_2","left","咳咳……",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_marisa_0","left","话说你知不知道外面出现了一个宝具？",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_1","right","……就当你转移话题成功了。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_0","right","那么，你在说什么？",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_marisa_3","left","什么你不知道吗？就是那个不断往外冒出魔力的大锅啊！",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_1","right","(所谓的“大锅”该不会是……)",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_0","right","……然后呢？",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_marisa_4","left","如果能找到它，就能开发出很多新魔法了！",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_marisa_4","left","我还以为你知道诶，作为魔法使你还真是迟钝啊，哈哈！",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_1","right","这句话原封不动的还给你。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_0","right","你会来这里，说明你还不知道它的位置。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_0","right","你作为魔法使，竟然会感知不到那“宝具”。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_2","right","你是不是又吃奇怪的蘑菇了？",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_marisa_2","left","这么说，你是知道在哪咯？",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_2","right","那是当然，实际上我还知道有些人已经过去了。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_marisa_4","left","那就快告诉我吧~！",600,0.65,0.65)
                _stop_music()
                boss.dialog.sentence(self,"image:void_boss2_1","right","不要。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_marisa_2","left","……",600,0.65,0.65)
                LoadMusicRecord("贤者の密室 ~ roaring element");_play_music("贤者の密室 ~ roaring element")
                boss.dialog.sentence(self,"image:void_boss2_1","right","把书还来，不然就走人。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_2","right","或者被我的魔法轰出去，你选一个？",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_marisa_2","left","果然又要打架了啊。",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_marisa_4","left","那么，你输了之后，就把宝具的位置告诉我吧！",600,0.65,0.65)
                lstg.player.dialog=false
            end)
        else
        end
        if lstg.player.name=='Sanae' then
            task.New(self,function()
                boss.dialog.sentence(self,"image:void_boss2_0","right","真是难得，守矢神社的巫女来这里做什么？",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_0","right","而且还闹得沸沸扬扬的，砸坏了好多书。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_sanae_2","left","你的门卫系统就像饿极了一样，直接向我攻击了，不反击我就miss了。",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_sanae_0","left","神奈子大人派我来调查外面的妖风，我觉得你有可能知情，就过来打扰了。",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_0","right","原来你把那股魔力称作“妖风”吗……",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_sanae_4","left","诶？你知道什么吗？",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_0","right","是魔界的“风”哦。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_sanae_3","left","魔界的妖风？难怪感觉很熟悉啊，上次登圣辇船前往魔界时吹过。",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_sanae_2","left","但这次怎么会从魔法之森那边……",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_0","right","如果说是有谁开了通向这里和魔界的“门”呢？有个妖怪能做到呢。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_sanae_0","left","……",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_sanae_4","left","如果是这样的话，我倒要去门的那一侧看看呢。",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_sanae_4","left","那么，先告辞了。",600,0.65,0.65)
                _stop_music()
                boss.dialog.sentence(self,"image:void_boss2_1","right","等等。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_0","right","你进来砸坏了很多东西，得算一下账啊。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_sanae_2","left","那个啊，是小恶魔……",20,0.65,0.65)
                task._Wait(20)
                LoadMusicRecord("贤者の密室 ~ roaring element");_play_music("贤者の密室 ~ roaring element")
                boss.dialog.sentence(self,"image:void_boss2_1","right","果然无论是哪里的巫女都一样吗。不要随便就把错推出去啊。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_sanae_1","left","所以说真的是小恶魔用符卡砸的啦！",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_2","right","我一定要把请款书塞到你手上，老老实实地满身疮痍吧！",600,-0.65,0.65)
                lstg.player.dialog=false
            end)
        else
        end
        if lstg.player.name=='Wuer' then
            task.New(self,function()
                boss.dialog.sentence(self,"image:void_boss2_0","right","……",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_wuer_0","left","？",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_0","right","我们什么时候聘了厨师吗？咲夜没跟我说过啊……",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_wuer_0","left","我不是厨师啊。从这里怎么出去啊？看起来这里没有通往我的世界的出口……",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_0","right","忘记跟你说我这里有门卫了，这次造成的破坏就算了吧。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_0","right","要出去的话原路返回就行。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_5","right","不过没想到这个厨师没有接受培训诶。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_wuer_2","left","我没有应聘厨师。",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_wuer_0","left","你看起来好像挺博学的，你知道怎么回外面的世界吗？",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_6","right","不过有厨师的话说不定能尝到新菜色，嗯……",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_wuer_1","left","都说了我不是厨师！！",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_0","right","……",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_0","right","抱歉，没见过你呢，外界人吗。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_0","right","但是看你也不像啊。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_wuer_2","left","我只知道我醒来时已经躺在神社外面了。",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_0","right","……",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_1","right","醒来时在神社？",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_1","right","……",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_0","right","这么说来，那家伙有提过修补过结界来着。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_1","right","看来你是在她修补大结界之前溜进来的。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_wuer_2","left","如果我是溜进来的，那为什么我会在那里从昏睡状态醒过来啊？",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_wuer_4","left","既然我陷入了昏睡，那么我应该是受到了药物控制……",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_wuer_4","left","或是相当强烈的撞击才对吧？",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_1","right","你是想说，你是意外进来的，而且是“掉”进来的？",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_0","right","等等，她还说过，大结界连到了奇怪的世界……",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_0","right","你该不会是来自那里？",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_wuer_2","left","重点是怎么回去啊？",600,0.65,0.65)
                _stop_music()
                boss.dialog.sentence(self,"image:void_boss2_2","right","别急，先测试一下。",600,-0.65,0.65)
                LoadMusicRecord("贤者の密室 ~ roaring element");_play_music("贤者の密室 ~ roaring element")
                boss.dialog.sentence(self,"image:void_boss2_2","right","如果你太弱了，还是死在这比较痛快，总比在外面被吃掉好。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_2","right","得先确定你是否能活着见到那个人。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_wuer_1","left","你在说谁弱啊？我可是黑锅界最强者，无耳！",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_wuer_5","left","你的弹幕，我炒定了！",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_1","right","(这家伙在说些什么啊……)",600,-0.65,0.65)
                lstg.player.dialog=false
            end)
        else
        end
        do for _=1,_infinite do
            if lstg.player.dialog==false then
                if true then break end
            else
            end
            task._Wait(1)
        end end
    end)
end
