                a=a+_d_a end end
                task._Wait(10)
            b=b+_d_b end end
            self.rune.lockon=0 for i=1,5 do self.stone[i].lockon=0 end
            self.rune.lockhold=0
            for i=1,5 do self.stone[i].lockhold=0 end
            task._Wait(30)
            task.New(self,function()
                do for _=1,120 do
                    self.rune.spinv=self.rune.spinv+0.495/120
                    for i=1,5 do self.stone[i].spinv=self.stone[i].spinv+0.495/120 end
                    task._Wait(1)
                end end
            end)
            task._Wait(0)
        sequence=sequence+_d_sequence end end
    end)
end
function _tmp_sc:del()
    self.breakdown=true
end
