            task.MoveToPlayer(60,-96,96,112,144,16,32,8,16,MOVE_ACC_DEC,MOVE_RANDOM)
            task._Wait(1)
            last=New(_editor_class["void_boss2_none1_charge"],self.x,self.y,_)
            PlaySound("ch02",0.4,self.x/256,false)
