                    if IsValid(self.prelava[i]) then
                        if abs(self.prelava[i].x-self.burstpoint[j])<32 then
                            last=New(_editor_class["void_boss2_flare_mid"],self.prelava[i].x,self.prelava[i].y,0,self.prelava[i].dx+0.5*(self.prelava[i].x-self.burstpoint[j])/32,self.prelava[i].dy+ran:Float(1,8.5)*(448-max(0,self.prelava[i].y+224))/448,-0.098,self)
                            _del(self.prelava[i],true)
                        else
                        end
                    else
                    end
                    task._Wait(0)
                j=j+_d_j end end
                task._Wait(0)
            i=i+_d_i end end
            PlaySound("void_burst2",3.0,0,false)
            misc.ShakeScreen(60, 5)
            for i=1,self.lavacount do
            	for j=1,self.burstcount do
            		if IsValid(self.lava[i]) then
            			if abs(self.lava[i].x-self.burstpoint[j])<32 then
            				self.lava[i].vh=self.lava[i].vh+0.25*(self.lava[i].x-self.burstpoint[j])/32
            				self.lava[i].vv=self.lava[i].vv+ran:Float(1,6.5)*(448-max(0,self.lava[i].y+224))/448
            				self.lava[i].changed=self.lava[i].changed+1
            			end
            		end
            	end
            end
            self.burstcount=0
            self.burstpoint={}
            task.MoveToPlayer(59,-96,96,112,144,16,32,8,16,MOVE_DECEL,MOVE_X_TOWARDS_PLAYER)
            task._Wait(1)
            boss.cast(self,60)
            last=New(_editor_class["void_boss2_lavacharge"],self.x,self.y,_)
            PlaySound("ch02",0.2,self.x/256,false)
            task._Wait(60)
            task._Wait(0)
        k=k+_d_k end end
    end)
end
