function _tmp_sc:init()
    task.New(self,function()
        task.MoveTo(0,144,120,MOVE_NORMAL)
    end)
    task.New(self,function()
        task._Wait(120)
        last=New(_editor_class["void_loadresource_five"],self.x,self.y,_)
        task._Wait(60)
        last=New(_editor_class["void_boss2_precharge"],self.x,self.y,_)
        PlaySound("ch02",0.4,self.x/256,false)
        task._Wait(60)
        do local b,_d_b=(ran:Float(0,360)),(72+6.7) local sgn,_d_sgn=(0),(1) for _=1,_infinite do
            do local i,_d_i=(1-sgn),(1) local a,_d_a=(0),(360/5) local wt,_d_wt=(28),(-7) for _=1,5 do
                PlaySound("slash",0.1,self.x/256,false)
                do local ag,_d_ag=(ran:Float(0,360)),(360/30) for _=1,30 do
                    last=New(_editor_class["void_boss2_five_grain"],self.x+75*cos(a+b),self.y+75*sin(a+b),(i%5)+1,1,ag)
                    task._Wait(0)
                ag=ag+_d_ag end end
                if self.timer>5400 then
                    last=New(_editor_class["void_boss2_five"],self.x+75*cos(a+b),self.y+75*sin(a+b),(i%5)+1,260,wt,self.x,self.y,self,(-1)^sgn)
                else
                    if lstg.tmpvar.boss.hp<1600 then
                        last=New(_editor_class["void_boss2_five"],self.x+75*cos(a+b),self.y+75*sin(a+b),(i%5)+1,225,wt,self.x,self.y,self,(-1)^sgn)
                    else
                        if lstg.tmpvar.boss.hp<2800 then
                            last=New(_editor_class["void_boss2_five"],self.x+75*cos(a+b),self.y+75*sin(a+b),(i%5)+1,175,wt,self.x,self.y,self,(-1)^sgn)
                        else
                            last=New(_editor_class["void_boss2_five"],self.x+75*cos(a+b),self.y+75*sin(a+b),(i%5)+1,100,wt,self.x,self.y,self,(-1)^sgn)
                        end
                    end
                end
                task._Wait(7)
            i=i+_d_i a=a+_d_a wt=wt+_d_wt end end
            task._Wait(240)
        b=b+_d_b sgn=sgn+_d_sgn end end
    end)
    task.New(self,function()
        do for _=1,_infinite do
            if lstg.tmpvar.boss.hp<2800 or self.timer>5400 then
                PlaySound("explode",0.3,self.x/256,false)
                if true then break end
            else
            end
            task._Wait(1)
        end end
        do local t,_d_t=(0),(1) for _=1,_infinite do
            if lstg.tmpvar.boss.hp<1600 or self.timer>5400 then
                PlaySound("explode",0.3,self.x/256,false)
                if true then break end
            else
            end
            task._Wait(1)
        t=t+_d_t end end
        do local t,_d_t=(0),(1) for _=1,_infinite do
            if self.timer>5400 then
                PlaySound("explode",0.3,self.x/256,false)
                if true then break end
            else
            end
            task._Wait(1)
        t=t+_d_t end end
    end)
    task.New(self,function()
        do for _=1,_infinite do
            if self.timer>5400 then
                PlaySound("alert",1.5,self.x/256,true)
                if true then break end
            else
            end
            task._Wait(1)
        end end
    end)
