_tmp_sc=boss.dialog.New(true)
function _tmp_sc:init()
	lstg.player.dialog=true
	_dialog_can_skip=true
	self.dialog_displayer=New(dialog_displayer)
    task.New(self,function()
        task._Wait(60)
        if lstg.player.name=='Reimu' then
            task.New(self,function()
                boss.dialog.sentence(self,"image:void_reimu_4","left","我现在可以问了吧？你都输了。",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_3","right","你问吧。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_reimu_0","left","你对这股异常魔力的来源有什么头绪吗？",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_4","right","……",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_4","right","至少可以肯定的是，不是来自这个世界的魔力。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_4","right","我猜……是魔界吧。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_reimu_3","left","魔界！？",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_reimu_3","left","也就是说，是命莲寺那群人？",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_3","right","不是的。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_3","right","如果是她们，你就不应该有时间跑过来，你应该忙着去加固大结界了。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_4","right","这股魔力是从魔法之森那里流过来的。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_4","right","不过实际上，你可以不用来找我的，你只要顺着魔力递增的方向找就能发现了。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_4","right","但是，既在魔法之森，又与魔界有所联系的人，到底是谁？",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_3","right","另外，制造这个源头所使用的手法……只有那个诡异的家伙才干的出来。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_3","right","也就是说，这次异变的犯人至少有两个人，我相信其中一个人你已经认识了。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_reimu_0","left","我明白了，我已经知道犯人都是谁了。",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_reimu_4","left","接下来就是揪出他们了。",600,0.65,0.65)
                lstg.player.dialog=false
            end)
        else
        end
        if lstg.player.name=='Marisa' then
            task.New(self,function()
                boss.dialog.sentence(self,"image:void_marisa_0","left","来吧，说出你知道的一切~",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_3","right","唉，魔法之森。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_marisa_3","left","哈啊？不就在我家附近？",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_4","right","详细地点，是在人偶师那边。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_4","right","不过……",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_marisa_3","left","？",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_3","right","没什么。快出去。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_marisa_4","left","嗯，谢咯~",600,0.65,0.65)
                last=New(_editor_class["void_marisa_disap"],self.x,self.y,_)
                boss.dialog.sentence(self,"image:void_empty","left","",0,0.5,0.5)
                task._Wait(60)
                boss.dialog.sentence(self,"image:void_boss2_4","right","紫那家伙……到底要做什么？竟然屏蔽了魔理沙周围的魔力。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_3","right","算了，收拾图书馆要紧，那边的事让他们去忙吧。",600,-0.65,0.65)
                lstg.player.dialog=false
            end)
        else
        end
        if lstg.player.name=='Sanae' then
            task.New(self,function()
                boss.dialog.sentence(self,"image:void_sanae_2","left","浪费了不少时间呢，关于赔偿我会报告给神奈子大人的。",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_3","right","下次要来请选择不那么暴力的方式。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_sanae_1","left","你先把门卫撤了再说吧。",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_4","right","对了还有一点。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_4","right","替我向里面的妖怪“问好”，托她的福我的图书馆今天被砸了两次。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_sanae_4","left","好好~我先走了。",600,0.65,0.65)
                last=New(_editor_class["void_sanae_disap"],0,0,_)
                boss.dialog.sentence(self,"image:void_empty","left","",0,1,1)
                task._Wait(60)
                boss.dialog.sentence(self,"image:void_boss2_3","right","太倒霉了，希望不要再来人了……",600,-0.65,0.65)
                lstg.player.dialog=false
            end)
        else
        end
        if lstg.player.name=='Wuer' then
            task.New(self,function()
                boss.dialog.sentence(self,"image:void_boss2_4","right","这下厨的能力，竟恐怖如斯！竟然把我的子弹当成食材烹饪了！",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_wuer_5","left","我说过了啊，你的弹幕，我炒定了！",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_3","right","总而言之，你去魔法之森吧，那里有个摆着人偶的屋子，到那你就知道了。",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_3","right","但是……",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_wuer_0","left","啊？",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_4","right","你真的不是厨师吗？",600,-0.65,0.65)
                boss.dialog.sentence(self,"image:void_wuer_2","left","我真的真的不是什么厨师……",600,0.65,0.65)
                boss.dialog.sentence(self,"image:void_boss2_3","right","啊，可惜啊……",600,-0.65,0.65)
                lstg.player.dialog=false
            end)
        else
        end
        do for _=1,_infinite do
            if lstg.player.dialog==false then
                if true then break end
            else
            end
            task._Wait(1)
        end end
    end)
end
