_editor_class["Yukariscbg-wyj"]=Class(_spellcard_background)
_editor_class["Yukariscbg-wyj"].init=function(self)
    _spellcard_background.init(self)
    _spellcard_background.AddLayer(self,"image:Yukari_sc_bg (1)",true,0,0,0,1,1,0,"",1,1,
        function(self)
        self.task={}
            self.a=75
        end,
        function(self)
        task.Do(self)
        end,
        function(self)
        end
    )
    _spellcard_background.AddLayer(self,"image:Yukari_sc_bg (1)",true,0,0,0,-1,-1,0,"",1,1,
        function(self)
        self.task={}
            self.a=75
        end,
        function(self)
        task.Do(self)
        end,
        function(self)
        end
    )
    _spellcard_background.AddLayer(self,"image:Yukari_sc_bg (2)",false,0,0,0,0,0,0,"",1,1,
        function(self)
        self.task={}
        end,
        function(self)
        task.Do(self)
        end,
        function(self)
        end
    )
end
