_editor_class["Yukari:Normal"]=Class(boss)
_editor_class["Yukari:Normal"].cards={}
_editor_class["Yukari:Normal"].name="Yakumo Yukari"
_editor_class["Yukari:Normal"].init=function(self,cards)
    boss.init(self,240,384,"Yakumo Yukari",cards,New(_editor_class["Yukariscbg-wyj"]))
	self.difficulty="Normal"
	self.ani_intv=16
	for i=1,4 do self['img'..i]={} end
	self.nn={5,2,2,10}
	self.mm={1,1,9}
	for i=2,4 do self['ani'..i]=self.nn[i]-self.mm[i-1] end
	for i=1,4 do
		for j=1,self.nn[i] do
			self['img'..i][j]='anonymous:'.."wyj_Yukari.png"..i..j
		end
	end
end
_editor_class["Yukari:Normal"].bgm = "wyj_Roadbgm"
_editor_class["Yukari:Normal"]._bg = wyj_SpaceElevator
_editor_class["Yukari:Normal"].difficulty = "Normal"
_tmp_sc=boss.dialog.New(true)
function _tmp_sc:init()
	lstg.player.dialog=true
	_dialog_can_skip=true
	self.dialog_displayer=New(dialog_displayer)
    task.New(self,function()
        boss.show_aura(self,false)
        task.MoveTo(0,144,80,MOVE_NORMAL)
        boss.dialog.sentence(self,"image:Yukari_talk_wyj (1)","right","到此为止了",240,0.8,0.8)
        boss.dialog.sentence(self,"image:Yukari_talk_wyj (2)","right","再继续前进我可就要动手了哦~",180,0.8,0.8)
        task._Wait(60)
        boss.show_aura(self,true)
    end)
end
table.insert(_editor_class["Yukari:Normal"].cards,_tmp_sc)
_tmp_sc=boss.card.New("结界「幻彩万花筒」",2,18,60,1000,{15,15,15},false)
function _tmp_sc:init()
    task.New(self,function()
        task.MoveTo(0,144,60,MOVE_NORMAL)
        New(boss_cast_ef,self.x,self.y)
        task._Wait(100)
        do for _=1,_infinite do
            do local n,_d_n=(0),(3) local k,_d_k=(1),(1) local d,_d_d=(60),(70) local t,_d_t=(0),(10) for _=1,5 do
                do local a,_d_a=(ran:Float(0,360)),(360/(6+n)) for _=1,6+n do
                    last=New(_editor_class["Yukari-sc1-point-wyj"],1000,10,a,(-1)^k,d,t)
                    _connect(self,last,0,true)
                a=a+_d_a end end
                task._Wait(10)
            n=n+_d_n k=k+_d_k d=d+_d_d t=t+_d_t end end
            task.MoveToPlayer(60,-140,140,112,144,30,60,8,16,MOVE_NORMAL,MOVE_RANDOM)
            task._Wait(300)
        end end
    end)
end
function _tmp_sc:del()
end
table.insert(_editor_class["Yukari:Normal"].cards,_tmp_sc)
table.insert(_sc_table,{"Yukari:Normal","结界「幻彩万花筒」",_tmp_sc,#_editor_class["Yukari:Normal"].cards,false})
_tmp_sc=boss.card.New("罔两「矛盾螺旋」",2,15,60,1000,{15,15,15},false)
function _tmp_sc:init()
    task.New(self,function()
        task.MoveTo(0,144,60,MOVE_NORMAL)
        New(boss_cast_ef,self.x,self.y)
        task._Wait(100)
        task.New(self,function()
            task._Wait(360)
            do for _=1,_infinite do
                task.MoveToPlayer(60,-120,120,112,144,24,48,8,16,MOVE_NORMAL,MOVE_RANDOM)
                task._Wait(60)
            end end
        end)
        task.New(self,function()
            task._Wait(240)
            do for _=1,_infinite do
                PlaySound("tan00",0.1,self.x/256,false)
                do local r,_d_r=(ran:Float(0,360)),(30) for _=1,12 do
                    last=New(_straight,ball_mid,COLOR_PURPLE,self.x,self.y,1.5,r,false,0,true,true,0,false,0,0,0,false)
                    _object.set_color(last,"mul+add",255,255,255,255)
                r=r+_d_r end end
                task._Wait(60)
            end end
        end)
        do for _=1,_infinite do
            last=New(_editor_class["Yukari-sc2-servent-wyj"],self.x,self.y,1,COLOR_PURPLE)
            _connect(self,last,0,true)
            task._Wait(360)
            last=New(_editor_class["Yukari-sc2-servent-wyj"],self.x,self.y,-1,COLOR_CYAN)
            _connect(self,last,0,true)
            task._Wait(360)
            last=New(_editor_class["Yukari-sc2-servent-wyj"],self.x,self.y,-1,COLOR_PURPLE)
            _connect(self,last,0,true)
            task._Wait(360)
            last=New(_editor_class["Yukari-sc2-servent-wyj"],self.x,self.y,1,COLOR_CYAN)
            _connect(self,last,0,true)
            task._Wait(360)
        end end
    end)
end
function _tmp_sc:del()
end
table.insert(_editor_class["Yukari:Normal"].cards,_tmp_sc)
table.insert(_sc_table,{"Yukari:Normal","罔两「矛盾螺旋」",_tmp_sc,#_editor_class["Yukari:Normal"].cards,false})
_tmp_sc=boss.card.New("「混沌蝴蝶」",3,18,60,1200,{15,15,15},false)
function _tmp_sc:init()
    task.New(self,function()
        task.MoveTo(0,144,60,MOVE_NORMAL)
        New(boss_cast_ef,self.x,self.y)
        task._Wait(100)
        task.New(self,function()
            task._Wait(120)
            New(boss_cast_ef,self.x,self.y)
            task._Wait(100)
            do for _=1,_infinite do
                PlaySound("kira00",0.1,self.x/256,false)
                last=New(_editor_class["Yukari-sc3-butterfly-wyj"],-192,ran:Float(40,140),ran:Float(-60,60))
                task._Wait(90)
                PlaySound("kira00",0.1,self.x/256,false)
                last=New(_editor_class["Yukari-sc3-butterfly-wyj"],192,ran:Float(40,140),ran:Float(120,240))
                task._Wait(90)
            end end
        end)
        local aaa = 30
        do for _=1,_infinite do
            do for _=1,90 do
                aaa=aaa+7
                do local r,_d_r=(aaa),(60) for _=1,6 do
                    last=New(_editor_class["Yukari-sc3-bullet-wyj"],self.x,self.y,r)
                r=r+_d_r end end
                task._Wait(4)
            end end
            do for _=1,90 do
                aaa=aaa-7
                do local r,_d_r=(aaa),(60) for _=1,6 do
                    last=New(_editor_class["Yukari-sc3-bullet-wyj"],self.x,self.y,r)
                r=r+_d_r end end
                task._Wait(4)
            end end
            task._Wait(0)
        end end
    end)
end
function _tmp_sc:del()
end
table.insert(_editor_class["Yukari:Normal"].cards,_tmp_sc)
table.insert(_sc_table,{"Yukari:Normal","「混沌蝴蝶」",_tmp_sc,#_editor_class["Yukari:Normal"].cards,false})
