    self.x,self.y=_x,_y
    _object.set_color(self,"mul+add",255,255,255,255)
    self.hscale=0.5
    self.vscale=0.5
    self.a=self.a*0.5
    self.b=self.b*0.5
    self.bound=false
    local xx = 0
    local yy = 0
    if k==1 then
        xx=self.x
        yy=self.y
    else
        xx=self.x+cos(a+180)*500
        yy=self.y+sin(a+180)*500
    end
    task.New(self,function()
        do local i,_d_i=(90/240),(90/240) local n,_d_n=(90/240),(90/240) for _=1,240 do
            if k==1 then
                self.x=xx+cos(a+k*240*sin(n))*180*sin(i)
                self.y=yy+sin(a+k*240*sin(n))*180*sin(i)
            else
                self.x=xx+cos(a+k*240*sin(n))*(500-260*sin(i))
                self.y=yy+sin(a+k*240*sin(n))*(500-260*sin(i))
            end
            task._Wait(1)
        i=i+_d_i n=n+_d_n end end
        task._Wait(30)
        last=New(_editor_class["The-Bullet-Breaks-wyj"],self.x,self.y,0.4,148,0,211)
