_editor_class["Alice-power-wyj"]=Class(_object)
_editor_class["Alice-power-wyj"].init=function(self,_x,_y,number)
    self.x,self.y=_x,_y
	self.img="leaf"
	self.layer=LAYER_BG
	self.group=GROUP_GHOST
	self.hide=true
	self.bound=false
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=false
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    task.New(self,function()
        PlaySound("ch00",0.4,self.x/256,false)
        if number==1 then
            do for _=1,30 do
                local rr = ran:Float(0,360)
                local d = ran:Float(60,120)
                last=New(_editor_class["Alice-power-red-wyj"],self.x+cos(rr)*d,self.y+sin(rr)*d,self.x,self.y,ran:Int(45,90))
                task._Wait(3)
            end end
        else
        end
        if number==2 then
            do for _=1,30 do
                local rr = ran:Float(0,360)
                local d = ran:Float(60,120)
                last=New(_editor_class["Alice-power-Gold-wyj"],self.x+cos(rr)*d,self.y+sin(rr)*d,self.x,self.y,ran:Int(45,90))
                task._Wait(3)
            end end
        else
        end
        if number==3 then
            do for _=1,5 do
                local rr = ran:Float(0,360)
                local d = ran:Float(90,150)
                last=New(_editor_class["Alice-power-Wood-wyj"],self.x+cos(rr)*d,self.y+sin(rr)*d,self.x,self.y,ran:Int(60,105))
                task._Wait(18)
            end end
        else
        end
        if number==4 then
            do for _=1,15 do
                local rr = ran:Float(0,360)
                local d = ran:Float(60,120)
                last=New(_editor_class["Alice-power-water-wyj"],self.x+cos(rr)*d,self.y+sin(rr)*d,self.x,self.y,ran:Int(45,90))
                task._Wait(6)
            end end
        else
        end
        if number==5 then
            do for _=1,30 do
                local rr = ran:Float(0,360)
                local d = ran:Float(60,120)
                last=New(_editor_class["Alice-power-earth-wyj"],self.x+cos(rr)*d,self.y+sin(rr)*d,self.x,self.y,ran:Int(45,90))
                task._Wait(3)
            end end
        else
        end
        if number==6 then
            do for _=1,30 do
                local rr = ran:Float(0,360)
                local d = ran:Float(100,180)
                last=New(_editor_class["Alice-power-Angel-wyj"],self.x+cos(rr)*d,self.y+sin(rr)*d,self.x,self.y,ran:Int(50,100))
                task._Wait(3)
            end end
        else
        end
        if number==7 then
            do for _=1,30 do
                local rr = ran:Float(0,360)
                local d = ran:Float(100,180)
                last=New(_editor_class["Alice-power-Darkness-wyj"],self.x+cos(rr)*d,self.y+sin(rr)*d,self.x,self.y,ran:Int(50,100))
                task._Wait(3)
            end end
        else
        end
        if number==8 then
            do local r,_d_r=(ran:Float(0,360)),(30) for _=1,12 do
                last=New(_editor_class["Alice-power-star-wyj"],self.x+cos(r)*120,self.y+sin(r)*120,self.x,self.y)
            r=r+_d_r end end
            task._Wait(45)
            do local r,_d_r=(ran:Float(0,360)),(30) for _=1,12 do
                last=New(_editor_class["Alice-power-star-wyj"],self.x+cos(r)*120,self.y+sin(r)*120,self.x,self.y)
            r=r+_d_r end end
            task._Wait(45)
        else
        end
        task._Wait(1)
        _del(self,true)
    end)
end
