_editor_class["Alicen-7sc-star"]=Class(_object)
_editor_class["Alicen-7sc-star"].init=function(self,_x,_y,k)
    self.x,self.y=_x,_y
	self.img="image:wyj_Ball_lights"
	self.layer=LAYER_ENEMY_BULLET
	self.group=GROUP_INDES
	self.hide=false
	self.bound=false
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    _object.set_color(self,"mul+add",255,148,0,211)
    task.New(self,function()
        task.New(self,function()
            do for _=1,8 do
                last=New(_editor_class["Alice-power-Darkness-wyj"],self.x,self.y,self.x,self.y,40)
                task._Wait(30)
            end end
        end)
        task.New(self,function()
            do local i,_d_i=(0),(8.7*k) local d,_d_d=(0),(k*4) local n,_d_n=(4),(4) for _=1,120 do
                last=New(_editor_class["Alicel-7sc-darkshoot"],self.x+cos(i)*i/4,self.y+sin(i)*i/12,i*2+d,n)
                last=New(_editor_class["Alicel-7sc-darkshoot"],self.x+cos(180+i)*i/4,self.y+sin(i+180)*i/12,i*2-d,n)
                task._Wait(2)
            i=i+_d_i d=d+_d_d n=n+_d_n end end
        end)
        task.MoveTo(self.x,200,240,MOVE_NORMAL)
        task._Wait(30)
        do for _=1,3 do
            do local r,_d_r=(ran:Float(0,360)),(10) for _=1,36 do
                last=New(_straight,ball_mid,COLOR_GRAY,self.x,self.y,2,r,false,0,true,true,0,false,0,0,0,false)
                _object.set_color(last,"mul+add",255,255,255,255)
            r=r+_d_r end end
            task._Wait(10)
        end end
        PlaySound("enep02",0.1,self.x/256,false)
        do local r,_d_r=(ran:Float(0,360)),(10*k) for _=1,6 do
            do local d,_d_d=(r),(60) for _=1,6 do
                last=New(_editor_class["Alicel-7sc-shoot"],self.x,self.y,d)
            d=d+_d_d end end
            task._Wait(0)
        r=r+_d_r end end
        last=New(_editor_class["The-Bullet-Breaks-wyj"],self.x,self.y,0.6,205,205,205)
        task._Wait(1)
        _del(self,true)
    end)
end
