_tmp_sc=boss.dialog.New(true)
function _tmp_sc:init()
	lstg.player.dialog=true
	_dialog_can_skip=true
	self.dialog_displayer=New(dialog_displayer)
    task.New(self,function()
        boss.show_aura(self,false)
        --[[ 啊....对话好难写，乱写点电波好了 --]]
        do
            if GetGlobal('player_name')=='reimu_player' then
                boss.dialog.sentence(self,"image:Reimu_talk_wyj (1)","left","通道的尽头居然是这样的一个世界",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Reimu_talk_wyj (1)","left","幻想乡里什么时候有这种地方吗",240,0.65,0.65)
                boss.dialog.sentence(self,"image:wyj_the_void","right","这里是魔界",240,0.65,0.65)
                boss.dialog.sentence(self,"image:wyj_the_void","right","创世神所一手创造的世界",240,0.65,0.65)
                task.MoveTo(0,144,90,MOVE_NORMAL)
                boss.dialog.sentence(self,"image:Reimu_talk_wyj (4)","left","你是，魔法之森的人偶师？",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Alice_talk_wyj (6)","right","我不是她，我们之间只是有着某种联系",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Alice_talk_wyj (5)","right","那么这位不知名的小姐，你来魔界是做什么的呢",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Reimu_talk_wyj (3)","left","幻想乡里突然多出来的大量魔力潮汐，就是你干的吧",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Alice_talk_wyj (3)","right","你还不知道吗",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Alice_talk_wyj (6)","right","那位贤者已经答应开放两个世界的魔力通道了",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Alice_talk_wyj (1)","right","而且这件事对双方都有好处",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Reimu_talk_wyj (3)","left","紫那家伙又背着我干了什么奇怪的事",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Reimu_talk_wyj (3)","left","..................",240,0.65,0.65)
                task._Wait(60)
                boss.dialog.sentence(self,"image:Reimu_talk_wyj (4)","left","但是你们的行为在幻想乡里造成了很大的破坏",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Reimu_talk_wyj (2)","left","已经属于异变的范畴，准备接受退治了吗",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Alice_talk_wyj (3)","right","什么嘛，突然就要打架",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Alice_talk_wyj (4)","right","既然这样",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Alice_talk_wyj (4)","right","那就让你体验一下",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Alice_talk_wyj (4)","right","结合了两个世界的魔力的究极大魔法吧！",240,0.65,0.65)
                lstg.player.dialog=false
            else
            end
            if GetGlobal('player_name')=='marisa_player' then
                boss.dialog.sentence(self,"image:Marisa_talk_wyj (4)","left","爱丽丝家里居然还有这么大的秘密空间",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Marisa_talk_wyj (1)","left","帕秋莉说的，到底在哪呢",240,0.65,0.65)
                boss.dialog.sentence(self,"image:wyj_the_void","right","你在找什么",240,0.65,0.65)
                task.MoveTo(0,144,90,MOVE_NORMAL)
                boss.dialog.sentence(self,"image:Marisa_talk_wyj (1)","left","呀！你来了",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Marisa_talk_wyj (5)","left","快告诉我宝具在哪吧，这样就能一起开发新魔法了",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Alice_talk_wyj (5)","right","...................",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Alice_talk_wyj (6)","right","这里是魔界，不存在什么宝具",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Alice_talk_wyj (5)","right","顺便，我不是你所认识的那个人偶师",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Marisa_talk_wyj (3)","left","你是不是吃错什么东西了，连我都不认识了",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Marisa_talk_wyj (5)","left","快点快点，好东西别私藏起来",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Alice_talk_wyj (2)","right","这里的魔力来自于魔界本身的力量",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Alice_talk_wyj (2)","right","只是因为两个世界被连接起来了所以才会出现在你们那边",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Marisa_talk_wyj (2)","left","什么嘛，不是宝具那就不能带走了",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Marisa_talk_wyj (5)","left","找点别的东西好了",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Marisa_talk_wyj (5)","left","你手里的那本书好像不错的样子，能借我看看吗",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Alice_talk_wyj (4)","right","我都说了根本不认识你，别装作一副很熟的样子",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Alice_talk_wyj (4)","right","既然你这么想看魔法，那就瞧瞧你能不能接的下吧！",240,0.65,0.65)
                lstg.player.dialog=false
            else
            end
            if GetGlobal('player_name')=='sanae_player' then
                boss.dialog.sentence(self,"image:Sanae_talk_wyj (5)","left","妖风的源头，就是在这里吗",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Sanae_talk_wyj (4)","left","现在是揪出异变主谋的时候了~",240,0.65,0.65)
                boss.dialog.sentence(self,"image:wyj_the_void","right","她又派人来做什么",240,0.65,0.65)
                task.MoveTo(0,144,90,MOVE_NORMAL)
                boss.dialog.sentence(self,"image:Alice_talk_wyj (5)","right","明明已经达成过协定了，连接两个世界的魔力通道",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Alice_talk_wyj (4)","right","她想毁约了？",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Sanae_talk_wyj (5)","left","说的是紫吗",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Sanae_talk_wyj (3)","left","这么大的事就这么擅作决定了，她想搞什么大新闻",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Sanae_talk_wyj (3)","left","我不管紫和你们商量了什么，但是造成了破坏就该被处理",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Alice_talk_wyj (2)","right","（这边的人都这么冲动的吗）",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Alice_talk_wyj (4)","right","你想来处理，那就看看你有没有这个本事了",240,0.65,0.65)
                lstg.player.dialog=false
            else
            end
            if GetGlobal('player_name')=='wuer_player' then
                boss.dialog.sentence(self,"image:Wuer_talk_wyj (5)","left","呃，这是哪里",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Wuer_talk_wyj (5)","left","魔法使小姐给我指的是什么路啊.....",240,0.65,0.65)
                boss.dialog.sentence(self,"image:wyj_the_void","right","你是谁",240,0.65,0.65)
                task.MoveTo(0,144,90,MOVE_NORMAL)
                boss.dialog.sentence(self,"image:Wuer_talk_wyj (3)","left","啊，你好",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Wuer_talk_wyj (3)","left","请问你知道怎么回外面的世界吗",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Alice_talk_wyj (5)","right","emmmmm...........",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Alice_talk_wyj (6)","right","外面的世界？从你来的方向原路返回就是啊",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Wuer_talk_wyj (6)","left","那里不是幻想乡吗",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Wuer_talk_wyj (1)","left","我说的是那个“外面”",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Alice_talk_wyj (5)","right","emmmmm...........",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Alice_talk_wyj (5)","right","这里是魔界，没有其他出口了",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Alice_talk_wyj (6)","right","看来你是顺着魔力潮汐找到这里的",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Alice_talk_wyj (1)","right","在魔力通道稳定之前，你先在这里待一会吧",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Wuer_talk_wyj (4)","left","那怎么行，我还赶着回去填坑呢",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Wuer_talk_wyj (4)","left","告辞",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Alice_talk_wyj (4)","right","那只能用魔法把你留下来了",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Alice_talk_wyj (4)","right","可不能因为你一个人让计划泡汤",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Wuer_talk_wyj (3)","left","区区魔法就想把我留下来，还是太年轻了",240,0.65,0.65)
                boss.dialog.sentence(self,"image:Wuer_talk_wyj (2)","left","你的弹幕，我炒定了！",240,0.65,0.65)
                lstg.player.dialog=false
            else
            end
        end
        task._Wait(60)
    end)
end
