_editor_class["Alicel-9sc-Circles"]=Class(_object)
_editor_class["Alicel-9sc-Circles"].init=function(self,_x,_y,a,k,d,index)
    self.x,self.y=_x,_y
	self.img="image:wyj_circle"
	self.layer=LAYER_ENEMY_BULLET-1
	self.group=GROUP_GHOST
	self.hide=false
	self.bound=false
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=false
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    self.flag=2333
    self.omiga=2*k
    local da = abs(a+90)
    do
        if index==1 then
            _object.set_color(self,"mul+add",255,255,55,55)
            last=New(_editor_class["Alice-9sc-mask"],self.x,self.y,255,55,55)
        else
        end
        if index==2 then
            _object.set_color(self,"mul+add",255,255,215,0)
            last=New(_editor_class["Alice-9sc-mask"],self.x,self.y,255,215,0)
        else
        end
        if index==3 then
            _object.set_color(self,"mul+add",255,50,205,50)
            last=New(_editor_class["Alice-9sc-mask"],self.x,self.y,50,205,50)
        else
        end
        if index==4 then
            _object.set_color(self,"mul+add",255,50,50,205)
            last=New(_editor_class["Alice-9sc-mask"],self.x,self.y,50,50,205)
        else
        end
        if index==5 then
            _object.set_color(self,"mul+add",255,250,128,10)
            last=New(_editor_class["Alice-9sc-mask"],self.x,self.y,250,128,10)
        else
        end
        if index==6 then
            _object.set_color(self,"mul+add",255,205,205,205)
            last=New(_editor_class["Alice-9sc-mask"],self.x,self.y,205,205,205)
        else
        end
        if index==7 then
            _object.set_color(self,"mul+add",255,148,0,211)
            last=New(_editor_class["Alice-9sc-mask"],self.x,self.y,148,0,211)
        else
        end
    end
    task.New(self,function()
        do local i,_d_i=(3),(3) for _=1,30 do
            self.hscale=0.15*i/90
            self.vscale=0.15*i/90
            task._Wait(1)
        i=i+_d_i end end
        task._Wait(240)
        do local i,_d_i=(87),(-3) for _=1,30 do
            self.hscale=0.15*i/90
            self.vscale=0.15*i/90
            task._Wait(1)
        i=i+_d_i end end
    end)
    task.New(self,function()
        task._Wait(30)
        do local i,_d_i=(1),(1) for _=1,240 do
            self.x=cos(a+da*i/120*k)*d
            self.y=sin(a+da*i/120*k)*d+239
            task._Wait(1)
        i=i+_d_i end end
        task._Wait(30)
        _del(self,true)
    end)
    task.New(self,function()
        task._Wait(30)
        if index==1 then
            do local rr,_d_rr=(ran:Float(0,360)),(17*k) for _=1,12 do
                PlaySound("tan00",0.1,self.x/256,false)
                _create_bullet_group(water_drop,COLOR_RED,self.x,self.y,5,0,1,1,rr,360,false,0,true,true,0,false,self)
                task._Wait(20)
            rr=rr+_d_rr end end
        else
        end
        if index==2 then
            do for _=1,2 do
                PlaySound("kira00",0.1,self.x/256,false)
                _create_bullet_group(ball_light,COLOR_YELLOW,self.x,self.y,9,0,2,2,0,360,true,0,true,true,0,false,self)
                task._Wait(120)
            end end
        else
        end
        if index==3 then
            do local r,_d_r=(ran:Float(0,360)),(29*k) for _=1,24 do
                PlaySound("tan00",0.1,self.x/256,false)
                _create_bullet_group(grain_b,COLOR_GREEN,self.x,self.y,3,0,3,3,r,360,true,0,true,true,0,false,self)
                task._Wait(10)
            r=r+_d_r end end
        else
        end
        if index==4 then
            last=New(_straight,ball_big,COLOR_BLUE,self.x,self.y,5,90,false,0,true,true,0,false,0,0,0,false)
            last=New(smear, last, 5)
            do local r,_d_r=(ran:Float(0,360)),(20) for _=1,18 do
                last=New(_straight,ball_mid,COLOR_DEEP_BLUE,self.x,self.y,3,r,false,0,true,true,0,false,0,0,0,false)
                _object.set_color(last,"mul+add",255,255,255,255)
            r=r+_d_r end end
            task._Wait(60)
            do for _=1,15 do
                last=New(_editor_class["Alicel-4sc-snow1"],ran:Float(-300,300),239,_)
                task._Wait(12)
                last=New(_editor_class["Alicel-4sc-snow2"],ran:Float(-300,300),239,_)
                task._Wait(12)
            end end
        else
        end
        if index==5 then
            do for _=1,3 do
                local d = ran:Float(0,360)
                do local r,_d_r=(d),(60) for _=1,6 do
                    do local a,_d_a=(r),(1) for _=1,9 do
                        last=New(_straight,ball_mid,COLOR_ORANGE,self.x,self.y,1.5,a,false,0,true,true,0,false,0,0,0,false)
                        _object.set_color(last,"mul+add",255,255,255,255)
                    a=a+_d_a end end
                r=r+_d_r end end
                task._Wait(80)
            end end
        else
        end
        if index==6 then
            task._Wait(180)
            local r = ran:Float(0,360)
            local xx = self.x
            local yy = self.y
            do local d,_d_d=(r),(120) for _=1,3 do
                last=New(_editor_class["Alicel-6non-line-wyj"],xx,yy,d)
            d=d+_d_d end end
            do local a,_d_a=(0),(1) for _=1,7 do
                do local d,_d_d=(r),(120) for _=1,3 do
                    last=New(_editor_class["Alicel-6non-line-wyj"],xx,yy,d+a)
                    last=New(_editor_class["Alicel-6non-line-wyj"],xx,yy,d-a)
                d=d+_d_d end end
                task._Wait(1)
            a=a+_d_a end end
        else
        end
        if index==7 then
            task._Wait(120)
            do
                local kk = (-1)^k
                local dr = ran:Float(0,360)
                do local n,_d_n=(0),(30/8) for _=1,9 do
                    --[[ 正三角 --]]
                    last=New(_editor_class["Alicel-9sc-star"],self.x,self.y,self.x-sqrt(3)*50*n/30,self.y+100-n*150/30,dr,kk)
                    last=New(_editor_class["Alicel-9sc-star"],self.x,self.y,self.x+sqrt(3)*50*n/30,self.y+100-n*150/30,dr,kk)
                    last=New(_editor_class["Alicel-9sc-star"],self.x,self.y,self.x-sqrt(3)*50+sqrt(3)*100*n/30,self.y-50,dr,kk)
                n=n+_d_n end end
            end
        else
        end
    end)
end
