_editor_class["Shinki:Lunatic"].init=function(self,cards)
    boss.init(self,0,384,"Shinki",cards,New(_editor_class["Shinkiscbg-wyj"]))
	self.difficulty="All"
	self.ani_intv=16
	for i=1,4 do self['img'..i]={} end
	self.nn={5,2,2,3}
	self.mm={5,1,1,3}
	for i=2,4 do self['ani'..i]=self.nn[i]-self.mm[i-1] end
	for i=1,4 do
		for j=1,self.nn[i] do
			self['img'..i][j]='anonymous:'.."wyj_Shinki.png"..i..j
		end
	end
end
