function _tmp_sc:del()
    if self.sc_get and lstg.var.sc_bonus>0 then
        self.sc_get=self.sc_get+1
    else
    end
    for _,unit in ObjList(GROUP_GHOST) do
        if unit.flag==777 then
            _del(unit,true)
        else
        end
        if unit.flag==11111 then
            _del(unit,true)
        else
        end
    end
end
