        end
        task.New(self,function()
            do for _=1,_infinite do
                local r = ran:Float(0,360)
                local dr1 = ran:Float(0,360)
                local dr2 = ran:Float(0,360)
                do local d,_d_d=(r),(30) for _=1,12 do
                    last=New(_editor_class["Shinki-lsc-light"],self.x,self.y,d)
                    last=New(_editor_class["Shinki-lsc-light"],self.x+70,self.y,d+dr1)
                    last=New(_editor_class["Shinki-lsc-light"],self.x-70,self.y,d-dr2)
                d=d+_d_d end end
                task._Wait(30)
            end end
        end)
        do local k,_d_k=(1),(1) for _=1,_infinite do
            local r = ran:Float(0,360)
            do local d,_d_d=(r),(36) for _=1,10 do
                if self.lscflag==7 then
                    PlaySound("kira00",0.1,self.x/256,false)
                    last=New(_editor_class["Shinki-lsc-the-ball"],self.x+70,self.y,d,(-1)^k,150,7)
                    last=New(_editor_class["Shinki-lsc-the-ball"],self.x-70,self.y,d,(-1)^(k+1),150,7)
                else
                end
            d=d+_d_d end end
            task._Wait(150)
        k=k+_d_k end end
    end)
end
function _tmp_sc:del()
    if self.sc_get and lstg.var.sc_bonus>0 then
        self.sc_get=self.sc_get+1
    else
    end
    if self.sc_get and self.sc_get>=2 then
        New(achievement_obj,1,22)
    else
    end
    for _,unit in ObjList(GROUP_GHOST) do
        if unit.flag==11233 then
            _del(unit,true)
        else
        end
    end
    _clear_bullet(false,true)
    New(tasker, function()
        do local an,_d_an=(0),(90/70) for _=1,70 do
            local x1=0+sin(an)*(32)
            local x2=640+sin(an)*(-224)
            local y1=0+sin(an)*(16)
            local y2=480+sin(an)*(-16)
            local x3=-224+sin(an)*(16)
            local x4=416+sin(an)*(-224)
            local y3=-240+sin(an)*(16)
            local y4=240+sin(an)*(-16)

            lstg.world.l=x3
            lstg.world.r=x4
            lstg.world.b=y3
            lstg.world.t=y4
            lstg.world.boundl=x3
            lstg.world.boundr=x4
            lstg.world.boundb=y3
            lstg.world.boundt=y4
            lstg.world.scrl=x1
            lstg.world.scrr=x2
            lstg.world.scrb=y1
            lstg.world.scrt=y2
            lstg.world.pl=-192
            lstg.world.pr=192
            lstg.world.pb=-224
            lstg.world.pt=224
            task._Wait(1)
        an=an+_d_an end end
        SetBound(-192,192,-224,224)
        for _,unit in ObjList(GROUP_ENEMY) do
            if unit~=_boss then
                _del(unit,true)
            else
            end
        end
        task._Wait(1)
        do return end
    end)
end
