_editor_class["yyzy_midboss:Lunatic"]=Class(enemy)
_editor_class["yyzy_midboss:Lunatic"].init=function(self,_x,_y,_)
    enemy.init(self,14,1000,true,true,false)
    self.x,self.y=_x,_y
    self.drop={25,25,0}
    task.New(self,function() self.protect=true task.Wait(150) self.protect=false end)
    SetV2(self,3,-90,false,false)
    _set_a(self,0.05,90,false)
    task.New(self,function()
        task._Wait(60)
        SetV2(self,0,0,false,false)
        _set_a(self,0,0,false)
        local radius = 0
        local v = 0
        local dirct = 1
        local ox = self.x
        local oy = self.y
        do for _=1,16 do
            do local wait,_d_wait=(120),(-6) local angle,_d_angle=(ran:Float(30,150)),(5) for _=1,5 do
                radius=ran:Float(40,80)
                v=ran:Float(1.5,2)
                dirct=ran:Sign()
                ox=self.x+ran:Float(-80,80)
                oy=self.y+ran:Float(-20,20)
                PlaySound("tan01",0.1,self.x/256,false)
                do local a,_d_a=(ran:Float(0,360)),(12) for _=1,30 do
                    if dirct==1 then
                        last=New(_straight,square,COLOR_DEEP_PURPLE,ox+radius*cos(a),oy+radius*sin(a),v,a+angle*dirct,false,0,true,true,wait,false,0,0,0,false)
                    else
                        last=New(_straight,square,COLOR_ORANGE,ox+radius*cos(a),oy+radius*sin(a),v,a+angle*dirct,false,0,true,true,wait,false,0,0,0,false)
                    end
                    task._Wait(0)
                a=a+_d_a end end
                task._Wait(6)
            wait=wait+_d_wait angle=angle+_d_angle end end
            task._Wait(20)
            do local an,_d_an=(ran:Float(0,360)),(12) for _=1,30 do
                last=New(_editor_class["yyzy_b02"],self.x,self.y,7,0.5,an,0.1,star_big,COLOR_YELLOW)
                PlaySound("tan00",0.1,self.x/256,false)
                task._Wait(0)
            an=an+_d_an end end
            task._Wait(20)
            do local an,_d_an=(ran:Float(0,360)),(12) for _=1,30 do
                last=New(_editor_class["yyzy_b02"],self.x,self.y,7,1,an,0.1,star_big,COLOR_YELLOW)
                PlaySound("tan00",0.1,self.x/256,false)
                task._Wait(0)
            an=an+_d_an end end
            task._Wait(20)
        end end
        task._Wait(60)
        SetV2(self,3,90,false,false)
    end)
end
_editor_class["yyzy_midboss:Lunatic"].kill=function(self)
    _drop_item(item_extend,1,self.x,self.y)
    self.class.base.kill(self)
end
