_editor_class["boss"]=Class(_spellcard_background)
_editor_class["boss"].init=function(self)
    _spellcard_background.init(self)
    _spellcard_background.AddLayer(self,"image:cdbg06a",false,0,0,0,0,0,0,"",1.62,1.62,
        function(self)
        self.task={}
        end,
        function(self)
        task.Do(self)
            self.rot=self.rot-0.2
        end,
        function(self)
        end
    )
    _spellcard_background.AddLayer(self,"image:cdbg06b",true,0,0,0,-1,-1,0,"mul+add",1.62,1.89,
        function(self)
        self.task={}
        end,
        function(self)
        task.Do(self)
        end,
        function(self)
        end
    )
end
