_tmp_sc=boss.dialog.New(true)
function _tmp_sc:init()
	lstg.player.dialog=true
	_dialog_can_skip=true
	self.dialog_displayer=New(dialog_displayer)
    task.New(self,function()
        if GetGlobal('player_name')=='reimu_player' then
            boss.dialog.sentence(self,"image:Reimu_normal","left","如果没弄错的话，这里就是那巨大声响传来的地方了吧",180,0.6,0.6)
            boss.dialog.sentence(self,"image:Reimu_noticed","left","咦，这不是阿空吗？你的主人最近似乎一直在找你哦，你跑哪去了？",180,0.6,0.6)
            boss.dialog.sentence(self,"image:Utsuho_embarrassed","right","啊……那、那个",180,-0.6,0.6)
            boss.dialog.sentence(self,"image:Reimu_question","left","诶，你在这里做什么？刚才有没有听见这里传来的巨大的爆炸声呢？",180,0.6,0.6)
            boss.dialog.sentence(self,"image:Utsuho_en","right","没……没有啊",180,-0.6,0.6)
            boss.dialog.sentence(self,"image:Reimu_unease","left","没有吗，我可是在自己的神社听见的呢，那声巨大的爆炸声，整个人里以周边地区的人和妖怪都听见了哦。",180,0.6,0.6)
            boss.dialog.sentence(self,"image:Utsuho_amazed","right","都听见了！？呃……总、总之我什么都不知道呢……",180,-0.6,0.6)
            boss.dialog.sentence(self,"image:Reimu_unease","left","你这家伙，很可疑呢！",180,0.6,0.6)
            boss.dialog.sentence(self,"image:Utsuho_angry","right","啊，搞什么啊，你的这个碍手碍脚的巫女……",180,-0.6,0.6)
            boss.dialog.sentence(self,"image:Reimu_angry","left","你说什么？如果你又想要搞什么异变的话，果然在这里先把你退治掉比较好呢！",180,0.6,0.6)
        else
        end
        if GetGlobal('player_name')=='marisa_player' then
            boss.dialog.sentence(self,"image:Marisa_normal","left","唉，这破地方离我家还蛮近的诶。那么到底是什么东西能有那么大的威力呢？",180,0.6,0.6)
            boss.dialog.sentence(self,"image:Marisa_noticed","left","啊，你是那个时候地底的地狱鸦，是叫什么，阿空对吧？",180,0.6,0.6)
            boss.dialog.sentence(self,"image:Utsuho_embarrassed","right","呃，是我，你是魔理沙吧。",180,-0.6,0.6)
            boss.dialog.sentence(self,"image:Marisa_satisfied","left","那么，快说明一下吧！",180,0.6,0.6)
            boss.dialog.sentence(self,"image:Utsuho_amazed","right","啊，你说什么？说明什么啊？",180,-0.6,0.6)
            boss.dialog.sentence(self,"image:Marisa_angry","left","哈？你不要给我装傻哦，我们全都听见了呢，那整个幻想乡都挺得见的巨大的爆炸声。",180,0.6,0.6)
            boss.dialog.sentence(self,"image:Marisa_satisfied","left","是你弄的吧，阿空。",180,0.6,0.6)
            boss.dialog.sentence(self,"image:Utsuho_embarrassed","right","呃，是……啊不对，和我没关系啊，我……我只是路过的。",180,-0.6,0.6)
            boss.dialog.sentence(self,"image:Marisa_upset","left","不要狡辩了，除了你的核融合之力，还什么有东西能弄出那么大的动静呢？",180,0.6,0.6)
            boss.dialog.sentence(self,"image:Utsuho_embarrassed","right","不不不，就算是我的力量也达不到那么大的威力的。",180,-0.6,0.6)
            boss.dialog.sentence(self,"image:Marisa_angry","left","看来你是不见棺材不落泪了daze，看来我又要像上次一样给你点颜色看看了！",180,0.6,0.6)
        else
        end
        if GetGlobal('player_name')=='sanae_player' then
            boss.dialog.sentence(self,"image:Sanae_speechless","left","就是这里了呢。居然就在妖怪之山山脚的不远处，要是对我们的神社造成了损害那可不太好啦。",180,0.6,0.6)
            boss.dialog.sentence(self,"image:Sanae_amazed","left","诶！是你，灵乌路空！",180,0.6,0.6)
            boss.dialog.sentence(self,"image:Utsuho_embarrassed","right","啊，早苗小姐，你好。",180,-0.6,0.6)
            boss.dialog.sentence(self,"image:Sanae_amazed","left","你在这里做什么？",180,0.6,0.6)
            boss.dialog.sentence(self,"image:Utsuho_en","right","我，我找神奈子大人有事，不过好像迷路了……",180,-0.6,0.6)
            boss.dialog.sentence(self,"image:Sanae_laugh","left","啊哈哈，我们的神社是在山上啊，你怎么找到这里来了，你果然是个鸟脑袋啊。",180,0.6,0.6)
            boss.dialog.sentence(self,"image:Utsuho_angry","right","（无法反驳，好想揍她一顿）",180,-0.6,0.6)
            boss.dialog.sentence(self,"image:Sanae_normal","left","话说，你又没有听见这里传来巨大的响声？那种大到全世界都能听见的声音。",180,0.6,0.6)
            boss.dialog.sentence(self,"image:Utsuho_en","right","那个，大概，就是我弄的吧。",180,-0.6,0.6)
            boss.dialog.sentence(self,"image:Sanae_amazed","left","什么？！你是在这里使用了你的核融合能力吗？这也太危险了吧！",180,0.6,0.6)
            boss.dialog.sentence(self,"image:Utsuho_amazed","right","我，我没有，那根本不是核融合之力，我就是为了这个才想去问问神奈子大人……",180,-0.6,0.6)
            boss.dialog.sentence(self,"image:Sanae_angry","left","不可饶恕，不可饶恕，看来得教训你一顿呢，你这个笨头笨脑的乌鸦。",180,0.6,0.6)
        else
        end
        if GetGlobal('player_name')=='wuer_player' then
            boss.dialog.sentence(self,"image:Utsuho_amazed","right","哇，在这种地方居然有人类啊。",180,-0.6,0.6)
            boss.dialog.sentence(self,"image:Utsuho_amazed","right","这里不是你该来的地方，很危险的哦，快回去吧。",180,-0.6,0.6)
            boss.dialog.sentence(self,"image:Utsuho_en","right","什么？你说你是来调查爆炸的？",180,-0.6,0.6)
            boss.dialog.sentence(self,"image:Utsuho_embarrassed","right","你认为是我干的吗？",180,-0.6,0.6)
            boss.dialog.sentence(self,"image:Utsuho_angry","right","人类，我觉得你有必要搞清楚你说话的对象，你以为你能活着从我面前离开吗？",180,-0.6,0.6)
            boss.dialog.sentence(self,"image:Utsuho_peace","right","是我干的又怎样？正好咱觉醒了新的力量呢。",180,-0.6,0.6)
            boss.dialog.sentence(self,"image:Utsuho_angry","right","那么 ，你就来当我的下一个试验品吧！",180,-0.6,0.6)
        else
        end
        LoadMusicRecord("Solar");_play_music("Solar")
    end)
end
