                vi=vi+_d_vi end end
                task._Wait(2)
            ani=ani+_d_ani n=n+_d_n waits=waits+_d_waits end end
            task._Wait(180)
            do local ani,_d_ani=(ran:Float(70,110)),(24) local n,_d_n=(1),(1) local waits,_d_waits=(60),(-1) for _=1,20 do
                local an = 0
                PlaySound("tan00",0.1,self.x/256,false)
                if n%3==0 then
                    an=an+20
                else
                    if n%3==1 then
                        an=an-20
                    else
