_tmp_sc=boss.card.New("",2,5,60,1200,{0,0,0},false)
function _tmp_sc:init()
    task.New(self,function()
        task.MoveTo(0,124,60,MOVE_NORMAL)
        task._Wait(60)
        do for _=1,_infinite do
            task.MoveTo(ran:Float(50,70),124,40,MOVE_NORMAL)
            task._Wait(180)
            task.MoveTo(ran:Float(-110,-70),104,60,MOVE_NORMAL)
            task._Wait(180)
            task.MoveTo(0,144,40,MOVE_NORMAL)
            task._Wait(120)
            task._Wait(180)
            task._Wait(5)
        end end
    end)
    task.New(self,function()
        task._Wait(120)
        do for _=1,_infinite do
            do local ani,_d_ani=(ran:Float(-20,30)),(10) local n,_d_n=(1),(1) local waits,_d_waits=(60),(-1) for _=1,20 do
                local an = 0
                PlaySound("tan00",0.1,self.x/256,false)
                if n%3==0 then
                    an=an+20
                else
                    if n%3==1 then
                        an=an-20
                    else
                    end
                end
                do local vi,_d_vi=(1),(0.3) for _=1,7 do
                    last=New(_editor_class["ynsc_2"],self.x,self.y,vi,ani+180,waits,an+180,true,1.6)
                    last=New(_editor_class["ynsc_2"],self.x,self.y,vi,ani,waits,an,true,1.6)
                    task._Wait(0)
                vi=vi+_d_vi end end
                task._Wait(2)
            ani=ani+_d_ani n=n+_d_n waits=waits+_d_waits end end
            task._Wait(180)
            do local ani,_d_ani=(ran:Float(160,200)),(8) local n,_d_n=(1),(1) local waits,_d_waits=(60),(-1) for _=1,30 do
                PlaySound("tan00",0.1,self.x/256,false)
                do local vi,_d_vi=(1),(0.3) for _=1,7 do
                    last=New(_editor_class["ynsc_2"],self.x,self.y,vi,ani,waits,Angle(self,player),false,1.6)
                    last=New(_editor_class["ynsc_2"],self.x,self.y,vi,ani+180,waits,Angle(self,player)+180,false,1.6)
                    task._Wait(0)
                vi=vi+_d_vi end end
                task._Wait(2)
            ani=ani+_d_ani n=n+_d_n waits=waits+_d_waits end end
            task._Wait(180)
            do local ani,_d_ani=(ran:Float(70,110)),(16) local n,_d_n=(1),(1) local waits,_d_waits=(60),(-1) for _=1,20 do
                local an = 0
                PlaySound("tan00",0.1,self.x/256,false)
                if n%3==0 then
                    an=an+20
                else
                    if n%3==1 then
                        an=an-20
                    else
                    end
                end
                do local vi,_d_vi=(1),(0.3) for _=1,7 do
                    last=New(_editor_class["ynsc_2"],self.x,self.y,vi,ani+180,waits,an+180,true,1.6)
                    last=New(_editor_class["ynsc_2"],self.x,self.y,vi,180-ani,waits,an,true,1.6)
                    task._Wait(0)
                vi=vi+_d_vi end end
                task._Wait(2)
            ani=ani+_d_ani n=n+_d_n waits=waits+_d_waits end end
            task._Wait(120)
            do for _=1,12 do
                _create_bullet_group(ball_huge,COLOR_RED,self.x,self.y,25,0,3,3,0,360,true,0,true,true,0,false,self)
                PlaySound("tan00",0.1,self.x/256,false)
                task._Wait(10)
            end end
            task._Wait(60)
            task._Wait(5)
        end end
    end)
end
function _tmp_sc:del()
end
