_tmp_sc=boss.card.New("「质子对湮灭」",5,8,115,4000,{0,0,0},true)
function _tmp_sc:init()
    boss.show_aura(self,true)
    self.colli=true
    boss.yyzyach2=1
    local yyzyach21 = player.death
    local yyzyach22 = player.nextspell
    task.New(self,function()
        task.MoveTo(0,144,90,MOVE_NORMAL)
        boss.cast(self,60)
        New(boss_cast_ef,self.x,self.y)
        task._Wait(60)
        local inv = 144
        do local s,_d_s=(1),(1) for _=1,_infinite do
            do local setx,_d_setx=(ran:Float(-210,-190)),(20) for _=1,24 do
                last=New(_editor_class["yzlast"],setx,230+ran:Float(-s,s)/4,0.8,-90,ran:Float(-s,s)-30)
                PlaySound("tan00",0.1,self.x/256,false)
                task._Wait(0)
            setx=setx+_d_setx end end
            task._Wait(inv)
            if inv>60 then
                inv=inv-4
            else
            end
            task._Wait(1)
        s=s+_d_s end end
    end)
    task.New(self,function()
        do for _=1,_infinite do
            if (player.death==yyzyach21) and (player.nextspell ==yyzyach22) then
            else
                boss.yyzyach2=0
                if true then break end
            end
            task._Wait(1)
        end end
    end)
end
function _tmp_sc:del()
    if (self.timer>=6900) and (boss.yyzyach2==1) and (not ext.replay.IsReplay()) then
        New(achievement_obj,1,24)
        --[[ 获得成就：不稳定的根源 --]]
    else
    end
end
