_editor_class["YYZY_boss2:Lunatic"].name="Utsuho?"
_editor_class["YYZY_boss2:Lunatic"].init=function(self,cards)
    boss.init(self,0,144,"Utsuho?",cards,New(_editor_class["boss"]))
	self.difficulty="Lunatic"
	self.ani_intv=8
	for i=1,4 do self['img'..i]={} end
	self.nn={4,3,3,4}
	self.mm={1,1,1}
	for i=2,4 do self['ani'..i]=self.nn[i]-self.mm[i-1] end
	for i=1,4 do
		for j=1,self.nn[i] do
			self['img'..i][j]='anonymous:'.."utsuho2.png"..i..j
		end
	end
end
