_tmp_sc=boss.dialog.New(true)
function _tmp_sc:init()
	lstg.player.dialog=true
	_dialog_can_skip=true
	self.dialog_displayer=New(dialog_displayer)
    task.New(self,function()
        boss.show_aura(self,false)
        LoadMusicRecord("star");_play_music("star")
        task._Wait(300)
        boss.cast(self,120)
        New(boss_cast_ef,self.x,self.y)
        PlaySound("explode",0.1,self.x/256,false)
        misc.ShakeScreen(120, 2)
        task._Wait(120)
        PlaySound("explode",0.1,self.x/256,false)
        misc.ShakeScreen(120, 4)
        task._Wait(120)
        PlaySound("explode",0.1,self.x/256,false)
        misc.ShakeScreen(120, 6)
        task._Wait(120)
        PlaySound("alert",8,self.x/256,false)
    end)
end
