_editor_class["s1b1"]=Class(bullet)
_editor_class["s1b1"].init=function(self,_x,_y,vi,an,dir)
    bullet.init(self,ball_mid_c,COLOR_BLUE,true,true)
    self.x,self.y=_x,_y
    SetV2(self,vi,an,true,false)
    task.New(self,function()
        do local t,_d_t=(0),(0.2) for _=1,_infinite do
            SetV2(self,vi,an+dir*t,true,false)
            task._Wait(1)
        t=t+_d_t end end
    end)
end
_editor_class["yyzy_b02"]=Class(bullet)
_editor_class["yyzy_b02"].init=function(self,_x,_y,vi,vt,an,ac,stl,co)
    bullet.init(self,stl,co,true,true)
    self.x,self.y=_x,_y
    SetV2(self,vi,an,true,false)
    task.New(self,function()
        if ac==0 then
        else
            local t = abs((vi-vt)/ac)
            _set_a(self,ac,an+180,false)
            task._Wait(t)
            _set_a(self,0,an,false)
        end
    end)
end
_editor_class["yyzy_b02"].frame=function(self)
    self.class.base.frame(self)
    self.rot=self.rot+0.5
end
_editor_class["Generlize"]=Class(bullet)
