_editor_class["return"]=Class(bullet)
_editor_class["return"].init=function(self,_x,_y,ve,an,ac)
    bullet.init(self,ball_mid,COLOR_BLUE,true,false)
    self.x,self.y=_x,_y
    self.bound=false
    task.New(self,function()
        SetV2(self,ve,an,true,false)
        do local ia,_d_ia=(an),(-ac) for _=1,180 do
            SetV2(self,ve,ia+180,true,false)
            task._Wait(1)
        ia=ia+_d_ia end end
        PlaySound("boon00",0.1,self.x/256,false)
        ChangeBulletImage(self,ball_mid,COLOR_DEEP_RED)
        do local ia,_d_ia=(an),(-ac) for _=1,180 do
            SetV2(self,-ve,ia-180,true,false)
            task._Wait(1)
        ia=ia+_d_ia end end
        self.bound=true
    end)
end
_editor_class["yyzy_ch"]=Class(bullet)
_editor_class["yyzy_ch"].init=function(self,_x,_y,vi,vt,a,flag,co,t)
    bullet.init(self,arrow_big,co,true,true)
    self.x,self.y=_x,_y
    SetV2(self,vi,a,true,false)
    task.New(self,function()
        task._Wait(t)
        if flag==1 then
            last=New(_straight,arrow_big,COLOR_RED,self.x,self.y,vt,0,true,0,true,true,0,false,0,0,0,false)
            _del(self,true)
        else
        end
    end)
end
_editor_class["transparent"]=Class(bullet)
_editor_class["transparent"].init=function(self,_x,_y,v,a)
    bullet.init(self,ball_mid,COLOR_BLUE,true,true)
    self.x,self.y=_x,_y
    SetV2(self,v,a,true,false)
    local flag = 1
    _object.set_color(self,"mul+add",255,255,255,255)
end
_editor_class["transparent"].frame=function(self)
    self.class.base.frame(self)
    flag=1
    for _,unit in ObjList(GROUP_INDES) do
        if Dist(unit,self)<unit.hscale*120 then
            flag=0
        else
            flag=flag*1
        end
    end
    if flag==1 then
        _object.set_color(self,"",5,255,255,255)
    else
        _object.set_color(self,"mul+add",255,255,255,255)
    end
end
_editor_class["def"]=Class(bullet)
_editor_class["def"].init=function(self,_x,_y,t,dir)
    bullet.init(self,ball_light,COLOR_YELLOW,true,false)
    self.x,self.y=_x,_y
    task.New(self,function()
        do local r,_d_r=(0),(t) local a,_d_a=(ran:Float(0,360)),(3*t) for _=1,_infinite do
            self.x=r*cos(a*dir)
            self.y=r*sin(a*dir)
            if dir>0 then
                last=New(_straight,arrow_big,COLOR_RED,self.x,self.y,0,4*a+90,false,0,true,true,300-self.timer,false,0.02,4*a+90,0.8,false)
            else
                last=New(_straight,arrow_big,COLOR_BLUE,self.x,self.y,0,4*a+90,false,0,true,true,300-self.timer,false,0.02,4*a+90,0.8,false)
            end
            task._Wait(1)
        r=r+_d_r a=a+_d_a end end
    end)
end
