_editor_class["nuclear_mid"]=Class(_object)
_editor_class["nuclear_mid"].init=function(self,_x,_y,v,wait)
    self.x,self.y=_x,_y
	self.img="image:etama7a"
	self.layer=LAYER_ENEMY_BULLET-1
	self.group=GROUP_INDES
	self.hide=false
	self.bound=true
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    _object.set_color(self,"mul+add",255,255,155,155)
    self.hscale=0.05
    self.vscale=0.05
    last=New(_editor_class["nuclear_flash_mid"],self.x,self.y,v,wait)
    task.New(self,function()
        PlaySound("ch02",0.1,self.x/256,false)
        do local p,_d_p=(0.05),(0.01) for _=1,45 do
            self.hscale=p
            self.vscale=p
            self.a=p*80
            self.b=p*80
            task._Wait(1)
        p=p+_d_p end end
        task._Wait(wait)
        SetV2(self,v,Angle(self,player),true,false)
        do for _=1,_infinite do
            if abs(self.y)>224 or abs(self.x)>192 then
                PlaySound("explode",0.1,self.x/256,false)
                do for _=1,25 do
                    last=New(_straight,water_drop,COLOR_DEEP_RED,self.x+ran:Float(-20,20),self.y+ran:Float(-20,20),ran:Float(1,2),ran:Float(0,360),false,0,true,true,0,false,0,0,0,false)
                    task._Wait(0)
                end end
                _kill(self,true)
            else
            end
            task._Wait(1)
        end end
    end)
end
