        do local p,_d_p=(0.05),(0.01) for _=1,45 do
            self.hscale=p
            self.vscale=p
            self.a=p*80
            self.b=p*80
            task._Wait(2)
        p=p+_d_p end end
        task._Wait(wait)
        PlaySound("explode",0.1,self.x/256,false)
