_editor_class["Rot"]=Class(_object)
_editor_class["Rot"].init=function(self,_x,_y,t,r,a,inc,v,way,inv)
    self.x,self.y=_x,_y
	self.img="image:etama7b"
	self.layer=LAYER_ENEMY_BULLET-1
	self.group=GROUP_INDES
	self.hide=false
	self.bound=true
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    self.hscale=0.8
    self.vscale=0.8
    _object.set_color(self,"mul+add",150,100,100,255)
    task.New(self,function()
        do local l,_d_l=(0),(1) for _=1,r do
            self.x=l*cos(a)
            self.y=l*sin(a)
            task._Wait(1)
        l=l+_d_l end end
        SetV2(self,0,0,true,false)
        task._Wait(60)
        do local theta,_d_theta=(a),(t) for _=1,_infinite do
            self.x=r*cos(theta)
            self.y=r*sin(theta)
            task._Wait(1)
        theta=theta+_d_theta end end
    end)
    task.New(self,function()
        task._Wait(120)
        do local an,_d_an=(ran:Float(0,360)),(inc) for _=1,_infinite do
            do local angle,_d_angle=(an),(360/way) for _=1,way do
                last=New(_editor_class["transparent"],self.x,self.y,v,angle)
                PlaySound("tan00",0.1,self.x/256,false)
                task._Wait(0)
            angle=angle+_d_angle end end
            task._Wait(inv)
        an=an+_d_an end end
    end)
end
