    self.vscale=0.05
    _object.set_color(self,"mul+add",150,100,100,255)
    task.New(self,function()
        do for _=1,_infinite do
            if self.hscale>pt then
                r=-abs(r)
            else
            end
            if self.hscale<pi then
                r=abs(r)
