    bullet.init(self,ball_mid_c,COLOR_GRAY,true,false)
    self.x,self.y=_x,_y
    SetV2(self,v,a,true,false)
    _object.set_color(self,"mul+rev",255,255,255,255)
    local newv = v*(self.y+mid)/(self.y-mid)
    last=New(_editor_class["yzdisp"],self.x,-self.y,newv,a+180,(self.y+mid)/newv)
    task.New(self,function()
        do for _=1,_infinite do
            if self.y<=mid then
                last=New(_straight,water_drop,COLOR_RED,self.x,self.y,ran:Float(0.7,1.3),ran:Float(0,360),false,0,true,true,0,false,0,0,0,false)
                last=New(_straight,water_drop,COLOR_BLUE,self.x,self.y,ran:Float(0.7,1.3),ran:Float(0,360),false,0,true,true,0,false,0,0,0,false)
                PlaySound("tan00",0.1,self.x/256,false)
                _del(self,true)
