_editor_class["yzsc5"]=Class(bullet)
_editor_class["yzsc5"].init=function(self,_x,_y,v,a,w,co,wait,way)
    bullet.init(self,ball_mid,co,true,false)
    self.x,self.y=_x,_y
    SetV2(self,v,a,true,false)
    _set_a(self,v/150,a+180,false)
    local flag = 1
    self.bound=false
    task.New(self,function()
        task._Wait(150)
        SetV2(self,0,0,true,false)
        _set_a(self,0,0,false)
        task._Wait(wait)
        PlaySound("tan02",0.1,self.x/256,false)
        ChangeBulletImage(self,ball_mid,co)
        do local r,_d_r=(Dist(self.x,self.y,0,0)),(0) local theta,_d_theta=(a),(w) for _=1,_infinite do
            self.x=r*cos(theta)
            self.y=r*sin(theta)
            for _,unit in ObjList(10) do
                if Dist(unit,self)<unit.hscale*96 then
                    flag=0
                else
                    flag=flag*1
                end
            end
            if flag==0 then
                PlaySound("explode",0.1,self.x/256,false)
                _create_bullet_group(ball_small,COLOR_DEEP_GRAY,self.x,self.y,way,0,1-v/4,1-v/4,theta,360,false,0,true,true,0,false,self)
                _del(self,true)
            else
            end
            task._Wait(1)
        r=r+_d_r theta=theta+_d_theta end end
    end)
end
_editor_class["yyzylsc1"]=Class(laser)
_editor_class["yyzylsc1"].init=function(self,_x,_y,a,w,co)
    laser.init(self,co,_x,_y,0,0,512,128,4,0,0)
    self.bound=false

    self.colli=false
    task.New(self,function()
        self.rot=a
        PlaySound("lazer00",0.3,self.x/256,false)
        laser._TurnHalfOn(self,1,true)
        task._Wait(60)
        laser._TurnOn(self,15,false,true)
        self.colli=true
        task._Wait(150)
        laser._TurnOff(self,15,true)
        _del(self,true)
    end)
    task.New(self,function()
        do for _=1,_infinite do
            self.rot=self.rot+w
            task._Wait(1)
        end end
    end)
end
