_editor_class["stupid_logo"]=Class(_object)
_editor_class["stupid_logo"].init=function(self,_x,_y,_)
    self.x,self.y=_x,_y
	self.img="image:stupid_logo"
	self.layer=LAYER_TOP+1
	self.group=GROUP_INDES
	self.hide=false
	self.bound=true
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=false
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    task.New(self,function()
        do local Alpha,_d_Alpha=(0),(2.5) for _=1,90 do
            _object.set_color(self,"",Alpha,255,255,255)
            task._Wait(1)
        Alpha=Alpha+_d_Alpha end end
        task._Wait(180)
        do local Alpha,_d_Alpha=(225),(-3.2) for _=1,60 do
            _object.set_color(self,"",Alpha,255,255,255)
            task._Wait(1)
        Alpha=Alpha+_d_Alpha end end
        _del(self,true)
    end)
    task.New(self,function()
        task.MoveTo(0,50,90,MOVE_NORMAL)
    end)
end
