_editor_class["wave1-1 r"]=Class(enemy)
_editor_class["wave1-1 r"].init=function(self,_x,_y,X)
    enemy.init(self,1,10,false,true,false)
    self.x,self.y=_x,_y
    self.drop={5,0,5}
    task.New(self,function() self.protect=true task.Wait(1) self.protect=false end)
    task.New(self,function()
        task.MoveTo(X,120,60,MOVE_ACC_DEC)
        task._Wait(30)
        do for _=1,3 do
            PlaySound("tan00",0.8,self.x/256,false)
            _create_bullet_group(grain_a,COLOR_RED,self.x,self.y,5,0,5,5,0,120,true,0,true,true,0,false,self)
            _create_bullet_group(grain_a,COLOR_ROYAL_BLUE,self.x,self.y,5,0,2,2,0,120,true,0,true,true,0,false,self)
            _create_bullet_group(grain_a,COLOR_PURPLE,self.x,self.y,5,0,1,1,0,120,true,0,true,true,0,false,self)
            _create_bullet_group(grain_a,COLOR_GREEN,self.x,self.y,5,0,4,4,0,120,true,0,true,true,0,false,self)
            _create_bullet_group(grain_a,COLOR_YELLOW,self.x,self.y,5,0,3,3,0,120,true,0,true,true,0,false,self)
            task._Wait(60)
        end end
        task.MoveTo(0,300,60,MOVE_ACC_DEC)
    end)
end
