    enemy.init(self,9,200,false,true,false)
    self.x,self.y=_x,_y
    self.drop={10,0,5}
    task.New(self,function() self.protect=true task.Wait(1) self.protect=false end)
    task.New(self,function()
        task.MoveTo(x1,y1,60,MOVE_DECEL)
        task.New(self,function()
            do for _=1,2 do
                PlaySound("tan00",1,self.x/256,false)
                _create_bullet_group(grain_a,COLOR_RED,self.x,self.y,30,0,0.75,0.75,0,360,true,0,true,true,0,false,self)
                do local a,_d_a=(-105),(60) for _=1,6 do
