_editor_class["梦想天生（伪）"]=Class(bullet)
_editor_class["梦想天生（伪）"].init=function(self,_x,_y,angle,color,V,V2,a)
    bullet.init(self,ball_big,COLOR_RED,true,true)
    self.x,self.y=_x,_y
    _object.set_color(self,"mul+add",255,255,255,255)
    task.New(self,function()
        SetV2(self,0,angle,true,false)
        do local v,_d_v=(V),(-V/20) for _=1,20 do
            SetV2(self,v,self.rot,true,false)
            task._Wait(1)
        v=v+_d_v end end
        task._Wait(20)
        PlaySound("kira00",0.5,self.x/256,false)
        do local v,_d_v=(0),(V2/20) for _=1,20 do
            SetV2(self,v,0,true,true)
            task._Wait(1)
        v=v+_d_v end end
        do for _=1,160 do
            SetV2(self,V2+0.01*a*Dist(self.x,self.y,player.x,player.y),0,true,true)
            task._Wait(1)
        end end
        PlaySound("kira00",1,self.x/256,false)
        do local a,_d_a=(0),(60) for _=1,6 do
            last=New(_editor_class["stupid_五角花弹幕"],self.x,self.y,a,1,2)
            task._Wait(0)
        a=a+_d_a end end
        do local a,_d_a=(0),(72) for _=1,5 do
            last=New(_editor_class["stupid_五角花弹幕"],self.x,self.y,a,3,1)
            task._Wait(0)
        a=a+_d_a end end
        task._Wait(2)
        _del(self,true)
    end)
end
