_editor_class["stupid_封位弹"].init=function(self,_x,_y,v1,co,v2,angle,b)
    bullet.init(self,arrow_big,co,true,true)
    self.x,self.y=_x,_y
    task.New(self,function()
        do local V,_d_V=(v1),(-v1/10) for _=1,10 do
            SetV2(self,V,angle,true,true)
            task._Wait(1)
        V=V+_d_V end end
        task._Wait(30)
        PlaySound("kira00",1,self.x/256,false)
        SetV2(self,0,self.rot+b,true,false)
        do local V,_d_V=(0),(v2/10) for _=1,10 do
