_editor_class["stupid_封位弹小妖精:Lunatic"]=Class(enemy)
_editor_class["stupid_封位弹小妖精:Lunatic"].init=function(self,_x,_y,x0,y0,x1,y1,t)
    enemy.init(self,8,80,false,true,false)
    self.x,self.y=_x,_y
    self.drop={10,0,10}
    task.New(self,function() self.protect=true task.Wait(1) self.protect=false end)
    --[[ x0,y0为位移至的初坐标， x1,y1为离场时的坐标,t为发射弹幕的等待时间 --]]
    task.New(self,function()
        task.MoveTo(x0,y0,60,MOVE_DECEL)
        task.New(self,function()
            task._Wait(t)
            do for _=1,_infinite do
                local A = ran:Int(-10,10)
                do local D,_d_D=(A),(30) for _=1,12 do
                    local B = D
                    task.New(self,function()
                        PlaySound("tan00",1,self.x/256,false)
                        do local C,_d_C=(B-30),(5) local v,_d_v=(1),(0.25) for _=1,12 do
                            last=New(_editor_class["stupid_封位弹"],self.x,self.y,8,1,v,C,-60)
                            task._Wait(0)
                        C=C+_d_C v=v+_d_v end end
                    end)
                    task._Wait(0)
                D=D+_d_D end end
                task._Wait(30)
                do local D,_d_D=(A),(-30) for _=1,12 do
                    local B = D
                    task.New(self,function()
                        PlaySound("tan00",1,self.x/256,false)
                        do local C,_d_C=(B+30),(-5) local v,_d_v=(1),(0.25) for _=1,12 do
                            last=New(_editor_class["stupid_封位弹"],self.x,self.y,8,5,v,C,60)
                            task._Wait(0)
                        C=C+_d_C v=v+_d_v end end
                    end)
                    task._Wait(0)
                D=D+_d_D end end
                task._Wait(210+3*t)
            end end
        end)
        task._Wait(240)
        task.MoveTo(x1,y1,180,MOVE_ACCEL)
        _del(self,true)
    end)
end
_editor_class["stupid_封位弹小妖精:Normal"]=Class(enemy)
_editor_class["stupid_封位弹小妖精:Normal"].init=function(self,_x,_y,x0,y0,x1,y1,t)
    enemy.init(self,8,80,false,true,false)
    self.x,self.y=_x,_y
    self.drop={10,0,10}
    task.New(self,function() self.protect=true task.Wait(1) self.protect=false end)
    --[[ x0,y0为位移至的初坐标， x1,y1为离场时的坐标,t为发射弹幕的等待时间 --]]
    task.New(self,function()
        task.MoveTo(x0,y0,60,MOVE_DECEL)
        task.New(self,function()
            task._Wait(t)
            do for _=1,_infinite do
                local A = ran:Int(-10,10)
                do local D,_d_D=(A),(60) for _=1,6 do
                    local B = D
                    task.New(self,function()
                        PlaySound("tan00",1,self.x/256,false)
                        do local C,_d_C=(B-60),(10) local v,_d_v=(1),(0.25) for _=1,12 do
                            last=New(_editor_class["stupid_封位弹"],self.x,self.y,8,1,v,C,-60)
                            task._Wait(0)
                        C=C+_d_C v=v+_d_v end end
                    end)
                    task._Wait(0)
                D=D+_d_D end end
                task._Wait(30)
                do local D,_d_D=(A),(-60) for _=1,6 do
                    local B = D
                    task.New(self,function()
                        PlaySound("tan00",1,self.x/256,false)
                        do local C,_d_C=(B+60),(-10) local v,_d_v=(1),(0.25) for _=1,12 do
                            last=New(_editor_class["stupid_封位弹"],self.x,self.y,8,5,v,C,60)
                            task._Wait(0)
                        C=C+_d_C v=v+_d_v end end
                    end)
                    task._Wait(0)
                D=D+_d_D end end
                task._Wait(210+3*t)
            end end
        end)
        task._Wait(240)
        task.MoveTo(x1,y1,180,MOVE_ACCEL)
        _del(self,true)
    end)
end
_editor_class["质子与中子"]=Class(bullet)
_editor_class["质子与中子"].init=function(self,_x,_y,co,B,A,r,v)
    bullet.init(self,ball_mid,co,true,true)
    self.x,self.y=_x,_y
    --[[ co=  (1为红色，5为蓝色） B为相关参数 A为与中心的角度 a为中心横坐标  b为中心纵坐标  r为半径  t为自转角速度  v为核弹炸裂后小玉的扩散速度。 --]]
    self.group=GROUP_ENEMY_BULLET
    task.New(self,function()
        B=1
        do local T,_d_T=(0),(1) for _=1,_infinite do
            if B==0 then
            else
                local t = T
                _set_rel_pos(self,r*cos(A+t),r*sin(A+t),self.rot,false)
            end
            task._Wait(1)
        T=T+_d_T end end
    end)
end
_editor_class["质子与中子"].frame=function(self)
    self.class.base.frame(self)
end
_editor_class["stupid_分裂圆周札"]=Class(bullet)
_editor_class["stupid_分裂圆周札"].init=function(self,_x,_y,v0,t,a0,a01,a1,co,v1)
    bullet.init(self,square,co,true,true)
    self.x,self.y=_x,_y
    --[[ v0为初速度，t为旋转时间，a0为初始角度，a01为每帧角度增量，a1为开始直线运动时角度偏转量，co为颜色（1为红，5为蓝）,v1为开始直线运动时的速度 --]]
    _object.set_color(self,"",220,255,255,255)
    task.New(self,function()
        task.New(self,function()
            self.bound=false
            task._Wait(240)
            self.bound=true
        end)
        self.colli=true
        SetV2(self,0,a0,true,true)
        do local a,_d_a=(self.rot),(a01) for _=1,t do
            SetV2(self,v0,a,true,false)
            task._Wait(1)
        a=a+_d_a end end
        SetV2(self,v1,self.rot+a1,true,false)
    end)
end
