                self.flag=0
                task.New(self,function()
                    SetV2(self,0,0,true,true)
                    PlaySound("kira00",1,self.x/256,false)
                    ChangeBulletImage(self,arrow_small,COLOR_RED)
                    task._Wait(40)
                    do local v,_d_v=(0),(v0/180) for _=1,180 do
                        SetV2(self,v,self.rot,true,false)
                        task._Wait(1)
                    v=v+_d_v end end
                end)
                if true then break end
            else
                SetV2(self,v,self.rot,true,false)
            end
            task._Wait(1)
        v=v+_d_v end end
    end)
end
