_editor_class["“⑨符”弹幕"]=Class(bullet)
_editor_class["“⑨符”弹幕"].init=function(self,_x,_y,v0,t1,an1,v1,t2,t,n,AN,T,n2,an2,n3,v2)
    bullet.init(self,grain_b,COLOR_BLUE,true,true)
    self.x,self.y=_x,_y
    task.New(self,function()
        self.bound=false
        SetV2(self,v0,an1,true,false)
        do local v,_d_v=(v0),(-v0/t1) for _=1,t1 do
            SetV2(self,v,self.rot,true,false)
            task._Wait(1)
        v=v+_d_v end end
        task._Wait(t)
        do local a,_d_a=(self.rot),(AN/n) for _=1,n do
            SetV2(self,0,a,true,false)
            task._Wait(1)
        a=a+_d_a end end
        do local v,_d_v=(0),(v1/t2) for _=1,t2 do
            SetV2(self,v,self.rot,true,false)
            task._Wait(1)
        v=v+_d_v end end
        task._Wait(T)
        do local a,_d_a=(self.rot),(an2/n2) for _=1,n2 do
            SetV2(self,v1,a,true,false)
            task._Wait(1)
        a=a+_d_a end end
        do local v,_d_v=(v1),(v2/n3) local a,_d_a=(self.rot),(an2/n3) for _=1,n3 do
