_editor_class["海市蜃楼弹幕"]=Class(bullet)
_editor_class["海市蜃楼弹幕"].init=function(self,_x,_y,n,angle,c,v,t,color,style,a)
    bullet.init(self,style,color,true,false)
    self.x,self.y=_x,_y
    --[[ n为折射率，angle，为初射角度，c为临界角，v为最大速度,t为等待时间,style为弹幕类型，color为弹幕颜色,a为弹幕加速度 --]]
    --[[ b为入射，d为出射 --]]
    task.New(self,function()
        self.bound=false
    end)
    task.New(self,function()
        SetV2(self,0,angle,true,false)
        task._Wait(t)
        PlaySound("kira00",1,self.x/256,false)
        do local v1,_d_v1=(0),(a) for _=1,240 do
            if self.x<-150 then
                if self.rot>0  and self.rot<=90 then
                    local d = self.rot
                    local e = sin(d)
                    local b = asin(e/n)
                    self.rot=b
                    SetV2(self,v1,self.rot,true,false)
                else
                end
                if self.rot>90 and self.rot<=180 then
                    if 180-self.rot<c then
                        local b = 180-self.rot
                        local e = sin(b)
                        local d = asin(n*e)
                        self.rot=180-d
                        SetV2(self,v1,self.rot,true,false)
                    else
                        local An = 180-2*self.rot
                        do local a,_d_a=(self.rot),(An/60) for _=1,60 do
                            SetV2(self,v1,a,true,false)
                            task._Wait(1)
                        a=a+_d_a end end
                    end
                else
                end
                if self.rot>180 and self.rot<=270 then
                    if self.rot-180<c then
                        local b = self.rot-180
                        local e = sin(b)
                        local d = asin(n*e)
                        self.rot=d+180
                        SetV2(self,v1,self.rot,true,false)
                    else
                        local An = 180-2*c
                        do local a,_d_a=(self.rot),(An/60) for _=1,60 do
                            SetV2(self,v1,a,true,false)
                            task._Wait(1)
                        a=a+_d_a end end
                    end
                else
                end
                if self.rot>270 and self.rot<=360 then
                    local d = 360-self.rot
                    local e = sin(d)
                    local b = asin(e/n)
                    self.rot=360-b
                    SetV2(self,v1,self.rot,true,false)
                else
                end
            else
                SetV2(self,v1,self.rot,true,false)
            end
            if self.x>=150 then
                if self.rot>0 and self.rot<=90 then
                    if self.rot<c then
                        local b = self.rot
                        local e = sin(b)
                        local d = asin(e*n)
                        self.rot=d
                        SetV2(self,v1,self.rot,true,false)
                    else
                        local An = 360-2*self.rot
                        do local a,_d_a=(self.rot),(An/60) for _=1,60 do
                            SetV2(self,v1,a,true,false)
                            task._Wait(1)
                        a=a+_d_a end end
                    end
                else
                end
                if self.rot>90 and self.rot<=180 then
                    local d = 180-self.rot
                    local e = sin(d)
                    local b = asin(e/n)
                    self.rot=180-b
                    SetV2(self,v1,self.rot,true,false)
                else
                end
                if self.rot>180 and self.rot<=270 then
                    local d = self.rot-180
                    local e = sin(d)
                    local b = asin(e/n)
                    self.rot=b+180
                    SetV2(self,v1,self.rot,true,false)
                else
                end
                if self.rot>270 and self.rot<=360 then
                    if 360-self.rot<c then
                        local b = 360-self.rot
                        local e = sin(b)
                        local d = asin(e*n)
                        self.rot=360-d
                        SetV2(self,v1,self.rot,true,false)
                    else
                        local An = 540-2*self.rot
                        do local a,_d_a=(self.rot),(An/60) for _=1,60 do
                            SetV2(self,v1,a,true,false)
                            task._Wait(1)
                        a=a+_d_a end end
                    end
                else
                end
            else
                SetV2(self,v1,self.rot,true,false)
            end
            task._Wait(1)
        v1=v1+_d_v1 end end
        do local v1,_d_v1=(240*a),(0) for _=1,_infinite do
            if self.x<-150 then
                if self.rot>0  and self.rot<=90 then
                    local d = self.rot
                    local e = sin(d)
                    local b = asin(e/n)
                    self.rot=b
                    SetV2(self,v1,self.rot,true,false)
                else
                end
                if self.rot>90 and self.rot<=180 then
                    if 180-self.rot<c then
                        local b = 180-self.rot
                        local e = sin(b)
                        local d = asin(n*e)
                        self.rot=180-d
                        SetV2(self,v1,self.rot,true,false)
                    else
                        local An = 180-2*self.rot
                        do local a,_d_a=(self.rot),(An/60) for _=1,60 do
                            SetV2(self,v1,a,true,false)
                            task._Wait(1)
                        a=a+_d_a end end
                    end
                else
                end
                if self.rot>180 and self.rot<=270 then
                    if self.rot-180<c then
                        local b = self.rot-180
                        local e = sin(b)
                        local d = asin(n*e)
                        self.rot=d+180
                        SetV2(self,v1,self.rot,true,false)
                    else
                        local An = 180-2*c
                        do local a,_d_a=(self.rot),(An/60) for _=1,60 do
                            SetV2(self,v1,a,true,false)
                            task._Wait(1)
                        a=a+_d_a end end
                    end
                else
                end
                if self.rot>270 and self.rot<=360 then
                    local d = 360-self.rot
                    local e = sin(d)
                    local b = asin(e/n)
                    self.rot=360-b
                    SetV2(self,v1,self.rot,true,false)
                else
                end
            else
                SetV2(self,v1,self.rot,true,false)
            end
            if self.x>=150 then
                if self.rot>0 and self.rot<=90 then
                    if self.rot<c then
                        local b = self.rot
                        local e = sin(b)
                        local d = asin(e*n)
                        self.rot=d
                        SetV2(self,v1,self.rot,true,false)
                    else
                        local An = 360-2*self.rot
                        do local a,_d_a=(self.rot),(An/60) for _=1,60 do
                            SetV2(self,v1,a,true,false)
                            task._Wait(1)
                        a=a+_d_a end end
                    end
                else
                end
                if self.rot>90 and self.rot<=180 then
                    local d = 180-self.rot
                    local e = sin(d)
                    local b = asin(e/n)
                    self.rot=180-b
                    SetV2(self,v1,self.rot,true,false)
                else
                end
                if self.rot>180 and self.rot<=270 then
                    local d = self.rot-180
                    local e = sin(d)
                    local b = asin(e/n)
                    self.rot=b+180
                    SetV2(self,v1,self.rot,true,false)
                else
                end
                if self.rot>270 and self.rot<=360 then
                    if 360-self.rot<c then
                        local b = 360-self.rot
                        local e = sin(b)
                        local d = asin(e*n)
                        self.rot=360-d
                        SetV2(self,v1,self.rot,true,false)
                    else
                        local An = 540-2*self.rot
                        do local a,_d_a=(self.rot),(An/60) for _=1,60 do
                            SetV2(self,v1,a,true,false)
                            task._Wait(1)
                        a=a+_d_a end end
                    end
                else
                end
            else
                SetV2(self,v1,self.rot,true,false)
            end
            task._Wait(1)
        v1=v1+_d_v1 end end
    end)
end
