_tmp_sc=boss.dialog.New(true)
function _tmp_sc:init()
	lstg.player.dialog=false
	_dialog_can_skip=true
	self.dialog_displayer=New(dialog_displayer)
    task.New(self,function()
        if GetGlobal('player_name')=='reimu_player' then
            boss.dialog.sentence(self,"image:stupid_facepisi","right","妖精们，都出来！今晚来搞一场大事~！",nil)
            boss.dialog.sentence(self,"image:stupid_reimu1","left","难道还想让巫女教训你第二次？？！",nil)
            boss.dialog.sentence(self,"image:stupid_facepisi","right","博丽的巫女？欢迎来参加一场......弹幕的盛宴！",nil)
        else
        end
        if GetGlobal('player_name')=='sanae_player' then
            boss.dialog.sentence(self,"image:stupid_facepisi","right","妖精们！都出来！尽情享受今晚的盛宴吧！",nil)
            boss.dialog.sentence(self,"image:stupid_sanae01","left","地狱妖精么？你怎么会在这里？",nil)
            boss.dialog.sentence(self,"image:stupid_facepisi","right","啊哈！你也想来参加这次宴会？",nil)
        else
        end
    end)
end
