_tmp_sc=boss.card.New("",2,3,25,600,{0,0,0},false)
function _tmp_sc:init()
    task.New(self,function()
        task._Wait(60)
        task.New(self,function()
            do for _=1,_infinite do
                PlaySound("ch00",1,self.x/256,false)
                New(boss_cast_ef,self.x,self.y)
                task._Wait(60)
                do local b,_d_b=(270),(36) for _=1,10 do
                    last=New(_editor_class["皮丝道中非的激光生成弹幕:Normal"],self.x,self.y,4,b)
                    task._Wait(2)
                b=b+_d_b end end
                task._Wait(120)
            end end
        end)
        task.New(self,function()
            do for _=1,_infinite do
                task.MoveToPlayer(30,-64,64,100,144,32,32,32,32,MOVE_ACC_DEC,MOVE_X_TOWARDS_PLAYER)
                task._Wait(120)
            end end
        end)
        task.New(self,function()
            s=180
            f=-90
            do for _=1,_infinite do
                _create_bullet_group(star_big,COLOR_RED,self.x,self.y,20,1,4,4,f,s,false,3,true,true,0,false,self)
                s=-s
                task._Wait(20)
            end end
        end)
    end)
end
function _tmp_sc:del()
end
