            do for _=1,_infinite do
                do local a,_d_a=(-90),(36) for _=1,5 do
                    last=New(_editor_class["⑨的冰锥（II）"],self.x,self.y,a)
                    task._Wait(0)
                a=a+_d_a end end
                task._Wait(180)
            end end
        end)
    end)
end
