_tmp_sc=boss.dialog.New(true)
function _tmp_sc:init()
	lstg.player.dialog=false
	_dialog_can_skip=true
	self.dialog_displayer=New(dialog_displayer)
    task.New(self,function()
        if GetGlobal('player_name')=='reimu_player' then
            boss.dialog.sentence(self,"image:stupid_reimu1","left","最近的妖精怎么这么焦躁，不会又有什么异变了吧？",300)
            boss.dialog.sentence(self,"image:stupid_face03no","right","诶，这不是博丽神社的巫女吗？",300)
            boss.dialog.sentence(self,"image:stupid_reimu2","left","又是妖精吗？？！",300)
            boss.dialog.sentence(self,"image:stupid_face02dp","right","哇，斯塔，你竟然找到了巫女！！",300)
            boss.dialog.sentence(self,"image:stupid_reimu3","left","找我？从没有妖精主动找上门过呢！~你们到底想干什么，不老实可是要被退治的~",nil)
            boss.dialog.sentence(self,"image:stupid_face01dp","right","当然是来向巫女发起挑战的咯~",300)
            boss.dialog.sentence(self,"image:stupid_reimu4","left","挑战？！向连妖怪都无法匹敌的巫女挑战？！最近的妖精是怎么了？！",300)
            boss.dialog.sentence(self,"image:stupid_face01dp","right","我们也不知道为什么，就感觉自己变强了很多！",300)
            boss.dialog.sentence(self,"image:stupid_reimu2","left","这群妖精真是和雾之湖的冰精一样哎~",nil)
            boss.dialog.sentence(self,"image:stupid_face02dp","right","哈哈，巫女怕我们了~",300)
            boss.dialog.sentence(self,"image:stupid_reimu1","left","什么嘛，硬要我奉陪的话，收拾你们也就三下五除二的事儿~",nil)
            LoadMusicRecord("BGM BOSS");_play_music("BGM BOSS")
            boss.dialog.sentence(self,"image:stupid_face03hp","right","那意思是要开战咯！~",300)
            boss.dialog.sentence(self,"image:stupid_reimu3","left","好吧，姑且陪你们玩玩，也顺便调查下异变的可能~",300)
            DDDD=1
            task._Wait(2)
            DDDD=2
        else
        end
        if GetGlobal('player_name')=='marisa_player' then
            boss.dialog.sentence(self,"image:stupid_marisa2","left","这些妖精究竟怎么了，这么活跃！~",nil)
            boss.dialog.sentence(self,"image:stupid_face03no","right","诶诶诶，前面的魔法使，等下！~",300)
            boss.dialog.sentence(self,"image:stupid_marisa1","left","这群不是之前被我收拾过的冰精收拾过的妖精么？",nil)
            boss.dialog.sentence(self,"image:stupid_face02dp","right","别提那个笨蛋，现在我们不一样了！",300)
            boss.dialog.sentence(self,"image:stupid_marisa3","left","妖精们总是这副好战的德性呢~省省吧，上次给那个冰精放水放得我好累。",nil)
            boss.dialog.sentence(self,"image:stupid_face01n2","right","你想走？没们儿！",300)
            boss.dialog.sentence(self,"image:stupid_marisa4","left","好啦好啦，你们多大啦，该成熟点了，小打小闹就算了。。",nil)
            boss.dialog.sentence(self,"image:stupid_face01an","right","露娜、斯塔，快栏住她！",300)
            LoadMusicRecord("BGM BOSS");_play_music("BGM BOSS")
            boss.dialog.sentence(self,"image:stupid_face01an","right","那个魔法使！我们是认真的！",300)
            boss.dialog.sentence(self,"image:stupid_marisa5","left","真的没办法了？那只好把你们一块儿收拾了。",nil)
            DDDD=1
            task._Wait(2)
            DDDD=2
        else
        end
        if GetGlobal('player_name')=='sanae_player' then
            boss.dialog.sentence(self,"image:stupid_sanae02","left","妖精怎么没完没了，再迟点恐怕要被神奈子大人骂了..",300)
            boss.dialog.sentence(self,"image:stupid_face03no","right","快看快看，这里有个人类！",300)
            boss.dialog.sentence(self,"image:stupid_face02dp","right","这么晚了居然还有人类，乐子来了！~",300)
            boss.dialog.sentence(self,"image:stupid_face01dp","right","晚上是咱们妖精的天下，不如来捉弄下这个人类，为宴会增加点乐子！~   我们这样做........",300)
            boss.dialog.sentence(self,"image:stupid_face03hp","right","计划完美！桑尼真聪明！她是怎么也想不到的！",300)
            boss.dialog.sentence(self,"image:stupid_face02dp","right","诶，大家准备好啊，她来了来了！",300)
            boss.dialog.sentence(self,"image:stupid_sanae04","left","哦！原来是要捉弄我啊~",300)
            boss.dialog.sentence(self,"image:stupid_face01an","right","喂喂喂，如此完美的计划！你怎么知道的！！",300)
            boss.dialog.sentence(self,"image:stupid_sanae06","left","你们不是说了么？",nil)
            boss.dialog.sentence(self,"image:stupid_sanae04","left","好啦，你们也别捣乱啦，我要走了~",nil)
            boss.dialog.sentence(self,"image:stupid_face01n2","right","能识破我计划的人类，怎么可能走得了？！",nil)
            LoadMusicRecord("BGM BOSS");_play_music("BGM BOSS")
            boss.dialog.sentence(self,"image:stupid_face01n2","right","妖精恶作剧，开始！",nil)
            boss.dialog.sentence(self,"image:stupid_sanae04","left","现在的妖精真是越来越不把人类放眼里了诶~ 只能把你们都退治掉咯~",nil)
            DDDD=1
            task._Wait(2)
            DDDD=2
        else
        end
        if GetGlobal('player_name')=='wuer_player' then
            boss.dialog.sentence(self,"image:stupid_wuer01","left","这里是哪里？怎么这么多奇怪的生物向我发射奇怪的东西..",300)
            boss.dialog.sentence(self,"image:stupid_face03no","right","快看快看，这个是狼女诶！",300)
            boss.dialog.sentence(self,"image:stupid_face02dp","right","为什么她（他）手上拿着一顶锅？",300)
            boss.dialog.sentence(self,"image:stupid_face01dp","right","不知道诶，但她（他）看上去好笨的样子。",300)
            boss.dialog.sentence(self,"image:stupid_wuer03","left","你们好，请问这是哪儿？",300)
            boss.dialog.sentence(self,"image:stupid_face02dp","right","啊，有比我们还笨的狼女？连路都不认识了。",300)
            boss.dialog.sentence(self,"image:stupid_face03hp","right","咱们不如来捉弄她（他）下",300)
            boss.dialog.sentence(self,"image:stupid_wuer01","left","这些奇怪的生物在嘟嘟囔囔什么呢？",300)
            boss.dialog.sentence(self,"image:stupid_face01n2","right","喂，前面那个，我会告诉你，这里是哪儿",nil)
            boss.dialog.sentence(self,"image:stupid_wuer04","left","嗯？",nil)
            boss.dialog.sentence(self,"image:stupid_face01dp","right","不过......",nil)
            LoadMusicRecord("BGM BOSS");_play_music("BGM BOSS")
            boss.dialog.sentence(self,"image:stupid_face01dp","right","请先帮我们......",nil)
            boss.dialog.sentence(self,"image:stupid_face01n2","right","把这口锅接了！",nil)
            DDDD=1
            task._Wait(2)
            DDDD=2
        else
        end
        task._Wait(60)
        DDDD=1
        task._Wait(10)
        DDDD=2
    end)
end
