            boss.dialog.sentence(self,"image:stupid_face01n2","right","能识破我计划的人类，怎么可能走得了？！",nil)
            LoadMusicRecord("BGM BOSS");_play_music("BGM BOSS")
            boss.dialog.sentence(self,"image:stupid_face01n2","right","妖精恶作剧，开始！",nil)
            boss.dialog.sentence(self,"image:stupid_sanae04","left","现在的妖精真是越来越不把人类放眼里了诶~ 只能把你们都退治掉咯~",nil)
            DDDD=1
            task._Wait(2)
            DDDD=2
        else
        end
        if GetGlobal('player_name')=='wuer_player' then
            boss.dialog.sentence(self,"image:stupid_wuer01","left","这里是哪里？怎么这么多奇怪的生物向我发射奇怪的东西..",300)
            boss.dialog.sentence(self,"image:stupid_face03no","right","快看快看，这个是狼女诶！",300)
            boss.dialog.sentence(self,"image:stupid_face02dp","right","为什么她（他）手上拿着一顶锅？",300)
            boss.dialog.sentence(self,"image:stupid_face01dp","right","不知道诶，但她（他）看上去好笨的样子。",300)
            boss.dialog.sentence(self,"image:stupid_wuer03","left","你们好，请问这是哪儿？",300)
            boss.dialog.sentence(self,"image:stupid_face02dp","right","啊，有比我们还笨的狼女？连路都不认识了。",300)
            boss.dialog.sentence(self,"image:stupid_face03hp","right","咱们不如来捉弄她（他）下",300)
            boss.dialog.sentence(self,"image:stupid_wuer01","left","这些奇怪的生物在嘟嘟囔囔什么呢？",300)
            boss.dialog.sentence(self,"image:stupid_face01n2","right","喂，前面那个，我会告诉你，这里是哪儿",nil)
            boss.dialog.sentence(self,"image:stupid_wuer04","left","嗯？",nil)
            boss.dialog.sentence(self,"image:stupid_face01dp","right","不过......",nil)
            LoadMusicRecord("BGM BOSS");_play_music("BGM BOSS")
            boss.dialog.sentence(self,"image:stupid_face01dp","right","请先帮我们......",nil)
            boss.dialog.sentence(self,"image:stupid_face01n2","right","把这口锅接了！",nil)
            DDDD=1
            task._Wait(2)
            DDDD=2
        else
        end
        task._Wait(60)
        DDDD=1
        task._Wait(10)
        DDDD=2
    end)
end
