_tmp_sc=boss.dialog.New(true)
function _tmp_sc:init()
	lstg.player.dialog=true
	_dialog_can_skip=true
	self.dialog_displayer=New(dialog_displayer)
    task.New(self,function()
        if GetGlobal('player_name')=='reimu_player' then
            boss.dialog.sentence(self,"image:stupid_face01sw","right","真的，好像有点厉害。。",nil)
            boss.dialog.sentence(self,"image:stupid_face02dp","right","看来得使用我们的协力技了！",nil)
            boss.dialog.sentence(self,"image:stupid_reimu3","left","要三只一起上了？？！",nil)
            boss.dialog.sentence(self,"image:stupid_face03dp","right","让你看看为什么我们叫光之妖精！！~",nil)
            do local Alpha,_d_Alpha=(255),(-2) for _=1,120 do
                _object.set_color(self,"",Alpha,255,255,255)
                task._Wait(1)
            Alpha=Alpha+_d_Alpha end end
            self.hide=true
            self.colli=false
            PPP=1
            boss.dialog.sentence(self,"image:stupid_reimu4","left","不见了？？！",nil)
            task._Wait(60)
        else
        end
        if GetGlobal('player_name')=='marisa_player' then
            boss.dialog.sentence(self,"image:stupid_marisa5","left","就只有这些吗？",nil)
            boss.dialog.sentence(self,"image:stupid_marisa5","left","不如三只一起上吧，这样收拾你们更快！",nil)
            boss.dialog.sentence(self,"image:stupid_face01an","right","不要小瞧我们！露娜、斯塔，快用协力技！",nil)
            boss.dialog.sentence(self,"image:stupid_face03dp","right","接下来让你见识下光之妖精的魔法吧！",nil)
            do local Alpha,_d_Alpha=(255),(-2) for _=1,120 do
                _object.set_color(self,"",Alpha,255,255,255)
                task._Wait(1)
            Alpha=Alpha+_d_Alpha end end
            self.hide=true
            self.colli=false
            PPP=1
            boss.dialog.sentence(self,"image:stupid_marisa1","left","怎么消失了？",nil)
        else
        end
        if GetGlobal('player_name')=='sanae_player' then
            boss.dialog.sentence(self,"image:stupid_sanae02","left","玩够了没啊？我真的得走了....",nil)
            boss.dialog.sentence(self,"image:stupid_face01n2","right","别着急！~真正的恶作剧在后头呢！",nil)
            do local Alpha,_d_Alpha=(255),(-2) for _=1,120 do
                _object.set_color(self,"",Alpha,255,255,255)
                task._Wait(1)
            Alpha=Alpha+_d_Alpha end end
            self.hide=true
            self.colli=false
            PPP=1
            boss.dialog.sentence(self,"image:stupid_sanae01","left","妖精呢？",nil)
        else
        end
        if GetGlobal('player_name')=='wuer_player' then
            boss.dialog.sentence(self,"image:stupid_wuer01","left","还是没搞懂你们是什么意思......",nil)
            boss.dialog.sentence(self,"image:stupid_face03dp","right","没事，你马上就会懂了~",nil)
            do local Alpha,_d_Alpha=(255),(-2) for _=1,120 do
                _object.set_color(self,"",Alpha,255,255,255)
                task._Wait(1)
            Alpha=Alpha+_d_Alpha end end
            self.hide=true
            self.colli=false
            PPP=1
            boss.dialog.sentence(self,"image:stupid_wuer02","left","咦，她们去哪儿了？",nil)
        else
        end
        PPP=1
        task._Wait(180)
        PPP=2
    end)
end
