_tmp_sc=boss.card.New("协力技「夏夜的帷幕」",0,20,125,4000,{0,0,100},true)
function _tmp_sc:init()
    task.New(self,function()
        task.New(self,function()
            task._Wait(7190)
            --[[ 获得成就：在流星雨中漫游~ --]]
        end)
        last=New(_editor_class["stupid_三月精立绘"],-120,0,_)
