_tmp_sc=boss.card.New("协力技「夏夜的帷幕」",0,20,125,4000,{0,0,100},true)
function _tmp_sc:init()
    task.New(self,function()
        task.New(self,function()
            task._Wait(7190)
            --[[ 获得成就：在流星雨中漫游~ --]]
        end)
        last=New(_editor_class["stupid_三月精立绘"],-120,0,_)
        task._Wait(120)
        New(boss_cast_ef,self.x,self.y)
        task._Wait(60)
        task.New(self,function()
            do local t,_d_t=(120),(-1) for _=1,120 do
                stupid_timer=t
                task._Wait(60)
            t=t+_d_t end end
        end)
        task.New(self,function()
            task.New(self,function()
                do for _=1,_infinite do
                    if _boss.hp<=3300 then
                        PlaySound("tan00",2,self.x/256,false)
                        if true then break end
                    else
                        last=New(_editor_class["sun(hide)"],self.x+100,self.y,self.x,self.y,40,220,45,0.005,1.004,1,20,4,60,15)
                        task._Wait(600)
                    end
                    if stupid_timer<=92 then
                        PlaySound("tan00",1,self.x/256,false)
                        _clear_bullet(true,false)
                        if true then break end
                    else
                    end
                    task._Wait(1)
                end end
            end)
            task.New(self,function()
                do for _=1,_infinite do
                    if _boss.hp<=3300 then
                        last=New(_editor_class["sun(hide)"],self.x+100,self.y,self.x,self.y,50,190,45,0.006,1.006,1,25,1,60,15)
                    else
                    end
                    task._Wait(600)
                end end
            end)
            task.New(self,function()
                do for _=1,_infinite do
                    if _boss.hp<=1900 then
                        PlaySound("tan00",1,self.x/256,false)
                        do for _=1,_infinite do
                            do local a,_d_a=(0),(36) for _=1,10 do
                                PlaySound("tan00",2,self.x/256,false)
                                last=New(_editor_class["stupid_P3狙"],self.x,self.y,a,1)
                                task._Wait(0)
                            a=a+_d_a end end
                            task._Wait(180)
                        end end
                    else
                    end
                    task._Wait(1)
                end end
            end)
            task.New(self,function()
                do for _=1,_infinite do
                    if _boss.hp<=800 then
                        PlaySound("tan00",2,self.x/256,false)
                        do for _=1,_infinite do
                            _create_bullet_group(star_small,COLOR_RED,self.x,self.y,30,0,2,2,ran:Float(0,360),360,false,4,true,true,0,false,self)
                            task._Wait(90)
                        end end
                    else
                    end
                    task._Wait(1)
                end end
            end)
        end)
        task.New(self,function()
            do for _=1,_infinite do
                if _boss.hp>=3300 then
                    self.sp_point={3300/4000*360+90,1900/4000*360+90,800/4000*360+90}
                else
                    PlaySound("enep02",1,self.x/256,false)
                    if true then break end
                end
                task._Wait(1)
            end end
            do for _=1,_infinite do
                if _boss.hp>=1900 then
                    self.sp_point={1900/4000*360+90,800/4000*360+90}
                else
                    New(boss_pointer,self)
                    if true then break end
                end
                task._Wait(1)
            end end
            do for _=1,_infinite do
                if _boss.hp>=800 then
                    self.sp_point={800/4000*360+90}
                else
                    New(boss_pointer,self)
                    if true then break end
                end
                task._Wait(1)
            end end
            self.sp_point={0/4000*360+90}
        end)
    end)
end
function _tmp_sc:del()
    for _,unit in ObjList(GROUP_ENEMY) do
        if unit~=_boss then
            _kill(unit,true)
        else
        end
    end
    if (not ext.replay.IsReplay()) and self.timer>=7500 then
        New(achievement_obj,1,28)
    else
    end
    _drop_item(item_point,100,self.x,self.y)
    _drop_item(item_extend,2,self.x,self.y)
end
