_tmp_sc=boss.dialog.New(true)
function _tmp_sc:init()
	lstg.player.dialog=false
	_dialog_can_skip=true
	self.dialog_displayer=New(dialog_displayer)
    task.New(self,function()
        if GetGlobal('player_name')=='reimu_player' then
            boss.dialog.sentence(self,"image:stupid_爆衣立绘","right","好厉害啊，我们果然不是巫女的对手~",300)
            boss.dialog.sentence(self,"image:stupid_reimu3","left","所以现在能告诉我你们是在做什么了吧！~",300)
            boss.dialog.sentence(self,"image:stupid_爆衣立绘","right","嗯嗯~最近在有两位特别的朋友从外界到了魔法森林，所以所有的妖精都跑来欢迎庆祝！~",300)
            boss.dialog.sentence(self,"image:stupid_reimu2","left","看来还没结束啊~~",300)
        else
        end
        if GetGlobal('player_name')=='marisa_player' then
            boss.dialog.sentence(self,"image:stupid_爆衣立绘","right","哇，你好厉害啊！我们明明变得这么强却还被你不费吹灰之力给打败了！",nil)
            boss.dialog.sentence(self,"image:stupid_marisa4","left","是比原来强了很多，在走之前，我想问下，你们这群小妖精是得到了什么力量么？",300)
            boss.dialog.sentence(self,"image:stupid_爆衣立绘","right","是的，最近有两位从外界进来的姐妹来到了魔法之森，她们的魔法力量使得我们这一块的妖精都变强了~",nil)
            boss.dialog.sentence(self,"image:stupid_marisa1","left","哦豁！看来事情没这么简单，让我去会会她们，看看是谁的魔法更加强大！~",300)
        else
        end
        if GetGlobal('player_name')=='sanae_player' then
            boss.dialog.sentence(self,"image:stupid_爆衣立绘","right","明明我们变聪明了，为什么还是捉弄不了一个笨笨的人类......",300)
            boss.dialog.sentence(self,"image:stupid_sanae04","left","因为你们的对手不是人类，是现人神！",300)
            boss.dialog.sentence(self,"image:stupid_爆衣立绘","right","神才没有这么笨呢，我们魔法森林这块近期也从外界进来了两个神！（补充：其实不是神啦，只是妖精比较笨，认为长得霸气点的就是神）",nil)
            boss.dialog.sentence(self,"image:stupid_sanae05","left","这样啊，怕不是守矢神社又有新的竞争对手了，大家的信仰不能轻易动摇，待到明日就去会会这两个神！",300)
        else
        end
        if GetGlobal('player_name')=='wuer_player' then
            boss.dialog.sentence(self,"image:stupid_爆衣立绘","right","好厉害，今天不是满月啊！",300)
            boss.dialog.sentence(self,"image:stupid_wuer01","left","还是不懂你们什么意思，话说可以带我出去了么！",300)
            boss.dialog.sentence(self,"image:stupid_爆衣立绘","right","（私下悄悄地说：不如我们把他带到她们那去！也算是恶作剧的一环啦啦！）",300)
            boss.dialog.sentence(self,"image:stupid_爆衣立绘","right","诶！这个狼女啊，往这片森林的正前方走，走到深处就能出去了~",300)
            boss.dialog.sentence(self,"image:stupid_wuer01","left","这样啊，走到深处就能走出去......这里的生物怪怪的，这里的地形也怪怪的......暂且听信它们的吧~",300)
        else
        end
    end)
end
