        function(self)
        self.task={}
        end,
        function(self)
        task.Do(self)
        end,
        function(self)
        end
    )
    _spellcard_background.AddLayer(self,"image:背景",false,0,0,0,0,0,0.09,"mul+add",1.5,1.5,
        function(self)
        self.task={}
        end,
        function(self)
        task.Do(self)
        end,
        function(self)
            _object.set_color(self,"add+alpha",255,255,100,100)
        end
    )
    _spellcard_background.AddLayer(self,"image:Vinoshu",false,-20,-50,0,0,0,0,"mul+add",1.3,1.3,
        function(self)
        self.task={}
        end,
