_editor_class["keraha:Lunatic"].init=function(self,cards)
    boss.init(self,240,384,"Keraha",cards,New(_editor_class["keraha"]))
	self.difficulty="Lunatic"
	self.ani_intv=8
	for i=1,3 do self['img'..i]={} end
	self.nn={4,4,4,4}
	self.mm={1,1}
	for i=2,3 do self['ani'..i]=self.nn[i]-self.mm[i-1] end
	for i=1,3 do
		for j=1,self.nn[i] do
			self['img'..i][j]='anonymous:'.."kerahawalk.png"..i..j
		end
	end
end
