function _tmp_sc:init()
	lstg.player.dialog=true
	_dialog_can_skip=false
	self.dialog_displayer=New(dialog_displayer)
    task.New(self,function()
        if GetGlobal('player_name')=='wuer_player' then
            boss.dialog.sentence(self,"image:keraha","right","狗。。。",100)
            boss.dialog.sentence(self,"image:keraha","right","别想到姐姐那里去！",100)
        else
            boss.dialog.sentence(self,"image:keraha","right","人类。。。",100)
            boss.dialog.sentence(self,"image:keraha","right","别想到姐姐那里去！",100)
        end
    end)
end
