_tmp_sc=boss.card.New("凛符「冰刺雹」",2,15,30,600,{0,0,0},false)
function _tmp_sc:init()
    task.New(self,function()
        task.MoveTo(0,144,60,MOVE_NORMAL)
        task._Wait(60)
        do for _=1,_infinite do
            do local o,_d_o=(-70),(20) for _=1,7 do
                last=New(_editor_class["笑脸-冰刺球"],self.x+15,self.y+20,o,0.5)
                task._Wait(0)
            o=o+_d_o end end
            New(boss_cast_ef,self.x,self.y)
            _create_bullet_group(ball_huge,COLOR_CYAN,self.x,self.y,8,0,1,1,ran:Int(0,70),360,false,0,true,true,0,false,self)
            PlaySound("tan00",0.1,self.x/256,false)
            _create_bullet_group(butterfly,COLOR_CYAN,self.x,self.y,30,0,2,2,0,360,false,0,true,true,0,false,self)
            task.MoveToPlayer(60,-96,96,112,144,16,32,8,16,MOVE_NORMAL,MOVE_X_TOWARDS_PLAYER)
            do for _=1,5 do
                last=New(_editor_class["笑脸-冰刺球"],ran:Int(-200,200),220,ran:Int(-30,30),0.5)
                task._Wait(10)
            end end
            task._Wait(70)
        end end
    end)
end
function _tmp_sc:del()
end
table.insert(_editor_class["keraha:Lunatic"].cards,_tmp_sc)
table.insert(_sc_table,{"keraha:Lunatic","凛符「冰刺雹」",_tmp_sc,#_editor_class["keraha:Lunatic"].cards,false})
