            do local b,_d_b=(0),(60) for _=1,6 do
                last=New(_editor_class["笑脸-laser"],self.x,self.y,b,inc)
                task._Wait(0)
            b=b+_d_b end end
            do local b,_d_b=(30),(60) for _=1,6 do
                last=New(_editor_class["笑脸-laser2"],self.x,self.y,b,inc)
                task._Wait(0)
            b=b+_d_b end end
            task._Wait(300)
        inc=inc+_d_inc end end
    end)
