    bullet.init(self,ball_huge_dark,COLOR_RED,true,false)
    self.x,self.y=_x,_y
    task.New(self,function()
        _object.set_color(self,"mul+add",255,255,255,255)
        do local a,_d_a=(1),(0.25) for _=1,_infinite do
            do local t,_d_t=(0),(5) for _=1,72 do
                self.vx=-3*cos(t)
                self.vy=2*sin(t)
                last=New(_editor_class["笑脸-非符固定变"],self.x,self.y,180-t*a)
                PlaySound("tan01",0.1,self.x/256,false)
                task._Wait(3)
            t=t+_d_t end end
            task._Wait(0)
        a=a+_d_a end end
    end)
end
