_editor_class["OLC_circle"]=Class(bullet)
_editor_class["OLC_circle"].init=function(self,_x,_y,cenX,cenY,rx,ry,angle,v,color,tt,ta)
    bullet.init(self,arrow_big,color,true,true)
    self.x,self.y=_x,_y
    PlaySound("tan00",0.1,self.x/256,false)
    self.navi = true
    self.bound = false
    task.New(self,function()
        do local t,_d_t=(tt),(ta) for _=1,_infinite do
            self.x = rx*cos(t)*cos(angle)-ry*sin(t)*sin(angle)+cenX
            self.y = rx*cos(t)*sin(angle)+ry*sin(t)*cos(angle)+cenY
            rx = rx + cos(angle)*v
            ry = ry + sin(angle)*v
            task._Wait(1)
        t=t+_d_t end end
    end)
end
