_editor_class["OLC_BF_Big_01"]=Class(enemy)
_editor_class["OLC_BF_Big_01"].init=function(self,_x,_y,rX,rY,angleC,BC,health,alivet)
    enemy.init(self,9,health,false,true,false)
    self.x,self.y=_x,_y
    self.drop={20,45,30}
    task.New(self,function() self.protect=true task.Wait(1) self.protect=false end)
    task.New(self,function()
        SetV2(self,1,270,false,false)
        task._Wait(60)
        SetV2(self,0,270,false,false)
        task._Wait(600)
        SetV2(self,1,270,false,false)
    end)
    task.New(self,function()
        task._Wait(120)
        do local angleC,_d_angleC=(angleC),(15) for _=1,5 do
            do local B,_d_B=(0),(360/BC) for _=1,BC do
                last=New(_editor_class["OLC_circle"],self.x,self.y,self.x,self.y,25,10,angleC,3,COLOR_RED,B,0.25)
                _connect(self,last,0,true)
                last=New(_editor_class["OLC_circle"],self.x,self.y,self.x,self.y,25,10,-angleC,3,COLOR_BLUE,B,0.25)
                _connect(self,last,0,true)
                task._Wait(0)
            B=B+_d_B end end
            task._Wait(30)
        angleC=angleC+_d_angleC end end
        do for _=1,4 do
            _create_bullet_group(arrow_big,COLOR_RED,self.x,self.y,BC,0,3,3,ran:Float(-360,360),360,false,0,true,true,0,false,self)
            PlaySound("tan00",0.1,self.x/256,false)
            task._Wait(30)
            _create_bullet_group(arrow_big,COLOR_BLUE,self.x,self.y,BC,0,3,3,ran:Float(-360,360),360,false,0,true,true,0,false,self)
            PlaySound("tan00",0.1,self.x/256,false)
            task._Wait(30)
        end end
    end)
    task.New(self,function()
        do for _=1,_infinite do
            if self.timer == alivet then
                _del(self,true)
            else
            end
            task._Wait(1)
        end end
    end)
end
_editor_class["OLC_BF_Big_01"].kill=function(self)
    self.class.base.kill(self)
    New(bullet_cleaner,self.x,self.y, 25, 1, 1, true, true, 0)
end
