    task.New(self,function()
        SetV2(self,3,270,false,false)
        task._Wait(20)
        SetV2(self,0,270,false,false)
        task._Wait(20)
        do local a,_d_a=(ran:Float(-360,360)),(ran:Float(7.5,19.5)) for _=1,_infinite do
            do local ai,_d_ai=(a),(360/d) for _=1,d do
                do for _=1,6 do
                    PlaySound("tan00",0.1,self.x/256,false)
