_editor_class["OLC_ZY_01b"]=Class(bullet)
_editor_class["OLC_ZY_01b"].init=function(self,_x,_y,master)
    bullet.init(self,ball_light,COLOR_YELLOW,true,true)
    self.x,self.y=_x,_y
    self.navi = true
    self.master = master
    task.New(self,function()
        do for _=1,_infinite do
            if IsValid(self.master) then
                _set_rel_pos(self,0,0,self.rot,false)
            else
                self.rect = true
                self.vscale = self.vscale * 0.1
                self.b = self.b * 0.1
                _set_a(self,0.05,0,true)
                if true then break end
            end
            task._Wait(1)
        end end
    end)
end
