_editor_class["OLC_SCDHD_01:Normal"]=Class(enemy)
_editor_class["OLC_SCDHD_01:Normal"].init=function(self,_x,_y,_)
    enemy.init(self,14,300,false,true,false)
    self.x,self.y=_x,_y
    self.drop={0,0,0}
    task.New(self,function() self.protect=true task.Wait(1) self.protect=false end)
    OLC_SCDHD_1 = self
    self.hpbarlen = self.hp/self.maxhp
    self.hscale,self.vscale = 0,0
    self.sc_name = '「镭射魔光」'
    lstg.var.sc_bonus = true
    self.is_combat = true
    self.colli = false
    _object.set_color(self,"",0,255,255,255)
    task.New(self,function()
        task.New(self,function()
            task.MoveTo(0,100,60,MOVE_NORMAL)
        end)
        do local size,_d_size=(0),(1/60) local a,_d_a=(0),(255/60) for _=1,60 do
            self.hscale,self.vscale = size,size
            _object.set_color(self,"",a,255,255,255)
            task._Wait(1)
        size=size+_d_size a=a+_d_a end end
        self.nokill = true
        self.sc_open= true
        New(OLC_spell_card_ef)
        PlaySound("cat00",0.1,self.x/256,false)
        last=New(_editor_class["OLC_SCDHD_01立绘"],self.x,self.y,_)
        self.timer = 0
        do local h,_d_h=(1),(299/60) for _=1,60 do
            self.hp = h
            self.show_hp = true
            task._Wait(1)
        h=h+_d_h end end
        self.hp = 300
        self.nokill = false
        self.colli = true
        task.New(self,function()
            do local a,_d_a=(0),(23) for _=1,_infinite do
                last=New(_editor_class["OLC_伪璃光_01"],self.x,self.y,a)
                task._Wait(5)
            a=a+_d_a end end
        end)
        task.New(self,function()
            do local a,_d_a=(180),(-23) for _=1,_infinite do
                last=New(_editor_class["OLC_伪璃光_01"],self.x,self.y,a)
                task._Wait(5)
            a=a+_d_a end end
        end)
    end)
end
_editor_class["OLC_SCDHD_01:Normal"].frame=function(self)
    self.class.base.frame(self)
    self.hpbarlen = self.hp/self.maxhp
end
_editor_class["OLC_SCDHD_01:Normal"].render=function(self)
    self.class.base.render(self)
    if self.show_hp then
        misc.Renderhpbar(self.x,self.y,90,360,60,64,360,1)
        misc.Renderhp(self.x,self.y,90,360,60,64,360,self.hpbarlen*min(1,self.timer/60))
        Render('base_hp',self.x,self.y,0,0.274,0.274)
        Render('base_hp',self.x,self.y,0,0.256,0.256)
    else
    end
    if self.sc_open then
        local ax,ay=0,0
        if IsValid(lstg.player) then
        	ax=min(max(lstg.player.x*0.05,0),0.9)
        	ay=min(max((lstg.player.y-160)*0.05,0),0.9)
        end
        local alpha=1-ax*ay
        SetFontState('time','',Color(alpha*255,255,255,255))
        local xoffset=384
        if lstg.var.sc_bonus then xoffset=max(384-self.timer*7,0) else xoffset=min(384,(self.timer+1)*7) end
        if self.sc_name~='' then
        	SetImageState('boss_spell_name_bg','',Color(alpha*255,255,255,255))
        	Render('boss_spell_name_bg',192+xoffset,236)
        	RenderTTF('sc_name',self.sc_name,193+xoffset,193+xoffset,226,226,Color(alpha*255,0,0,0),'right','noclip')
        	RenderTTF('sc_name',self.sc_name,192+xoffset,192+xoffset,227,227,Color(alpha*255,255,255,255),'right','noclip')
        end
    else
    end
end
_editor_class["OLC_SCDHD_01:Normal"].kill=function(self)
    self.class.base.kill(self)
    if self.nokill then
        PreserveObject(self)
    else
        _clear_bullet(true,false)
    end
end
