        New(OLC_spell_card_ef)
        PlaySound("cat00",0.1,self.x/256,false)
        last=New(_editor_class["OLC_SCDHD_03立绘"],self.x,self.y,_)
        self.timer = 0
        do local h,_d_h=(1),(299/60) for _=1,60 do
            self.hp = h
            self.show_hp = true
            task._Wait(1)
        h=h+_d_h end end
        self.hp = 300
        self.nokill = false
        self.colli = true
        task.New(self,function()
            do for _=1,_infinite do
                _create_bullet_group(arrow_small,COLOR_RED,self.x,self.y,11,0,0.5,2.5,0,135,true,0,true,true,0,false,self)
                _create_bullet_group(arrow_small,COLOR_RED,self.x,self.y,11,0,1,3,0,135,true,0,true,true,0,false,self)
                _create_bullet_group(arrow_small,COLOR_RED,self.x,self.y,11,0,1.5,3.5,0,135,true,0,true,true,0,false,self)
