_editor_class["OLC_SCDHD_03:Normal"].frame=function(self)
    self.class.base.frame(self)
    self.hpbarlen = self.hp/self.maxhp
end
_editor_class["OLC_SCDHD_03:Normal"].render=function(self)
    self.class.base.render(self)
    if self.show_hp then
        misc.Renderhpbar(self.x,self.y,90,360,60,64,360,1)
        misc.Renderhp(self.x,self.y,90,360,60,64,360,self.hpbarlen*min(1,self.timer/60))
        Render('base_hp',self.x,self.y,0,0.274,0.274)
        Render('base_hp',self.x,self.y,0,0.256,0.256)
    else
    end
    if self.sc_open then
        local ax,ay=0,0
        if IsValid(lstg.player) then
        	ax=min(max(lstg.player.x*0.05,0),0.9)
        	ay=min(max((lstg.player.y-160)*0.05,0),0.9)
        end
        local alpha=1-ax*ay
        SetFontState('time','',Color(alpha*255,255,255,255))
        local xoffset=384
        if lstg.var.sc_bonus then xoffset=max(384-self.timer*7,0) else xoffset=min(384,(self.timer+1)*7) end
        if self.sc_name~='' then
        	SetImageState('boss_spell_name_bg','',Color(alpha*255,255,255,255))
        	Render('boss_spell_name_bg',192+xoffset,236-60)
        	RenderTTF('sc_name',self.sc_name,193+xoffset,193+xoffset,226-60,226-60,Color(alpha*255,0,0,0),'right','noclip')
        	RenderTTF('sc_name',self.sc_name,192+xoffset,192+xoffset,227-60,227-60,Color(alpha*255,255,255,255),'right','noclip')
        end
    else
    end
end
_editor_class["OLC_SCDHD_03:Normal"].kill=function(self)
    self.class.base.kill(self)
    if self.nokill then
        PreserveObject(self)
    else
        _clear_bullet(true,false)
    end
end
