    if self.givepc then
        _drop_item(item_extend,1,0,100)
    else
    end
    if self.givebc then
        _drop_item(item_bomb,1,0,100)
    else
    end
    _drop_item(item_power,self.givepd,0,100)
    _drop_item(item_point,self.givefd,0,100)
