_editor_class["OLC_YF_1"]=Class(bullet)
_editor_class["OLC_YF_1"].init=function(self,_x,_y,v,angle,aca,delay)
    bullet.init(self,music,COLOR_BLUE,true,false)
    self.x,self.y=_x,_y
    self.timer = 11
    self.rot = 270
    self.navi = false
    self.colli = false
    self.hide = true
    self.layer = LAYER_ENEMY_BULLET+1
    task.New(self,function()
        task._Wait(delay/2)
        PlaySound("lgods1",0.1,self.x/256,false)
        self.colli = true
        self.hide = false
        self.layer = LAYER_ENEMY_BULLET+1
        task._Wait(delay/2)
        SetV2(self,v,angle,true,false)
        do for _=1,_infinite do
            angle = angle + aca
            self.rot = 270
            SetV2(self,v,angle,false,false)
            task._Wait(1)
        end end
    end)
end
_editor_class["OLC_YF_2"]=Class(bullet)
_editor_class["OLC_YF_2"].init=function(self,_x,_y,v,angle,aca)
    bullet.init(self,music,COLOR_RED,true,false)
    self.x,self.y=_x,_y
    PlaySound("lgods1",0.1,self.x/256,false)
    self.rot = 270
    self.navi = false
    SetV2(self,v,angle,true,false)
    task.New(self,function()
        do for _=1,_infinite do
            angle = angle + aca
            SetV2(self,v,angle,false,false)
            self.rot = 270
            if self.timer == 50 then
            	v = v/2
            end
            task._Wait(1)
        end end
    end)
end
_editor_class["OLC_Laser_99_1"]=Class(laser_bent)
_editor_class["OLC_Laser_99_1"].init=function(self,_x,_y,a,b,c,ea,eaa,delay,bdelay,bc,bdelay2,angletype)
    laser_bent.init(self,COLOR_GOLDEN_YELLOW,_x,_y,80,8,4,0)
    task.New(self,function()
        SetV2(self,5,a,true,false)
        task._Wait(delay)
        do local acc,_d_acc=(a),(b*5) for _=1,c do
            SetV2(self,2,acc,true,false)
            task._Wait(40/c)
        acc=acc+_d_acc end end
        do local ea,_d_ea=(ea),(eaa) for _=1,_infinite do
            SetV2(self,5,ea,true,false)
            task._Wait(1)
        ea=ea+_d_ea end end
    end)
    task.New(self,function()
        task._Wait(45+delay)
        do local acc,_d_acc=(a),(5) for _=1,bc do
            if angletype == 1 then
                last=New(_editor_class["OLC_YF_1"],self.x,self.y,ran:Float(0.5,1.5),Angle(self,player),ran:Float(-0.75,0.75),bdelay2)
            else
                last=New(_editor_class["OLC_YF_1"],self.x,self.y,ran:Float(0.5,1.5),ran:Float(-360,360),ran:Float(-0.75,0.75 ),bdelay2)
            end
            task._Wait(bdelay)
        acc=acc+_d_acc end end
    end)
end
