_editor_class["OLC_Laser_99_2"].init=function(self,_x,_y,cenx,ceny,rx,ry,startat,v,delay)
    laser_bent.init(self,COLOR_GOLDEN_YELLOW,_x,_y,270/abs(v),8,4,5)
    task.New(self,function()
        do local t,_d_t=(startat),(v) for _=1,_infinite do
            self.x,self.y=cenx+rx*cos(t),ceny+ry*sin(t)
            task._Wait(1)
        t=t+_d_t end end
    end)
    task.New(self,function()
        do for _=1,_infinite do
            last=New(_editor_class["OLC_YF_1"],self.x,self.y,ran:Float(1,2),ran:Float(260,280),ran:Float(-0.8,0.8),0)
            task._Wait(delay)
        end end
    end)
end
