    task.New(self,function()
        do local t,_d_t=(startat),(v) for _=1,_infinite do
            cenx,ceny=player.x,player.y
            self.x,self.y=cenx+rx*cos(t),ceny+ry*sin(t)
            task._Wait(1)
        t=t+_d_t end end
    end)
end
