    PlaySound("lgods4",0.5,self.x/256,false)
    SetV2(self,v,a,true,false)
end
_editor_class["OLC_Bullet_99_2"]=Class(bullet)
_editor_class["OLC_Bullet_99_2"].init=function(self,_x,_y,v,angle,aca)
    bullet.init(self,music,COLOR_RED,true,false)
    self.x,self.y=_x,_y
    PlaySound("lgods1",0.1,self.x/256,false)
    self.rot = 270
    self.navi = false
    self.group = GROUP_INDES
    SetV2(self,v,angle,true,false)
    task.New(self,function()
        self.flag = 1
        self.vd = v
        self.acad = aca
        do for _=1,_infinite do
            if self.flag == 1 and Dist(self,player) <= 80 then
                angle = Angle(self,player)
                aca = 0
                v = 0
                self.flag = 0
                SetV2(self,v,angle,false,false)
                self.rot = 270
                ChangeBulletImage(self,music,COLOR_BLUE)
                task._Wait(60)
                SetV2(self,self.vd,angle,false,false)
                task._Wait(120)
            else
                aca = self.acad
                v = self.vd
                self.flag = 1
                SetV2(self,v,angle,false,false)
                angle = angle + aca
                ChangeBulletImage(self,music,COLOR_RED)
                self.rot = 270
            end
            task._Wait(1)
        end end
    end)
end
_editor_class["OLC_Bullet_99_3"]=Class(bullet)
_editor_class["OLC_Bullet_99_3"].init=function(self,_x,_y,v,angle,aca)
    bullet.init(self,music,COLOR_RED,true,false)
    self.x,self.y=_x,_y
    PlaySound("lgods1",0.1,self.x/256,false)
    self.rot = 270
    self.navi = false
    SetV2(self,v,angle,true,false)
    task.New(self,function()
        do for _=1,_infinite do
            angle = angle + aca
            SetV2(self,v,angle,false,false)
            self.rot = 270
            if self.timer >= 35 then
                SetV2(self,v/2,angle,false,false)
            else
            end
            task._Wait(1)
        end end
    end)
end
