_editor_class["OLC_ZMW_Wan_1"]=Class(_object)
_editor_class["OLC_ZMW_Wan_1"].init=function(self,_x,_y,d)
    self.x,self.y=_x,_y
	self.img="image:OLC_碗"
	self.layer=LAYER_ENEMY+1
	self.group=GROUP_ENEMY
	self.hide=false
	self.bound=true
	self.navi=false
	self.hp=100000000
	self.maxhp=100000000
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    wan = self
    self.d = d
    _connect(self,last,0,true)
    self.hp = 100
    self.maxhp = 100
    task.New(self,function()
        do local size,_d_size=(0),(1.2/30) for _=1,30 do
            self.hscale = size
            self.vscale = size
            task._Wait(1)
        size=size+_d_size end end
        do local size,_d_size=(1.2),(-0.2/15) for _=1,15 do
            self.hscale = size
            self.vscale = size
            task._Wait(1)
        size=size+_d_size end end
        do local y,_d_y=(self.y),((200-self.y)/60) local rot,_d_rot=(0),(180/60) local x,_d_x=(self.x),((175-self.x)/60) for _=1,60 do
            self.x,self.y = x,y
            self.rot = rot
            task._Wait(1)
        y=y+_d_y rot=rot+_d_rot x=x+_d_x end end
        do for _=1,_infinite do
            task.MoveTo(ran:Float(-300,300),ran:Float(180,200),60,MOVE_NORMAL)
            task._Wait(15)
        end end
    end)
    task.New(self,function()
        task._Wait(105)
        do for _=1,_infinite do
            do for _=1,ran:Float(2*d,4*d) do
                self.bx = ran:Float(-75*cos(self.rot),75*cos(self.rot))
                self.by = -self.bx*sin(self.rot)
                last=New(_editor_class["OLC_ZMW_1符bullet"],self.x+self.bx,self.y+self.by,ran:Float(0.25*d,0.75*d),self.rot+90+ran:Float(-45,45))
                task._Wait(5-d)
            end end
            task._Wait(8-d)
        end end
    end)
    task.New(self,function()
        task._Wait(105)
        do for _=1,_infinite do
            do local rot,_d_rot=(180),(-20/60) for _=1,60 do
                self.rot = rot
                task._Wait(1)
            rot=rot+_d_rot end end
            do local rot,_d_rot=(160),(40/120) for _=1,120 do
                self.rot = rot
                task._Wait(1)
            rot=rot+_d_rot end end
            do local rot,_d_rot=(200),(-20/60) for _=1,60 do
                self.rot = rot
                task._Wait(1)
            rot=rot+_d_rot end end
            task._Wait(1)
        end end
    end)
end
