_editor_class["OLC_ZMW_Wan_1"].kill=function(self)
    self.class.base.kill(self)
    _create_bullet_group(ball_light,ran:Int(1,16),self.x,self.y,4*self.d+1,0,5,5,0,360,true,0,true,true,0,false,self)
    _create_bullet_group(ball_light,ran:Int(1,16),self.x,self.y,4*self.d+1,0,4,4,0,360,true,0,true,true,0,false,self)
    _create_bullet_group(ball_light,ran:Int(1,16),self.x,self.y,4*self.d+1,0,3,3,0,360,true,0,true,true,0,false,self)
    PlaySound("enep00",0.8,self.x/256,false)
    if IsValid(_boss) then
        _boss.olc_achi=_boss.olc_achi+1
    else
    end
end
