_editor_class["OLC_Bullet_ZMW_01"]=Class(bullet)
_editor_class["OLC_Bullet_ZMW_01"].init=function(self,_x,_y,v,a,holdtime,color,d)
    bullet.init(self,ball_light,color,true,true)
    self.x,self.y=_x,_y
    self.flag = 2
    task.New(self,function()
        SetV2(self,v,a,true,false)
        do for _=1,_infinite do
            if self.flag == 2 and Dist(self,player) < 80 then
                PlaySound("kira02",0.1,self.x/256,false)
                ChangeBulletImage(self,ball_light_dark,COLOR_RED)
                do local vi,_d_vi=(v),(-v/10) local size,_d_size=(2),(-1/10) local ap,_d_ap=(0),(255/10) for _=1,10 do
                    SetV2(self,vi,a,true,false)
                    self.hscale = size
                    self.vscale = size
                    _object.set_color(self,"mul+add",ap,255,255,255)
                    task._Wait(1)
                vi=vi+_d_vi size=size+_d_size ap=ap+_d_ap end end
                self.flag = 0
                self.timer = 20
            else
            end
            if self.flag == 1 and Dist(self,player) < 80 then
                PlaySound("kira02",0.1,self.x/256,false)
                SetV2(self,0,0,true,true)
                do local size,_d_size=(2),(-1/10) local ap,_d_ap=(0),(255/10) for _=1,10 do
                    self.hscale = size
                    self.vscale = size
                    _object.set_color(self,"mul+add",ap,255,255,255)
                    task._Wait(1)
                size=size+_d_size ap=ap+_d_ap end end
                ChangeBulletImage(self,ball_light_dark,COLOR_RED)
                self.flag = 0
                self.timer = 20
            else
            end
            if self.flag == 0 and Dist(self,player) > 120  then
                ChangeBulletImage(self,ball_light_dark,COLOR_BLUE)
                _set_a(self,0,0,true)
                SetV2(self,0,0,true,true)
                do local size,_d_size=(2),(-1/10) local ap,_d_ap=(0),(255/10) for _=1,10 do
                    self.hscale = size
                    self.vscale = size
                    _object.set_color(self,"mul+add",ap,255,255,255)
                    task._Wait(1)
                size=size+_d_size ap=ap+_d_ap end end
                self.flag = 1
                self.timer = 20
            else
            end
            if self.flag == 0 and Dist(self,player) < 120 and self.timer >= 20+holdtime then
                _set_a(self,0.0125*d,0,true)
            else
            end
            if self.flag == 1 and Dist(self,player) > 120 and self.timer == 20+holdtime then
                SetV2(self,v,0,true,true)
            else
            end
            task._Wait(1)
        end end
    end)
end
_editor_class["OLC_ZMW_3非bullet"]=Class(bullet)
_editor_class["OLC_ZMW_3非bullet"].init=function(self,_x,_y,v,a,ac,vd,holdtime,aa2,bt)
    bullet.init(self,knife,COLOR_GRAY,true,true)
    self.x,self.y=_x,_y
