    self.rect = true
    self.vscale,self.b = self.vscale,self.b
    SetV2(self,v,a,true,false)
    task.New(self,function()
        do local an,_d_an=(a),(ac) local vn,_d_vn=(v),(-v/vd) for _=1,vd do
            SetV2(self,vn,an,true,false)
            task._Wait(1)
        an=an+_d_an vn=vn+_d_vn end end
        do for _=1,holdtime do
            SetV2(self,0,0,true,true)
            task._Wait(1)
        end end
        _set_a(self,aa2,0,true)
    end)
end
