    self.vscale,self.b = 1*0.5,self.pandinb*0.5
    self.hscale,self.a = 1*0,self.pandina*0
    self.group = GROUP_INDES
    task.New(self,function()
        SetV2(self,10,a,true,false)
        do local a,_d_a=(0),(3/20) for _=1,20 do
            self.vscale,self.b = 1*0.25,self.pandinb*0.25
            self.hscale,self.a = 1*a,self.pandina*a
            if self.x<= -300 or self.x >= 300 or self.y <= -230 or self.y >= 230 then
                if true then break end
            else
            end
            task._Wait(1)
        a=a+_d_a end end
        do for _=1,_infinite do
            if self.x<= -300 or self.x >= 300 or self.y <= -230 or self.y >= 230 then
                _boss.moveto = true
                if true then break end
            else
            end
            task._Wait(1)
        end end
    end)
end
