    self.hscale,self.a = self.hscale*3,self.a*3
    self.rect = true
    self.vscale,self.b = self.vscale,self.b
    SetV2(self,3,Angle(self,_boss),true,false)
    self.omiga = 9*ran:Sign()
    task.New(self,function()
        do for _=1,_infinite do
            last=New(_straight,arrow_big,COLOR_RED,self.x+50*cos(self.rot),self.y+50*sin(self.rot),3,self.rot,false,0,true,true,0,false,0,0,0,false)
            task._Wait(6-d)
