_editor_class["OLC_ZMW_4符bullet"]=Class(bullet)
_editor_class["OLC_ZMW_4符bullet"].init=function(self,_x,_y,v,a)
    bullet.init(self,knife,COLOR_GRAY,true,true)
    self.x,self.y=_x,_y
    self.group = GROUP_INDES
    self.hscale,self.a = self.hscale*2,self.a*2
    self.vscale,self.b = self.vscale,self.b
    self.rect = true
    SetV2(self,v,a,true,false)
    self.reflectcount = 0
end
_editor_class["OLC_ZMW_4符bullet"].frame=function(self)
    self.class.base.frame(self)
    if not self.reflected then
    	if self.y> 240 then self.vy=-self.vy self.y= 480-self.y self.rot=     -self.rot self.reflected=true return end
    	if self.y<-240 then self.vy=-self.vy self.y=-480-self.y self.rot=     -self.rot self.reflected=true return end
    	if self.x> 320 then self.vx=-self.vx self.x= 640-self.x self.rot=180-self.rot self.reflected=true return end
    	if self.x<-320 then self.vx=-self.vx self.x=-640-self.x self.rot=180-self.rot self.reflected=true return end
    end
    if self.reflected and self.reflectcount <= 5 then
        last=New(_straight,ball_light,ran:Int(1,16),self.x,self.y,3,0,true,0,true,true,0,false,0.005,Angle(self,player),0,false)
        self.reflectcount = self.reflectcount + 1
        self.reflected = false
    else
        if self.reflected and self.reflectcount > 5 then
            last=New(_straight,ball_light,ran:Int(1,16),self.x,self.y,3,0,true,0,true,true,0,false,0.005,Angle(self,player),0,false)
            _del(self,true)
        else
        end
    end
end
_editor_class["OLC_Bullet_ZMW_B"]=Class(bullet)
_editor_class["OLC_Bullet_ZMW_B"].init=function(self,_x,_y,v,a,mt,dt,d)
    bullet.init(self,ball_light,COLOR_YELLOW,true,true)
    self.x,self.y=_x,_y
    SetV2(self,v,a,true,false)
    task.New(self,function()
        task._Wait(mt)
        do local vi,_d_vi=(v),(-v/60) for _=1,60 do
            SetV2(self,vi,a,true,false)
            task._Wait(1)
        vi=vi+_d_vi end end
        task._Wait(dt)
        do local ai,_d_ai=(a-45),(90/(d+1)) for _=1,d+1 do
            last=New(_editor_class["OLC_ZMW_5非bullet"],self.x,self.y,2,ai)
            task._Wait(0)
        ai=ai+_d_ai end end
        _del(self,true)
    end)
end
