_editor_class["OLC_BombProtect"]=Class(_object)
_editor_class["OLC_BombProtect"].init=function(self,_x,_y,_)
    self.x,self.y=_x,_y
	self.img="img_void"
	self.layer=LAYER_ENEMY+1
	self.group=GROUP_ENEMY
	self.hide=false
	self.bound=false
	self.navi=false
	self.hp=1000
	self.maxhp=1000
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    self.img="image:OLC_Protect"
    _object.set_color(self,"mul+add",255,255,255,255)
    OLC_BombProtect = self
    self.omiga = 9
    task.New(self,function()
        do local size,_d_size=(0),(2/60) for _=1,60 do
            self.hscale,self.vscale = size,size
            self.a,self.b = size*35,size*35
            task._Wait(1)
        size=size+_d_size end end
    end)
    task.New(self,function()
        do for _=1,_infinite do
            _set_rel_pos(self,0,0,self.rot,false)
            task._Wait(1)
        end end
    end)
    task.New(self,function()
        do for _=1,_infinite do
            if self.hp < 1000 then
                PlaySound("nodamage",0.1,self.x/256,false)
                self.hp = 1000
            else
            end
            if player.nextspell<=0 and not lstg.var.block_spell then
                do local size,_d_size=(2),(-2/60) for _=1,60 do
                    self.hscale,self.vscale = size,size
                    self.a,self.b = size*35,size*35
                    task._Wait(1)
                size=size+_d_size end end
                _del(self,true)
            else
            end
            task._Wait(1)
        end end
    end)
end
_editor_class["OLC_Bullet_ZMW_02"]=Class(bullet)
_editor_class["OLC_Bullet_ZMW_02"].init=function(self,_x,_y,v,a,delay,color)
