    self.x,self.y=_x,_y
    task.New(self,function()
        SetV2(self,v,a,true,false)
        task._Wait(delay)
        do local vi,_d_vi=(v),(-v/15) for _=1,15 do
            SetV2(self,vi,a,true,false)
            task._Wait(1)
        vi=vi+_d_vi end end
        task._Wait(delay)
        do local vi,_d_vi=(0),(v/15) for _=1,15 do
            SetV2(self,vi,0,true,true)
            task._Wait(1)
        vi=vi+_d_vi end end
        SetV2(self,v,0,true,true)
    end)
end
