_tmp_sc=boss.dialog.New(true)
function _tmp_sc:init()
	lstg.player.dialog=true
	_dialog_can_skip=true
	self.dialog_displayer=New(dialog_displayer)
    task.New(self,function()
        if (lstg.var.player_name=='reimu_player') then
            boss.dialog.sentence(self,"image:OLC_Reimu","left","啧，怎么这些家伙又闹腾起来了啊",nil,1,1)
            boss.dialog.sentence(self,"img_void","right","那是，因为我啊",0,-1,1)
            last=New(_editor_class["OLC_particle"],self.x,self.y,0,144)
            task._Wait(105)
            task.MoveTo(0,144,0,MOVE_NORMAL)
            task._Wait(25)
            boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","又见面了，灵梦。",nil,1,1)
            boss.dialog.sentence(self,"image:OLC_Reimu","left","啧，原来又是你啊",nil,1,1)
            boss.dialog.sentence(self,"image:OLC_Reimu","left","你烦不烦啊，悠闲的过日子不好么？",nil,1,1)
            boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","因为我想找人玩玩嘛~",nil,1,1)
            boss.dialog.sentence(self,"image:OLC_Reimu","left","赶紧的，把你散播出去的那些魔力回收了",nil,1,1)
            boss.dialog.sentence(self,"image:OLC_Reimu","left","我还要去喝茶睡觉呢",nil,1,1)
            boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","不要，先打一架再说！",nil,1,1)
            boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","不过，这个场地似乎有点小",nil,1,1)
            boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","变大吧！",0,1,1)
            do
                last=New(_editor_class["OLC_particle"],self.x,self.y,0,144)
                last=New(_editor_class["OLC_开宽屏"],self.x,self.y,_)
                do local x,_d_x=(320-(13/2)),(-13) local l,_d_l=(0),(1) for _=1,8 do
                    last=New(_editor_class["OLC_Life"],x,-195,l)
                    last=New(_editor_class["OLC_Bomb"],x,-220,l)
                    task._Wait(0)
                x=x+_d_x l=l+_d_l end end
                last=New(_editor_class["OLC_Per"],260,-207,1)
                last=New(_editor_class["OLC_Per"],260,-232,0)
                PlaySound("ch00",0.1,self.x/256,false)
                task._Wait(130)
            end
            boss.dialog.sentence(self,"image:OLC_Reimu","left","你把万宝槌的力量这么用，它会哭的哦",nil,1,1)
        else
            if (lstg.var.player_name=='marisa_player') then
                boss.dialog.sentence(self,"image:OLC_Marisa","left","妖精们又活跃起来了呢",nil,1,1)
                boss.dialog.sentence(self,"image:OLC_Marisa","left","难道又是一场新的异变？",nil,1,1)
                boss.dialog.sentence(self,"img_void","right","呦？",0,-1,1)
                last=New(_editor_class["OLC_particle"],self.x,self.y,0,144)
                task._Wait(105)
                task.MoveTo(0,144,0,MOVE_NORMAL)
                task._Wait(25)
                boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","你好啊",nil,1,1)
                boss.dialog.sentence(self,"image:OLC_Marisa","left","这不是针妙丸么？",nil,1,1)
                boss.dialog.sentence(self,"image:OLC_Marisa","left","你在这里干什么？",nil,1,1)
                boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","我在……",nil,1,1)
                boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","搞事情啊~",nil,1,1)
                boss.dialog.sentence(self,"image:OLC_Marisa","left","搞事情？事情是什么？",nil,1,1)
                boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","……",nil,1,1)
                boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","看来现在貌似和你没法沟通啊",nil,1,1)
                boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","来吧~",0,1,1)
                do
                    last=New(_editor_class["OLC_particle"],self.x,self.y,0,144)
                    last=New(_editor_class["OLC_开宽屏"],self.x,self.y,_)
                    do local x,_d_x=(320-(13/2)),(-13) local l,_d_l=(0),(1) for _=1,8 do
                        last=New(_editor_class["OLC_Life"],x,-195,l)
                        last=New(_editor_class["OLC_Bomb"],x,-220,l)
                        task._Wait(0)
                    x=x+_d_x l=l+_d_l end end
                    last=New(_editor_class["OLC_Per"],260,-207,1)
                    last=New(_editor_class["OLC_Per"],260,-232,0)
                    PlaySound("ch00",0.1,self.x/256,false)
                    task._Wait(130)
                end
                boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","先来和我战斗一场吧！",nil,1,1)
                boss.dialog.sentence(self,"image:OLC_Marisa","left","哈？突然就开打了？",nil,1,1)
            else
                if (lstg.var.player_name=='sanae_player') then
                    boss.dialog.sentence(self,"image:OLC_Sanae","left","哎呀，这些妖精是什么鬼啊",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_Sanae","left","怎么这么凶残啊？",nil,1,1)
                    boss.dialog.sentence(self,"img_void","right","凶残吗？我不觉得呢~",0,-1,1)
                    last=New(_editor_class["OLC_particle"],self.x,self.y,0,144)
                    task._Wait(105)
                    task.MoveTo(0,144,0,MOVE_NORMAL)
                    task._Wait(25)
                    boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","你好啊",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_Sanae","left","你是……针妙丸？",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_Sanae","left","为什么你会在这里？",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","我啊，在找人玩呢~",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_Sanae","left","呃……",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","我感觉你很不错哦~",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","来打一架吧~",0,1,1)
                    do
                        last=New(_editor_class["OLC_particle"],self.x,self.y,0,144)
                        last=New(_editor_class["OLC_开宽屏"],self.x,self.y,_)
                        do local x,_d_x=(320-(13/2)),(-13) local l,_d_l=(0),(1) for _=1,8 do
                            last=New(_editor_class["OLC_Life"],x,-195,l)
                            last=New(_editor_class["OLC_Bomb"],x,-220,l)
                            task._Wait(0)
                        x=x+_d_x l=l+_d_l end end
                        last=New(_editor_class["OLC_Per"],260,-207,1)
                        last=New(_editor_class["OLC_Per"],260,-232,0)
                        PlaySound("ch00",0.1,self.x/256,false)
                        task._Wait(130)
                    end
                    boss.dialog.sentence(self,"image:OLC_Sanae","left","嗯？活动范围变大了？",nil,1,1)
                else
                    boss.dialog.sentence(self,"image:OLC_Wuer","left","哦吼吼，又搜集到了好多素材呢~",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_Wuer","left","又可以创造许多神奇的料理了",nil,1,1)
                    boss.dialog.sentence(self,"img_void","right","呃……你这有点过分了吧……",0,-1,1)
                    last=New(_editor_class["OLC_particle"],self.x,self.y,0,144)
                    task._Wait(105)
                    task.MoveTo(0,144,0,MOVE_NORMAL)
                    task._Wait(25)
                    boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","你搜集这么多妖精的尸体",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","你竟然说用来做料理？",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","天哪，真可怕",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_Wuer","left","呃……",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_Wuer","left","不好意思，习惯了",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","等等，话说我以前貌似没见过你呢",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_Wuer","left","那是自然",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_Wuer","left","我先自我介绍一下吧",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_Wuer","left","在很久很久以前，盘古开天辟地，混沌初分……",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","……",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","你有病吧？自我介绍要讲到那么久远的时间么？",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_Wuer","left","不用",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","……那就是说你有病喽？",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","走了",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_Wuer","left","诶？等等啊，见面不打一架怎么行！",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","好吧",0,1,1)
                    do
                        last=New(_editor_class["OLC_particle"],self.x,self.y,0,144)
                        last=New(_editor_class["OLC_开宽屏"],self.x,self.y,_)
                        do local x,_d_x=(320-(13/2)),(-13) local l,_d_l=(0),(1) for _=1,8 do
