                    boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","那么，就先和你打一架再说！",nil,1,1)
                end
            end
        end
        LoadMusicRecord("OLC_辉针城的小人族");_play_music("OLC_辉针城的小人族")
        last=New(_editor_class["OLC_MusicName2"],20,-230,_)
    end)
