        last=New(_editor_class["OLC_少名针妙丸开符立绘"],self.x,self.y-55,_)
        task._Wait(60)
        do
            last=New(_editor_class["OLC_particle"],self.x,self.y,0,0)
            PlaySound("ch00",0.5,self.x/256,false)
            task._Wait(105)
        end
        do for _=1,_infinite do
            last=New(_editor_class["OLC_ZMW_Wan_1"],self.x,self.y-55,2)
            _connect(self,last,0.8,true)
            do for _=1,_infinite do
                if not IsValid(wan) then break end
                task._Wait(1)
            end end
            do
                last=New(_editor_class["OLC_particle"],self.x,self.y,0,0)
                PlaySound("ch00",0.5,self.x/256,false)
                task._Wait(105)
            end
            task._Wait(1)
        end end
    end)
    task.New(self,function()
        task._Wait(120+60)
        do for _=1,_infinite do
            boss.cast(self,1)
            task._Wait(29*8)
        end end
    end)
