function _tmp_sc:del()
    if self.olc_achi>=5 and lstg.var.sc_bonus>0 and (not ext.replay.IsReplay()) then
        New(achievement_obj,1,30)
    else
    end
    task.New(self,function()
        if ext.sc_pr then
            do
                last=New(_editor_class["OLC_关宽屏"],self.x,self.y,_)
            end
        else
        end
    end)
end
