function _tmp_sc:init()
    task.New(self,function()
        do for _=1,_infinite do
            if player.nextspell<=0 and not lstg.var.block_spell and not IsValid(OLC_BombProtect) then
            else
                if IsValid(OLC_BombProtect) then
                else
                    last=New(_editor_class["OLC_BombProtect"],self.x,self.y,_)
                    _connect(self,last,0,true)
                end
            end
            task._Wait(1)
        end end
    end)
    task.New(self,function()
        self.ui.hpbarcolor2=nil
        task.MoveTo(0,100,60,MOVE_NORMAL)
        self.sp_point={((2500/3500)*360+90),((1500/3500)*360+90),((500/3500)*360+90)}
        task._Wait(30)
        last=New(_editor_class["OLC_少名针妙丸开符立绘"],self.x,self.y-55,_)
        task._Wait(60)
        do
            last=New(_editor_class["OLC_particle"],self.x,self.y,self.x,self.y)
            PlaySound("ch00",0.5,self.x/256,false)
            task._Wait(105)
        end
    end)
    task.New(self,function()
        task._Wait(150+120)
        self.de = 25
        do local a,_d_a=(0),(5) for _=1,_infinite do
            if _boss.timer < (125-30)*60 then
                self.de = 25
            else
                self.de = 5
            end
            _create_bullet_group(arrow_big,COLOR_RED,self.x,self.y,2,0,1.5,1.5,a+(360/12)*0,360,false,0,true,true,0,false,self)
            _create_bullet_group(arrow_big,COLOR_PURPLE,self.x,self.y,2,0,1.5,1.5,a+(360/12)*1,360,false,0,true,true,0,false,self)
            _create_bullet_group(arrow_big,COLOR_BLUE,self.x,self.y,2,0,1.5,1.5,a+(360/12)*2,360,false,0,true,true,0,false,self)
            _create_bullet_group(arrow_big,COLOR_GREEN,self.x,self.y,2,0,1.5,1.5,a+(360/12)*3,360,false,0,true,true,0,false,self)
            _create_bullet_group(arrow_big,COLOR_YELLOW,self.x,self.y,2,0,1.5,1.5,a+(360/12)*4,360,false,0,true,true,0,false,self)
            _create_bullet_group(arrow_big,COLOR_ORANGE,self.x,self.y,2,0,1.5,1.5,a+(360/12)*5,360,false,0,true,true,0,false,self)
            task._Wait(self.de)
        a=a+_d_a end end
    end)
    task.New(self,function()
        task._Wait(300+120)
        last=New(_editor_class["OLC_ZMW"],self.x+100,self.y,0)
        _connect(self,last,0.8,true)
        last=New(_editor_class["OLC_ZMW"],self.x-100,self.y,0)
        _connect(self,last,0.8,true)
        do for _=1,_infinite do
            do local a,_d_a=(ran:Float(-360,360)),(360/8) for _=1,8 do
                last=New(_editor_class["OLC_Bullet_ZMW_02"],self.x+100,self.y,3,a,25,COLOR_GREEN)
                last=New(_editor_class["OLC_Bullet_ZMW_02"],self.x-100,self.y,3,a,25,COLOR_GREEN)
                PlaySound("tan00",0.5,self.x/256,false)
                task._Wait(0)
            a=a+_d_a end end
            task._Wait(200)
        end end
    end)
    task.New(self,function()
        do for _=1,_infinite do
            if self.hp <= 2500 or _boss.timer >= (145-30)*60 then
                PlaySound("enep02",0.5,self.x/256,false)
                if _boss.timer >= (145-30)*60 then
                    self.sp_point={}
                else
                    self.sp_point={((1500/3500)*360+90),((500/3500)*360+90)}
                end
                last=New(_editor_class["OLC_ZMW"],self.x+200,self.y-50,0)
                _connect(self,last,0.8,true)
                last=New(_editor_class["OLC_ZMW"],self.x-200,self.y-50,0)
                _connect(self,last,0.8,true)
                do for _=1,_infinite do
                    _create_bullet_group(ball_light,COLOR_RED,self.x+200,self.y-50,7,0,1.5,1.5,ran:Float(-360,360),360,false,0,true,true,0,false,self)
                    _create_bullet_group(ball_light,COLOR_RED,self.x-200,self.y-50,7,0,1.5,1.5,ran:Float(-360,360),360,false,0,true,true,0,false,self)
                    PlaySound("tan00",0.5,self.x/256,false)
                    task._Wait(100)
                end end
            else
            end
            task._Wait(1)
        end end
        self.de = 150
    end)
    task.New(self,function()
        do for _=1,_infinite do
            if self.hp <= 1500 or _boss.timer >= (145-30)*60 then
                PlaySound("enep02",0.1,self.x/256,false)
                if _boss.timer >= (145-30)*60 then
                    self.sp_point={}
                else
                    self.sp_point={((500/3500)*360+90)}
                end
                last=New(_editor_class["OLC_ZMW"],self.x,self.y+50,0)
                _connect(self,last,0.8,true)
                do local a,_d_a=(ran:Float(-360,360)),(9) for _=1,_infinite do
                    _create_bullet_group(ball_light,COLOR_YELLOW,self.x,self.y+50,7,0,1,1,a+30,360,false,0,true,true,0,false,self)
                    PlaySound("tan00",0.1,self.x/256,false)
                    task._Wait(50)
                a=a+_d_a end end
            else
            end
            task._Wait(1)
        end end
        self.de = 150
    end)
    task.New(self,function()
        do for _=1,_infinite do
            if self.hp <= 500 or _boss.timer >= (145-30)*60 then
                PlaySound("enep02",0.1,self.x/256,false)
                self.sp_point={}
                last=New(_editor_class["OLC_ZMW"],self.x,self.y-50,0)
                _connect(self,last,0.8,true)
                do for _=1,_infinite do
                    _create_bullet_group(ball_light,COLOR_BLUE,self.x,self.y-50,5,0,3,3,ran:Float(-360,360),360,false,0,true,true,0,false,self)
                    PlaySound("tan00",0.1,self.x/256,false)
                    task._Wait(85)
                end end
            else
            end
            task._Wait(1)
        end end
        self.de = 150
    end)
    task.New(self,function()
        task._Wait(120)
        do for _=1,_infinite do
            boss.cast(self,1)
            task._Wait(29*8)
        end end
    end)
end
