_tmp_sc=boss.dialog.New(true)
function _tmp_sc:init()
	lstg.player.dialog=true
	_dialog_can_skip=true
	self.dialog_displayer=New(dialog_displayer)
    task.New(self,function()
        task.MoveTo(240,384,0,MOVE_NORMAL)
        if (lstg.var.player_name=='reimu_player') then
            boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","哎呦，灵梦，你这么凶干嘛",nil,1,1)
            boss.dialog.sentence(self,"image:OLC_Reimu","left","还不是因为你浪费我时间",nil,1,1)
            boss.dialog.sentence(self,"image:OLC_Reimu","left","快点，把魔力都收回去！",nil,1,1)
            boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","好啦好啦……",nil,1,1)
            boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","我收回去就是了……",nil,1,1)
        else
            if (lstg.var.player_name=='marisa_player') then
                boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","emmmm……你这火力还是一如既往的高啊……",nil,1,1)
                boss.dialog.sentence(self,"image:OLC_Marisa","left","那当然，毕竟是我嘛~",nil,1,1)
            else
                if (lstg.var.player_name=='sanae_player') then
                    boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","哎呦，你这么厉害的吗？",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_Sanae","left","毕竟我可是守矢神社的风祝呢",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_Sanae","left","不厉害点怎么得了",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","呃，看来我得庆幸之前的异变你没来了……",nil,1,1)
                else
                    boss.dialog.sentence(self,"image:OLC_Wuer","left","真是轻松啊",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","你这……",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","有点厉害啊",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","可惜是个变态呢……",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_Wuer","left","……你想死么？",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","不想，我先走了~",nil,1,1)
                end
            end
        end
        last=New(_editor_class["OLC_关宽屏"],self.x,self.y,_)
    end)
end
