_editor_class["OLC_ZMW:Lunatic"].name="Sukuna Shinmyoumaru"
_editor_class["OLC_ZMW:Lunatic"].init=function(self,cards)
    boss.init(self,240,384,"Sukuna Shinmyoumaru",cards,New(_editor_class["ZMW_SCBG"]))
	self.difficulty="Lunatic"
	self.ani_intv=8
	for i=1,4 do self['img'..i]={} end
	self.nn={10,6,6,29}
	self.mm={1,1,29}
	for i=2,4 do self['ani'..i]=self.nn[i]-self.mm[i-1] end
	for i=1,4 do
		for j=1,self.nn[i] do
			self['img'..i][j]='anonymous:'.."OLC_针妙丸.png"..i..j
		end
	end
end
