function _tmp_sc:init()
	lstg.player.dialog=true
	_dialog_can_skip=true
	self.dialog_displayer=New(dialog_displayer)
    task.New(self,function()
        if (lstg.var.player_name=='reimu_player') then
            boss.dialog.sentence(self,"image:OLC_Reimu","left","啧，怎么这些家伙又闹腾起来了啊",nil,1,1)
            boss.dialog.sentence(self,"img_void","right","那是，因为我啊",0,-1,1)
            last=New(_editor_class["OLC_particle"],self.x,self.y,0,144)
            task._Wait(105)
            task.MoveTo(0,144,0,MOVE_NORMAL)
            task._Wait(25)
            boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","又见面了，灵梦。",nil,1,1)
            boss.dialog.sentence(self,"image:OLC_Reimu","left","啧，原来又是你啊",nil,1,1)
            boss.dialog.sentence(self,"image:OLC_Reimu","left","你烦不烦啊，悠闲的过日子不好么？",nil,1,1)
            boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","因为我想找人玩玩嘛~",nil,1,1)
            boss.dialog.sentence(self,"image:OLC_Reimu","left","赶紧的，把你散播出去的那些魔力回收了",nil,1,1)
            boss.dialog.sentence(self,"image:OLC_Reimu","left","我还要去喝茶睡觉呢",nil,1,1)
            boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","不要，先打一架再说！",nil,1,1)
            boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","不过，这个场地似乎有点小",nil,1,1)
            boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","变大吧！",0,1,1)
            do
                last=New(_editor_class["OLC_particle"],self.x,self.y,0,144)
