                task._Wait(130)
            end
            boss.dialog.sentence(self,"image:OLC_Reimu","left","你把万宝槌的力量这么用，它会哭的哦",nil,1,1)
        else
            if (lstg.var.player_name=='marisa_player') then
                boss.dialog.sentence(self,"image:OLC_Marisa","left","妖精们又活跃起来了呢",nil,1,1)
                boss.dialog.sentence(self,"image:OLC_Marisa","left","难道又是一场新的异变？",nil,1,1)
                boss.dialog.sentence(self,"img_void","right","呦？",0,-1,1)
                last=New(_editor_class["OLC_particle"],self.x,self.y,0,144)
                task._Wait(105)
                task.MoveTo(0,144,0,MOVE_NORMAL)
                task._Wait(25)
                boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","你好啊",nil,1,1)
                boss.dialog.sentence(self,"image:OLC_Marisa","left","这不是针妙丸么？",nil,1,1)
                boss.dialog.sentence(self,"image:OLC_Marisa","left","你在这里干什么？",nil,1,1)
                boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","我在……",nil,1,1)
                boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","搞事情啊~",nil,1,1)
                boss.dialog.sentence(self,"image:OLC_Marisa","left","搞事情？事情是什么？",nil,1,1)
                boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","……",nil,1,1)
                boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","看来现在貌似和你没法沟通啊",nil,1,1)
                boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","来吧~",0,1,1)
                do
                    last=New(_editor_class["OLC_particle"],self.x,self.y,0,144)
                    last=New(_editor_class["OLC_开宽屏"],self.x,self.y,_)
                    do local x,_d_x=(320-(13/2)),(-13) local l,_d_l=(0),(1) for _=1,8 do
