                boss.dialog.sentence(self,"image:OLC_Marisa","left","哈？突然就开打了？",nil,1,1)
            else
                if (lstg.var.player_name=='sanae_player') then
                    boss.dialog.sentence(self,"image:OLC_Sanae","left","哎呀，这些妖精是什么鬼啊",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_Sanae","left","怎么这么凶残啊？",nil,1,1)
                    boss.dialog.sentence(self,"img_void","right","凶残吗？我不觉得呢~",0,-1,1)
