                        x=x+_d_x l=l+_d_l end end
                        last=New(_editor_class["OLC_Per"],260,-207,1)
                        last=New(_editor_class["OLC_Per"],260,-232,0)
                        PlaySound("ch00",0.1,self.x/256,false)
                        task._Wait(130)
                    end
                    boss.dialog.sentence(self,"image:OLC_Sanae","left","嗯？活动范围变大了？",nil,1,1)
                else
                    boss.dialog.sentence(self,"image:OLC_Wuer","left","哦吼吼，又搜集到了好多素材呢~",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_Wuer","left","又可以创造许多神奇的料理了",nil,1,1)
                    boss.dialog.sentence(self,"img_void","right","呃……你这有点过分了吧……",0,-1,1)
                    last=New(_editor_class["OLC_particle"],self.x,self.y,0,144)
