                    boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","你竟然说用来做料理？",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","天哪，真可怕",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_Wuer","left","呃……",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_Wuer","left","不好意思，习惯了",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","等等，话说我以前貌似没见过你呢",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_Wuer","left","那是自然",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_Wuer","left","我先自我介绍一下吧",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_Wuer","left","在很久很久以前，盘古开天辟地，混沌初分……",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","……",nil,1,1)
                    boss.dialog.sentence(self,"image:OLC_针妙丸立绘","right","你有病吧？自我介绍要讲到那么久远的时间么？",nil,1,1)
