_editor_class["er_saoqi"]=Class(_object)
_editor_class["er_saoqi"].init=function(self,_x,_y,bb,r1,b1,g1,r2,b2,g2,r3,b3,g3)
    self.x,self.y=_x,_y
	self.img="leaf"
	self.layer=LAYER_ENEMY-5
	self.group=GROUP_GHOST
	self.hide=true
	self.bound=false
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    _boss.saoqi=self
    saoqi=self
    self.boss=bb
    self.flag=0
    self.r1=r1 self.b1=b1 self.g1=g1
    self.r2=r2 self.b2=b2 self.g2=g2
    self.r3=r3 self.b3=b3 self.g3=g3
    task.New(self,function()
        _object.set_color(self,"",100,r3,g3,b3)
        task.New(self,function()
            do local s,_d_s=(0),(0.9/60) for _=1,61 do
                self.hscale=s self.vscale=s
                task._Wait(1)
            s=s+_d_s end end
        end)
        task.New(self,function()
            do for _=1,_infinite do
                if IsValid(_boss) then
                    self.x=_boss.x self.y=_boss.y
                else
                end
                task._Wait(1)
            end end
        end)
        task.New(self,function()
            do for _=1,_infinite do
                last=New(_editor_class["er_saoqi1"],self.x,self.y,self.x,self.y,ran:Float(-10,10),self.r1,self.b1,self.g1)
                task._Wait(10)
            end end
        end)
        task.New(self,function()
            do for _=1,_infinite do
                last=New(_editor_class["er_saoqi2"],self.x,self.y,self.x,self.y,ran:Float(0,360))
                task._Wait(16)
            end end
        end)
        task.New(self,function()
            do for _=1,_infinite do
                last=New(_editor_class["er_saoqi3"],self.x,self.y,self.x,self.y,ran:Float(0,360),self.r2,self.b2,self.g2)
                task._Wait(5)
            end end
        end)
    end)
end
_editor_class["er_saoqi"].frame=function(self)
    self.class.base.frame(self)
    if not(IsValid(_boss)) then
        self.flag=self.flag+2
    else
    end
    if self.flag>0 then
        self.flag=self.flag-1
    else
    end
    if self.flag>5 then
        _del(self,true)
    else
    end
end
_editor_class["er_saoqi1"]=Class(_object)
_editor_class["er_saoqi1"].init=function(self,_x,_y,x,y,rot,r,b,g)
    self.x,self.y=_x,_y
	self.img="image:er_saoqi1"
	self.layer=LAYER_ENEMY-1
	self.group=GROUP_GHOST
	self.hide=false
	self.bound=false
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    self.rot=rot
    self.hscale=1.5 self.vscale=0 self.alpha=100
    self.rr=r self.bb=b self.gg=g
    task.New(self,function()
        task.New(self,function()
            do local a,_d_a=(self.rot+90),(0) local r,_d_r=(0),(2) for _=1,_infinite do
                if IsValid(_boss) then
                    self.x=_boss.x+r*cos(a)
                    self.y=_boss.y+r*sin(a)
                else
                end
                task._Wait(1)
            a=a+_d_a r=r+_d_r end end
        end)
        task.New(self,function()
            do local s,_d_s=(1),(0.5/30) local ss,_d_ss=(0),(2/30) for _=1,31 do
                self.hscale=s self.vscale=ss
                task._Wait(1)
            s=s+_d_s ss=ss+_d_ss end end
        end)
        do local a,_d_a=(255),(-255/40) for _=1,41 do
            _object.set_color(self,"mul+add",a,r,g,b)
            task._Wait(1)
        a=a+_d_a end end
        _del(self,true)
    end)
end
_editor_class["er_saoqi1"].del=function(self)
end
_editor_class["er_saoqi1"].render=function(self)
    self.class.base.render(self)
    Render(self.img,self.x,self.y,self.rot,self.hscale,self.vscale)
end
