_editor_class["er_charge_in"]=Class(_object)
_editor_class["er_charge_in"].init=function(self,_x,_y,r,g,b,sound,img)
    self.x,self.y=_x,_y
	self.img="image:er_charge"
	self.layer=LAYER_ENEMY+50
	self.group=GROUP_GHOST
	self.hide=false
	self.bound=true
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    task.New(self,function()
        if sound then
            PlaySound(sound,0.5,0,false)
        else
        end
        do local s,_d_s=(1),(-1/60) local a,_d_a=(80),(2) local i,_d_i=(1),(1) for _=1,61 do
            if i<45 then
                local angle=ran:Float(0,360)
                local lifetime=ran:Int(30,45)
                local l=ran:Float(120,200)
                last=New(_editor_class["er_charge_eff"],self.x+l*cos(angle),self.y+l*sin(angle),l/lifetime,angle+180,1,lifetime,ran:Float(3.5,5),img)
            else
            end
            self.hscale=s self.vscale=s
            _object.set_color(self,"mul+add",a,r,g,b)
            task._Wait(1)
        s=s+_d_s a=a+_d_a i=i+_d_i end end
    end)
end
_editor_class["er_charge_in"].del=function(self)
end
