_editor_class["er_charge_eff"]=Class(_object)
_editor_class["er_charge_eff"].init=function(self,_x,_y,v,a,mode,lifetime,size,img)
    self.x,self.y=_x,_y
	self.img="img_void"
	self.layer=LAYER_ENEMY+1
	self.group=GROUP_GHOST
	self.hide=false
	self.bound=false
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    if img then
        self.img='image:er_charge_eff'..img
    else
    end
    local x,y=self.x,self.y
    self.rot=ran:Float(0,360)
    self.lifetime=lifetime
    self.omiga=ran:Float(0.8,1.2)*ran:Sign()
    self.hscale=size self.vscale=size
    task.New(self,function()
        do local s,_d_s=(size),(-ran:Float(1,3)*size/lifetime) local al,_d_al=(125),(-125/lifetime) local i,_d_i=(0),(90/lifetime) local l,_d_l=(v*lifetime),(0) for _=1,lifetime do
            self.x=x+l*cos(a)*sin(i) self.y=y+l*sin(a)*sin(i)
            self.hscale=s
            if self.timer>lifetime-15 then
                _object.set_color(self,"mul+add",125*(lifetime-self.timer-1)/15,255,255,255)
            else
                _object.set_color(self,"mul+add",125,255,255,255)
            end
            task._Wait(1)
        s=s+_d_s al=al+_d_al i=i+_d_i l=l+_d_l end end
    end)
end
_editor_class["er_charge_eff"].frame=function(self)
    self.class.base.frame(self)
    if self.timer>=self.lifetime then
        _del(self,true)
    else
    end
end
_editor_class["er_charge_eff"].del=function(self)
end
