        do local s,_d_s=(0),(1.8) local al,_d_al=(0),(255/15) for _=1,51 do
            _object.set_color(self,"mul+add",min(al,255),255,128,0)
            self.hscale=2*cos(s) self.vscale=2*cos(s)
            task._Wait(1)
        s=s+_d_s al=al+_d_al end end
        _del(self,false)
    end)
end
