_editor_class["wuer_map"].render=function(self)
    SetViewMode'ui'
    Render('image:fake_ui',530,100)
    local x,y=468,176
    	for i=0,3 do
    		for j=0,3 do
    			if labyrinth.show[i+1][j+1] then SetImageState('bg_map'..j+i*4+1,'',Color(0xA0FFFFFF))
    else
    SetImageState('bg_map'..j+i*4+1,'',Color(0xA0000000))
    end
    			Render('bg_map'..j+i*4+1,x+40*j,y-40*i,0,0.625,0.625)
    		end
    	end
