end
_editor_class["wuer_bg_change"]=Class(_object)
_editor_class["wuer_bg_change"].init=function(self,_x,_y,mode)
    self.x,self.y=_x,_y
	self.img="leaf"
	self.layer=LAYER_TOP+10
	self.group=GROUP_GHOST
	self.hide=false
	self.bound=true
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    self.mode=mode
    PlaySound("boon01",0.1,self.x/256,false)
    task.New(self,function()
        task._Wait(120)
        if self.mode==2 then
            labyrinth.p_out=2
        else
        end
        if self.mode==3 then
            labyrinth.p_out=3
        else
        end
        if self.mode==4 then
            labyrinth.p_out=4
        else
        end
        if self.mode==6 then
            if player.x>-64 then
                labyrinth.p_out=3
            else
                labyrinth.p_out=2
            end
        else
        end
        if self.mode==8 then
            if player.x>0 then
                labyrinth.p_out=4
            else
                labyrinth.p_out=2
            end
        else
        end
        if self.mode==12 then
            if player.x>64 then
                labyrinth.p_out=4
            else
                labyrinth.p_out=3
            end
        else
        end
        labyrinth.change=true
        task._Wait(30)
        _del(self,false)
    end)
end
_editor_class["wuer_bg_change"].render=function(self)
    if self.timer<120 then
        SetImageState('white','',Color(0x80FFFFFF))
    else
        SetImageState('white','',Color(128-(self.timer-120)*128/30,255,255,255))
    end
    if self.mode==2 then
        RenderRect('white',188,190,240,240-10*self.timer)
    else
    end
    if self.mode==4 then
        RenderRect('white',-190,-188,240,240-10*self.timer)
    else
    end
    if self.mode==3 then
        RenderRect('white',188,190,240,240-10*self.timer)
        RenderRect('white',-190,-188,240,240-10*self.timer)
    else
    end
    if self.mode==8 then
        RenderRect('white',-1,1,240,240-10*self.timer)
    else
    end
    if self.mode==6 then
        RenderRect('white',-65,-63,240,240-10*self.timer)
    else
    end
    if self.mode==12 then
        RenderRect('white',63,65,240,240-10*self.timer)
    else
    end
end
