_editor_class["yamame_s1_laser"]=Class(laser)
_editor_class["yamame_s1_laser"].init=function(self,_x,_y,rot,t)
    laser.init(self,COLOR_DEEP_GRAY,_x,_y,0,0,0,0,8,8,0)
    laser.ChangeImage(self,3,orginal)
    self.rot=rot
    task.New(self,function()
        PlaySound("boon00",0.1,self.x/256,false)
        PlaySound("lazer01",0.1,self.x/256,false)
        laser._TurnHalfOn(self,1,false)
        local d,l=1,0
        local L=self.l1+self.l2+self.l3
        do for _=1,_infinite do
            d=d+0.05
            l=l+d
            self.l1=0.5*l self.l2=2*l self.l3=0.5*l
            L=self.l1+self.l2+self.l3
            if (self.x+L*cos(self.rot)>192 or self.x+L*cos(self.rot)<-192 or self.y+L*sin(self.rot)>224 or self.y+L*sin(self.rot)<-224) and L>15 then break end
            task._Wait(1)
        end end
        PlaySound("kira00",0.1,self.x/256,false)
        last=New(_editor_class["wuer_yamame_laser_eff"],self.x+L*cos(self.rot),self.y+L*sin(self.rot),_)
        if t>0 then
            last=New(_editor_class["yamame_s1_laser"],self.x+L*cos(self.rot),self.y+L*sin(self.rot),Angle(self.x+L*cos(self.rot),self.y+L*sin(self.rot),player.x,player.y)+ran:Float(-10,10),t-1)
        else
        end
        task._Wait(60)
        laser._TurnOn(self,15,true,false)
        task._Wait(45)
        _del(self,true)
    end)
end
