_tmp_sc=boss.dialog.New(true)
function _tmp_sc:init()
	lstg.player.dialog=true
	_dialog_can_skip=true
	self.dialog_displayer=New(dialog_displayer)
    task.New(self,function()
        if player.class==reimu_player then
            boss.dialog.sentence(self,"image:wuer_yamame_scpic2","right","可了不得，怎么见一次打我一次",600,1,1)
            boss.dialog.sentence(self,"image:wuer_reimu_dialog5","left","诶......我还以为是你一直跟着我，看来是我迷路了",600)
            boss.dialog.sentence(self,"image:wuer_yamame_scpic1","right","原来你是想找这个洞窟的出口吗？",600,1,1)
            boss.dialog.sentence(self,"image:wuer_yamame_scpic1","right","我刚刚挖好一个通道，可以从这里出去，要出去吗？",600,1,1)
            boss.dialog.sentence(self,"image:wuer_reimu_dialog2","left","好啊，那就带我出去吧",600)
        else
        end
        if player.class==marisa_player then
            boss.dialog.sentence(self,"image:wuer_yamame_scpic2","right","哎哟，别再打我啦！",600,1,1)
            boss.dialog.sentence(self,"image:wuer_marisa_dialog5","left","不是你一直跟踪我吗？",600)
            boss.dialog.sentence(self,"image:wuer_yamame_scpic1","right","我一直待在原地啊！",600,1,1)
            boss.dialog.sentence(self,"image:wuer_marisa_dialog1","left","啊？看来是这个迷宫太绕了，你知道哪边能出去吗？",600)
            boss.dialog.sentence(self,"image:wuer_yamame_scpic3","right","我挖了一条通道，可以出去，要来吗？",600,1,1)
            boss.dialog.sentence(self,"image:wuer_marisa_dialog1","left","好啊，带我出去吧",600)
        else
        end
        if player.class==sanae_player then
            boss.dialog.sentence(self,"image:wuer_yamame_scpic2","right","可了不得，怎么见一次打我一次",600,1,1)
            boss.dialog.sentence(self,"image:wuer_sanae_dialog4","left","收拾妖怪是我的工作啊，不过是你一直出现在我附近的吧......",600)
            boss.dialog.sentence(self,"image:wuer_yamame_scpic1","right","并不是，大概是你自己迷路了吧？",600,1,1)
            boss.dialog.sentence(self,"image:wuer_sanae_dialog5","left","你有发现出口吗？",600)
            boss.dialog.sentence(self,"image:wuer_yamame_scpic2","right","没有，但我挖了一条通道，可以出去",600,1,1)
            boss.dialog.sentence(self,"image:wuer_sanae_dialog2","left","正好，那就让我使用一下吧",600)
        else
        end
        if player.class==wuer_player then
            boss.dialog.sentence(self,"image:wuer_yamame_scpic2","right","可了不得，怎么见一次打我一次",600,1,1)
            boss.dialog.sentence(self,"image:wuer_wuer_dialog1","left","啊，我大概是迷路了，然后我又挺怕虫的，虽然蜘蛛不是虫......",600)
            boss.dialog.sentence(self,"image:wuer_yamame_scpic1","right","你看上去不是这里的人呢",600,1,1)
            boss.dialog.sentence(self,"image:wuer_wuer_dialog1","left","我是从异世界来的，四处寻找适合我料理的食材",600)
            boss.dialog.sentence(self,"image:wuer_wuer_dialog3","left","（土蜘蛛的话，感觉吃了会生病）",600)
            boss.dialog.sentence(self,"image:wuer_yamame_scpic2","right","额......我可不是食材",600,1,1)
            boss.dialog.sentence(self,"image:wuer_wuer_dialog1","left","你知道离开这里的路吗？",600)
            boss.dialog.sentence(self,"image:wuer_yamame_scpic3","right","我有一条秘密通道，要来吗？",600,1,1)
            boss.dialog.sentence(self,"image:wuer_wuer_dialog4","left","那可真是太棒了",600)
        else
        end
        last=New(_editor_class["wuer_change_bg_ufo"],self.x,self.y,_)
        task._Wait(30)
        player.dialog=false
        _del(self,true)
    end)
end
