_editor_class["wuer_portal_bullet"]=Class(bullet)
_editor_class["wuer_portal_bullet"].init=function(self,_x,_y,co,v,a)
    bullet.init(self,grain_c,co,true,false)
    self.x,self.y=_x,_y
    self.bound=false
    self.navi=true
    self.vx=1.25*v*cos(a) self.vy=v*sin(a)
    _forbid_v(self,3.75,'original','original')
    _set_a(self,0.01,-90,false)
    task.New(self,function()
        do for _=1,_infinite do
            do for _=1,_infinite do
                if self.y<-230 then break end
                task._Wait(1)
            end end
            local vx,vy=self.vx,self.vy
            local x,y=self.x,self.y
            if IsValid(_boss) and _boss.flag==1 then
                self.vx=vy self.vy=-vx
                self.x=200 self.y=-x
            else
            end
            if IsValid(_boss) and _boss.flag==2 then
                self.y=230
            else
            end
            if IsValid(_boss) and _boss.flag==3 then
                self.vx=-vy self.vy=vx
                self.x=-200 self.y=x
            else
            end
            task._Wait(0)
        end end
    end)
end
