_editor_class["wuer_otohime_S1_1"]=Class(bullet)
_editor_class["wuer_otohime_S1_1"].init=function(self,_x,_y,v,a)
    bullet.init(self,ball_huge,COLOR_BLUE,true,false)
    self.x,self.y=_x,_y
    self.omiga=9
    task.New(self,function()
        do local vv,_d_vv=(0.5),(0.075) for _=1,61 do
            SetV2(self,vv,a,false,false)
            if abs(self.x)>192 or abs(self.y)>224 then break end
            task._Wait(1)
        vv=vv+_d_vv end end
        local acc=0.1125
        local acca=0
        do for _=1,_infinite do
            if self.x>192 then
                self.x=192 self.vx=0 self.vy=0
                acca=ran:Float(-3,3)+180
                if true then break end
            else
            end
            if self.x<-192 then
                self.x=-192 self.vx=0 self.vy=0
                acca=ran:Float(-3,3)
                if true then break end
            else
            end
            if self.y>224 then
                self.y=224 self.vx=0 self.vy=0
                acca=ran:Float(-3,3)-90
                if true then break end
            else
            end
            if self.y<-224 then
                self.y=-224 self.vx=0 self.vy=0
                acca=ran:Float(-3,3)+90
                if true then break end
            else
            end
            task._Wait(1)
        end end
        task._Wait(10)
        _set_a(self,acc,acca,false)
        task._Wait(40)
        do local i,_d_i=(0),(1) local aa,_d_aa=(ran:Float(0,360)),(7*ran:Sign()) for _=1,_infinite do
            if i%3==0 then
                PlaySound("tan00",0.1,self.x/256,false)
                last=New(_editor_class["wuer_otohime_S1_2"],self.x,self.y,ran:Float(0.5,1),aa,star_small,ran:Int(1,7)*2)
            else
            end
            if i%9==0 then
                last=New(_editor_class["wuer_otohime_S1_2"],self.x,self.y,ran:Float(0.5,1),ran:Float(0,360),star_small,ran:Int(1,7)*2)
            else
            end
            task._Wait(1)
        i=i+_d_i aa=aa+_d_aa end end
    end)
end
