    task.New(self,function()
        self.no_killeff=true
        task.MoveTo(0,112,60,MOVE_DECEL)
        if player.class==reimu_player then
            boss.dialog.sentence(self,"image:otohime_dialog","right","你是......之前的那个红色巫女",600,1,1)
            boss.dialog.sentence(self,"image:otohime_dialog","right","正好，你有没有见到过一个叫7[-/V!<Д的人呢？",600,1,1)
            boss.dialog.sentence(self,"image:wuer_reimu_dialog5","left","这是什么奇怪的东西，感觉念都念不出来的音调",600)
            boss.dialog.sentence(self,"image:wuer_reimu_dialog1","left","这个洞穴似乎没有什么奇怪的东西，也有可能是我没遇到？",600)
            boss.dialog.sentence(self,"image:otohime_dialog","right","这样啊，看来不在这里呢......",600,1,1)
            boss.dialog.sentence(self,"image:wuer_reimu_dialog4","left","这个洞穴是你干的好事吧",600)
            boss.dialog.sentence(self,"image:wuer_reimu_dialog4","left","上一次是降下大雨，这一次是奇怪的洞穴",600)
            boss.dialog.sentence(self,"image:otohime_dialog","right","并不是我做的哦，我只是来找很久没见的友人",600,1,1)
            boss.dialog.sentence(self,"image:wuer_reimu_dialog3","left","废话少说，打倒你就知道是不是你做的了",600)
            boss.dialog.sentence(self,"image:otohime_dialog","right","还是那么不讲理呢，红色的巫女",600,1,1)
        else
        end
        if player.class==marisa_player then
            boss.dialog.sentence(self,"image:otohime_dialog","right","你是......之前的那个蓝色魔法使",600,1,1)
            boss.dialog.sentence(self,"image:otohime_dialog","right","正好，你有没有见到过一个叫7[-/V!<Д的人呢？",600,1,1)
            boss.dialog.sentence(self,"image:wuer_marisa_dialog5","left","没听过这样的名字呢",600)
            boss.dialog.sentence(self,"image:wuer_marisa_dialog4","left","这个洞穴似乎没有奇怪的人，要说最奇怪的大概就是你了吧",600)
            boss.dialog.sentence(self,"image:otohime_dialog","right","看来不在这里呢，我到外面看看吧",600,1,1)
            boss.dialog.sentence(self,"image:wuer_marisa_dialog1","left","等一下，带我一起出去吧",600)
            boss.dialog.sentence(self,"image:otohime_dialog","right","实力不够的人，大概是穿不过那个门的",600,1,1)
            boss.dialog.sentence(self,"image:otohime_dialog","right","想要体验一次死亡的感觉吗？",600,1,1)
        else
        end
        if player.class==sanae_player then
            boss.dialog.sentence(self,"image:otohime_dialog","right","你是......之前的那个绿色缺德宗教家",600,1,1)
            boss.dialog.sentence(self,"image:wuer_sanae_dialog4","left","什么！？我可是守矢神社的现人神",600)
            boss.dialog.sentence(self,"image:wuer_sanae_dialog3","left","你是这个迷宫异变的黑幕吧？快让我离开这里",600)
            boss.dialog.sentence(self,"image:otohime_dialog","right","想出去的话，就让我们来进行第二次的弹幕胜负吧！",600,1,1)
        else
        end
        if player.class==wuer_player then
            boss.dialog.sentence(self,"image:otohime_dialog","right","没见过的人呢，跟三原色人类是一伙的吗？",600,1,1)
            boss.dialog.sentence(self,"image:wuer_wuer_dialog1","left","虽然我认识，但我跟她们应该不是一路的哦",600)
            boss.dialog.sentence(self,"image:otohime_dialog","right","似乎你也是异世界来的人呢",600,1,1)
            boss.dialog.sentence(self,"image:wuer_wuer_dialog1","left","是的，我从奇怪的次元通道来到这里，就顺便当做旅游了",600)
            boss.dialog.sentence(self,"image:wuer_wuer_dialog3","left","没想到突然就被困在这个迷宫里",600)
            boss.dialog.sentence(self,"image:otohime_dialog","right","难道你也是\"旅人\"吗？",600,1,1)
            boss.dialog.sentence(self,"image:wuer_wuer_dialog1","left","旅人？我只是恰好看见异世界的通道而来的",600)
            boss.dialog.sentence(self,"image:wuer_wuer_dialog3","left","现在我只想离开这里，你知道哪里有出口吗？",600)
            boss.dialog.sentence(self,"image:otohime_dialog","right","出口我不知道，但我有办法出去。",600,1,1)
            boss.dialog.sentence(self,"image:wuer_wuer_dialog4","left","真的？带我一起出去吧~",600)
            boss.dialog.sentence(self,"image:otohime_dialog","right","那先陪我来玩一场游戏吧",600,1,1)
            boss.dialog.sentence(self,"image:wuer_wuer_dialog3","left","又是弹幕游戏吗？",600)
        else
        end
    end)
