_tmp_sc=boss.card.New("",2,2,60,750,{0,0,0},false)
function _tmp_sc:init()
    task.New(self,function()
        task.MoveTo(0,112,60,MOVE_DECEL)
        last=New(_editor_class["wuer_charge"],-180,220,255,255,0)
        last=New(_editor_class["wuer_charge"],180,220,255,255,0)
        task._Wait(15)
        local i=1
        task.New(self,function()
            task._Wait(180)
            do for _=1,_infinite do
                task.MoveToPlayer(40,-94,94,96,112,32,32,4,8,MOVE_DECEL,MOVE_X_TOWARDS_PLAYER)
                task._Wait(180)
            end end
        end)
        do for _=1,_infinite do
            local dy=ran:Float(-30,30)
            last=New(_editor_class["otohime_non2_light"],-180,330+dy,i)
            last=New(_editor_class["otohime_non2_light"],180,330+dy,i)
            do local x,_d_x=(200*i),(-400/13*i) for _=1,13 do
                last=New(_editor_class["otohime_non2_mid"],x,330+dy+i*40,-i*1.25)
            x=x+_d_x end end
            i=-i
            do local x,_d_x=(200*i),(-400/13*i) for _=1,13 do
                last=New(_editor_class["otohime_non2_mid"],x,330+dy+i*40,-i*1.25)
            x=x+_d_x end end
            task._Wait(120)
        end end
    end)
end
function _tmp_sc:del()
end
