_tmp_sc=boss.card.New("转移「物质传送枪Portal-Gun」",2,5,60,1500,{80,80,80},false)
function _tmp_sc:init()
    last=New(_editor_class["otohime_sc_pic"],self.x,self.y,'otohime_sc')
    task.New(self,function()
        task._Wait(90)
        task.New(self,function()
            do for _=1,3000 do
                do local y,_d_y=(-180),(90) for _=1,5 do
                    last=New(_editor_class["wuer_charge"],192,y,255,128,0)
                y=y+_d_y end end
                last=New(_editor_class["wuer_portal_out"],192+80,0,300,-90)
                task._Wait(60)
                self.flag=1
                task._Wait(300)
                do local x,_d_x=(-160),(80) for _=1,5 do
                    last=New(_editor_class["wuer_charge"],x,224,255,128,0)
                x=x+_d_x end end
                last=New(_editor_class["wuer_portal_out"],0,224+80,300,0)
                task._Wait(60)
                self.flag=2
                task._Wait(300)
                do local y,_d_y=(-180),(90) for _=1,5 do
                    last=New(_editor_class["wuer_charge"],-192,y,255,128,0)
                y=y+_d_y end end
                last=New(_editor_class["wuer_portal_out"],-192-80,0,300,-90)
                task._Wait(60)
                self.flag=3
                task._Wait(300)
            end end
        end)
        task.MoveTo(-60,80,60,MOVE_DECEL)
        do for _=1,_infinite do
            task.New(self,function()
                task.MoveTo(0,112,90,MOVE_NORMAL)
            end)
            do local a,_d_a=(ran:Float(0,360)),(0.612*60) for _=1,45 do
                PlaySound("kira00",0.1,self.x/256,false)
                PlaySound("tan00",0.1,self.x/256,false)
                do local aa,_d_aa=(a),(120) local co,_d_co=(2),(4) for _=1,3 do
                    last=New(_editor_class["wuer_portal_bulletN"],self.x,self.y,co,1.5,aa)
                aa=aa+_d_aa co=co+_d_co end end
                task._Wait(2)
            a=a+_d_a end end
            task._Wait(120)
            task.MoveTo(ran:Float(-100,100),ran:Float(80,144),60,MOVE_DECEL)
            task._Wait(0)
        end end
    end)
end
function _tmp_sc:del()
    _clear_bullet(true,true)
end
