function _tmp_sc:init()
	lstg.player.dialog=true
	_dialog_can_skip=true
	self.dialog_displayer=New(dialog_displayer)
    task.New(self,function()
        task.MoveTo(0,112,60,MOVE_DECEL)
        task._Wait(90)
        labyrinth.otohime_meet=true
        if player.class==reimu_player then
            boss.dialog.sentence(self,"image:otohime_dialog","right","早就说过不是我弄的啦！",600,1,1)
            boss.dialog.sentence(self,"image:wuer_reimu_dialog4","left","无所谓啦，快用你手中的武器送我出去",600)
            boss.dialog.sentence(self,"image:otohime_dialog","right","一如既往的自说自话呢",600,1,1)
            boss.dialog.sentence(self,"image:otohime_dialog","right","出口就在那里了，要走自己走吧",600,1,1)
            player.dialog=false
            task.MoveTo(200,240,90,MOVE_DECEL)
            _del(self,true)
        else
        end
        if player.class==marisa_player then
            boss.dialog.sentence(self,"image:wuer_marisa_dialog5","left","嘿嘿，你又输给我了",600)
            boss.dialog.sentence(self,"image:otohime_dialog","right","比起上次，实力又增强了嘛",600,1,1)
            boss.dialog.sentence(self,"image:wuer_marisa_dialog1","left","那当然，每天都在修行",600)
            boss.dialog.sentence(self,"image:otohime_dialog","right","门我就放在这里了，要出去的话请自便吧",600,1,1)
            task.MoveTo(200,240,90,MOVE_DECEL)
            task.MoveTo(200,400,1,MOVE_DECEL)
            boss.dialog.sentence(self,"image:wuer_marisa_dialog1","left","等一下，把你那个奇怪的枪留下啊",600)
            player.dialog=false
            _del(self,true)
        else
        end
        if player.class==sanae_player then
            boss.dialog.sentence(self,"image:otohime_dialog","right","哎呀呀，又输了",600,1,1)
            boss.dialog.sentence(self,"image:otohime_dialog","right","作为回礼，给你一份最佳的Present",600,1,1)
            boss.dialog.sentence(self,"image:wuer_sanae_dialog4","left","！？",600)
            task.MoveTo(200,240,90,MOVE_DECEL)
            task.MoveTo(200,400,1,MOVE_DECEL)
            boss.dialog.sentence(self,"img_void","right"," ",1,1,1)
            boss.dialog.sentence(self,"image:wuer_sanae_dialog2","left","这是......看上去是迷宫出口",600)
            player.dialog=false
            _del(self,true)
        else
        end
        if player.class==wuer_player then
            boss.dialog.sentence(self,"image:wuer_wuer_dialog3","left","玩够了吗？",600)
            boss.dialog.sentence(self,"image:otohime_dialog","right","意外的冷淡啊",600,1,1)
            boss.dialog.sentence(self,"image:wuer_wuer_dialog3","left","明明是你强迫我玩的",600)
            boss.dialog.sentence(self,"image:wuer_wuer_dialog3","left","现在能让我出去了吧",600)
            boss.dialog.sentence(self,"image:otohime_dialog","right","可以啊，传送门就放这里了",600,1,1)
            boss.dialog.sentence(self,"image:otohime_dialog","right","想出去的话请自便",600,1,1)
            task.MoveTo(200,240,90,MOVE_DECEL)
            boss.dialog.sentence(self,"img_void","right"," ",1,1,1)
            task.MoveTo(200,400,1,MOVE_DECEL)
            boss.dialog.sentence(self,"image:wuer_wuer_dialog4","left","这个门......好像在我玩过的一个游戏里出现过",600)
            boss.dialog.sentence(self,"image:wuer_wuer_dialog3","left","出去前要不要先吃个午饭呢",600)
            player.dialog=false
            _del(self,true)
        else
        end
    end)
end
