_editor_class["wuer_xlc_laser"].frame=function(self)
    task.Do(self)
    if self.colli then
    	local x=player.x-self.x
    	local y=player.y-self.y
    	local rot=self.rot
    	x,y=x*cos(rot)+y*sin(rot),y*cos(rot)-x*sin(rot)
    	y=abs(y)
    	if x>0 then
    		if y<self.w*10/32 then player.class.colli(player,self) end
    		if self.timer%4==0 then
    			if y<self.w*24/32 then item.PlayerGraze() player.grazer.grazed=true end
    		end
    	end
    end
end
_editor_class["wuer_xlc_laser"].render=function(self)
    local w=self.w*0.5
    local l=(self.timer*self.v)%256
    local rot=self.rot
    local x,y=self.x,self.y
    local c=self.color
    local c0=Color(0xFFFFFFFF)
    	w=self.w
    	SetImageState('image:wuer_xlc_laser2','mul+add',c)
    	for i=1,64 do
    		Render('image:wuer_xlc_laser2',self.x+16*i*cos(rot),self.y+16*i*sin(rot),rot,1,self.w/32)
    	end
    	w=self.w*0.5
    	RenderTexture(self.texture,'',
    		{x+w*cos(rot+90)			,y+w*sin(rot+90)				,0.5,256-l	,0	,c0},
    		{x+w*cos(rot+90)+l*cos(rot)	,y+w*sin(rot+90)+l*sin(rot)		,0.5,256	,0	,c0},
    		{x+w*cos(rot-90)+l*cos(rot)	,y+w*sin(rot-90)+l*sin(rot)		,0.5,256	,32	,c0},
    		{x+w*cos(rot-90)			,y+w*sin(rot-90)				,0.5,256-l	,32	,c0}
    	)
    	for i=1,3 do
    	RenderTexture(self.texture,'',
    		{x+w*cos(rot+90)+(l+(i-1)*256)*cos(rot)	,y+w*sin(rot+90)+(l+(i-1)*256)*sin(rot)	,0.5,0	,0	,c0},
    		{x+w*cos(rot+90)+(l+i*256)*cos(rot)		,y+w*sin(rot+90)+(l+i*256)*sin(rot)		,0.5,256	,0	,c0},
    		{x+w*cos(rot-90)+(l+i*256)*cos(rot)		,y+w*sin(rot-90)+(l+i*256)*sin(rot)		,0.5,256	,32	,c0},
    		{x+w*cos(rot-90)+(l+(i-1)*256)*cos(rot)	,y+w*sin(rot-90)+(l+(i-1)*256)*sin(rot)	,0.5,0	,32	,c0}
    	)
    	end
    SetImageState('image:wuer_xlc_lasernode1','mul+add',self.color)
    SetImageState('image:wuer_xlc_lasernode2','mul+add',self.color)
    Render('image:wuer_xlc_lasernode'..(int(self.timer/2)%2+1),self.x,self.y,self.rot,self.hscale*1.6,self.vscale*1.2)
    SetImageState('image:wuer_xlc_lasernode1','mul+add',Color(0xFFFFFFFF))
    SetImageState('image:wuer_xlc_lasernode2','mul+add',Color(0xFFFFFFFF))
    Render('image:wuer_xlc_lasernode'..(int(self.timer/2)%2+1),self.x,self.y,self.rot,self.vscale,self.hscale)
end
