_editor_class["ufo_dialog_obj"]=Class(_object)
_editor_class["ufo_dialog_obj"].init=function(self,_x,_y,_)
    self.x,self.y=_x,_y
	self.img="ani:wuer_ufo_dialog"
	self.layer=LAYER_ENEMY_BULLET
	self.group=GROUP_GHOST
	self.hide=false
	self.bound=false
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    self.ufo=true
    task.New(self,function()
        local dis=_boss.dialog_displayer
        do for _=1,_infinite do
            if not(IsValid(dis)) then break end
            if dis.active<0 then
                _object.set_color(self,"",min(255,255+192*(1-dis.t/16)-(dis.death/30)),63+192*(1-dis.t/16),63+192*(1-dis.t/16),63+192*(1-dis.t/16))
                local t=(dis.t/16)^3
                self.x,self.y=224+dis.active*((1-2*t)*16-128)-dis.death*dis.active*12,240-65-t*16-25
            else
            end
            if dis.active>0 then
                _object.set_color(self,"",min(255,255+192*(dis.t/16)-(dis.death/30)),63+192*(dis.t/16),63+192*(dis.t/16),63+192*(dis.t/16))
                local t=(1-dis.t/16)^3
                self.x,self.y=224+dis.active*(-(1-2*t)*16+128)-dis.death*dis.active*12,240-65-t*16-25
            else
            end
            task._Wait(1)
        end end
        _del(self,false)
    end)
end
