    SetViewMode'ui'
    self.class.base.render(self)
    SetViewMode'world'
end
_editor_class["wuer_choose_stage"]=Class(_object)
_editor_class["wuer_choose_stage"].init=function(self,_x,_y,list)
    self.x,self.y=_x,_y
	self.img="leaf"
	self.layer=LAYER_TOP+11
	self.group=GROUP_GHOST
	self.hide=false
	self.bound=false
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    task.New(self,function()
        self.list=list
        self.pos=1
        self.text={}
        self.text[1]='好呀！'
        self.text[2]='不要......'
        _object.set_color(self,"",0,255,255,255)
    end)
end
_editor_class["wuer_choose_stage"].frame=function(self)
    self.class.base.frame(self)
    player.lock=true
    player.dialog=true
    if KeyIsPressed'up' then self.pos=self.pos-1 PlaySound('select00',0.3) end
    if KeyIsPressed'left' then self.pos=self.pos-1 PlaySound('select00',0.3) end
    if KeyIsPressed'down' then self.pos=self.pos+1 PlaySound('select00',0.3) end
    if KeyIsPressed'right' then self.pos=self.pos+1 PlaySound('select00',0.3) end
    self.pos=(self.pos-1+2)%(2)+1
    if KeyIsPressed'shoot' and self.pos==1 and self.timer>60 then PlaySound('ok00',0.3) self.list.stage=0 self.list.jump=1 Del(self) end
    if KeyIsPressed'shoot' and self.pos==2 and self.timer>60 then PlaySound('ok00',0.3) self.list.stage=1 self.list.jump=1 Del(self) end
end
_editor_class["wuer_choose_stage"].render=function(self)
    self.class.base.render(self)
    SetImageState('white','',Color(0xC0000000))
    --RenderRect('white',-176,176,-176,-100)
    RenderTTF('dialog','',-167,169,-115,-125,Color(0xFFFFFFFF),'paragraph')
    if self.pos==1 then
    RenderTTF('dialog',string.format('\n')..self.text[1],-168,168,-115,-125,Color(0xFFA0FFFF),'paragraph')
    RenderTTF('dialog',string.format('\n')..self.text[2],-120,169,-115,-125,Color(0x33A0FFFF),'paragraph')
    elseif self.pos==2 then
    RenderTTF('dialog',string.format('\n')..self.text[1],-168,168,-115,-125,Color(0x33A0FFFF),'paragraph')
    RenderTTF('dialog',string.format('\n')..self.text[2],-120,169,-115,-125,Color(0xFFA0FFFF),'paragraph')
    end
end
_editor_class["wuer_ufo_laser"]=Class(laser)
_editor_class["wuer_ufo_laser"].init=function(self,_x,_y,a1,a2)
    laser.init(self,COLOR_GREEN,_x,_y,0,15,1,15,8,12,8)
    task.New(self,function()
        self.layer=LAYER_ENEMY_BULLET-2
        task.New(self,function()
            self.rot=a1
            task.New(self,function()
                task._Wait(60)
                do local i,_d_i=(0),(1) for _=1,91 do
                    self.rot=a1+(a2-a1)*sin(i)
                    task._Wait(1)
                i=i+_d_i end end
            end)
            local r=0
            do local i,_d_i=(ran:Int(1,5)),(1) for _=1,_infinite do
                _set_rel_pos(self,32*cos(self.rot),32*sin(self.rot),self.rot,false)
                self.l2=self.l2+6
                do local rr,_d_rr=(0),(5) for _=1,101 do
                    r=rr
                    if Dist(self.x+r*cos(self.rot),self.y+r*sin(self.rot),player.x,player.y)<60 then break end
                rr=rr+_d_rr end end
                if r<450 then
                    self.l2=r-30
                    if i%10==0 then
                        PlaySound("kira00",0.1,self.x/256,false)
                        do local aa,_d_aa=(Angle(self.x+r*cos(self.rot),self.y+r*sin(self.rot),player.x,player.y)+ran:Float(-2,2)),(36) for _=1,10 do
                            last=New(_editor_class["wuer_ufo_bullet1"],self.x+r*cos(self.rot),self.y+r*sin(self.rot),0.7,aa)
                        aa=aa+_d_aa end end
                    else
                    end
                else
                end
                task._Wait(1)
            i=i+_d_i end end
        end)
        laser._TurnOn(self,30,true,true)
    end)
end
