	self.maxhp=10
	self.colli=false
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    _object.set_color(self,"mul+add",255,255,255,255)
    self.hscale=0.05
    task.New(self,function()
        task.New(self,function()
            task._Wait(60)
            do local s,_d_s=(0.05),(1/30) for _=1,31 do
                self.hscale=s
                task._Wait(1)
            s=s+_d_s end end
        end)
        task._Wait(90)
        do local i,_d_i=(0),(1) for _=1,_infinite do
            _set_rel_pos(self,0,0,0,false)
            if i%7<3 then
                _object.set_color(self,"mul+add",233,233,233,233)
            else
                _object.set_color(self,"mul+add",255,255,255,255)
            end
            for _,unit in ObjList(GROUP_ENEMY_BULLET) do
                if unit.y<self.y and abs(unit.x-self.x)<0.25*abs(self.y-unit.y) then
                    if not(unit.flag) then
                        unit.flag=true
                    else
                    end
                    unit.vy=unit.vy+0.05
                else
                end
            end
            if player.y<self.y and abs(self.x-player.x)<abs(player.y-self.y)*0.25 then
                player.y=player.y+0.75
            else
            end
            task._Wait(1)
        i=i+_d_i end end
    end)
end
