_editor_class["enm_dfhlaser"]=Class(laser)
_editor_class["enm_dfhlaser"].init=function(self,_x,_y,a,ii)
    laser.init(self,COLOR_PURPLE,_x,_y,0,5,1,5,8,8,16)
    self.bound=false
    laser.ChangeImage(self,4,orginal)
    task.New(self,function()
        task.New(self,function()
            self.rot=a
            --self.omiga=0.9*ii
            local length=0
            local pr=72
            local shot=8
            local shot_t=0
            do local i,_d_i=(ran:Int(1,5)),(1) local aa,_d_aa=(a),(0.6*ii) for _=1,_infinite do
                local vx,vy=cos(aa),sin(aa)/3
                local vr=(cos(aa)^2+sin(aa)^2/9)^0.5
                local la=atan2(vy,vx)
                local ll=length*vr
                local lx,ly=self.x+vx*length,self.y+vy*length
                local lr=((lx-player.x)^2+(ly-player.y)^2)^0.5
                if lr>pr then
                    length=min(1200,length+16)
                else
                end
                if ll>lr-pr then
                    local r=abs(vy*(self.x-player.x)-vx*(self.y-player.y))
                    if r<=pr then
                        local lh=(pr^2-r^2)^0.5
                        local ld=(((self.x-player.x)^2+(self.y-player.y)^2)-r^2)^0.5-lh
                        if ld<ll then
                            ll=ld
                            length=ld/vr
                            shot_t=shot_t+1
                            if shot_t>shot then
                                shot_t=shot_t-shot
                                last=New(_straight,ball_mid,COLOR_PURPLE,lx,ly,1,self.rot,false,0,true,true,0,false,0,0,0,false)
                                _object.set_color(last,"mul+add",255,255,255,255)
                                last.timer=6
                            else
                            end
                        else
                        end
                    else
                    end
                else
                end
                _set_rel_pos(self,60*vx,60*vy,la,false)
                self.l2=ll
                task._Wait(1)
            i=i+_d_i aa=aa+_d_aa end end
        end)
        laser._TurnOn(self,30,true,true)
    end)
end
