_editor_class["wuer_bar_main"]=Class(_object)
_editor_class["wuer_bar_main"].init=function(self,_x,_y,t)
    self.x,self.y=_x,_y
	self.img="leaf"
	self.layer=LAYER_ENEMY_BULLET
	self.group=GROUP_GHOST
	self.hide=true
	self.bound=false
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=false
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    task.New(self,function()
        task._Wait(t)
        _del(self,true)
    end)
    task.New(self,function()
        local x,y=player.x,player.y
        do for _=1,_infinite do
            if player.protect<=0 then
                for _,unit in ObjList(8) do
                    local c1 = atan(unit.b/unit.a)%360
                    local c2 = Angle(unit,player)%360
                    --[[ y<=unit.y+unit.b and c2>c1 and c2<180-c1 --]]
                    if player.y<unit.y+unit.b and c2>c1 and c2<=180-c1 then
                        player.y=unit.y+unit.b
                    else
                    end
                    if player.y>unit.y-unit.b and c2<-c1+360 and c2>180+c1 then
                        player.y=unit.y-unit.b
                    else
                    end
                    if player.x<unit.x+unit.a and ((c2<=c1 and c2>=0) or (c2>=360-c1 and c2<=360)) then
                        player.x=unit.x+unit.a
                    else
                    end
                    if player.x>unit.x-unit.a and c2>180-c1 and c2<=180+c1 then
                        player.x=unit.x-unit.a
                    else
                    end
                end
            else
            end
            if player.protect<=0 and player.y<-224+16 then
                player.class.colli(player,enemy)
            else
            end
            task._Wait(1)
        end end
    end)
end
