_editor_class["wuer_enm_1-1_laser"]=Class(laser)
_editor_class["wuer_enm_1-1_laser"].init=function(self,_x,_y,enm1,enm2)
    laser.init(self,COLOR_RED,_x,_y,0,0,0,0,4,0,8)
    self.bound=false
    task.New(self,function()
        self.layer=LAYER_ENEMY-2
        laser._TurnOn(self,1,false,true)
        do for _=1,_infinite do
            if (not IsValid(enm1)) or (not IsValid(enm2)) then break end
            self.x=enm1.x self.y=enm1.y
            self.l2=Dist(enm1,enm2)
            self.rot=Angle(enm1,enm2)
            task._Wait(1)
        end end
        _kill(self,true)
    end)
end
_editor_class["wuer_enm_1-1_laser"].render=function(self)
    if self.w>0 then
    		local c=Color(255*self.alpha,255,255,255)
    		local c2=Color(255*self.alpha,200,200,200)
    		local data = laser_data[self.imgid]
    		local l=(self.l1+self.l2+self.l3)*0.95
    		if self.timer%8<4 then
    			SetImageState(self.img2,'mul+add',c)
    		else
    			SetImageState(self.img2,'mul+add',c2)
    		end
    		Render(self.img2,self.x+self.l1*cos(self.rot),self.y+self.l1*sin(self.rot),self.rot,self.l2/data[2],0.8)
    		SetImageState(self.img2,'',Color(0xFF000000))
    		Render(self.img2,self.x+self.l1*cos(self.rot),self.y+self.l1*sin(self.rot),self.rot,self.l2/data[2],0.3)
    		if self.node>0 then
    			c=Color(255*self.w/self.w0,255,255,255)
    			SetImageState(self.img4,'mul+add',c)
    			Render(self.img4,self.x,self.y, 18*self.timer,self.node/8)
    			Render(self.img4,self.x,self.y,-18*self.timer,self.node/8)
    		end
    end
end
