_editor_class["wuer_enm_1-1:Normal"].init=function(self,_x,_y,a,da,x,y,vy,i,enm,co)
    enemy.init(self,23,50,false,false,false)
    self.x,self.y=_x,_y
    self.drop={6,2,2}
    task.New(self,function() self.protect=true task.Wait(1) self.protect=false end)
    self.enm=enm
    if i==1 then
        last=New(_editor_class["wuer_enm_1-1_laser"],self.x,self.y,self,self.enm)
    else
    end
    task.New(self,function()
        local rx,ry=190,100
        do local aa,_d_aa=(a),(da) local n,_d_n=(0),(1) for _=1,_infinite do
            if n%90<13 and n%4==0 then
                last=New(_straight,grain_c,COLOR_RED,self.x,self.y,1.5,aa,false,0,true,true,0,false,0,0,0,false)
            else
            end
            self.x=x+rx*cos(aa) self.y=y+ry*sin(aa)
            y=y+vy
            if y<-240-ry then
                _del(self,true)
            else
            end
            task._Wait(1)
        aa=aa+_d_aa n=n+_d_n end end
    end)
end
