    self.x,self.y=_x,_y
    self.bound=false
    self.colli=false
    task.New(self,function()
        self.colli=false
        task._Wait(60)
        self.colli=true
        do local a,_d_a=(aa),(0) local a2,_d_a2=(aa2),(0) local i,_d_i=(1),(1) for _=1,_infinite do
            self.x=200*cos(a)+60*cos(a2)+r*cos(a+180) self.y=200*sin(a)+60*sin(a2)+r*sin(a+180)
            if i%900<450 then
                _d_a=min(_d_a+0.004,0.4)
                _d_a2=max(_d_a2-0.01,-1)
            else
                _d_a=max(_d_a-0.004,-0.4)
                _d_a2=min(_d_a2+0.01,1)
            end
            task._Wait(1)
        a=a+_d_a a2=a2+_d_a2 i=i+_d_i end end
    end)
end
_editor_class["otohime_b_in"]=Class(_object)
_editor_class["otohime_b_in"].init=function(self,_x,_y,v,a,t,d,time,jump)
    self.x,self.y=_x,_y
	self.img="image:otohime_bullet1"
	self.layer=LAYER_ENEMY_BULLET
	self.group=GROUP_INDES
	self.hide=false
	self.bound=false
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    self.jump=jump
    SetV2(self,v,a,false,false)
    self.img='image:otohime_bullet1'
    if t==2 then
        self.colli=false
        self.img='image:otohime_bullet1'
    else
        self.colli=true
        self.img='image:otohime_bullet2'
    end
    task.New(self,function()
        do for _=1,_infinite do
            if BoxCheck(self,-192,192,-224,224) then break end
            task._Wait(1)
        end end
        self.bound=true
    end)
    task.New(self,function()
        do for _=1,_infinite do
            if self.jump then break end
            task._Wait(1)
        end end
        task._Wait(time)
        do for _=1,_infinite do
            t=-t
            if t==2 then
                self.colli=false
                self.img='image:otohime_bullet1'
            else
                self.colli=true
                self.img='image:otohime_bullet2'
            end
            task._Wait(180)
        end end
    end)
end
_editor_class["otohime_b_in"].kill=function(self)
end
_editor_class["otohime_b_in"].del=function(self)
end
