_editor_class["wuer_bgchange_fog"]=Class(_object)
_editor_class["wuer_bgchange_fog"].init=function(self,_x,_y,a,r,g,b)
    self.x,self.y=_x,_y
	self.img="image:wuer_fog"
	self.layer=LAYER_ENEMY
	self.group=GROUP_GHOST
	self.hide=false
	self.bound=false
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    self.x=0 self.y=0
    self.hscale=3 self.vscale=3
    self.rot=ran:Float(0,360)
    self.omiga=ran:Sign()*0.09
    _object.set_color(self,"mul+add",60,r,g,b)
    task.New(self,function()
        task.New(self,function()
            do local v,_d_v=(0),(ran:Float(3.2,4)/151) for _=1,151 do
                SetV2(self,v,a,false,false)
                task._Wait(1)
            v=v+_d_v end end
        end)
        task.New(self,function()
            do local s,_d_s=(1),(9/151) for _=1,151 do
                self.hscale=s self.vscale=s
                task._Wait(1)
            s=s+_d_s end end
        end)
        do local al,_d_al=(0),(0.5) for _=1,61 do
            _object.set_color(self,"mul+add",al,r,g,b)
            task._Wait(1)
        al=al+_d_al end end
        task._Wait(60)
        do local al,_d_al=(30),(-0.5) for _=1,61 do
            _object.set_color(self,"mul+add",al,r,g,b)
            task._Wait(1)
        al=al+_d_al end end
        _del(self,false)
    end)
end
