	self.img="image:wuer_scroll_circle"
	self.layer=LAYER_BG-0.05
	self.group=GROUP_GHOST
	self.hide=false
	self.bound=true
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    self.img='image:'..img
    self.scroll=scroll
    self.hscale=0 self.vscale=0
    task.New(self,function()
        do local s,_d_s=(0),(1.58/180) local r,_d_r=(ran:Float(0,360)),(ran:Sign()*30/180) local ss,_d_ss=(0),(1.48/180) for _=1,181 do
            self.hscale=s*s*s self.vscale=ss*ss*ss
            self.rot=r
            task._Wait(1)
        s=s+_d_s r=r+_d_r ss=ss+_d_ss end end
        _del(self,false)
    end)
