_editor_class["wuer_sc_change2"].render=function(self)
    PopRenderTarget('er_render')
    if self.scroll then
        Render('image:wuer_scroll',self.x,self.y,self.rot,self.hscale,self.vscale)
    else
    end
    PushRenderTarget('er_render_area')
    RenderClear(Color(0xFF000000))
    self.class.base.render(self)
    PopRenderTarget('er_render_area')
    PostEffect('er_render','fx_switch','',{tex='er_render_area'})
end
