_editor_class["wuer_sc_name"].render=function(self)
    local ax,ay=0,0
    	if IsValid(lstg.player) then
    		ax=min(max((lstg.player.x+40)*0.05,0),0.9)
    		ay=min(max((lstg.player.y-140)*0.05,0),0.9)
    	end
    	local alpha=1-ax*ay
    local xoffset=max(384-self.timer*7,0)
    		SetViewMode'ui'
    SetImageState('boss_spell_name_bg','',Color(alpha*255,255,255,255))
    		local w=lstg.world
    		local x01,y01=WorldToScreen((192+xoffset)*(w.r-w.l)/(w.scrr-w.scrl)+w.centerx,204*(w.t-w.b)/(w.scrt-w.scrb)+w.centery)
    		local x02,y02=WorldToScreen((193+xoffset)*(w.r-w.l)/(w.scrr-w.scrl)+w.centerx,194*(w.t-w.b)/(w.scrt-w.scrb)+w.centery)
    		local x03,y03=WorldToScreen((192+xoffset)*(w.r-w.l)/(w.scrr-w.scrl)+w.centerx,195*(w.t-w.b)/(w.scrt-w.scrb)+w.centery)
    Render('boss_spell_name_bg',x01,y01)
    		RenderTTF('sc_name',self.sc_name,x02,x02,y02,y02,Color(alpha*255,0,0,0),'right','noclip')
    		RenderTTF('sc_name',self.sc_name,x03,x03,y03,y03,Color(alpha*255,255,255,255),'right','noclip')
    		SetViewMode'world'
end
_editor_class["wuer_sc_name"].del=function(self)
end
_editor_class["wuer_sc_name"].kill=function(self)
end
