_editor_class["performing_m-c"]=Class(_object)
_editor_class["performing_m-c"].init=function(self,_x,_y,x,y,s)
    self.x,self.y=_x,_y
	self.img="ani:wuer_magic_circle"
	self.layer=LAYER_ENEMY-1
	self.group=GROUP_INDES
	self.hide=false
	self.bound=true
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=false
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    PlaySound("boon00",0.1,self.x/256,false)
    self.hscale=0.5 self.vscale=0.5
    task.New(self,function()
        _object.set_color(self,"",255,255,255,50)
        task.MoveTo(x,y,30,MOVE_DECEL)
        PlaySound("kira00",0.1,self.x/256,false)
        do local t,_d_t=(60),(-1) local y,_d_y=(self.y+3),(3) for _=1,15 do
            last=New(_editor_class["performing_bullet"],self.x+ran:Float(-16,16),self.y,t,1,y)
            last=New(_editor_class["performing_bullet"],self.x+ran:Float(-16,16),self.y,t,1,y)
            last=New(_editor_class["performing_bullet"],self.x+ran:Float(-16,16),self.y,t,1,y)
            task._Wait(2)
        t=t+_d_t y=y+_d_y end end
        last=New(_editor_class["er_charge_in_onlyeff"],self.x,self.y,255,255,0,nil,6)
