_editor_class["wuer_black_bullet"].init=function(self,_x,_y,v,a)
    bullet.init(self,ball_light_dark_er,COLOR_YELLOW,true,false)
    self.x,self.y=_x,_y
    self.bound=false
    self.timer=11
    last=New(_editor_class["wuer_black_bullet_light"],self.x,self.y,self,COLOR_YELLOW)
    _connect(self,last,0,true)
    self.hscale=0.5 self.vscale=0.5
    SetV2(self,v,a,true,false)
    task.New(self,function()
        do for _=1,_infinite do
            self.a=11.5*self.hscale self.b=11.5*self.vscale
            task._Wait(1)
        end end
    end)
    task.New(self,function()
        do local vv,_d_vv=(0.5),((v-0.5)/90) for _=1,_infinite do
            SetV2(self,min(vv,v),a,true,false)
            if abs(self.x)>216 or abs(self.y)>248 then
                self.vx=0 self.vy=0
                if IsValid(_boss) then
                    self.rot=Angle(self.x,self.y,_boss.x,_boss.y+20)
                else
                end
                if true then break end
            else
            end
            task._Wait(1)
        vv=vv+_d_vv end end
        do for _=1,_infinite do
            if self.flag then break end
            task._Wait(1)
        end end
        task._Wait(ran:Int(1,120))
        task.New(self,function()
            do local s,_d_s=(0.5),(1.5/45) local ss,_d_ss=(0.5),(-0.3/45) for _=1,46 do
                self.hscale=s
                self.vscale=ss
                self.rect=true
                task._Wait(1)
            s=s+_d_s ss=ss+_d_ss end end
        end)
        task._Wait(20)
        if IsValid(_boss) then
            task.MoveTo(_boss.x,_boss.y+20,ran:Int(120,150),MOVE_ACCEL)
        else
            task.MoveTo(0,0,ran:Int(120,150),MOVE_ACCEL)
        end
        do local s,_d_s=(1.5),(-1/30) local ss,_d_ss=(0.2),(0.3/30) for _=1,31 do
            self.hscale=s
            self.vscale=ss
            self.rect=true
            task._Wait(1)
        s=s+_d_s ss=ss+_d_ss end end
        _del(self,false)
    end)
end
