_editor_class["touyingA"].init=function(self,_x,_y,mxr,myr,angle,z0,x0,style,co)
    bullet.init(self,style,co,true,false)
    self.x,self.y=_x,_y
    self.img='ball_mid_light'..(co/2)
    self.x0=self.x
    self.y0=self.y
    local dir=sign(self.x)
    task.New(self,function()
        self.bound=false
        local xr=0
        local yr=0
        task.New(self,function()
            do local a,_d_a=(0),(90/180) for _=1,180 do
                xr=mxr*sin(a)
                yr=myr*sin(a)
                task._Wait(1)
            a=a+_d_a end end
            local dy=0
            task.New(self,function()
                do for _=1,61 do
                    dy=dy+1/60
                    task._Wait(1)
                end end
            end)
            do local y0,_d_y0=(self.y0),(0) for _=1,900 do
                self.y0=y0
                y0=y0-dy
                task._Wait(1)
            y0=y0+_d_y0 end end
            _del(self,true)
        end)
        --[[  --]]
        local dxa=10
        do local ya,_d_ya=(angle),(0.1*dir) local za,_d_za=(z0),(0.1*dir) local xa,_d_xa=(x0),(-0.1*dir) for _=1,_infinite do
            self.x=xr*cos(ya)*cos(za)+(yr*cos(xa+dxa)+xr*sin(xa+dxa)*sin(ya))*sin(za)+self.x0
            self.y=-xr*cos(ya)*sin(za)+(yr*cos(xa-dxa)+xr*sin(xa-dxa)*sin(ya))*cos(za)+self.y0
            task._Wait(1)
        ya=ya+_d_ya za=za+_d_za xa=xa+_d_xa end end
    end)
end
