_editor_class["life_game1"]=Class(bullet)
_editor_class["life_game1"].init=function(self,_x,_y,s,b,x,y)
    bullet.init(self,ball_mid,COLOR_BLUE,true,false)
    self.x,self.y=_x,_y
    self.timer=11
    self.bound=false
    local n=0
    _object.set_color(self,"mul+add",0,255,255,255)
    self.colli=false
    self.f=0
    if false then
        _object.set_color(self,"mul+add",255,255,255,255)
        self.colli=true
        self.f=1
    else
    end
    if s==1 and false then
        _object.set_color(self,"mul+add",255,255,255,255)
        self.colli=true
        self.f=1
    else
    end
    task.New(self,function()
        do local a,_d_a=(0),(1) for _=1,_infinite do
            SetV2(self,0.1,a,false,false)
            task._Wait(1)
        a=a+_d_a end end
    end)
    task.New(self,function()
        task._Wait(60)
        local time=15
        do for _=1,_infinite do
            time=max(5,time-0.05)
            n=0
            self.flag=true
            if x>1 and x<33 and y>1 and y<37 then
                if IsValid(_boss.list[x-1][y-1]) and _boss.list[x-1][y-1].colli==true then
                    n=n+1
                else
                end
                if IsValid(_boss.list[x][y-1]) and _boss.list[x][y-1].colli==true then
                    n=n+1
                else
                end
                if IsValid(_boss.list[x+1][y-1]) and _boss.list[x+1][y-1].colli==true then
                    n=n+1
                else
                end
                if IsValid(_boss.list[x-1][y]) and _boss.list[x-1][y].colli==true then
                    n=n+1
                else
                end
                if IsValid(_boss.list[x+1][y]) and _boss.list[x+1][y].colli==true then
                    n=n+1
                else
                end
                if IsValid(_boss.list[x-1][y+1]) and _boss.list[x-1][y+1].colli==true then
                    n=n+1
                else
                end
                if IsValid(_boss.list[x][y+1]) and _boss.list[x][y+1].colli==true then
                    n=n+1
                else
                end
                if IsValid(_boss.list[x+1][y+1]) and _boss.list[x+1][y+1].colli==true then
                    n=n+1
                else
                end
                if (n<2 or n>3) and self.colli==true and self.flag then
                    self.f=0
                    self.flag=nil
                else
                end
                if n==3 and self.colli==false and self.flag then
                    self.f=1
                    self.flag=nil
                else
                end
            else
            end
            task._Wait(1)
            if self.f==1 then
                if self.colli==false then
                    do local al,_d_al=(0),(255/19) for _=1,20 do
                        _object.set_color(self,"mul+add",al,255,255,255)
                        task._Wait(1)
                    al=al+_d_al end end
                else
                    task._Wait(20)
                end
            else
                if self.colli==true then
                    self.colli=false
                    do local al,_d_al=(255),(-255/19) for _=1,20 do
                        _object.set_color(self,"mul+add",al,255,255,255)
                        task._Wait(1)
                    al=al+_d_al end end
                else
                    task._Wait(20)
                end
            end
            if self.f==1 then
                self.colli=true
                _object.set_color(self,"mul+add",255,255,255,255)
                ChangeBulletImage(self,ball_mid,COLOR_BLUE)
            else
                self.colli=false
                _object.set_color(self,"mul+add",0,255,255,255)
            end
            task._Wait(5)
        end end
    end)
end
_editor_class["life_game1"].kill=function(self)
    if self.colli then
        New(item_faith_minor,self.x,self.y)
        	if self._index then New(BulletBreak,self.x,self.y,self._index) end
        	if self.imgclass.size==2.0 then
        		self.imgclass.del(self)
        	end
    else
    end
end
