_editor_class["wuer_laby_bullet1"].init=function(self,_x,_y,mas,da)
    bullet.init(self,ball_mid,COLOR_RED,true,false)
    self.x,self.y=_x,_y
    self.img='ball_mid_light1'
    local d,a=Dist(self,mas),Angle(mas,self)
    self.bound=false
    self.colli=false
    _object.set_color(self,"mul+add",128,255,255,255)
    task.New(self,function()
        task.New(self,function()
            task._Wait(60)
            do local al,_d_al=(128),(127/29) for _=1,30 do
                _object.set_color(self,"mul+add",al,255,255,255)
                task._Wait(1)
            al=al+_d_al end end
            self._blend=nil
            self.colli=true
        end)
        task._Wait(90)
        local dda=0
        do local aa,_d_aa=(a),(0) for _=1,_infinite do
            dda=min(dda+0.001,da)
            aa=aa+dda
            if IsValid(mas) then
                self.x=mas.x+d*cos(aa) self.y=mas.y+d*sin(aa)
            else
            end
            task._Wait(1)
