_editor_class["wuer_lsc_shader_ball"]=Class(_object)
_editor_class["wuer_lsc_shader_ball"].init=function(self,_x,_y,size,v,a)
    self.x,self.y=_x,_y
	self.img="image:shader_ball"
	self.layer=LAYER_TOP+0.4
	self.group=GROUP_INDES
	self.hide=false
	self.bound=false
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    last=New(_editor_class["wuer_lsc_shader_ball2"],self.x,self.y,size)
    _connect(self,last,0,true)
    self.a=size self.b=size self.hscale=size/120 self.vscale=size/120
    _object.set_color(self,"mul+add",255,255,255,255)
    self.can_kill=true
    task.New(self,function()
        do for _=1,_infinite do
            if abs(self.x)<192 and abs(self.y)<224 then break end
            task._Wait(1)
        end end
        do for _=1,_infinite do
            if abs(self.x)>200+size and abs(self.y)>232+size then break end
            task._Wait(1)
        end end
        _del(self,false)
    end)
    task.New(self,function()
        SetV2(self,v,a,true,false)
    end)
end
