            _set_rel_pos(self,0,0,self.rot,false)
            task._Wait(1)
        end end
    end)
end
_editor_class["wuer_lsc_shader_ball2"].colli=function(self,other)
    if other.group==GROUP_ENEMY_BULLET then
        _del(other,true)
    else
    end
    if other.group==GROUP_ENEMY and other~=_boss then
        other.hp=other.hp-100
    else
    end
end
