_editor_class["wuer_lsc_laser"].init=function(self,_x,_y,x1,y1,x2,y2,t2,x3,y3,t3,x4,y4,t4)
    laser.init(self,COLOR_PURPLE,_x,_y,0,0,0,0,8,0,0)
    self.rot=Angle(self.x,self.y,x1,y1)
    local d1=Dist(self.x,self.y,x1,y1)
    task.New(self,function()
        PlaySound("boon01",0.1,self.x/256,false)
        laser._TurnOn(self,60,false,false)
        do local ll,_d_ll=(0),(d1/180) for _=1,61 do
            self.l1=ll self.l2=ll self.l3=ll
            task._Wait(1)
        ll=ll+_d_ll end end
        task._Wait(15)
        PlaySound("slash",0.1,self.x/256,false)
        do local i,_d_i=(0),(90/t2) local a,_d_a=(ran:Float(0,360)),(7) local t,_d_t=(0),(1/t2) local n,_d_n=(0),(1) for _=1,t2+1 do
            local x,y=x1+(x2-x1)*t,y1+(y2-y1)*t
            local d=Dist(self.x,self.y,x,y)
            local rot=Angle(self.x,self.y,x,y)
            self.rot=rot
            self.l1=d/3 self.l2=d/3 self.l3=d/3
            if n then
                do local f,_d_f=(1),(-0.33) for _=1,3 do
                    do local aa,_d_aa=(a),(90) for _=1,4 do
                        last=New(_editor_class["wuer_lsc_bullet"],self.x+d*f*cos(rot),self.y+d*f*sin(rot),water_drop,4,1.5,aa,60,false)
                    aa=aa+_d_aa end end
                f=f+_d_f end end
            else
            end
            task._Wait(1)
        i=i+_d_i a=a+_d_a t=t+_d_t n=n+_d_n end end
        if x3 then
            PlaySound("slash",0.1,self.x/256,false)
            do local i,_d_i=(0),(90/t3) local a,_d_a=(ran:Float(0,360)),(7) local t,_d_t=(0),(1/t3) local n,_d_n=(0),(1) for _=1,t3+1 do
                local x,y=x2+(x3-x2)*sin(i),y2+(y3-y2)*sin(i)
                local d=Dist(self.x,self.y,x,y)
                local rot=Angle(self.x,self.y,x,y)
                self.rot=rot
                self.l1=d/3 self.l2=d/3 self.l3=d/3
                if n then
                    do local f,_d_f=(1),(-0.33) for _=1,3 do
                        do local aa,_d_aa=(a),(90) for _=1,4 do
                            last=New(_editor_class["wuer_lsc_bullet"],self.x+d*f*cos(rot),self.y+d*f*sin(rot),water_drop,4,1.5,aa,60,false)
                        aa=aa+_d_aa end end
                    f=f+_d_f end end
                else
                end
                task._Wait(1)
            i=i+_d_i a=a+_d_a t=t+_d_t n=n+_d_n end end
        else
            _del(self,true)
        end
        if x4 then
            PlaySound("slash",0.1,self.x/256,false)
            do local i,_d_i=(0),(90/t4) local a,_d_a=(ran:Float(0,360)),(7) local t,_d_t=(0),(1/t4) local n,_d_n=(0),(1) for _=1,t4+1 do
                local x,y=x3+(x4-x3)*sin(i),y3+(y4-y3)*sin(i)
                local d=Dist(self.x,self.y,x,y)
