_editor_class["otohime_dialog_dot"]=Class(_object)
_editor_class["otohime_dialog_dot"].init=function(self,_x,_y,_)
    self.x,self.y=_x,_y
	self.img="leaf"
	self.layer=LAYER_ENEMY
	self.group=GROUP_ENEMY
	self.hide=false
	self.bound=false
	self.navi=false
	self.hp=10000
	self.maxhp=10000
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    self.imgs={}
    for i=1,12 do self.imgs[i]='image:otohime_dialog_dot'..i end
    self.ani_intv=8
    self.lr=1
    task.New(self,function()
        task.MoveTo(-60,112,90,MOVE_DECEL)
        self.flag=nil
        do for _=1,_infinite do
            if self.flag then break end
            task._Wait(1)
        end end
        task.MoveTo(-260,220,180,MOVE_ACCEL)
        _del(self,false)
    end)
end
_editor_class["otohime_dialog_dot"].frame=function(self)
    task.Do(self)
    if self.dx>0.5 then dx=1 elseif self.dx<-0.5 then dx=-1 else dx=0 end
    	self.lr=self.lr+dx
    	if self.lr> 18 then self.lr= 18 end
    	if self.lr<-18 then self.lr=-18 end
    	if self.lr==0 then self.lr=self.lr+dx end
    	if dx==0 then
    		if self.lr> 1 then self.lr=self.lr-1 end
    		if self.lr<-1 then self.lr=self.lr+1 end
    	end
    	if self.imgs then
    			if abs(self.lr)==1 then
    				self.img=self.imgs[int(self.ani/self.ani_intv)%4+1]
    			elseif abs(self.lr)==18 then
    				self.img=self.imgs[8]
    			else
    				self.img=self.imgs[int((abs(self.lr)-2)/4)+5]
    			end
    	end
    	self.hscale=sign(self.lr)
end
