_editor_class["tenka1:Normal"].init=function(self,cards)
    boss.init(self,240,384,"Sin Tenka",cards,New(_editor_class["tenka_bg"]))
	self.difficulty="Normal"
	self.ani_intv=8
	for i=1,4 do self['img'..i]={} end
	self.nn={7,5,5,5}
	self.mm={3,3,3}
	for i=2,4 do self['ani'..i]=self.nn[i]-self.mm[i-1] end
	for i=1,4 do
		for j=1,self.nn[i] do
			self['img'..i][j]='anonymous:'.."sin_tenka.png"..i..j
		end
	end
end
