function _tmp_sc:init()
	lstg.player.dialog=true
	_dialog_can_skip=true
	self.dialog_displayer=New(dialog_displayer)
    task.New(self,function()
        boss.show_aura(self,false)
        if player.class==reimu_player then
            boss.dialog.sentence(self,"image:wuer_reimu_dialog4","left","这是......这个迷宫几乎把幻想乡全域都覆盖了！",360)
            task.MoveTo(0,112,90,MOVE_DECEL)
            boss.dialog.sentence(self,"image:tenka_sc_pic","right","你是......人类？",360,1,1)
            boss.dialog.sentence(self,"image:wuer_reimu_dialog4","left","你是谁？该不会这个迷宫就是你弄出来的？",360)
            last=New(_editor_class["otohime_dialog_dot"],-240,384,_)
            task.MoveTo(60,112,60,MOVE_DECEL)
            boss.dialog.sentence(self,"image:otohime_dialog","right","你出来了啊",360,1,1)
            boss.dialog.sentence(self,"image:otohime_dialog","right","啊，天卦也在这里",360,1,1)
            boss.dialog.sentence(self,"image:wuer_reimu_dialog3","left","......",360)
            boss.dialog.sentence(self,"image:otohime_dialog","right","我来介绍一下，这位是心天卦，是我好久不见的友人哦",360,1,1)
            boss.dialog.sentence(self,"image:tenka_sc_pic","right","这个星球，已经有那么多的生物了呢",360,1,1)
            boss.dialog.sentence(self,"image:tenka_dialog_1","right","是时候出来玩一玩了~",360,1,1)
            boss.dialog.sentence(self,"image:wuer_reimu_dialog4","left","所以你就是异变的黑幕咯？",360)
            boss.dialog.sentence(self,"image:tenka_dialog_2","right","异变？我只是想跟你们这些玩具玩耍而已",360,1,1)
            boss.dialog.sentence(self,"image:wuer_reimu_dialog3","left","我们可不是玩具！",360)
            boss.dialog.sentence(self,"image:tenka_sc_pic","right","你们的始祖，就是用我的能力造出来的哦",360,1,1)
            boss.dialog.sentence(self,"image:tenka_dialog_1","right","在我的眼中，你们都是我的玩具罢了",360,1,1)
            boss.dialog.sentence(self,"image:otohime_dialog","right","别玩了啦，那么久没见了，我们找个地方聊一聊吧",360,1,1)
            boss.dialog.sentence(self,"image:wuer_reimu_dialog3","left","你们不许走！",360)
