            _stop_music()
            task._Wait(10)
            boss.dialog.sentence(self,"image:tenka_dialog_2","right","区区玩具也敢威胁我？有必要让你回炉重造一下！",360,1,1)
            boss.dialog.sentence(self,"image:wuer_reimu_dialog4","left","黑幕都是那么中二的吗？",360)
            for _,unit in ObjList(GROUP_ENEMY) do
                if unit~=_boss then
                    unit.flag=true
                else
                end
            end
        else
