        if player.class==marisa_player then
            boss.dialog.sentence(self,"image:wuer_marisa_dialog1","left","哇哦，这个迷宫真大啊",360)
            boss.dialog.sentence(self,"img_void","right","那当然",360,1,1)
            last=New(_editor_class["otohime_dialog_dot1"],-240,384,_)
            task._Wait(90)
            boss.dialog.sentence(self,"image:otohime_dialog","right","这是我朋友做出来的",360,1,1)
