                end
            end
            task.MoveTo(60,112,90,MOVE_DECEL)
            boss.dialog.sentence(self,"image:otohime_dialog","right","给你介绍一下，这是心天卦",360,1,1)
            boss.dialog.sentence(self,"image:tenka_dialog_1","right","哎呀，你好啊",360,1,1)
            boss.dialog.sentence(self,"image:wuer_marisa_dialog1","left","这么大的迷宫是你一个人做出来的，那你一定很强吧！",360)
            boss.dialog.sentence(self,"image:tenka_sc_pic","right","没有生命的东西算什么，你们理论上都是我的作品",360,1,1)
            boss.dialog.sentence(self,"image:wuer_marisa_dialog5","left","你想说生命都是你造出来的吗？",360)
            boss.dialog.sentence(self,"image:tenka_dialog_1","right","大部分啦",360,1,1)
            boss.dialog.sentence(self,"image:wuer_marisa_dialog2","left","既然你那么强，那就让我来当一回叛逆期的坏小孩吧",360)
            do local s,_d_s=(1),(-1/40) for _=1,41 do
              SetBGMVolume('black opal labyrinth',s)
              task._Wait(1)
            s=s+_d_s end end
            _stop_music()
            task._Wait(10)
            boss.dialog.sentence(self,"image:tenka_dialog_1","right","真是有趣的想法，想过顶撞长辈的后果吗？",360,1,1)
            for _,unit in ObjList(GROUP_ENEMY) do
                if unit~=_boss then
                    unit.flag=true
                else
                end
            end
        else
        end
        if player.class==sanae_player then
            boss.dialog.sentence(self,"image:wuer_sanae_dialog5","left","这么大的迷宫......",360)
            boss.dialog.sentence(self,"image:wuer_sanae_dialog2","left","就算是那两位也造不出来吧",360)
            boss.dialog.sentence(self,"img_void","right","那当然",360,1,1)
            last=New(_editor_class["otohime_dialog_dot1"],-240,384,_)
            task._Wait(90)
            boss.dialog.sentence(self,"image:otohime_dialog","right","这是我朋友做出来的",360,1,1)
            boss.dialog.sentence(self,"image:wuer_sanae_dialog2","left","哦~~我很满意你的Present",360)
            for _,unit in ObjList(GROUP_ENEMY) do
                if unit~=_boss then
                    unit.flag=true
                else
                end
            end
            task.MoveTo(60,112,90,MOVE_DECEL)
            boss.dialog.sentence(self,"image:otohime_dialog","right","给你介绍一下，这是心天卦",360,1,1)
            boss.dialog.sentence(self,"image:otohime_dialog","right","天卦，这家伙就是那个缺德宗教家",360,1,1)
            boss.dialog.sentence(self,"image:tenka_dialog_2","right","明明还有光辉的生命，还敢自称为神",360,1,1)
            boss.dialog.sentence(self,"image:wuer_sanae_dialog3","left","我是神，我也从幻想乡收集很多信仰了",360)
            boss.dialog.sentence(self,"image:tenka_sc_pic","right","信仰吗？以前的人都称我为女娲，不是你这个小小现人神可以比的",360,1,1)
            boss.dialog.sentence(self,"image:wuer_sanae_dialog4","left","女娲？是那位上古之神吗？",360)
            boss.dialog.sentence(self,"image:tenka_sc_pic","right","是不是神无所谓",360,1,1)
            boss.dialog.sentence(self,"image:wuer_sanae_dialog3","left","如果你是来抢信仰的话，我就要把你退治了！",360)
                do local s,_d_s=(1),(-1/40) for _=1,41 do
                    SetBGMVolume('black opal labyrinth',s)
                    task._Wait(1)
                s=s+_d_s end end
                _stop_music()
            task._Wait(10)
            boss.dialog.sentence(self,"image:tenka_dialog_2","right","乙姬，这家伙真的很讨厌啊",360,1,1)
            boss.dialog.sentence(self,"image:otohime_sc","right","那就把他弄碎吧！",360,1,1)
            for _,unit in ObjList(GROUP_ENEMY) do
                if unit~=_boss then
                    unit.flag=true
                else
                end
            end
        else
        end
        if player.class==wuer_player then
            boss.dialog.sentence(self,"image:wuer_wuer_dialog4","left","这个迷宫还真是大呢",360)
            boss.dialog.sentence(self,"img_void","right","那当然",360,1,1)
            last=New(_editor_class["otohime_dialog_dot1"],-240,384,_)
            task._Wait(90)
            boss.dialog.sentence(self,"image:otohime_dialog","right","这是我朋友做出来的",360,1,1)
            for _,unit in ObjList(GROUP_ENEMY) do
                if unit~=_boss then
                    unit.flag=true
                else
                end
            end
            task.MoveTo(60,112,90,MOVE_DECEL)
            boss.dialog.sentence(self,"image:otohime_dialog","right","给你介绍一下，这是心天卦",360,1,1)
            boss.dialog.sentence(self,"image:tenka_dialog_2","right","你似乎不是这个星球上的人？",360,1,1)
            boss.dialog.sentence(self,"image:wuer_wuer_dialog3","left","我是地球人！",360)
            boss.dialog.sentence(self,"image:otohime_dialog","right","他是从别的世界来的",360,1,1)
            boss.dialog.sentence(self,"image:tenka_dialog_2","right","原来如此，在你身上感觉不到我的气息",360,1,1)
            boss.dialog.sentence(self,"image:wuer_wuer_dialog1","left","气息？",360)
            boss.dialog.sentence(self,"image:tenka_dialog_1","right","没错，这个星球上的人几乎都是我创造的",360,1,1)
            boss.dialog.sentence(self,"image:tenka_dialog_1","right","从远古时代，人们就称我为大地之母，也有人叫我女娲",360,1,1)
            boss.dialog.sentence(self,"image:wuer_wuer_dialog3","left","（女娲是外星人？？好像有种既视感......）",360)
            boss.dialog.sentence(self,"image:wuer_wuer_dialog2","left","难道你是想重现你星球的未来吗？",360)
            boss.dialog.sentence(self,"image:tenka_dialog_2","right","啊？并不是哦，我只是在这星球创造了一些生命",360,1,1)
            boss.dialog.sentence(self,"image:tenka_dialog_1","right","为了让我们的生活有趣一些",360,1,1)
            boss.dialog.sentence(self,"image:wuer_wuer_dialog1","left","原来如此",360)
            boss.dialog.sentence(self,"image:tenka_dialog_1","right","异界有什么有趣的事，能跟我说说吗？",360,1,1)
            boss.dialog.sentence(self,"image:wuer_wuer_dialog3","left","啊，好麻烦啊，不要",360)
                do local s,_d_s=(1),(-1/40) for _=1,41 do
                    SetBGMVolume('black opal labyrinth',s)
                    task._Wait(1)
                s=s+_d_s end end
                _stop_music()
            task._Wait(10)
            boss.dialog.sentence(self,"image:tenka_sc_pic","right","那就让我看看你的实力吧！",360,1,1)
            boss.dialog.sentence(self,"image:wuer_wuer_dialog3","left","难道一言不合就打一架是这个世界的常识吗......",360)
            for _,unit in ObjList(GROUP_ENEMY) do
