_tmp_sc=boss.card.New("",5,10,50,1000,{0,0,0},false)
function _tmp_sc:init()
    task.New(self,function()
        task._Wait(60)
        task.New(self,function()
            task._Wait(420)
            do local a,_d_a=(ran:Float(0,360)),(16) local a1,_d_a1=(ran:Float(0,360)),(-8) for _=1,_infinite do
                PlaySound("tan00",0.1,self.x/256,false)
                do local aa,_d_aa=(a1),(120) for _=1,3 do
                    last=New(_straight,ball_mid,COLOR_BLUE,self.x+36*cos(a)+18*cos(aa),self.y+36*sin(a)+18*sin(aa),0.5,aa+90,false,0,true,true,0,false,0.015,'original',1.8,false)
                aa=aa+_d_aa end end
                task._Wait(7)
            a=a+_d_a a1=a1+_d_a1 end end
        end)
        do for _=1,_infinite do
            last=New(_editor_class["wuer_charge_new"],self.x,self.y,_)
            last=New(_editor_class["er_charge_in"],self.x,self.y,255,255,0,'ch02',6)
            task._Wait(60)
            last=New(_editor_class["er_charge_out"],self.x,self.y,255,255,0,'enep02',6)
            last=New(_editor_class["performing_m-c"],self.x,self.y,-100,60,211)
            last=New(_editor_class["performing_m-c"],self.x,self.y,100,60,211)
            task._Wait(480)
        end end
    end)
end
function _tmp_sc:del()
end
table.insert(_editor_class["tenka1:Normal"].cards,_tmp_sc)
_tmp_sc=boss.card.New("元始「膨胀的气球」",5,10,70,2200,{50,50,50},false)
function _tmp_sc:init()
    task.New(self,function()
        do for _=1,90 do
            for _,unit in ObjList(GROUP_ENEMY) do
                if unit~=_boss then
                    _del(unit,true)
                else
                end
            end
            task._Wait(1)
        end end
    end)
    task.New(self,function()
        do for _=1,_infinite do
            if player.nextspell>0 then
                self.DMG_factor=0.5
            else
                self.DMG_factor=1
            end
            task._Wait(1)
        end end
    end)
    last=New(_editor_class["tenka_sc_pic"],self.x,self.y,_)
    local co,t=2,1000
    local r,g,b=255,0,0
    if player.class==reimu_player then
        co,t=2,880
        r,g,b=255,0,0
    else
    end
    if player.class==marisa_player then
        co,t=6,820
        r,g,b=0,0,255
    else
    end
    if player.class==sanae_player then
        co,t=10,450
        r,g,b=0,255,0
    else
    end
    if player.class==wuer_player then
        co,t=4,1180
        r,g,b=255,0,255
    else
    end
    task.New(self,function()
        task.MoveTo(0,112,60,MOVE_DECEL)
        do for _=1,_infinite do
            boss.cast(self,60)
            last=New(_editor_class["er_charge_in"],self.x,self.y,r,g,b,'ch02',1)
            task._Wait(60)
            last=New(_editor_class["er_charge_out"],self.x,self.y,r,g,b,'kira00',1)
            last=New(_editor_class["balloon_shooterN"],self.x,self.y,co)
            task._Wait(t-60)
        end end
    end)
end
function _tmp_sc:del()
end
table.insert(_editor_class["tenka1:Normal"].cards,_tmp_sc)
table.insert(_sc_table,{"tenka1:Normal","元始「膨胀的气球」",_tmp_sc,#_editor_class["tenka1:Normal"].cards,false})
_tmp_sc=boss.card.New("",5,10,50,1000,{0,0,0},false)
function _tmp_sc:init()
    task.New(self,function()
        local a=0
        local i=1
        task._Wait(90)
        last=New(_editor_class["er_charge_in"],self.x,self.y,0,0,255,'ch02',1)
        task._Wait(30)
        last=New(_editor_class["er_charge_in"],self.x,self.y,255,0,0,'ch02',1)
        task._Wait(30)
        last=New(_editor_class["tenka_back"],self.x,self.y,1)
        task._Wait(30)
        do for _=1,100 do
            local xx,yy=ran:Float(1,40)*i,180
            local z0,x0=ran:Float(-30,30),ran:Float(-30,30)
            PlaySound("boon01",0.1,self.x/256,false)
            do local r,_d_r=(0),(283/9) local y,_d_y=(200),(-400/9) for _=1,9 do
                do local aa,_d_aa=(atan(3^0.5)),(120) for _=1,3 do
                    last=New(_editor_class["touyingA"],xx,yy,r,y,aa,z0,x0,ball_mid,4+2*i)
                aa=aa+_d_aa end end
            r=r+_d_r y=y+_d_y end end
            do local d,_d_d=(244.8),(-244.8/4.5) for _=1,10 do
                a=atan(d/141.5)
                do local aa,_d_aa=(a),(120) for _=1,3 do
                    last=New(_editor_class["touyingA"],xx,yy,(d*d+141.5*141.5)^0.5,-200,aa,z0,x0,ball_mid,4+i*2)
                aa=aa+_d_aa end end
            d=d+_d_d end end
            i=-i
            task._Wait(60)
            task.MoveToPlayer(60,-96,96,112,144,24,32,4,8,MOVE_DECEL,MOVE_X_TOWARDS_PLAYER)
            task._Wait(120)
        end end
    end)
end
function _tmp_sc:del()
end
