_tmp_sc=boss.card.New("形成「生命代码」",5,10,70,1600,{50,50,50},false)
function _tmp_sc:init()
    last=New(_editor_class["tenka_sc_pic"],self.x,self.y,_)
    task.New(self,function()
        do for _=1,_infinite do
            if player.nextspell>0 then
                self.DMG_factor=0.5
            else
                self.DMG_factor=1
            end
            task._Wait(1)
        end end
    end)
    task.New(self,function()
        task.MoveTo(0,144,60,MOVE_DECEL)
        task._Wait(60)
        self.list={}
        do local x,_d_x=(-214.5),(13) local i,_d_i=(1),(1) for _=1,33 do
            self.list[i]={}
            do local y,_d_y=(-240.5),(13) local j,_d_j=(1),(1) for _=1,37 do
                last=New(_editor_class["life_game1"],x,y,ran:Sign(),nil,i,j)
                _connect(self,last,0,true)
                self.list[i][j]=last
            y=y+_d_y j=j+_d_j end end
        x=x+_d_x i=i+_d_i end end
        task._Wait(60)
        do local a,_d_a=(-90-30),(30) for _=1,3 do
            last=New(_editor_class["life_game2"],self.x,self.y,3,a)
        a=a+_d_a end end
        task._Wait(240)
        task.New(self,function()
            task._Wait(300)
            do local a,_d_a=(ran:Float(0,360)),(0.618*180*2) local aa,_d_aa=(ran:Float(0,360)),(-0.618*180*2) for _=1,_infinite do
                PlaySound("tan00",0.1,self.x/256,false)
                do local a1,_d_a1=(a),(180) local aa1,_d_aa1=(aa),(180) for _=1,1 do
                    last=New(_straight,kite,COLOR_BLUE,self.x+18,self.y,1.25,a1,false,0,true,true,0,false,0.0075,'original',0,false)
                    last=New(_straight,kite,COLOR_RED,self.x-18,self.y,1.25,aa1,false,0,true,true,0,false,0.0075,'original',0,false)
                a1=a1+_d_a1 aa1=aa1+_d_aa1 end end
                task._Wait(4)
            a=a+_d_a aa=aa+_d_aa end end
        end)
        do for _=1,800 do
            do local a,_d_a=(Angle(self,player)-45),(45) for _=1,3 do
                last=New(_editor_class["life_game2"],self.x,self.y,4.25,a)
                task._Wait(100)
            a=a+_d_a end end
            task._Wait(60)
            task.MoveToPlayer(60,-96,96,80,112,24,32,4,8,MOVE_DECEL,MOVE_X_TOWARDS_PLAYER)
            task._Wait(60)
        end end
    end)
end
