function _tmp_sc:init()
    task.New(self,function()
        task._Wait(60)
        last=New(_editor_class["wuer_charge_new"],self.x,self.y,_)
        last=New(_editor_class["er_charge_in"],self.x,self.y,255,255,0,'ch02',6)
        task._Wait(60)
        last=New(_editor_class["er_charge_out"],self.x,self.y,255,255,0,'enep02',6)
        last=New(_editor_class["tenka_back"],self.x,self.y,1)
        task.New(self,function()
            task._Wait(60)
            do for _=1,_infinite do
                task.MoveToPlayer(60,-96,96,100,144,24,32,4,8,MOVE_DECEL,MOVE_X_TOWARDS_PLAYER)
                task._Wait(90)
            end end
        end)
        do local a,_d_a=(ran:Float(0,360)),(0.618*180) local t,_d_t=(0),(1) for _=1,_infinite do
            if t%3==0 then
                PlaySound("tan00",0.1,self.x/256,false)
            else
            end
            do local aa,_d_aa=(a),(90) for _=1,1 do
                do local da,_d_da=(-45),(45) for _=1,2 do
                    last=New(_editor_class["wuer_black_bullet2"],self.x,self.y,1.5,aa,da)
                da=da+_d_da end end
            aa=aa+_d_aa end end
            task._Wait(2)
        a=a+_d_a t=t+_d_t end end
    end)
end
