        do local n,_d_n=(1),(1) for _=1,_infinite do
            last=New(_editor_class["wuer_charge_new"],self.x,self.y,_)
            last=New(_editor_class["er_charge_in"],self.x,self.y,255,255,0,'ch02',6)
            boss.cast(self,60)
            task._Wait(60)
            last=New(_editor_class["er_charge_out"],self.x,self.y,255,255,0,'enep02',6)
            if n==1 then
                last=New(_editor_class["performing_m-c"],self.x,self.y,80,90,311)
                last=New(_editor_class["performing_m-c"],self.x,self.y,-80,90,311)
                last=New(_editor_class["performing_m-c"],self.x,self.y,130,50,321)
                last=New(_editor_class["performing_m-c"],self.x,self.y,-130,50,321)
            else
                last=New(_editor_class["performing_m-c"],self.x,self.y,80,90,316+ran:Sign()*5)
                last=New(_editor_class["performing_m-c"],self.x,self.y,-80,90,316+ran:Sign()*5)
                last=New(_editor_class["performing_m-c"],self.x,self.y,130,50,316+ran:Sign()*5)
                last=New(_editor_class["performing_m-c"],self.x,self.y,-130,50,316+ran:Sign()*5)
            end
            task.New(self,function()
                task._Wait(60)
                do for _=1,6 do
                    PlaySound("kira00",0.1,self.x/256,false)
                    do local a,_d_a=(ran:Float(0,360)),(12) for _=1,30 do
                        last=New(_straight,ball_mid,COLOR_ORANGE,self.x,self.y,1,a,false,0,true,true,0,false,0.0125,a,0,false)
                        _object.set_color(last,"mul+add",255,255,255,255)
                    a=a+_d_a end end
                    task._Wait(90)
                end end
            end)
            task._Wait(600)
            last=New(_editor_class["wuer_charge_new"],self.x,self.y,_)
            last=New(_editor_class["er_charge_in"],self.x,self.y,255,255,0,'ch02',6)
            task._Wait(60)
            last=New(_editor_class["er_charge_out_big"],self.x,self.y,255,255,0,'kira00',nil)
            for _,unit in ObjList(GROUP_ENEMY) do
                if unit~=_boss then
                    unit.flag=true
                else
                end
            end
            task._Wait(270)
            last=New(_editor_class["er_charge_in"],self.x,self.y,255,255,0,'power02',6)
            task._Wait(30)
            for _,unit in ObjList(GROUP_INDES) do
                if unit~=_boss then
                    unit.flag=true
                else
                end
            end
            task._Wait(30)
            last=New(_editor_class["wuer_charge_new"],self.x,self.y,_)
            task._Wait(270)
            task._Wait(0)
        n=n+_d_n end end
    end)
end
