_tmp_sc=boss.card.New("",5,10,50,1000,{0,0,0},false)
function _tmp_sc:init()
    task.New(self,function()
        local a=0
        local i=1
        local edge=200
        local rp,rs,re=edge*(3^0.5+15^0.5)/4,edge*(250+110*5^0.5)^0.5/20,edge*(5^0.5+3)/4
        local _rp=(0.5*edge)/sin(36)
        local _re=cos(36)*_rp
        local d2=100/tan(18)
        task._Wait(90)
        last=New(_editor_class["er_charge_in"],self.x,self.y,0,0,255,'ch02',1)
        task._Wait(30)
        last=New(_editor_class["er_charge_in"],self.x,self.y,255,0,0,'ch02',1)
        task._Wait(60)
        last=New(_editor_class["tenka_back"],self.x,self.y,1)
        do for _=1,100 do
            local xx,yy=ran:Float(1,40)*i,180
            local z0,x0=ran:Float(-30,30),ran:Float(-30,30)
            PlaySound("boon01",0.1,self.x/256,false)
            do local d,_d_d=(edge/2),(-edge/7) for _=1,8 do
                a=atan(d/_re)
                do local aa,_d_aa=(a),(72) for _=1,5 do
                    last=New(_editor_class["touyingB"],xx,yy,(d*d+_re*_re)^0.5,rs,aa,z0,x0,ball_mid,4+i*2)
                aa=aa+_d_aa end end
            d=d+_d_d end end
            do local r,_d_r=(_rp),((rp-_rp)/7) local y,_d_y=(rs),(-0.7*rs/7) for _=1,7 do
                do local aa,_d_aa=(atan((edge/2)/_re)),(72) for _=1,5 do
                    last=New(_editor_class["touyingB"],xx,yy,r,y,aa,z0,x0,ball_mid,4+2*i)
                aa=aa+_d_aa end end
            r=r+_d_r y=y+_d_y end end
            do local d,_d_d=(85),(-170/7) local y,_d_y=(rs*0.3),(-0.3*rs/3.5) local da,_d_da=(atan((edge/2)/_re)),(36/7) for _=1,8 do
                a=atan(d/re)+18
                do local aa,_d_aa=(a),(72) for _=1,5 do
                    last=New(_editor_class["touyingB"],xx,yy,(d*d+re*re)^0.5,y,aa,z0,x0,ball_mid,4+2*i)
                aa=aa+_d_aa end end
            d=d+_d_d y=y+_d_y da=da+_d_da end end
            do local d,_d_d=(85),(-170/7) local y,_d_y=(-rs*0.3),(0.3*rs/3.5) local da,_d_da=(atan((edge/2)/_re)),(36/7) for _=1,8 do
                a=atan(d/re)+18+36
                do local aa,_d_aa=(a),(72) for _=1,5 do
                    last=New(_editor_class["touyingB"],xx,yy,(d*d+re*re)^0.5,y,aa,z0,x0,ball_mid,4+2*i)
                aa=aa+_d_aa end end
            d=d+_d_d y=y+_d_y da=da+_d_da end end
            do local r,_d_r=(_rp),((rp-_rp)/7) local y,_d_y=(-rs),(0.7*rs/7) for _=1,7 do
                do local aa,_d_aa=(atan((edge/2)/_re)+36),(72) for _=1,5 do
                    last=New(_editor_class["touyingB"],xx,yy,r,y,aa,z0,x0,ball_mid,4+2*i)
                aa=aa+_d_aa end end
            r=r+_d_r y=y+_d_y end end
            do local d,_d_d=(edge/2),(-edge/7) for _=1,8 do
                a=atan(d/_re)
                do local aa,_d_aa=(a+36),(72) for _=1,5 do
                    last=New(_editor_class["touyingB"],xx,yy,(d*d+_re*_re)^0.5,-rs,aa,z0,x0,ball_mid,4+i*2)
                aa=aa+_d_aa end end
            d=d+_d_d end end
            i=-i
            --a=atan(d/d2)+atan((edge/2)/_re)+18
            task._Wait(300)
        end end
    end)
end
function _tmp_sc:del()
end
