            boss.dialog.sentence(self,"image:wuer_marisa_dialog1","left","是我赢啦",360)
            boss.dialog.sentence(self,"image:tenka_dialog_2","right","哎呀，现在的人类也有那么强的实力吗",360,1,1)
            boss.dialog.sentence(self,"image:wuer_marisa_dialog2","left","这当然，每天都会修行的！",360)
            boss.dialog.sentence(self,"image:tenka_sc_pic","right","有没有什么秘诀，能教教我吗？",360,1,1)
            boss.dialog.sentence(self,"image:wuer_marisa_dialog5","left","多跟大家玩玩弹幕游戏就可以啦",360)
            boss.dialog.sentence(self,"image:tenka_dialog_1","right","那我们再来一场吧？",360,1,1)
            boss.dialog.sentence(self,"image:otohime_dialog","right","这次我可不来了",360,1,1)
            boss.dialog.sentence(self,"image:wuer_marisa_dialog4","left","饶了我吧，刚刚在迷宫走就已经很累了",360)
        else
        end
        if player.class==sanae_player then
            boss.dialog.sentence(self,"image:wuer_sanae_dialog2","left","是我赢了",360)
            boss.dialog.sentence(self,"image:tenka_dialog_2","right","哎呀，真是不甘心啊",360,1,1)
            boss.dialog.sentence(self,"image:tenka_dialog_2","right","偏偏输给这个",360,1,1)
            boss.dialog.sentence(self,"image:otohime_dialog","right","缺德宗教家",360,1,1)
            boss.dialog.sentence(self,"image:tenka_dialog_2","right","嗯",360,1,1)
            boss.dialog.sentence(self,"image:wuer_sanae_dialog2","left","在这个幻想乡可不能用常识看待呢",360)
            boss.dialog.sentence(self,"image:wuer_sanae_dialog2","left","诶不对，我要说的是，不要跟我们守矢一家抢信仰了",360)
            boss.dialog.sentence(self,"image:tenka_dialog_2","right","哎呀呀，我们可没说过这些啊，还是赶紧走吧",360,1,1)
            boss.dialog.sentence(self,"image:otohime_dialog","right","再见",360,1,1)
        else
        end
        if player.class==wuer_player then
            boss.dialog.sentence(self,"image:wuer_wuer_dialog3","left","嗯......是我赢了呢，那我可以离开了吗",360)
            boss.dialog.sentence(self,"image:tenka_dialog_2","right","啊，就那么不想分享一下你的旅行见闻吗，旅人？",360,1,1)
            boss.dialog.sentence(self,"image:wuer_wuer_dialog3","left","那么来交换条件吧",360)
            boss.dialog.sentence(self,"image:wuer_wuer_dialog1","left","让你的同伴开一条通往其他世界的路",360)
            boss.dialog.sentence(self,"image:wuer_wuer_dialog4","left","然后你做一个土锅给我吧，黑的用腻了",360)
            boss.dialog.sentence(self,"image:tenka_dialog_1","right","哎呀，这个简单，不过要一会儿时间呢，我们先去好好聊聊吧",360,1,1)
            boss.dialog.sentence(self,"image:otohime_dialog","right","真是麻烦啊，这两个人",360,1,1)
        else
        end
    end)
end
