_editor_class["yahoon-扭曲弹"].init=function(self,_x,_y,v,r,r2,v2,i,co)
    bullet.init(self,water_drop,co,true,true)
    self.x,self.y=_x,_y
    self.co=co
    self.i=0
    task.New(self,function()
        task._Wait(60)
        do local i,_d_i=(0),(1/29) for _=1,30 do
            self.i=i
            task._Wait(1)
        i=i+_d_i end end
        self.i=1
    end)
    task.New(self,function()
        do local i,_d_i=(0),(v2*i) for _=1,_infinite do
            self.x=v*cos(r+r2*sin(i))+self.x
            self.y=v*sin(r+r2*sin(i))+self.y
            self.navi=true
            task._Wait(1)
        i=i+_d_i end end
    end)
end
_editor_class["yahoon-扭曲弹"].render=function(self)
    ChangeBulletImage(self,water_drop_dark,self.co)
    _object.set_color(self,"",255*(self.i),255,255,255)
    self.class.base.render(self)
    ChangeBulletImage(self,water_drop,self.co)
    _object.set_color(self,"mul+add",255*(1-self.i),255,255,255)
    self.class.base.render(self)
end
