_editor_class["自机狙(红):Normal"]=Class(enemy)
_editor_class["自机狙(红):Normal"].init=function(self,_x,_y,x)
    enemy.init(self,23,5,false,true,false)
    self.x,self.y=_x,_y
    self.drop={5,0,0}
    task.New(self,function() self.protect=true task.Wait(52) self.protect=false end)
    task.New(self,function()
        task._Wait(50)
        do for _=1,1 do
            task.New(self,function()
                do local v,_d_v=(4),(-0.35) for _=1,20/4 do
                    do local rr,_d_rr=(0),(30) for _=1,1 do
                        last=New(_straight,ball_mid,COLOR_RED,self.x,self.y,v,rr,true,0,true,true,0,false,0,0,0,false)
                        task._Wait(0)
                    rr=rr+_d_rr end end
                    PlaySound("tan00",0.1,self.x/256,false)
                    task._Wait(4)
                v=v+_d_v end end
            end)
            task._Wait(24)
        end end
    end)
    task.New(self,function()
        task.BezierMoveTo(180,MOVE_NORMAL,0,0,-x/3,0,0,50,x,50)
        _del(self,true)
    end)
end
