        task.MoveTo(self.x,self.y-100,120,MOVE_DECEL)
        task._Wait(240)
        task.MoveTo(self.x,self.y+100,240,MOVE_ACCEL)
        _del(self,true)
    end)
    task.New(self,function()
        self.flag=0
        do for _=1,_infinite do
            if self.flag==5 then break end
            task._Wait(1)
        end end
        _kill(self,true)
    end)
end
_editor_class["落耶弹子机:Lunatic"]=Class(enemy)
_editor_class["落耶弹子机:Lunatic"].init=function(self,_x,_y,r,i,master)
    enemy.init(self,26,5,false,false,false)
    self.x,self.y=_x,_y
    self.drop={2,2,2}
    task.New(self,function() self.protect=true task.Wait(60) self.protect=false end)
    self.i=i
    self.master=master
    self.ii=r
    task.New(self,function()
        R=50
        do local I,_d_I=(0),(90/19) for _=1,20 do
            self.x=master.x+R*sin(I)*cos(self.ii) self.y=master.y+R*sin(I)*sin(self.ii)
            self.ii=5*self.i*sin(I)+self.ii
            task._Wait(1)
        I=I+_d_I end end
        do local I,_d_I=(90),(0) local ii,_d_ii=(self.ii),(5*self.i) for _=1,120+240+240-20 do
            self.x=master.x+R*sin(I)*cos(ii) self.y=master.y+R*sin(I)*sin(ii)
            task._Wait(1)
        I=I+_d_I ii=ii+_d_ii end end
        _del(self,true)
    end)
    task.New(self,function()
        do for _=1,20/4 do
            PlaySound("tan01",0.1,self.x/256,false)
            last=New(_straight,grain_a,COLOR_DEEP_PURPLE,self.x,self.y,2,self.ii,false,0,true,true,0,false,0.02,self.ii,0,false)
            task._Wait(4)
        end end
        do local aa,_d_aa=(r+5*self.i*20),(5*self.i) for _=1,(30*5-20)/4 do
            PlaySound("tan01",0.1,self.x/256,false)
            last=New(_straight,grain_a,COLOR_DEEP_PURPLE,self.x,self.y,2,aa,false,0,true,true,0,false,0.02,aa,0,false)
            task._Wait(4)
        aa=aa+_d_aa end end
    end)
end
