            self.r1=0 self.r2=0
            self.mode=sin(90)
            self.angle=360
            self.alpha=255
        end,
        function(self)
        task.Do(self)
            if IsValid(_boss) then
                _boss.fxr=238 _boss.fxg=118 _boss.fxb=50
            else
            end
            --self.angle=self.angle+self.mode
            self.r1=self.timer
            if self.timer>360 then
            	self.r2=self.timer-360
