            					     {self.r2*cos(angle-da)+self.x,self.r2*sin(angle-da)+self.y,0.5,h+4,v,Color(al,255,255,255)},
            					     {self.r2*cos(angle)+self.x,self.r2*sin(angle)+self.y,    0.5,h,  v,Color(al,255,255,255)})
            	angle=angle-da
            	h=h+4
            end
            end
        end
    )
    _spellcard_background.AddLayer(self,"img_void",false,0,112,0,0,0,0,"",1,1,
        function(self)
        self.task={}
            self.timer=1080
            self.r1=0 self.r2=0
            self.mode=sin(90)
            self.angle=360
            self.alpha=255
        end,
        function(self)
        task.Do(self)
            --self.angle=self.angle+self.mode
            self.r1=self.timer
            if self.timer>360 then
            	self.r2=self.timer-360
            end
            --if self.r2>780 then Del(self) end
            if self.timer>=360*4 then self.timer=0 self.r1=0 self.r2=0 end
        end,
        function(self)
            SetViewMode"world"
            local angle=self.angle
            local h=0
            local v=min(512,512*self.r1/360)
            local da=360/128
            local al=self.alpha*_boss.bg.alpha
            if self.timer<800 then
            for i=1,128 do
            	RenderTexture('texture:A',"",{self.r1*cos(angle)+self.x,self.r1*sin(angle)+self.y,    0.5,h,  0,Color(al,255,255,255)},
            					     {self.r1*cos(angle-da)+self.x,self.r1*sin(angle-da)+self.y,0.5,h+4,0,Color(al,255,255,255)},
            					     {self.r2*cos(angle-da)+self.x,self.r2*sin(angle-da)+self.y,0.5,h+4,v,Color(al,255,255,255)},
            					     {self.r2*cos(angle)+self.x,self.r2*sin(angle)+self.y,    0.5,h,  v,Color(al,255,255,255)})
            	angle=angle-da
            	h=h+4
            end
            end
        end
    )
end
