	self.maxhp=10
	self.colli=false
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    _object.set_color(self,"",0,0,0,0)
    self.flag=-1
    if sty>20 then
        self.img="image:yahoon-name3"
        self.rot=0
        task.New(self,function()
            task.New(self,function()
                do for _=1,_infinite do
                    self.rot=self.rot+1
                    task._Wait(1)
                end end
            end)
            task.New(self,function()
                do local i,_d_i=(1),(-(1/2)/19) for _=1,20 do
                    self.hscale=i self.vscale=i
                    task._Wait(1)
                i=i+_d_i end end
            end)
            do local i,_d_i=(0),(1/9) for _=1,10 do
                if self.flag==-2 then break end
                _object.set_color(self,"",255*i,255*i,255*i,255*i)
                task._Wait(1)
            i=i+_d_i end end
            do for _=1,240 do
                if self.flag==-2 then break end
                task._Wait(1)
            end end
            do local i,_d_i=(1),(-1/29) for _=1,30 do
                if self.flag==-2 then break end
                _object.set_color(self,"",255*i,255*i,255*i,255*i)
                task._Wait(1)
            i=i+_d_i end end
            _del(self,true)
        end)
    else
        if sty>10 then
            self.img="image:yahoon-name2"..(sty-10)
        else
            self.img="image:yahoon-name1"..sty
        end
        self.rot=5*ran:Int(-1,1)+r/2
        task.New(self,function()
            task.New(self,function()
                do local i,_d_i=(0.5*2),(-(0.5)/19) for _=1,20 do
                    self.hscale=i self.vscale=i
                    task._Wait(1)
                i=i+_d_i end end
            end)
            do local i,_d_i=(0),(1/9) for _=1,10 do
                if self.flag==-2 then break end
                _object.set_color(self,"",255*i,255*i,255*i,255*i)
                task._Wait(1)
            i=i+_d_i end end
            do for _=1,240 do
                if self.flag==-2 then break end
                task._Wait(1)
            end end
            do local i,_d_i=(1),(-1/29) for _=1,30 do
                if self.flag==-2 then break end
                _object.set_color(self,"",255*i,255*i,255*i,255*i)
                task._Wait(1)
            i=i+_d_i end end
            _del(self,true)
        end)
    end
end
