_editor_class["yahoon-words"]=Class(_object)
_editor_class["yahoon-words"].init=function(self,_x,_y,words,style,l,rot,class,flag)
    self.x,self.y=_x,_y
	self.img="image:balloon_a2"
	self.layer=LAYER_TOP+2
	self.group=GROUP_GHOST
	self.hide=false
	self.bound=false
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=false
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    self.style=style
    if class=='boss' then
        self.vscale=1/2*rot self.hscale=-1/2
    else
        if class=='player' then
            self.vscale=1/2*rot self.hscale=1/2
        else
            self.hscale=nil
        end
    end
    self.flag=flag
    self.l=l
    self.text={}
    self.text[1]=words
    if style<20 then
        self.img="image:balloon_a"..style*2
    else
    end
    if style>20 then
        self.img="image:balloon_a_"..(style-20)*2+20
    else
    end
    if class=='boss' then
        task.New(self,function()
            last=New(_editor_class["yahoon-words2"],self.x-81/2-l*30/2,self.y,style,rot,class,flag)
            if l>0 then
                do local ll,_d_ll=(0),(30/2) for _=1,l do
                    last=New(_editor_class["yahoon-words3"],self.x-ll-55/2,self.y,style,rot,class,flag)
                    task._Wait(0)
                ll=ll+_d_ll end end
            else
            end
        end)
    else
        task.New(self,function()
            last=New(_editor_class["yahoon-words2"],self.x+81/2+l*30/2,self.y,style,rot,class,flag)
            if l>0 then
                do local ll,_d_ll=(0),(30/2) for _=1,l do
                    last=New(_editor_class["yahoon-words3"],self.x+ll+55/2,self.y,style,rot,class,flag)
                    task._Wait(0)
                ll=ll+_d_ll end end
            else
            end
        end)
    end
    task.New(self,function()
        do local i,_d_i=(0),((1/2)/4) for _=1,5 do
            self.vscale=i*rot
            task._Wait(1)
        i=i+_d_i end end
    end)
end
_editor_class["yahoon-words"].render=function(self)
    SetViewMode('ui')
    self.class.base.render(self)
    if self.hscale>0 then
        if self.vscale>0 then
            if self.style>10 then
                RenderTTF('dialog',self.text[1],self.x-5,self.x+60/2+self.l*30/2,self.y-15,self.y+15,Color(255,0,0,0),'paragraph')

            else
                RenderTTF('dialog',self.text[1],self.x-5,self.x+60/2+self.l*30/2,self.y-10,self.y+10,Color(255,0,0,0),'paragraph')

            end
        else
            if self.style>10 then
                RenderTTF('dialog',self.text[1],self.x-5,self.x+60/2+self.l*30/2,self.y-10,self.y+20,Color(255,0,0,0),'paragraph')

            else
                RenderTTF('dialog',self.text[1],self.x-5,self.x+60/2+self.l*30/2,self.y,self.y+10,Color(255,0,0,0),'paragraph')

            end
        end
    else
        if self.vscale>0 then
            if self.style>10 then
                RenderTTF('dialog',self.text[1],self.x-60/2-self.l*30/2,self.x+5,self.y-15,self.y+15,Color(255,0,0,0),'paragraph')

            else
                RenderTTF('dialog',self.text[1],self.x-60/2-self.l*30/2,self.x+5,self.y-10,self.y+10,Color(255,0,0,0),'paragraph')

            end
        else
            if self.style>10 then
                RenderTTF('dialog',self.text[1],self.x-60/2-self.l*30/2,self.x+5,self.y-10,self.y+20,Color(255,0,0,0),'paragraph')

            else
                RenderTTF('dialog',self.text[1],self.x-60/2-self.l*30/2,self.x+5,self.y,self.y+10,Color(255,0,0,0),'paragraph')

            end
        end
    end
    SetViewMode('world')
end
