            end
            if self.sty=='wuer3' then
                self.img="image:无耳3"
            else
            end
            if self.sty=='wuer4' then
                self.img="image:无耳4"
            else
            end
            task._Wait(1)
        end end
    end)
    task.New(self,function()
        self.X=self.x self.Y=self.y
        self.X2=self.X+30*cos(r)
        self.Y2=self.Y+10
        self.i=0
        self.v=2
        do local i,_d_i=(0),(255/29) for _=1,30 do
            if self.mode=='down' then
                _object.set_color(self,"",i,100,100,100)
                self.color=100
            else
            end
            if self.mode=='up' then
                _object.set_color(self,"",i,255,255,255)
                self.color=255
                if self.i<1 then
                    self.i=self.i+self.v/14
                    self.v=self.v-2/14
                else
                    self.i=1
                    self.time=0
                    self.v=2
                end
            else
            end
            self.x=self.X2*(self.i)+self.X*(1-self.i)
            self.y=self.Y2*(self.i)+self.Y*(1-self.i)
            task._Wait(1)
        i=i+_d_i end end
        task.New(self,function()
            self.time=0
            self.moveup=true
            self.movedown=true
            do for _=1,_infinite do
                if self.mode=='down' and self.color>100 then
                    if KeyIsDown('spell') then
                        self.color=100
                    else
                    end
                    _object.set_color(self,"",255,self.color,self.color,self.color)
                    self.color=self.color-155/29
                    if self.mdown then
                        self.v=2
                        self.mdown=false
                    else
                    end
                    if self.time>15 then
                        if self.i>0 then
                            self.i=self.i-self.v/14
                            self.v=self.v-2/14
                        else
                            self.i=0
                            self.time=0
                            self.v=2
                        end
                        self.mup=true
                    else
                        self.time=self.time+1
                    end
                else
                end
                if self.mode=='up' and self.color<255 then
                    self.time=0
                    if KeyIsDown('spell') then
                        self.color=255
                    else
                    end
                    _object.set_color(self,"",255,self.color,self.color,self.color)
                    self.color=self.color+155/29
                    if self.mup then
                        self.v=2
                        self.mup=false
                    else
                    end
                    if self.i<1 then
                        self.i=self.i+self.v/14
                        self.v=self.v-2/14
                    else
                        self.i=1
                        self.time=0
                        self.v=2
                    end
                    self.mdown=true
                else
                end
                self.x=self.X2*(self.i)+self.X*(1-self.i)
                self.y=self.Y2*(self.i)+self.Y*(1-self.i)
                task._Wait(1)
            end end
        end)
        do for _=1,_infinite do
            if master.flag==10  then break end
            task._Wait(1)
        end end
        do local v,_d_v=(0),(90/29) local i,_d_i=(255),(-255/29) for _=1,30 do
            if self.mode=='down' then
                _object.set_color(self,"",i,100,100,100)
                self.color=100
            else
            end
            if self.mode=='up' then
                _object.set_color(self,"",i,255,255,255)
                self.color=255
                if self.i>0 then
                    self.i=self.i-1/14
                    self.v=self.v-2/14
                else
                    self.i=0
                    self.time=0
                    self.v=2
                end
            else
            end
            self.x=self.X2*(self.i)+self.X*(1-self.i)
            self.y=self.Y2*(self.i)+self.Y*(1-self.i)
            task._Wait(1)
        v=v+_d_v i=i+_d_i end end
        _del(self,false)
    end)
end
