_editor_class["yahoon-ice:Lunatic"]=Class(bullet)
_editor_class["yahoon-ice:Lunatic"].init=function(self,_x,_y,r,r0,i,co)
    bullet.init(self,ball_mid_c,co,true,false)
    self.x,self.y=_x,_y
    self.r0=r0
    self.i=i
    PlaySound("nice",0.7,self.x/256,true)
    self.X=self.x self.Y=self.y self.r=r
    task.New(self,function()
        self.n=2
        self.d00=50
        self.dv=150
        self.dl=0
        self.rv=30
        do for _=1,50 do
            self.n=self.n+1
            self.ro=360/self.n self.ri=180/self.n
            self.d0=self.d00*sin(self.ri/2)
            self.r1=self.r%self.ro
            self.d=self.d0/cos(self.ro/2-self.r1)
            self.r00=self.r0
            do local i,_d_i=(0),(1/59) for _=1,60 do
                self.x=self.X+((self.d-self.dl)*sin(i*90)+self.dl)*cos(self.r+self.r0) self.y=self.Y+((self.d-self.dl)*sin(i*90)+self.dl)*sin(self.r+self.r0)
                self.r0=self.r00+self.rv*sin(i*90)*self.i
                task._Wait(1)
            i=i+_d_i end end
            if self.r1<360/60 then
                PlaySound("ice",0.4,self.x/256,true)
                do local r,_d_r=(ran:Float(0,360)),(360/self.n) for _=1,self.n do
                    last=New(_straight,grain_b,co,self.x+5*cos(r),self.y+5*sin(r),0,r,false,0,true,true,5,false,0.02,r,2,false)
                    task._Wait(0)
                r=r+_d_r end end
            else
            end
            self.dl=self.d
            self.d00=self.d00+self.dv
            self.dv=self.dv+150
            self.rv=self.rv/2
            task._Wait(30)
        end end
    end)
end
