            last=New(_editor_class["yahoon-particle2"],self.x,self.y,_)
            _connect(self,last,0,true)
        end)
        task.New(self,function()
            PlaySound("ch00",0.1,self.x/256,false)
            do local r,_d_r=(0),(360/5) for _=1,5 do
                do local i,_d_i=(-2),(4) for _=1,2 do
                    last=New(_editor_class["yahoon-particle3"],self.x,self.y,r,i,0,112)
                    task._Wait(0)
                i=i+_d_i end end
                task._Wait(0)
            r=r+_d_r end end
            task._Wait(60)
            task.MoveTo(0,112,1,MOVE_NORMAL)
        end)
        self.flag=1
        if player.name=='Reimu' then
            last=New(_editor_class["yahoon-talkface"],80-20,150,self,0,20,'down','reimu1')
        else
        end
        if player.name=='Marisa' then
