        else
        end
        if player.name=='Sanae' then
            last=New(_editor_class["yahoon-talkface"],80-20,150,self,0,20,'down','sanae1')
        else
        end
        if player.name=='Wuer' then
            last=New(_editor_class["yahoon-talkface"],80-20,150,self,0,20,'down','wuer1')
        else
        end
        task._Wait(60+15)
        last=New(_editor_class["yahoon-talkface"],400+40,150,self,180,10,'up','biiru4')
        task._Wait(30-15)
        last=New(_editor_class["yahoon-words"],330,300,'哦呀，新面孔',1,4,-1,'boss',1)
        task._Wait(120-30)
        for _,unit in ObjList(GROUP_GHOST) do
            if unit.flag==1 then
                _del(unit,false)
            else
            end
        end
        last=New(_editor_class["yahoon-words"],350,300,'欢迎来到下酒菜至上主义的酒场！',1,13,-1,'boss',1)
        last=New(_editor_class["yahoon-words-special2"],210,302,'实  力',1)
        task._Wait(120-30)
        for _,unit in ObjList(GROUP_GHOST) do
            if unit.flag==1 then
                _del(unit,false)
            else
            end
            if unit.flag==10 then
                unit.sty='biiru2'
            else
            end
        end
        last=New(_editor_class["yahoon-words"],330,300,'还不太熟悉这里的规矩吗？',21,5,-1,'boss',1)
        task._Wait(120-30)
        for _,unit in ObjList(GROUP_GHOST) do
            if unit.flag==1 then
                _del(unit,false)
            else
            end
        end
        last=New(_editor_class["yahoon-words"],330,300,'你只需要注意一件事哦',1,8,-1,'boss',1)
        task._Wait(120-30)
        for _,unit in ObjList(GROUP_GHOST) do
            if unit.flag==1 then
                _del(unit,false)
            else
            end
        end
        last=New(_editor_class["yahoon-words"],330,300,'在这个旧约酒场',1,5,-1,'boss',1)
        task._Wait(120-30)
        for _,unit in ObjList(GROUP_GHOST) do
            if unit.flag==1 then
                _del(unit,false)
            else
            end
        end
        last=New(_editor_class["yahoon-words"],330,300,'无论是谁来到这里，',1,7,-1,'boss',2)
        task.New(self,function()
            task._Wait(30)
            for _,unit in ObjList(GROUP_GHOST) do
                if unit.flag==2 then
                    _del(unit,false)
                else
                end
                if unit.flag==10 then
                    unit.sty='biiru4'
                else
                end
            end
            last=New(_editor_class["yahoon-words"],330,300,'无论是谁来到这里，都只能',21,7,-1,'boss',2)
            task._Wait(30)
            task._Wait(60*(1+23/100-88/100))
            last=New(_editor_class["yahoon-words-special"],280-20,290,'一',2)
            task._Wait(60*(1+23/100-88/100))
            last=New(_editor_class["yahoon-words-special"],295-20,290,'醉',2)
            task._Wait(60*(1+23/100-88/100))
            last=New(_editor_class["yahoon-words-special"],310-20,290,'方',2)
            task._Wait(60*(1+23/100-88/100))
            last=New(_editor_class["yahoon-words-special"],325-20,290,'休',2)
        end)
        task._Wait(120-30)
        boss.cast(self,60)
        task._Wait(60)
        for _,unit in ObjList(GROUP_GHOST) do
            if unit.flag==2 then
                _del(unit,false)
            else
            end
        end
        self.flag=10
    end)
end
