            _connect(self,last,0,true)
            last=New(_editor_class["yahoon-particle2"],self.x,self.y,_)
            _connect(self,last,0,true)
        end)
        self.I=1
        do local a,_d_a=(0),(33) local R,_d_R=(50),(0) for _=1,_infinite do
            do local r,_d_r=(a),(360/10) for _=1,10 do
                if R>100 then
                    last=New(_editor_class["yahoon-beer2:Lunatic"],self.x,self.y,r,self.I,125,3)
                    _connect(self,last,0,true)
                else
                    last=New(_editor_class["yahoon-beer2:Lunatic"],self.x,self.y,r,self.I,R,3)
                    _connect(self,last,0,true)
                end
                task._Wait(0)
            r=r+_d_r end end
            task._Wait((22.22-19.26)*60-80)
            do local i,_d_i=(Angle(self,player)-360/16),(360/8) for _=1,8 do
                last=New(_editor_class["yahoon-lightshoot"],self.x,self.y,4,i,0)
                task._Wait(0)
            i=i+_d_i end end
            task._Wait(80-7)
            self.I=-self.I
            task._Wait(0)
        a=a+_d_a R=R+_d_R end end
    end)
end
