                self.bg.alpha=0.25
                task._Wait(1)
            end end
        end)
        _boss.ui.name='???'
        self.I=1
        task.MoveTo(0,112,180,MOVE_NORMAL)
        task.New(self,function()
            task._Wait(180)
            do for _=1,_infinite do
                New(boss_cast_ef,self.x,self.y)
                task._Wait(60)
                do local r,_d_r=(ran:Float(0,360)),(36) for _=1,20 do
                    PlaySound("tan02",0.35,self.x/256,true)
                    last=New(_editor_class["yahoon-Humulus lupulus"],self.x,self.y,ran:Float(1,3),r,Angle(self,player))
                    task._Wait(5)
                r=r+_d_r end end
                task._Wait(60)
            end end
        end)
        task.New(self,function()
            do local RRR,_d_RRR=(0),(10*5) for _=1,_infinite do
                do local RR,_d_RR=(1),(-2) for _=1,2 do
                    do local r,_d_r=(RR*RRR),(RR) local v,_d_v=(90),(-30/4) for _=1,5 do
                        PlaySound("tan00",0.2,self.x/256,false)
                        do local rr,_d_rr=(0),(120) for _=1,3 do
                            do local rrr,_d_rrr=(-90),(180) for _=1,2 do
                                last=New(_straight,grain_a,COLOR_ORANGE,self.x+50*cos(r+rr),self.y+50*sin(r+rr),3*sin(v),r+rr+rrr+ran:Float(-0.1,0.1),false,0,true,true,0,false,0,0,0,false)
                                last.navi=true
                                task._Wait(0)
                            rrr=rrr+_d_rrr end end
                            task._Wait(0)
                        rr=rr+_d_rr end end
                        task._Wait(1)
                    r=r+_d_r v=v+_d_v end end
                    task._Wait(0)
                RR=RR+_d_RR end end
                task._Wait(3)
            RRR=RRR+_d_RRR end end
        end)
    end)
