            _connect(self,last,0,true)
        end)
        task.MoveTo(0,144,180,MOVE_NORMAL)
        self.achievement1=0
        task.New(self,function()
            do for _=1,_infinite do
                if player.drunk then
                    PlaySound("hyz_gosp",1,self.x/256,true)
                    player.X=player.x player.Y=player.y
                    do local r,_d_r=(0),(30) local i,_d_i=(0),(7.346) local R,_d_R=(5),(-5/60) for _=1,60 do
                        player.x=player.X+R*sin(r)*cos(i) player.y=player.Y+R*sin(r)*sin(i)
                        task._Wait(1)
                    r=r+_d_r i=i+_d_i R=R+_d_R end end
                    self.achievement1=self.achievement1+1
                    player.drunk=false
                else
                end
                task._Wait(1)
            end end
        end)
        boss.cast(self,45)
        New(boss_cast_ef,self.x,self.y)
        task._Wait(45)
        task.New(self,function()
            task._Wait(30)
            do local i,_d_i=(0),(45.255) for _=1,1000 do
                do local r,_d_r=(0),(360/240) for _=1,240 do
                    last=New(_straight,ball_small,COLOR_ORANGE,self.x,self.y,sin(r*12)/5+1,i+r,false,0,true,true,0,false,0,0,0,false)
                    task._Wait(0)
                r=r+_d_r end end
                self.i=1
                do for _=1,2 do
                    PlaySound("tan00",0.1,self.x/256,false)
                    do local r,_d_r=(0),(360/12) for _=1,12 do
                        last=New(_straight,ball_big,COLOR_ORANGE,self.x,self.y,2,i+r,false,0,true,true,0,false,0.01,i+r+90*i,0,false)
                        task._Wait(0)
                    r=r+_d_r end end
                    self.i=-self.i
                    task._Wait(60)
                end end
                task._Wait(0)
            i=i+_d_i end end
        end)
        do for _=1,_infinite do
            do for _=1,1 do
                self.t=2.5
                PlaySound("old_kira00",0.1,self.x/256,false)
                do local r,_d_r=(180),(-150/9) for _=1,10 do
