function _tmp_sc:del()
    for _,unit in ObjList(GROUP_GHOST) do
        if unit.flag==1 then
            _del(unit,true)
        else
        end
    end
    if (not ext.replay.IsReplay()) and self.achievement1>=20 and lstg.var.sc_bonus>0 then
        New(achievement_obj,1,34)
        --[[ 成就【饮酒需待二十岁】完成！！ --]]
    else
    end
