_editor_class["ed-open:Lunatic"]=Class(_object)
_editor_class["ed-open:Lunatic"].init=function(self,_x,_y,_)
    self.x,self.y=_x,_y
	self.img="img_void"
	self.layer=LAYER_TOP
	self.group=GROUP_GHOST
	self.hide=false
	self.bound=false
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=false
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    task.New(self,function()
        do for _=1,1 do
            self.wx,self.wy = 320,240
            self.wa,self.wb,self.wc,self.wd =0,640,0,480
            self.wbx,self.wby =340,270
            local w = lstg.world
            
            w.l,w.r,w.b,w.t=-self.wx,self.wx,-self.wy,self.wy
            w.scrl,w.scrr,w.scrb,w.scrt=self.wa,self.wb,self.wc,self.wd
            w.pl,w.pr,w.pb,w.pt=-self.wx,self.wx,-self.wy,self.wy
            w.boundl,w.boundr,w.boundb,w.boundt=-self.wbx,self.wbx,-self.wby,self.wby
            
            SetBound(w.boundl,w.boundr,w.boundb,w.boundt)
            task._Wait(1)
        end end
    end)
    task.New(self,function()
        task._Wait(60*5*2)
        lstg.var.bgfly=true
        task._Wait(60*26-60*8)
        task.New(self,function()
            self.alphaa=5
            do for _=1,_infinite do
                last=New(_editor_class["ed-light"],0,240+50,1,self.alphaa)
                task._Wait(240-(self.alphaa/50)*140)
                if self.alphaa<50 then
                    self.alphaa=self.alphaa+5
                else
                    self.alphaa=50
                end
                task._Wait(0)
            end end
        end)
        task._Wait(60)
