_editor_class["ed-light"]=Class(_object)
_editor_class["ed-light"].init=function(self,_x,_y,mode,alpha)
    self.x,self.y=_x,_y
	self.img="leaf"
	self.layer=LAYER_TOP+110
	self.group=GROUP_GHOST
	self.hide=false
	self.bound=false
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    self.r1=0
    self.r2=0
    self.mode=mode
    self.angle=360
    self.alphaa=alpha
    self.alpha=alpha
    task.New(self,function()
        do for _=1,_infinite do
            self.r1=self.r1+1*2
            if self.r1>240 then
            	self.r2=self.r2+1*2
                          self.alpha=self.alpha-0.15*(self.alphaa/50)
            end
            if self.r2>480+120 then Del(self) end
            task._Wait(1)
        end end
    end)
end
_editor_class["ed-light"].frame=function(self)
    self.class.base.frame(self)
    if KeyIsDown('shoot') then
        task.Do(self)
        task.Do(self)
    else
    end
end
_editor_class["ed-light"].render=function(self)
    SetViewMode"world"
    local angle=self.angle
    local h=0
    local v=min(512,512*self.r1/240)
    local da=180/64
    local al=self.alpha
    for i=1,64 do
    	RenderTexture("texture:ed-light","mul+add",{self.r1*cos(angle)+self.x,self.r1*sin(angle)+self.y,    0.5,h,  0,Color(al,255,255,255)},
    					     {self.r1*cos(angle-da)+self.x,self.r1*sin(angle-da)+self.y,0.5,h+8,0,Color(al,255,255,255)},
    					     {self.r2*cos(angle-da)+self.x,self.r2*sin(angle-da)+self.y,0.5,h+8,v,Color(al,255,255,255)},
    					     {self.r2*cos(angle)+self.x,self.r2*sin(angle)+self.y,    0.5,h,  v,Color(al,255,255,255)})
    	angle=angle-da
    	h=h+8
    end
end
_editor_class["ed-light"].del=function(self)
end
