	self.maxhp=10
	self.colli=false
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    self.vscale=1/2
    self.flag=1
    self.img="image:staff"..sty
    if sty==6 then
        task.New(self,function()
            _object.set_color(self,"",0,255,255,255)
            task.New(self,function()
                task._Wait(30)
                do local r,_d_r=(0),(1/29) for _=1,30 do
                    _object.set_color(self,"",255*r,255,255,255)
                    task._Wait(1)
                r=r+_d_r end end
            end)
            do local i,_d_i=(0),(1/119) for _=1,120 do
                self.rot=90-90*sin(i*90) self.hscale=1/2*sin(i*90)
                task._Wait(1)
            i=i+_d_i end end
            do for _=1,_infinite do
                if self.flag==2 then break end
                task._Wait(1)
            end end
            task.New(self,function()
                task._Wait(30)
                do local r,_d_r=(1),(-1/29) for _=1,30 do
                    _object.set_color(self,"",255*r,255,255,255)
                    task._Wait(1)
                r=r+_d_r end end
            end)
            do local i,_d_i=(1),(-1/119) for _=1,120 do
                self.rot=0-90*(1-sin(i*90)) self.hscale=1/2*sin(i*90)
                task._Wait(1)
            i=i+_d_i end end
            _del(self,true)
        end)
    else
        task.New(self,function()
            _object.set_color(self,"",0,255,255,255)
            task.New(self,function()
                task._Wait(30)
                do local r,_d_r=(0),(1/29) for _=1,30 do
                    _object.set_color(self,"",255*r,255,255,255)
                    task._Wait(1)
                r=r+_d_r end end
            end)
            do local i,_d_i=(0),(1/119) for _=1,120 do
                self.rot=90-90*sin(i*90) self.hscale=1/2*sin(i*90)
                task._Wait(1)
            i=i+_d_i end end
            task._Wait(180)
            task.New(self,function()
                task._Wait(30)
                do local r,_d_r=(1),(-1/29) for _=1,30 do
                    _object.set_color(self,"",255*r,255,255,255)
                    task._Wait(1)
                r=r+_d_r end end
            end)
            do local i,_d_i=(1),(-1/119) for _=1,120 do
                self.rot=0-90*(1-sin(i*90)) self.hscale=1/2*sin(i*90)
                task._Wait(1)
            i=i+_d_i end end
            _del(self,true)
        end)
    end
